#define setnil(o) ((o)->tt = T_NIL)
#define setbool(o, b) ((o)->tt = (b) ? T_TRUE : T_FALSE)
#define setint(o, x) do { TValue *io_ = (o); io_->v.i = (x); io_->tt = T_INT; } while (0)
#define setflt(o, x) do { TValue *io_ = (o); io_->v.n = (x); io_->tt = T_FLT; } while (0)
#define setgco(o, x, t) do { TValue *io_ = (o); io_->v.gc = (GCObj *)(x); io_->tt = (t); } while (0)
#define setstr(o, s) setgco(o, s, T_STR)
#define settab(o, t) setgco(o, t, T_TAB)
#define setlcl(o, c) setgco(o, c, T_LCL)
#define setccl(o, c) setgco(o, c, T_CCL)
#define setud(o, u) setgco(o, u, T_UD)
#define setthr(o, t) setgco(o, t, T_THR)
#define setlcf(o, fn) do { TValue *io_ = (o); io_->v.f = (fn); io_->tt = T_LCF; } while (0)
