void d_hook(State *L, int event, int line);
TValue *d_tryfuncTM(State *L, TValue *func);
#define checkstack(L, n) do { if ((L)->stack_last - (L)->top <= (n)) d_checkstack(L, n); } while (0)
#define next_ci(L) ((L)->ci->next ? ((L)->ci = (L)->ci->next) : ((L)->ci = d_extendci(L)))

