{"command":"cd /workspace/src && cat > obj.c <<'EOF'
/* strings, numbers, and miscellaneous object helpers */
#include "core.h"
#include <ctype.h>
#include <errno.h>

const TValue absentkey = {{0}, T_NIL};

const char *const typenames[] = {
  "no value", "nil", "boolean", "userdata", "number",
  "string", "table", "function", "userdata", "thread", "upvalue", "proto"
};

const int basetypeof[16] = {
  TY_NIL, TY_BOOL, TY_BOOL, TY_NUM, TY_NUM, TY_LUD, TY_FUNC, TY_NIL,
  TY_STR, TY_TAB, TY_FUNC, TY_FUNC, TY_UD, TY_THR, 9, 10
};

/* ---------------- strings ---------------- */

static uint32_t strhash(const char *s, size_t l, uint32_t seed) {
  uint32_t h = seed ^ (uint32_t)l ^ 0x9e3779b9u;
  size_t i;
  for (i = 0; i < l; i++) {
    h ^= (uint8_t)s[i];
    h *= 16777619u;
  }
  h ^= h >> 15;
  return h;
}

uint32_t str_hashlong(Str *s) {
  if (!s->hashed) {
    s->hash = strhash(s->data, s->len, 0x2545F491u);
    s->hashed = 1;
  }
  return s->hash;
}

int str_eqlong(Str *a, Str *b) {
  size_t len = a->len;
  return (a == b) || (len == b->len && memcmp(a->data, b->data, len) == 0);
}

void str_resize(State *L, int newsize) {
  StrTab *tb = &G(L)->strt;
  Str **nh = mem_newvec(L, newsize, Str *);
  int i;
  for (i = 0; i < newsize; i++) nh[i] = NULL;
  for (i = 0; i < tb->size; i++) {
    Str *p = tb->hash[i];
    while (p) {
      Str *hn = p->hnext;
      unsigned int h = p->hash & (newsize - 1);
      p->hnext = nh[h];
      nh[h] = p;
      p = hn;
    }
  }
  if (tb->hash) mem_freevec(L, tb->hash, tb->size, Str *);
  tb->hash = nh;
  tb->size = newsize;
}

void str_init(State *L) {
  str_resize(L, 128);
}

static Str *createstr(State *L, size_t l, int tt) {
  size_t totalsize = offsetof(Str, data) + l + 1;
  Str *ts = (Str *)mem_alloc(L, totalsize);
  ts->tt = tt;
  ts->marked = 0;
  ts->gcnext = NULL;
  ts->reserved = 0;
  ts->hashed = 0;
  ts->hash = 0;
  ts->len = l;
  ts->hnext = NULL;
  ts->data[l] = '\0';
  return ts;
}

void str_remove(State *L, Str *ts) {
  StrTab *tb = &G(L)->strt;
  Str **p = &tb->hash[ts->hash & (tb->size - 1)];
  while (*p != ts) p = &(*p)->hnext;
  *p = (*p)->hnext;
  tb->nuse--;
}

static Str *internshort(State *L, const char *str, size_t l) {
  Global *g = G(L);
  StrTab *tb = &g->strt;
  uint32_t h = strhash(str, l, g->seed);
  Str **list = &tb->hash[h & (tb->size - 1)];
  Str *ts;
  for (ts = *list; ts != NULL; ts = ts->hnext) {
    if (l == ts->len && memcmp(str, ts->data, l) == 0) {
      /* resurrect if dead (only during sweep would that matter) */
      ts->marked &= ~2;  /* clear any 'dead' bit */
      return ts;
    }
  }
  if (tb->nuse >= tb->size) {
    str_resize(L, tb->size * 2);
    list = &tb->hash[h & (tb->size - 1)];
  }
  ts = createstr(L, l, T_STR);
  ts->isshort = 1;
  ts->hash = h;
  ts->hashed = 1;
  memcpy(ts->data, str, l);
  ts->marked = g->currentwhite;
  ts->hnext = *list;
  *list = ts;
  tb->nuse++;
  return ts;
}

Str *str_newlong(State *L, size_t l) {
  Str *ts;
  if (l >= ((size_t)1 << 62)) dbg_runerror(L, "string length overflow");
  ts = createstr(L, l, T_STR);
  ts->isshort = 0;
  ts->marked = G(L)->currentwhite;
  ts->gcnext = G(L)->allgc;
  G(L)->allgc = (GCObj *)ts;
  return ts;
}

Str *str_new(State *L, const char *s, size_t l) {
  if (l <= MAXSHORTLEN) return internshort(L, s, l);
  else {
    Str *ts = str_newlong(L, l);
    memcpy(ts->data, s, l);
    return ts;
  }
}

Str *str_newc(State *L, const char *s) {
  return str_new(L, s, strlen(s));
}

Udata *ud_new(State *L, size_t s, int nuv) {
  Udata *u;
  int i;
  if (s > ((size_t)1 << 60)) dbg_runerror(L, "not enough memory");
  u = (Udata *)gc_new(L, T_UD, offsetof(Udata, data) + s);
  u->len = s;
  u->nuv = nuv;
  u->meta = NULL;
  u->uv = NULL;
  if (nuv > 0) {
    u->uv = mem_newvec(L, nuv, TValue);
    for (i = 0; i < nuv; i++) setnil(&u->uv[i]);
  }
  return u;
}

/* ---------------- numbers ---------------- */

int hexavalue(int c) {
  if (isdigit(c)) return c - '0';
  else return (tolower(c) - 'a') + 10;
}

static int isneg(const char **s) {
  if (**s == '-') { (*s)++; return 1; }
  else if (**s == '+') (*s)++;
  return 0;
}

static const char *l_str2int(const char *s, lint *result) {
  luint a = 0;
  int empty = 1;
  int neg;
  while (isspace((unsigned char)*s)) s++;
  neg = isneg(&s);
  if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
    s += 2;
    for (; isxdigit((unsigned char)*s); s++) {
      a = a * 16 + hexavalue(*s);
      empty = 0;
    }
  } else {
    luint maxby10 = (luint)(INT64_MAX / 10);
    int maxlastd = (int)(INT64_MAX % 10);
    for (; isdigit((unsigned char)*s); s++) {
      int d = *s - '0';
      if (a >= maxby10 && (a > maxby10 || d > maxlastd + neg))
        return NULL;
      a = a * 10 + d;
      empty = 0;
    }
  }
  while (isspace((unsigned char)*s)) s++;
  if (empty || *s != '\0') return NULL;
  *result = (lint)(neg ? 0u - a : a);
  return s;
}

static const char *l_str2d(const char *s, lnum *result) {
  char *endptr;
  const char *pmode = strpbrk(s, ".xXnN");
  int mode = pmode ? tolower((unsigned char)*pmode) : 0;
  if (mode == 'n') return NULL;
  *result = strtod(s, &endptr);
  if (endptr == s) return NULL;
  while (isspace((unsigned char)*endptr)) endptr++;
  return (*endptr == '\0') ? endptr : NULL;
}

size_t str2number(const char *s, TValue *o) {
  lint i;
  lnum n;
  const char *e;
  if ((e = l_str2int(s, &i)) != NULL) {
    setint(o, i);
  } else if ((e = l_str2d(s, &n)) != NULL) {
    setflt(o, n);
  } else
    return 0;
  return (size_t)(e - s) + 1;
}

int num_tostrbuf(const TValue *o, char *buff) {
  int len;
  if (isint(o)) {
    len = snprintf(buff, 50, "%lld", (long long)ivalue(o));
  } else {
    lnum n = fltvalue(o);
    len = snprintf(buff, 50, "%.15g", n);
    if (strtod(buff, NULL) != n)
      len = snprintf(buff, 50, "%.17g", n);
    if (buff[strspn(buff, "-0123456789")] == '\0') {
      buff[len++] = '.';
      buff[len++] = '0';
      buff[len] = '\0';
    }
  }
  return len;
}

void obj_tostring(State *L, TValue *o) {
  char buff[64];
  int len = num_tostrbuf(o, buff);
  setstr(o, str_new(L, buff, len));
}

int flt_tointeger(lnum n, lint *p, int mode) {
  lnum f = floor(n);
  if (n != f) {
    if (mode == 0) return 0;
    else if (mode == 2) f += 1;
  }
  if (f >= -9223372036854775808.0 && f < 9223372036854775808.0) {
    *p = (lint)f;
    return 1;
  }
  return 0;
}

static int cvt2num(const TValue *o, TValue *v) {
  if (isstr(o)) {
    Str *s = strvalue(o);
    return str2number(s->data, v) == s->len + 1;
  }
  return 0;
}

int obj_tonumber(const TValue *o, lnum *n) {
  TValue v;
  if (isint(o)) { *n = (lnum)ivalue(o); return 1; }
  if (isflt(o)) { *n = fltvalue(o); return 1; }
  if (cvt2num(o, &v)) { *n = nvalue(&v); return 1; }
  return 0;
}

int obj_tointeger(const TValue *o, lint *p, int mode) {
  TValue v;
  if (cvt2num(o, &v)) o = &v;
  if (isint(o)) { *p = ivalue(o); return 1; }
  if (isflt(o)) return flt_tointeger(fltvalue(o), p, mode);
  return 0;
}

/* integer-only conversions (no strings) */
int vm_tointeger(const TValue *o, lint *p) {
  if (isint(o)) { *p = ivalue(o); return 1; }
  if (isflt(o)) return flt_tointeger(fltvalue(o), p, 0);
  return 0;
}

int utf8esc(char *buff, unsigned long x) {
  int n = 1;  /* number of bytes put in buffer (backwards) */
  if (x < 0x80)
    buff[7] = (char)x;
  else {
    unsigned int mfb = 0x3f;
    do {
      buff[8 - (n++)] = (char)(0x80 | (x & 0x3f));
      x >>= 6;
      mfb >>= 1;
    } while (x > mfb);
    buff[8 - n] = (char)((~mfb << 1) | x);
  }
  return n;
}

/* ---------------- arithmetic helpers ---------------- */

lint int_mod(State *L, lint m, lint n) {
  if ((luint)n + 1u <= 1u) {
    if (n == 0) dbg_runerror(L, "attempt to perform 'n%%%%0'");
    return 0;
  } else {
    lint r = m % n;
    if (r != 0 && (r ^ n) < 0) r += n;
    return r;
  }
}

lint int_idiv(State *L, lint m, lint n) {
  if ((luint)n + 1u <= 1u) {
    if (n == 0) dbg_runerror(L, "attempt to divide by zero");
    return (lint)(0u - (luint)m);
  } else {
    lint q = m / n;
    if ((m ^ n) < 0 && m % n != 0) q -= 1;
    return q;
  }
}

lnum flt_mod(lnum a, lnum b) {
  lnum m = fmod(a, b);
  if ((m > 0) ? b < 0 : (m < 0 && b != m)) m += b;
  return m;
}

lint shiftl(lint x, lint y) {
  if (y < 0) {
    if (y <= -64) return 0;
    return (lint)((luint)x >> (luint)(-y));
  } else {
    if (y >= 64) return 0;
    return (lint)((luint)x << (luint)y);
  }
}

static lint intarith(State *L, int op, lint v1, lint v2) {
  switch (op) {
    case OPARITH_ADD: return (lint)((luint)v1 + (luint)v2);
    case OPARITH_SUB: return (lint)((luint)v1 - (luint)v2);
    case OPARITH_MUL: return (lint)((luint)v1 * (luint)v2);
    case OPARITH_MOD: return int_mod(L, v1, v2);
    case OPARITH_IDIV: return int_idiv(L, v1, v2);
    case OPARITH_BAND: return (lint)((luint)v1 & (luint)v2);
    case OPARITH_BOR: return (lint)((luint)v1 | (luint)v2);
    case OPARITH_BXOR: return (lint)((luint)v1 ^ (luint)v2);
    case OPARITH_SHL: return shiftl(v1, v2);
    case OPARITH_SHR: return shiftl(v1, (lint)(0u - (luint)v2));
    case OPARITH_UNM: return (lint)(0u - (luint)v1);
    case OPARITH_BNOT: return (lint)(~(luint)0 ^ (luint)v1);
    default: return 0;
  }
}

static lnum numarith(int op, lnum v1, lnum v2) {
  switch (op) {
    case OPARITH_ADD: return v1 + v2;
    case OPARITH_SUB: return v1 - v2;
    case OPARITH_MUL: return v1 * v2;
    case OPARITH_DIV: return v1 / v2;
    case OPARITH_POW: return (v2 == 2) ? v1 * v1 : pow(v1, v2);
    case OPARITH_IDIV: return floor(v1 / v2);
    case OPARITH_UNM: return -v1;
    case OPARITH_MOD: return flt_mod(v1, v2);
    default: return 0;
  }
}

/* raw arithmetic on numbers only (no strings); returns 0 if not possible */
int raw_arith(State *L, int op, const TValue *p1, const TValue *p2, TValue *res) {
  switch (op) {
    case OPARITH_BAND: case OPARITH_BOR: case OPARITH_BXOR:
    case OPARITH_SHL: case OPARITH_SHR: case OPARITH_BNOT: {
      lint i1, i2;
      if (vm_tointeger(p1, &i1) && vm_tointeger(p2, &i2)) {
        setint(res, intarith(L, op, i1, i2));
        return 1;
      }
      return 0;
    }
    case OPARITH_DIV: case OPARITH_POW: {
      lnum n1, n2;
      if (isnum(p1) && isnum(p2)) {
        n1 = nvalue(p1); n2 = nvalue(p2);
        setflt(res, numarith(op, n1, n2));
        return 1;
      }
      return 0;
    }
    default: {
      if (isint(p1) && isint(p2)) {
        setint(res, intarith(L, op, ivalue(p1), ivalue(p2)));
        return 1;
      } else if (isnum(p1) && isnum(p2)) {
        setflt(res, numarith(op, nvalue(p1), nvalue(p2)));
        return 1;
      }
      return 0;
    }
  }
}

/* ---------------- formatted strings ---------------- */

static void addstr2buf(char **buf, size_t *n, size_t *cap, const char *s, size_t l) {
  if (*n + l + 1 > *cap) {
    size_t nc = (*cap) * 2 + l + 16;
    *buf = realloc(*buf, nc);
    *cap = nc;
  }
  memcpy(*buf + *n, s, l);
  *n += l;
}

const char *pushvfstring(State *L, const char *fmt, va_list argp) {
  size_t cap = 128, n = 0;
  char *buf = malloc(cap);
  const char *e;
  Str *res;
  while ((e = strchr(fmt, '%')) != NULL) {
    addstr2buf(&buf, &n, &cap, fmt, (size_t)(e - fmt));
    switch (*(e + 1)) {
      case 's': {
        const char *s = va_arg(argp, char *);
        if (s == NULL) s = "(null)";
        addstr2buf(&buf, &n, &cap, s, strlen(s));
        break;
      }
      case 'c': {
        char c = (char)(unsigned char)va_arg(argp, int);
        addstr2buf(&buf, &n, &cap, &c, 1);
        break;
      }
      case 'd': {
        char b[32];
        int l = snprintf(b, sizeof(b), "%d", va_arg(argp, int));
        addstr2buf(&buf, &n, &cap, b, l);
        break;
      }
      case 'I': {
        char b[32];
        int l = snprintf(b, sizeof(b), "%lld", (long long)va_arg(argp, lint));
        addstr2buf(&buf, &n, &cap, b, l);
        break;
      }
      case 'f': {
        char b[64];
        TValue v;
        int l;
        setflt(&v, va_arg(argp, lnum));
        l = num_tostrbuf(&v, b);
        addstr2buf(&buf, &n, &cap, b, l);
        break;
      }
      case 'p': {
        char b[40];
        void *p = va_arg(argp, void *);
        int l = snprintf(b, sizeof(b), "%p", p);
        addstr2buf(&buf, &n, &cap, b, l);
        break;
      }
      case 'U': {
        char b[8];
        int l = utf8esc(b, (unsigned long)va_arg(argp, long));
        addstr2buf(&buf, &n, &cap, b + 8 - l, l);
        break;
      }
      case '%': {
        addstr2buf(&buf, &n, &cap, "%", 1);
        break;
      }
      default: {
        addstr2buf(&buf, &n, &cap, e, 2);
        break;
      }
    }
    fmt = e + 2;
  }
  addstr2buf(&buf, &n, &cap, fmt, strlen(fmt));
  res = str_new(L, buf, n);
  free(buf);
  setstr(L->top, res);
  L->top++;
  return getstr(res);
}

const char *pushfstring(State *L, const char *fmt, ...) {
  const char *msg;
  va_list argp;
  va_start(argp, fmt);
  msg = pushvfstring(L, fmt, argp);
  va_end(argp);
  return msg;
}

#define RETS "..."
#define PRE "[string \""
#define POS "\"]"
#define LL(x) (sizeof(x) / sizeof(char) - 1)

void chunkid(char *out, const char *source, size_t srclen) {
  size_t bufflen = IDSIZE;
  if (*source == '=') {
    if (srclen <= bufflen) {
      memcpy(out, source + 1, srclen - 1);
      out[srclen - 1] = '\0';
    } else {
      memcpy(out, source + 1, bufflen - 1);
      out[bufflen - 1] = '\0';
    }
  } else if (*source == '@') {
    if (srclen <= bufflen) {
      memcpy(out, source + 1, srclen - 1);
      out[srclen - 1] = '\0';
    } else {
      memcpy(out, RETS, LL(RETS));
      out += LL(RETS);
      bufflen -= LL(RETS);
      memcpy(out, source + 1 + srclen - bufflen, bufflen - 1);
      out[bufflen - 1] = '\0';
    }
  } else {
    const char *nl = memchr(source, '\n', srclen);
    memcpy(out, PRE, LL(PRE));
    out += LL(PRE);
    bufflen -= LL(PRE RETS POS) + 1;
    if (srclen < bufflen && nl == NULL) {
      memcpy(out, source, srclen);
      out += srclen;
    } else {
      if (nl != NULL) srclen = (size_t)(nl - source);
      if (srclen > bufflen) srclen = bufflen;
      memcpy(out, source, srclen);
      out += srclen;
      memcpy(out, RETS, LL(RETS));
      out += LL(RETS);
    }
    memcpy(out, POS, LL(POS) + 1);
  }
}
