void str_resize(State *L, int newsize) {
  StrTab *tb = &G(L)->strt;
  Str **nh = mem_newvec(L, newsize, Str *);
  int i;
  for (i = 0; i < newsize; i++) nh[i] = NULL;
  for (i = 0; i < tb->size; i++) {
    Str *p = tb->hash[i];
    while (p) {
      Str *hn = p->hnext;
      unsigned int h = p->hash & (newsize - 1);
      p->hnext = nh[h];
      nh[h] = p;
      p = hn;
    }
  }
  if (tb->hash) mem_freevec(L, tb->hash, tb->size, Str *);
  tb->hash = nh;
  tb->size = newsize;
}

