/* hash tables with array part */
#include "core.h"

#define MAXABITS 31
#define MAXASIZE (1u << MAXABITS)
#define MAXHBITS 30

static Node dummynode_ = {{{0}, T_NIL}, {{0}, T_NIL}, 0};
#define dummynode (&dummynode_)
#define isdummy(t) ((t)->lastfree == NULL)
#define gnode(t, i) (&(t)->node[i])

static int ceillog2(unsigned int x) {
  int l = 0;
  x--;
  while (x >= 256) { l += 8; x >>= 8; }
  while (x > 0) { l++; x >>= 1; }
  return l;
}

static Node *hashpow2(const Table *t, uint32_t n) {
  return gnode(t, n & (sizenode(t) - 1));
}

static Node *hashmod(const Table *t, luint n) {
  return gnode(t, n % ((sizenode(t) - 1) | 1));
}

static Node *hashint(const Table *t, lint i) {
  luint ui = (luint)i;
  if (ui <= (luint)INT_MAX)
    return hashmod(t, (unsigned int)(int)ui);
  else
    return hashmod(t, ui);
}

static int l_hashfloat(lnum n) {
  int i;
  lint ni;
  n = frexp(n, &i) * -(lnum)INT_MIN;
  if (!(n >= -9223372036854775808.0 && n < 9223372036854775808.0))
    return 0;
  else {
    unsigned int u;
    ni = (lint)n;
    u = (unsigned int)i + (unsigned int)ni;
    return (int)(u <= (unsigned int)INT_MAX ? u : ~u);
  }
}

static Node *hashptr(const Table *t, const void *p) {
  uintptr_t u = (uintptr_t)p;
  return hashmod(t, (unsigned int)(u & 0xffffffffu));
}

static Node *mainposition(const Table *t, int tt, const Value *kv) {
  switch (tt) {
    case T_INT: return hashint(t, kv->i);
    case T_FLT: return hashmod(t, (unsigned int)l_hashfloat(kv->n));
    case T_STR: {
      Str *s = (Str *)kv->gc;
      if (s->isshort) return hashpow2(t, s->hash);
      return hashpow2(t, str_hashlong(s));
    }
    case T_FALSE: return hashpow2(t, 0);
    case T_TRUE: return hashpow2(t, 1);
    case T_LUD: return hashptr(t, kv->p);
    case T_LCF: return hashptr(t, (void *)(uintptr_t)kv->f);
    default: return hashptr(t, kv->gc);
  }
}

static Node *mainpositionTV(const Table *t, const TValue *key) {
  return mainposition(t, key->tt, &key->v);
}

static Node *mainpositionfromnode(const Table *t, Node *nd) {
  return mainposition(t, nd->key.tt, &nd->key.v);
}

static int equalkey(const TValue *k1, const Node *n2, int deadok) {
  if (k1->tt != n2->key.tt) {
    if (deadok && n2->key.tt == T_DEADKEY && iscollectable(k1))
      return gcvalue(k1) == n2->key.v.gc;
    return 0;
  }
  switch (k1->tt) {
    case T_NIL: case T_FALSE: case T_TRUE: return 1;
    case T_INT: return k1->v.i == n2->key.v.i;
    case T_FLT: return k1->v.n == n2->key.v.n;
    case T_LUD: return k1->v.p == n2->key.v.p;
    case T_LCF: return k1->v.f == n2->key.v.f;
    case T_STR: return str_eq(strvalue(k1), (Str *)n2->key.v.gc);
    default: return k1->v.gc == n2->key.v.gc;
  }
}

static const TValue *getgeneric(Table *t, const TValue *key, int deadok) {
  Node *n = mainpositionTV(t, key);
  for (;;) {
    if (equalkey(key, n, deadok)) return &n->val;
    else {
      int nx = n->next;
      if (nx == 0) return &absentkey;
      n += nx;
    }
  }
}

const TValue *tab_getint(Table *t, lint key) {
  if ((luint)key - 1u < (luint)t->asize)
    return &t->array[key - 1];
  else {
    Node *n = hashint(t, key);
    for (;;) {
      if (n->key.tt == T_INT && n->key.v.i == key)
        return &n->val;
      else {
        int nx = n->next;
        if (nx == 0) break;
        n += nx;
      }
    }
    return &absentkey;
  }
}

const TValue *tab_getshortstr(Table *t, Str *key) {
  Node *n = hashpow2(t, key->hash);
  for (;;) {
    if (n->key.tt == T_STR && (Str *)n->key.v.gc == key)
      return &n->val;
    else {
      int nx = n->next;
      if (nx == 0) return &absentkey;
      n += nx;
    }
  }
}

const TValue *tab_getstr(Table *t, Str *key) {
  if (key->isshort) return tab_getshortstr(t, key);
  else {
    TValue ko;
    setstr(&ko, key);
    return getgeneric(t, &ko, 0);
  }
}

const TValue *tab_get(Table *t, const TValue *key) {
  switch (key->tt) {
    case T_STR: return tab_getstr(t, strvalue(key));
    case T_INT: return tab_getint(t, ivalue(key));
    case T_NIL: return &absentkey;
    case T_FLT: {
      lint k;
      if (flt_tointeger(fltvalue(key), &k, 0))
        return tab_getint(t, k);
      return getgeneric(t, key, 0);
    }
    default:
      return getgeneric(t, key, 0);
  }
}

/* ---------- sizes ---------- */

static unsigned int computesizes(unsigned int nums[], unsigned int *pna) {
  int i;
  unsigned int twotoi;
  unsigned int a = 0;
  unsigned int na = 0;
  unsigned int optimal = 0;
  for (i = 0, twotoi = 1; twotoi > 0 && *pna > twotoi / 2; i++, twotoi *= 2) {
    a += nums[i];
    if (a > twotoi / 2) {
      optimal = twotoi;
      na = a;
    }
  }
  *pna = na;
  return optimal;
}

static int countint(lint key, unsigned int *nums) {
  if ((luint)key - 1u < (luint)MAXASIZE) {
    nums[ceillog2((unsigned int)key)]++;
    return 1;
  }
  return 0;
}

static unsigned int numusearray(const Table *t, unsigned int *nums) {
  int lg;
  unsigned int ttlg;
  unsigned int ause = 0;
  unsigned int i = 1;
  unsigned int asize = t->asize;
  for (lg = 0, ttlg = 1; lg <= MAXABITS; lg++, ttlg *= 2) {
    unsigned int lc = 0;
    unsigned int lim = ttlg;
    if (lim > asize) {
      lim = asize;
      if (i > lim) break;
    }
    for (; i <= lim; i++) {
      if (!isnil(&t->array[i - 1])) lc++;
    }
    nums[lg] += lc;
    ause += lc;
  }
  return ause;
}

static int numusehash(const Table *t, unsigned int *nums, unsigned int *pna) {
  int totaluse = 0;
  int ause = 0;
  int i = (int)sizenode(t);
  while (i--) {
    Node *n = &t->node[i];
    if (!isnil(&n->val)) {
      if (n->key.tt == T_INT) ause += countint(n->key.v.i, nums);
      totaluse++;
    }
  }
  *pna += ause;
  return totaluse;
}

static void setnodevector(State *L, Table *t, unsigned int size) {
  if (size == 0) {
    t->node = dummynode;
    t->lsizenode = 0;
    t->lastfree = NULL;
  } else {
    int i;
    int lsize = ceillog2(size);
    if (lsize > MAXHBITS) dbg_runerror(L, "table overflow");
    size = 1u << lsize;
    t->node = mem_newvec(L, size, Node);
    for (i = 0; i < (int)size; i++) {
      Node *n = gnode(t, i);
      n->next = 0;
      setnil(&n->key);
      setnil(&n->val);
    }
    t->lsizenode = (uint8_t)lsize;
    t->lastfree = gnode(t, size);
  }
}

static void exchangehash(Table *t1, Table *t2) {
  uint8_t lsizenode = t1->lsizenode;
  Node *node = t1->node;
  Node *lastfree = t1->lastfree;
  t1->lsizenode = t2->lsizenode;
  t1->node = t2->node;
  t1->lastfree = t2->lastfree;
  t2->lsizenode = lsizenode;
  t2->node = node;
  t2->lastfree = lastfree;
}

static void reinsert(State *L, Table *ot, Table *t) {
  int j;
  int size = (int)sizenode(ot);
  for (j = 0; j < size; j++) {
    Node *old = gnode(ot, j);
    if (!isnil(&old->val)) {
      TValue k = old->key;
      TValue *slot = tab_set(L, t, &k);
      *slot = old->val;
    }
  }
}

static void freehash(State *L, Table *t) {
  if (!isdummy(t)) mem_freevec(L, t->node, sizenode(t), Node);
}

void tab_resize(State *L, Table *t, unsigned int newasize, unsigned int nhsize) {
  unsigned int i;
  Table newt;
  unsigned int oldasize = t->asize;
  TValue *newarray;
  if (newasize > MAXASIZE) dbg_runerror(L, "table overflow");
  newt.flags = 0;
  setnodevector(L, &newt, nhsize);
  if (newasize < oldasize) {
    t->asize = newasize;
    exchangehash(t, &newt);
    for (i = newasize; i < oldasize; i++) {
      if (!isnil(&t->array[i])) {
        TValue *slot = tab_setint(L, t, (lint)i + 1);
        *slot = t->array[i];
      }
    }
    t->asize = oldasize;
    exchangehash(t, &newt);
  }
  newarray = mem_reallocvec(L, t->array, oldasize, newasize, TValue);
  exchangehash(t, &newt);
  t->array = newarray;
  t->asize = newasize;
  for (i = oldasize; i < newasize; i++) setnil(&t->array[i]);
  reinsert(L, &newt, t);
  freehash(L, &newt);
}

void tab_resizearray(State *L, Table *t, unsigned int nasize) {
  int nsize = isdummy(t) ? 0 : (int)sizenode(t);
  tab_resize(L, t, nasize, (unsigned int)nsize);
}

static void rehash(State *L, Table *t, const TValue *ek) {
  unsigned int asize;
  unsigned int na;
  unsigned int nums[MAXABITS + 1];
  int i;
  int totaluse;
  for (i = 0; i <= MAXABITS; i++) nums[i] = 0;
  na = numusearray(t, nums);
  totaluse = (int)na;
  totaluse += numusehash(t, nums, &na);
  if (isint(ek)) na += countint(ivalue(ek), nums);
  totaluse++;
  asize = computesizes(nums, &na);
  tab_resize(L, t, asize, (unsigned int)totaluse - na);
}

Table *tab_new(State *L) {
  Table *t = (Table *)gc_new(L, T_TAB, sizeof(Table));
  t->meta = NULL;
  t->flags = 0xff;
  t->array = NULL;
  t->asize = 0;
  t->gclist = NULL;
  setnodevector(L, t, 0);
  return t;
}

void tab_free(State *L, Table *t) {
  freehash(L, t);
  mem_freevec(L, t->array, t->asize, TValue);
  mem_free(L, t, sizeof(Table));
}

static Node *getfreepos(Table *t) {
  if (!isdummy(t)) {
    while (t->lastfree > t->node) {
      t->lastfree--;
      if (t->lastfree->key.tt == T_NIL)
        return t->lastfree;
    }
  }
  return NULL;
}

static TValue *newkey(State *L, Table *t, const TValue *key) {
  Node *mp;
  TValue aux;
  if (isnil(key))
    dbg_runerror(L, "table index is nil");
  else if (isflt(key)) {
    lnum f = fltvalue(key);
    lint k;
    if (flt_tointeger(f, &k, 0)) {
      setint(&aux, k);
      key = &aux;
    } else if (f != f)
      dbg_runerror(L, "table index is NaN");
  }
  mp = mainpositionTV(t, key);
  if (!isnil(&mp->val) || isdummy(t)) {
    Node *othern;
    Node *f = getfreepos(t);
    if (f == NULL) {
      rehash(L, t, key);
      return tab_set(L, t, key);
    }
    othern = mainpositionfromnode(t, mp);
    if (othern != mp) {
      while (othern + othern->next != mp) othern += othern->next;
      othern->next = (int)(f - othern);
      *f = *mp;
      if (mp->next != 0) {
        f->next += (int)(mp - f);
        mp->next = 0;
      }
      setnil(&mp->val);
    } else {
      if (mp->next != 0)
        f->next = (int)((mp + mp->next) - f);
      mp->next = (int)(f - mp);
      mp = f;
    }
  }
  mp->key = *key;
  return &mp->val;
}

TValue *tab_set(State *L, Table *t, const TValue *key) {
  const TValue *p;
  t->flags = 0;
  p = tab_get(t, key);
  if (!isabstkey(p)) return (TValue *)p;
  return newkey(L, t, key);
}

TValue *tab_setint(State *L, Table *t, lint key) {
  const TValue *p = tab_getint(t, key);
  if (!isabstkey(p)) return (TValue *)p;
  else {
    TValue k;
    setint(&k, key);
    return newkey(L, t, &k);
  }
}

void tab_setstr(State *L, Table *t, Str *key, const TValue *v) {
  TValue k;
  TValue *slot;
  setstr(&k, key);
  slot = tab_set(L, t, &k);
  *slot = *v;
}

static unsigned int findindex(State *L, Table *t, TValue *key, unsigned int asize) {
  unsigned int i;
  if (isnil(key)) return 0;
  if (isint(key) && (luint)ivalue(key) - 1u < (luint)asize)
    return (unsigned int)ivalue(key);
  else {
    const TValue *n;
    TValue k = *key;
    if (isflt(key)) {
      lint ik;
      if (flt_tointeger(fltvalue(key), &ik, 0)) {
        if ((luint)ik - 1u < (luint)asize) return (unsigned int)ik;
        setint(&k, ik);
      }
    }
    n = getgeneric(t, &k, 1);
    if (isabstkey(n))
      dbg_runerror(L, "invalid key to 'next'");
    i = (unsigned int)(((const Node *)((const char *)n - offsetof(Node, val))) - gnode(t, 0));
    return (i + 1) + asize;
  }
}

int tab_next(State *L, Table *t, TValue *key) {
  unsigned int asize = t->asize;
  unsigned int i = findindex(L, t, key, asize);
  for (; i < asize; i++) {
    if (!isnil(&t->array[i])) {
      setint(key, (lint)i + 1);
      key[1] = t->array[i];
      return 1;
    }
  }
  for (i -= asize; (int)i < (int)sizenode(t); i++) {
    if (!isnil(&gnode(t, i)->val)) {
      Node *n = gnode(t, i);
      key[0] = n->key;
      key[1] = n->val;
      return 1;
    }
  }
  return 0;
}

static luint hash_search(Table *t, luint j) {
  luint i;
  if (j == 0) j++;
  do {
    i = j;
    if (j <= (luint)INT64_MAX / 2)
      j *= 2;
    else {
      j = (luint)INT64_MAX;
      if (isnil(tab_getint(t, (lint)j)))
        break;
      else
        return j;
    }
  } while (!isnil(tab_getint(t, (lint)j)));
  while (j - i > 1u) {
    luint m = (i + j) / 2;
    if (isnil(tab_getint(t, (lint)m))) j = m;
    else i = m;
  }
  return i;
}

luint tab_getn(Table *t) {
  unsigned int limit = t->asize;
  if (limit > 0 && isnil(&t->array[limit - 1])) {
    unsigned int i = 0, j = limit;
    if (limit >= 2 && !isnil(&t->array[limit - 2]))
      return limit - 1;
    while (j - i > 1u) {
      unsigned int m = (i + j) / 2;
      if (isnil(&t->array[m - 1])) j = m;
      else i = m;
    }
    return i;
  }
  if (isdummy(t) || isnil(tab_getint(t, (lint)limit + 1)))
    return limit;
  else
    return hash_search(t, limit);
}

size_t tab_size(Table *t) {
  return sizeof(Table) + sizeof(TValue) * t->asize + (isdummy(t) ? 0 : sizeof(Node) * sizenode(t));
}
