/* AST used between parser and code generator */
#ifndef AST_H
#define AST_H
#include "core.h"

typedef struct Expr Expr;
typedef struct Stat Stat;
typedef struct Block Block;
typedef struct FuncAST FuncAST;

/* variable declaration kinds */
#define VD_REG 0
#define VD_CONST 1
#define VD_CLOSE 2
#define VD_GLOBAL 3
#define VD_GCONST 4

typedef struct VarDesc {
  Str *name;      /* NULL for 'global *' */
  uint8_t kind;
  uint8_t captured;
  uint8_t isglobal;
  int reg;        /* register (assigned by codegen) */
  int locidx;     /* index into proto locvars (codegen) */
} VarDesc;

enum {
  E_NIL, E_TRUE, E_FALSE, E_INT, E_FLT, E_STR, E_VARARG, E_FUNC, E_TABLE,
  E_BIN, E_UN, E_AND, E_OR, E_LOCAL, E_UPVAL, E_GLOBAL, E_INDEX, E_CALL,
  E_METHCALL, E_PAREN
};

/* binary operators */
enum {
  OPR_ADD, OPR_SUB, OPR_MUL, OPR_MOD, OPR_POW, OPR_DIV, OPR_IDIV,
  OPR_BAND, OPR_BOR, OPR_BXOR, OPR_SHL, OPR_SHR,
  OPR_CONCAT, OPR_EQ, OPR_LT, OPR_LE, OPR_NE, OPR_GT, OPR_GE,
  OPR_AND, OPR_OR, OPR_NOBINOPR
};
enum { OPR_MINUS, OPR_BNOT, OPR_NOT, OPR_LEN, OPR_NOUNOPR };

typedef struct TField {
  Expr *key;   /* NULL for positional */
  Expr *val;
  int line;
} TField;

struct Expr {
  uint8_t k;
  uint8_t op;
  int line;
  union {
    lint ival;
    lnum nval;
    Str *sval;
    struct { Expr *a, *b; } bin;
    VarDesc *var;
    struct { int idx; Str *name; } up;
    struct { Expr *env; Str *name; uint8_t isconst; } glb;
    struct { Expr *obj, *key; } idx;
    struct { Expr *fn; Expr **args; int nargs; Str *mname; } call;
    struct { TField *f; int n; int narr, nhash; } tab;
    FuncAST *func;
  } u;
};

enum {
  S_CALL, S_LOCAL, S_ASSIGN, S_DO, S_WHILE, S_REPEAT, S_IF, S_NUMFOR,
  S_GENFOR, S_RETURN, S_BREAK, S_GOTO, S_LABEL, S_LOCALFUNC, S_GLOBAL,
  S_GLOBALFUNC
};

struct Stat {
  uint8_t k;
  int line;
  int line2;
  Stat *next;
  union {
    Expr *call;
    struct { VarDesc **vars; int nvars; Expr **exprs; int nexprs; } local;
    struct { Expr **targets; int nt; Expr **exprs; int ne; } assign;
    struct { Block *body; } blk;
    struct { Expr *cond; Block *body; } loop;
    struct { Expr **conds; Block **blocks; int n; Block *elseb; } ifs;
