/* lexical analyzer */
#include "lex.h"
#include <ctype.h>

#define EOZ (-1)

static const char *const tokens[] = {
  "and", "break", "do", "else", "elseif",
  "end", "false", "for", "function", "goto", "if",
  "in", "local", "nil", "not", "or", "repeat",
  "return", "then", "true", "until", "while",
  "//", "..", "...", "==", ">=", "<=", "~=",
  "<<", ">>", "::", "<eof>",
  "<number>", "<integer>", "<name>", "<string>"
};

#define lnext(ls) ((ls)->current = ((ls)->n > 0) ? ((ls)->n--, (unsigned char)*(ls)->p++) : EOZ)
#define currIsNewline(ls) ((ls)->current == '\n' || (ls)->current == '\r')
#define lislalpha(c) (isalpha(c) || (c) == '_')
#define lislalnum(c) (isalnum(c) || (c) == '_')
#define lisdigit(c) ((c) >= '0' && (c) <= '9')
#define lisxdigit(c) (isxdigit(c))
#define lisspace(c) ((c) == ' ' || (c) == '\t' || (c) == '\n' || (c) == '\r' || (c) == '\f' || (c) == '\v')

static void lexerror(Lex *ls, const char *msg, int token) __attribute__((noreturn));

static void save(Lex *ls, int c) {
  if (ls->nbuf + 1 > ls->bufsize) {
    size_t newsize = ls->bufsize * 2;
    if (newsize < 64) newsize = 64;
    ls->buf = realloc(ls->buf, newsize);
    ls->bufsize = newsize;
  }
  ls->buf[ls->nbuf++] = (char)c;
}

#define save_and_next(ls) (save(ls, (ls)->current), lnext(ls))

void lex_init(State *L) {
  int i;
  for (i = 0; i < NUM_RESERVED; i++) {
    Str *ts = str_newc(L, tokens[i]);
    ts->marked |= 4;  /* fixed */
    ts->reserved = (uint8_t)(i + 1);
  }
}

const char *lex_token2str(Lex *ls, int token) {
  if (token < FIRST_RESERVED) {
    if (isprint(token))
      return pushfstring(ls->L, "'%c'", token);
    else
      return pushfstring(ls->L, "'<\\%d>'", token);
  } else {
    const char *s = tokens[token - FIRST_RESERVED];
    if (token < TK_EOS)
      return pushfstring(ls->L, "'%s'", s);
    else
      return s;
  }
}

static const char *txtToken(Lex *ls, int token) {
  switch (token) {
    case TK_NAME: case TK_STRING:
    case TK_FLT: case TK_INT:
      save(ls, '\0');
      return pushfstring(ls->L, "'%s'", ls->buf);
    default:
      return lex_token2str(ls, token);
  }
}

static void lexerror(Lex *ls, const char *msg, int token) {
  char buff[IDSIZE];
  chunkid(buff, getstr(ls->source), ls->source->len);
  msg = pushfstring(ls->L, "%s:%d: %s", buff, ls->linenumber, msg);
  if (token)
    pushfstring(ls->L, "%s near %s", msg, txtToken(ls, token));
  d_throw(ls->L, TS_ERRSYNTAX);
}

void lex_syntaxerror(Lex *ls, const char *msg) {
  lexerror(ls, msg, ls->t.token);
}

void lex_semerror(Lex *ls, const char *msg) {
  ls->t.token = 0;
  lexerror(ls, msg, 0);
}

static Str *newstring(Lex *ls, const char *s, size_t l) {
  return str_new(ls->L, s, l);
}

static void inclinenumber(Lex *ls) {
  int old = ls->current;
  lnext(ls);
  if (currIsNewline(ls) && ls->current != old)
    lnext(ls);
  if (++ls->linenumber >= INT_MAX)
    lexerror(ls, "chunk has too many lines", 0);
}

void lex_setinput(State *L, Lex *ls, const char *p, size_t n, Str *source) {
  ls->L = L;
  ls->p = p;
  ls->n = n;
  ls->t.token = 0;
  ls->lookahead.token = TK_EOS;
  ls->linenumber = 1;
  ls->lastline = 1;
  ls->source = source;
  ls->envn = str_newc(L, "_ENV");
  ls->nbuf = 0;
  ls->level = 0;
  lnext(ls);
}

static int check_next1(Lex *ls, int c) {
  if (ls->current == c) {
    lnext(ls);
    return 1;
  }
  return 0;
}

static int check_next2(Lex *ls, const char *set) {
  if (ls->current == set[0] || ls->current == set[1]) {
    save_and_next(ls);
    return 1;
  }
  return 0;
}

static int read_numeral(Lex *ls, SemInfo *seminfo) {
  TValue obj;
  const char *expo = "Ee";
  int first = ls->current;
  save_and_next(ls);
  if (first == '0' && check_next2(ls, "xX"))
    expo = "Pp";
  for (;;) {
    if (check_next2(ls, expo))
      check_next2(ls, "-+");
    else if (ls->current != EOZ && (lisxdigit(ls->current) || ls->current == '.'))
      save_and_next(ls);
    else
      break;
  }
  if (ls->current != EOZ && lislalpha(ls->current))
    save_and_next(ls);
  save(ls, '\0');
  if (str2number(ls->buf, &obj) == 0)
    lexerror(ls, "malformed number", TK_FLT);
  ls->nbuf--;  /* remove '\0' */
  if (isint(&obj)) {
    seminfo->i = ivalue(&obj);
    return TK_INT;
  } else {
    seminfo->r = fltvalue(&obj);
    return TK_FLT;
  }
}

static size_t skip_sep(Lex *ls) {
  size_t count = 0;
  int s = ls->current;
  save_and_next(ls);
  while (ls->current == '=') {
    save_and_next(ls);
    count++;
  }
  return (ls->current == s) ? count + 2 : (count == 0) ? 1 : 0;
}

static void read_long_string(Lex *ls, SemInfo *seminfo, size_t sep) {
  int line = ls->linenumber;
  save_and_next(ls);
  if (currIsNewline(ls))
    inclinenumber(ls);
  for (;;) {
    switch (ls->current) {
      case EOZ: {
        const char *what = (seminfo ? "string" : "comment");
        const char *msg = pushfstring(ls->L, "unfinished long %s (starting at line %d)", what, line);
        lexerror(ls, msg, TK_EOS);
        break;
      }
      case ']': {
        if (skip_sep(ls) == sep) {
          save_and_next(ls);
          goto endloop;
        }
        break;
      }
      case '\n': case '\r': {
        save(ls, '\n');
        inclinenumber(ls);
        if (!seminfo) ls->nbuf = 0;
        break;
      }
      default: {
        if (seminfo) save_and_next(ls);
        else lnext(ls);
      }
    }
  }
endloop:
  if (seminfo)
    seminfo->ts = newstring(ls, ls->buf + sep, ls->nbuf - 2 * sep);
}

static void esccheck(Lex *ls, int c, const char *msg) {
  if (!c) {
    if (ls->current != EOZ)
      save_and_next(ls);
    lexerror(ls, msg, TK_STRING);
  }
}

static int gethexa(Lex *ls) {
  save_and_next(ls);
  esccheck(ls, ls->current != EOZ && lisxdigit(ls->current), "hexadecimal digit expected");
  return hexavalue(ls->current);
}

static int readhexaesc(Lex *ls) {
  int r = gethexa(ls);
  r = (r << 4) + gethexa(ls);
  ls->nbuf -= 2;
  return r;
}

static unsigned long readutf8esc(Lex *ls) {
  unsigned long r;
  int i = 4;
  save_and_next(ls);
  esccheck(ls, ls->current == '{', "missing '{' in \\u{xxxx}");
  r = (unsigned long)gethexa(ls);
  while ((void)save_and_next(ls), ls->current != EOZ && lisxdigit(ls->current)) {
    i++;
    esccheck(ls, r <= (0x7FFFFFFFu >> 4), "UTF-8 value too large");
    r = (r << 4) + (unsigned long)hexavalue(ls->current);
  }
  esccheck(ls, ls->current == '}', "missing '}' in \\u{xxxx}");
  lnext(ls);
  ls->nbuf -= (size_t)i;
  return r;
}

static void utf8esc_(Lex *ls) {
  char buff[8];
  int n = utf8esc(buff, readutf8esc(ls));
  for (; n > 0; n--) save(ls, buff[8 - n]);
}

static int readdecesc(Lex *ls) {
  int i;
  int r = 0;
  for (i = 0; i < 3 && lisdigit(ls->current); i++) {
    r = 10 * r + ls->current - '0';
    save_and_next(ls);
  }
  esccheck(ls, r <= UCHAR_MAX, "decimal escape too large");
  ls->nbuf -= (size_t)i;
  return r;
}

static void read_string(Lex *ls, int del, SemInfo *seminfo) {
  save_and_next(ls);
  while (ls->current != del) {
    switch (ls->current) {
      case EOZ:
        lexerror(ls, "unfinished string", TK_EOS);
        break;
      case '\n': case '\r':
        lexerror(ls, "unfinished string", TK_STRING);
        break;
      case '\\': {
        int c;
        save_and_next(ls);
        switch (ls->current) {
          case 'a': c = '\a'; goto read_save;
          case 'b': c = '\b'; goto read_save;
          case 'f': c = '\f'; goto read_save;
          case 'n': c = '\n'; goto read_save;
          case 'r': c = '\r'; goto read_save;
          case 't': c = '\t'; goto read_save;
          case 'v': c = '\v'; goto read_save;
          case 'x': c = readhexaesc(ls); goto read_save;
          case 'u': utf8esc_(ls); goto no_save;
          case '\n': case '\r':
            inclinenumber(ls); c = '\n'; goto only_save;
          case '\\': case '\"': case '\'':
            c = ls->current; goto read_save;
          case EOZ: goto no_save;
          case 'z': {
            ls->nbuf -= 1;
            lnext(ls);
            while (ls->current != EOZ && lisspace(ls->current)) {
              if (currIsNewline(ls)) inclinenumber(ls);
              else lnext(ls);
            }
            goto no_save;
          }
          default: {
            esccheck(ls, lisdigit(ls->current), "invalid escape sequence");
            c = readdecesc(ls);
            goto only_save;
          }
        }
      read_save:
        lnext(ls);
      only_save:
        ls->nbuf -= 1;
        save(ls, c);
      no_save:
        break;
      }
      default:
        save_and_next(ls);
    }
  }
  save_and_next(ls);
  seminfo->ts = newstring(ls, ls->buf + 1, ls->nbuf - 2);
}

static int llex(Lex *ls, SemInfo *seminfo) {
  ls->nbuf = 0;
  for (;;) {
    switch (ls->current) {
      case '\n': case '\r': {
        inclinenumber(ls);
        break;
      }
      case ' ': case '\f': case '\t': case '\v': {
        lnext(ls);
        break;
      }
      case '-': {
        lnext(ls);
        if (ls->current != '-') return '-';
        lnext(ls);
        if (ls->current == '[') {
          size_t sep = skip_sep(ls);
          ls->nbuf = 0;
          if (sep >= 2) {
            read_long_string(ls, NULL, sep);
            ls->nbuf = 0;
            break;
          }
        }
        while (!currIsNewline(ls) && ls->current != EOZ)
          lnext(ls);
        break;
      }
      case '[': {
        size_t sep = skip_sep(ls);
        if (sep >= 2) {
          read_long_string(ls, seminfo, sep);
          return TK_STRING;
        } else if (sep == 0)
          lexerror(ls, "invalid long string delimiter", TK_STRING);
        return '[';
      }
      case '=': {
        lnext(ls);
        if (check_next1(ls, '=')) return TK_EQ;
        else return '=';
      }
      case '<': {
        lnext(ls);
        if (check_next1(ls, '=')) return TK_LE;
        else if (check_next1(ls, '<')) return TK_SHL;
        else return '<';
      }
      case '>': {
        lnext(ls);
        if (check_next1(ls, '=')) return TK_GE;
        else if (check_next1(ls, '>')) return TK_SHR;
        else return '>';
      }
      case '/': {
        lnext(ls);
        if (check_next1(ls, '/')) return TK_IDIV;
        else return '/';
      }
      case '~': {
        lnext(ls);
        if (check_next1(ls, '=')) return TK_NE;
        else return '~';
      }
      case ':': {
        lnext(ls);
        if (check_next1(ls, ':')) return TK_DBCOLON;
        else return ':';
      }
      case '"': case '\'': {
        read_string(ls, ls->current, seminfo);
        return TK_STRING;
      }
      case '.': {
        save_and_next(ls);
        if (check_next1(ls, '.')) {
          if (check_next1(ls, '.'))
            return TK_DOTS;
          else return TK_CONCAT;
        } else if (!lisdigit(ls->current)) return '.';
        else return read_numeral(ls, seminfo);
      }
      case '0': case '1': case '2': case '3': case '4':
      case '5': case '6': case '7': case '8': case '9': {
        return read_numeral(ls, seminfo);
      }
      case EOZ: {
        return TK_EOS;
      }
      default: {
        if (lislalpha(ls->current)) {
          Str *ts;
          do {
            save_and_next(ls);
          } while (ls->current != EOZ && lislalnum(ls->current));
          ts = newstring(ls, ls->buf, ls->nbuf);
          seminfo->ts = ts;
          if (ts->reserved)
            return ts->reserved - 1 + FIRST_RESERVED;
          else
            return TK_NAME;
        } else {
          int c = ls->current;
          lnext(ls);
          return c;
        }
      }
    }
  }
}

void lex_next(Lex *ls) {
  ls->lastline = ls->linenumber;
  if (ls->lookahead.token != TK_EOS) {
    ls->t = ls->lookahead;
    ls->lookahead.token = TK_EOS;
  } else
    ls->t.token = llex(ls, &ls->t.seminfo);
}

int lex_lookahead(Lex *ls) {
  ls->lookahead.token = llex(ls, &ls->lookahead.seminfo);
  return ls->lookahead.token;
}
