/* parser: builds an AST with resolved variable references */
#include "lex.h"

#define MAXVARS 200
#define MAXUPVAL 255

typedef struct PBlock {
  struct PBlock *prev;
  int nactvar;
  int isloop;
} PBlock;

typedef struct PFunc {
  struct PFunc *prev;
  FuncAST *f;
  PBlock *bl;
  int firstlocal;
  int nregvars;   /* active register variables */
} PFunc;

/* ---------------- arena ---------------- */
typedef struct ArenaBlk { struct ArenaBlk *next; } ArenaBlk;

void *arena_alloc(Arena *a, size_t sz) {
  void *p;
  sz = (sz + 15) & ~(size_t)15;
  if (a->chunk == NULL || a->used + sz > a->cap) {
    size_t cap = 64 * 1024;
    ArenaBlk *b;
    if (sz + 16 > cap) cap = sz + 16;
    b = malloc(cap + 16);
    if (!b) abort();
    b->next = a->blocks;
    a->blocks = b;
    a->chunk = (char *)b + 16;
    a->cap = cap;
    a->used = 0;
  }
  p = a->chunk + a->used;
  a->used += sz;
  memset(p, 0, sz);
  return p;
}

void arena_free(Arena *a) {
  ArenaBlk *b = a->blocks;
  while (b) {
    ArenaBlk *n = b->next;
    free(b);
    b = n;
  }
  a->blocks = NULL;
  a->chunk = NULL;
  a->used = a->cap = 0;
}

/* growable pointer vector */
typedef struct PVec { void **items; int n, cap; } PVec;
static void pv_push(PVec *v, void *p) {
  if (v->n >= v->cap) {
    v->cap = v->cap ? v->cap * 2 : 8;
    v->items = realloc(v->items, sizeof(void *) * v->cap);
  }
  v->items[v->n++] = p;
}
static void **pv_finish(Lex *ls, PVec *v) {
  void **res = NULL;
  if (v->n > 0) {
    res = arena_alloc(ls->arena, sizeof(void *) * v->n);
    memcpy(res, v->items, sizeof(void *) * v->n);
  }
  free(v->items);
  v->items = NULL;
  return res;
}

#define NEW(ls, T) ((T *)arena_alloc((ls)->arena, sizeof(T)))

static Expr *newexpr(Lex *ls, int k, int line) {
  Expr *e = NEW(ls, Expr);
  e->k = (uint8_t)k;
  e->line = line;
  return e;
}

static Stat *newstat(Lex *ls, int k, int line) {
  Stat *s = NEW(ls, Stat);
  s->k = (uint8_t)k;
  s->line = line;
  return s;
}

/* ---------------- error helpers ---------------- */

static void error_expected(Lex *ls, int token) __attribute__((noreturn));
static void error_expected(Lex *ls, int token) {
  lex_syntaxerror(ls, pushfstring(ls->L, "%s expected", lex_token2str(ls, token)));
}

static void errorlimit(Lex *ls, PFunc *fs, int limit, const char *what) __attribute__((noreturn));
static void errorlimit(Lex *ls, PFunc *fs, int limit, const char *what) {
  int line = fs->f->line;
  const char *where = (line == 0) ? "main function" : pushfstring(ls->L, "function at line %d", line);
  const char *msg = pushfstring(ls->L, "too many %s (limit is %d) in %s", what, limit, where);
  lex_syntaxerror(ls, msg);
}

static int testnext(Lex *ls, int c) {
  if (ls->t.token == c) {
    lex_next(ls);
    return 1;
  }
  return 0;
}

static void check(Lex *ls, int c) {
  if (ls->t.token != c) error_expected(ls, c);
}

static void checknext(Lex *ls, int c) {
  check(ls, c);
  lex_next(ls);
}

#define check_condition(ls, c, msg) { if (!(c)) lex_syntaxerror(ls, msg); }

static void check_match(Lex *ls, int what, int who, int where) {
  if (ls->t.token != what) {
    if (where == ls->linenumber)
      error_expected(ls, what);
    else {
      lex_syntaxerror(ls, pushfstring(ls->L, "%s expected (to close %s at line %d)",
                      lex_token2str(ls, what), lex_token2str(ls, who), where));
    }
  }
  lex_next(ls);
}

static Str *str_checkname(Lex *ls) {
  Str *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  lex_next(ls);
  return ts;
}

static void enterlevel(Lex *ls) {
  if (++ls->level + ls->L->nCcalls >= MAXCCALLS) {
    pushfstring(ls->L, "C stack overflow");
    d_throw(ls->L, TS_ERRSYNTAX);
  }
}
#define leavelevel(ls) ((ls)->level--)

/* ---------------- variables ---------------- */

static VarDesc *new_vardesc(Lex *ls, Str *name, int kind) {
  VarDesc *vd = NEW(ls, VarDesc);
  vd->name = name;
  vd->kind = (uint8_t)kind;
  vd->isglobal = (kind == VD_GLOBAL || kind == VD_GCONST);
  vd->reg = -1;
  return vd;
}

static void push_actvar(Lex *ls, VarDesc *vd) {
  if (ls->nactvar >= ls->sizeactvar) {
    ls->sizeactvar = ls->sizeactvar ? ls->sizeactvar * 2 : 64;
    ls->actvar = realloc(ls->actvar, sizeof(VarDesc *) * ls->sizeactvar);
  }
  ls->actvar[ls->nactvar++] = vd;
  if (!vd->isglobal) {
    PFunc *fs = ls->fs;
    fs->nregvars++;
    if (fs->nregvars > MAXVARS) errorlimit(ls, fs, MAXVARS, "local variables");
  }
}

static void removevars(Lex *ls, int tolevel) {
  PFunc *fs = ls->fs;
  while (ls->nactvar > tolevel) {
    VarDesc *vd = ls->actvar[--ls->nactvar];
    if (!vd->isglobal) fs->nregvars--;
  }
}

static int searchupvalue(PFunc *fs, Str *name) {
  int i;
  FuncAST *f = fs->f;
  for (i = 0; i < f->nups; i++) {
    if (f->ups[i].name == name) return i;
  }
  return -1;
}

static int newupvalue(Lex *ls, PFunc *fs, Str *name, int instack, VarDesc *pvar, int pidx, int kind) {
  FuncAST *f = fs->f;
  UpvalAST *up;
  if (f->nups >= MAXUPVAL) errorlimit(ls, fs, MAXUPVAL, "upvalues");
  if (f->nups >= f->sizeups) {
    int ns = f->sizeups ? f->sizeups * 2 : 8;
    UpvalAST *nu = arena_alloc(ls->arena, sizeof(UpvalAST) * ns);
    if (f->nups) memcpy(nu, f->ups, sizeof(UpvalAST) * f->nups);
    f->ups = nu;
    f->sizeups = ns;
  }
  up = &f->ups[f->nups];
  up->name = name;
  up->instack = (uint8_t)instack;
  up->pvar = pvar;
  up->pidx = pidx;
  up->kind = (uint8_t)kind;
  return f->nups++;
}

/* resolution results */
#define R_NONE 0
#define R_LOCAL 1
#define R_UPVAL 2
#define R_GLOBAL 3

typedef struct Resolved {
  int kind;
  VarDesc *var;
  int idx;
  int vkind;  /* VD_* */
} Resolved;

static void singlevaraux(Lex *ls, PFunc *fs, Str *n, Resolved *r, int base) {
  int i;
  for (i = ls->nactvar - 1; i >= fs->firstlocal; i--) {
    VarDesc *vd = ls->actvar[i];
    if (vd->name == n) {
      if (vd->isglobal) {
        r->kind = R_GLOBAL;
        r->vkind = vd->kind;
      } else {
        r->kind = R_LOCAL;
        r->var = vd;
        r->vkind = vd->kind;
        if (!base) vd->captured = 1;
      }
      return;
    }
  }
  {
    int idx = searchupvalue(fs, n);
    if (idx >= 0) {
      r->kind = R_UPVAL;
      r->idx = idx;
      r->vkind = fs->f->ups[idx].kind;
      return;
    }
  }
  if (fs->prev == NULL) {
    r->kind = R_NONE;
    return;
  }
  singlevaraux(ls, fs->prev, n, r, 0);
  if (r->kind == R_LOCAL) {
    r->idx = newupvalue(ls, fs, n, 1, r->var, 0, r->vkind);
    r->kind = R_UPVAL;
  } else if (r->kind == R_UPVAL) {
    r->idx = newupvalue(ls, fs, n, 0, NULL, r->idx, r->vkind);
  }
}

static Expr *resolved2expr(Lex *ls, Resolved *r, Str *name, int line) {
  Expr *e;
  if (r->kind == R_LOCAL) {
    e = newexpr(ls, E_LOCAL, line);
    e->u.var = r->var;
  } else {
    e = newexpr(ls, E_UPVAL, line);
    e->u.up.idx = r->idx;
    e->u.up.name = name;
  }
  return e;
}

static Expr *singlevar_name(Lex *ls, Str *varname, int line) {
  Resolved r;
  memset(&r, 0, sizeof(r));
  singlevaraux(ls, ls->fs, varname, &r, 1);
  if (r.kind == R_LOCAL || r.kind == R_UPVAL) {
    Expr *e = resolved2expr(ls, &r, varname, line);
    e->op = (uint8_t)r.vkind;  /* remember kind for const checks */
    return e;
  } else {
    Expr *e;
    Resolved er;
    int gkind = VD_GLOBAL;
    if (r.kind == R_NONE) {
      /* look for collective declaration */
      int i, found = 0, anyexplicit = 0;
      for (i = ls->nactvar - 1; i >= 0; i--) {
        VarDesc *vd = ls->actvar[i];
        if (vd->isglobal) {
          if (vd->name == NULL) {
            found = 1;
            gkind = vd->kind;
            break;
          }
          anyexplicit = 1;
        }
      }
      if (!found && anyexplicit) {
        lex_semerror(ls, pushfstring(ls->L, "variable '%s' not declared", getstr(varname)));
      }
    } else
      gkind = r.vkind;
    memset(&er, 0, sizeof(er));
    singlevaraux(ls, ls->fs, ls->envn, &er, 1);
    e = newexpr(ls, E_GLOBAL, line);
    if (er.kind == R_LOCAL || er.kind == R_UPVAL)
      e->u.glb.env = resolved2expr(ls, &er, ls->envn, line);
    else {
      /* _ENV not found as variable: should not happen */
      e->u.glb.env = newexpr(ls, E_NIL, line);
    }
    e->u.glb.name = varname;
    e->u.glb.isconst = (gkind == VD_GCONST);
    return e;
  }
}

static void check_readonly(Lex *ls, Expr *e) {
  Str *varname = NULL;
  switch (e->k) {
    case E_LOCAL:
      if (e->u.var->kind != VD_REG) varname = e->u.var->name;
      break;
    case E_UPVAL:
      if (e->op != VD_REG) varname = e->u.up.name;
      break;
    case E_GLOBAL:
      if (e->u.glb.isconst) varname = e->u.glb.name;
      break;
    default:
      return;
  }
  if (varname)
    lex_semerror(ls, pushfstring(ls->L, "attempt to assign to const variable '%s'", getstr(varname)));
}

/* ---------------- blocks ---------------- */

static void enterblock(Lex *ls, PBlock *bl, int isloop) {
  PFunc *fs = ls->fs;
  bl->prev = fs->bl;
  bl->nactvar = ls->nactvar;
  bl->isloop = isloop;
  fs->bl = bl;
}

static void leaveblock(Lex *ls) {
  PFunc *fs = ls->fs;
  PBlock *bl = fs->bl;
  removevars(ls, bl->nactvar);
  fs->bl = bl->prev;
}

static int block_follow(Lex *ls, int withuntil) {
  switch (ls->t.token) {
    case TK_ELSE: case TK_ELSEIF:
    case TK_END: case TK_EOS:
      return 1;
    case TK_UNTIL: return withuntil;
    default: return 0;
  }
}

static Stat *statement(Lex *ls);
static Expr *expr(Lex *ls);
static Expr *subexpr(Lex *ls, int limit);

static void addstat(Block *b, Stat *s) {
  if (s == NULL) return;
  if (b->last) b->last->next = s;
  else b->first = s;
  b->last = s;
}

static void statlist(Lex *ls, Block *b) {
  while (!block_follow(ls, 1)) {
    if (ls->t.token == TK_RETURN) {
      addstat(b, statement(ls));
      return;
    }
    addstat(b, statement(ls));
  }
}

static Block *block(Lex *ls) {
  PBlock bl;
  Block *b = NEW(ls, Block);
  enterblock(ls, &bl, 0);
  statlist(ls, b);
  leaveblock(ls);
  return b;
}

/* ---------------- functions ---------------- */

static void open_func(Lex *ls, PFunc *fs, FuncAST *f, PBlock *bl) {
  fs->prev = ls->fs;
  fs->f = f;
  fs->firstlocal = ls->nactvar;
  fs->nregvars = 0;
  fs->bl = NULL;
  ls->fs = fs;
  enterblock(ls, bl, 0);
}

static void close_func(Lex *ls) {
  PFunc *fs = ls->fs;
  leaveblock(ls);
  ls->fs = fs->prev;
}

static void parlist(Lex *ls, FuncAST *f, PVec *params) {
  int isvararg = 0;
  if (ls->t.token != ')') {
    do {
      switch (ls->t.token) {
        case TK_NAME: {
          VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_REG);
          pv_push(params, vd);
          push_actvar(ls, vd);
          break;
        }
        case TK_DOTS: {
          lex_next(ls);
          isvararg = 1;
          if (ls->t.token == TK_NAME) {
            VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_CONST);
            f->vartab = vd;
            isvararg = 2;
          }
          break;
        }
        default:
          lex_syntaxerror(ls, "<name> or '...' expected");
      }
    } while (!isvararg && testnext(ls, ','));
  }
  f->is_vararg = isvararg;
}

static FuncAST *body(Lex *ls, int ismethod, int line) {
  PFunc nfs;
  PBlock bl;
  PVec params = {0};
  FuncAST *f = NEW(ls, FuncAST);
  f->line = line;
  f->ismethod = ismethod;
  open_func(ls, &nfs, f, &bl);
  checknext(ls, '(');
  if (ismethod) {
    VarDesc *vd = new_vardesc(ls, str_newc(ls->L, "self"), VD_REG);
    pv_push(&params, vd);
    push_actvar(ls, vd);
  }
  parlist(ls, f, &params);
  f->nparams = params.n;
  f->params = (VarDesc **)pv_finish(ls, &params);
  if (f->vartab) push_actvar(ls, f->vartab);
  checknext(ls, ')');
  f->body = NEW(ls, Block);
  statlist(ls, f->body);
  f->lastline = ls->linenumber;
  check_match(ls, TK_END, TK_FUNCTION, line);
  f->endline = ls->linenumber;
  close_func(ls);
  return f;
}

/* ---------------- expressions ---------------- */

static int explist(Lex *ls, PVec *v) {
  int n = 1;
  pv_push(v, expr(ls));
  while (testnext(ls, ',')) {
    pv_push(v, expr(ls));
    n++;
  }
  return n;
}

static Expr *funcargs(Lex *ls, Expr *f, Str *mname, int line) {
  PVec args = {0};
  Expr *e;
  switch (ls->t.token) {
    case '(': {
      lex_next(ls);
      if (ls->t.token != ')')
        explist(ls, &args);
      check_match(ls, ')', '(', line);
      break;
    }
    case '{': {
      extern Expr *constructor_(Lex *ls);
      pv_push(&args, constructor_(ls));
      break;
    }
    case TK_STRING: {
      Expr *s = newexpr(ls, E_STR, ls->linenumber);
      s->u.sval = ls->t.seminfo.ts;
      pv_push(&args, s);
      lex_next(ls);
      break;
    }
    default:
      lex_syntaxerror(ls, "function arguments expected");
  }
  e = newexpr(ls, mname ? E_METHCALL : E_CALL, line);
  e->u.call.fn = f;
  e->u.call.mname = mname;
  e->u.call.nargs = args.n;
  e->u.call.args = (Expr **)pv_finish(ls, &args);
  return e;
}

static Expr *primaryexp(Lex *ls) {
  switch (ls->t.token) {
    case '(': {
      int line = ls->linenumber;
      Expr *e, *inner;
      lex_next(ls);
      inner = expr(ls);
      check_match(ls, ')', '(', line);
      e = newexpr(ls, E_PAREN, line);
      e->u.bin.a = inner;
      return e;
    }
    case TK_NAME: {
      int line = ls->linenumber;
      Str *name = str_checkname(ls);
      return singlevar_name(ls, name, line);
    }
    default:
      lex_syntaxerror(ls, "unexpected symbol");
  }
}

static Expr *suffixedexp(Lex *ls) {
  int line = ls->linenumber;
  Expr *e = primaryexp(ls);
  for (;;) {
    switch (ls->t.token) {
      case '.': {
        Expr *k, *ix;
        lex_next(ls);
        k = newexpr(ls, E_STR, ls->linenumber);
        k->u.sval = str_checkname(ls);
        ix = newexpr(ls, E_INDEX, ls->lastline);
        ix->u.idx.obj = e;
        ix->u.idx.key = k;
        e = ix;
        break;
      }
      case '[': {
        Expr *k, *ix;
        lex_next(ls);
        k = expr(ls);
        checknext(ls, ']');
        ix = newexpr(ls, E_INDEX, ls->lastline);
        ix->u.idx.obj = e;
        ix->u.idx.key = k;
        e = ix;
        break;
      }
      case ':': {
        Str *mname;
        lex_next(ls);
        mname = str_checkname(ls);
        e = funcargs(ls, e, mname, line);
        break;
      }
      case '(': case TK_STRING: case '{': {
        e = funcargs(ls, e, NULL, line);
        break;
      }
      default:
        return e;
    }
  }
}

Expr *constructor_(Lex *ls) {
  int line = ls->linenumber;
  PVec fields = {0};
  int narr = 0, nhash = 0, i;
  Expr *t = newexpr(ls, E_TABLE, line);
  TField *tf;
  checknext(ls, '{');
  do {
    TField *f;
    if (ls->t.token == '}') break;
    f = NEW(ls, TField);
    f->line = ls->linenumber;
    switch (ls->t.token) {
      case TK_NAME: {
        if (lex_lookahead(ls) != '=') {
          f->val = expr(ls);
          narr++;
        } else {
          Expr *k = newexpr(ls, E_STR, ls->linenumber);
          k->u.sval = str_checkname(ls);
          checknext(ls, '=');
          f->key = k;
          f->val = expr(ls);
          nhash++;
        }
        break;
      }
      case '[': {
        lex_next(ls);
        f->key = expr(ls);
        checknext(ls, ']');
        checknext(ls, '=');
        f->val = expr(ls);
        nhash++;
        break;
      }
      default: {
        f->val = expr(ls);
        narr++;
        break;
      }
    }
    pv_push(&fields, f);
  } while (testnext(ls, ',') || testnext(ls, ';'));
  check_match(ls, '}', '{', line);
  t->u.tab.n = fields.n;
  tf = fields.n ? arena_alloc(ls->arena, sizeof(TField) * fields.n) : NULL;
  for (i = 0; i < fields.n; i++) tf[i] = *(TField *)fields.items[i];
  free(fields.items);
  t->u.tab.f = tf;
  t->u.tab.narr = narr;
  t->u.tab.nhash = nhash;
  return t;
}

static Expr *simpleexp(Lex *ls) {
  Expr *e;
  int line = ls->linenumber;
  switch (ls->t.token) {
    case TK_FLT:
      e = newexpr(ls, E_FLT, line);
      e->u.nval = ls->t.seminfo.r;
      break;
    case TK_INT:
      e = newexpr(ls, E_INT, line);
      e->u.ival = ls->t.seminfo.i;
      break;
    case TK_STRING:
      e = newexpr(ls, E_STR, line);
      e->u.sval = ls->t.seminfo.ts;
      break;
    case TK_NIL:
      e = newexpr(ls, E_NIL, line);
      break;
    case TK_TRUE:
      e = newexpr(ls, E_TRUE, line);
      break;
    case TK_FALSE:
      e = newexpr(ls, E_FALSE, line);
      break;
    case TK_DOTS: {
      check_condition(ls, ls->fs->f->is_vararg, "cannot use '...' outside a vararg function");
      e = newexpr(ls, E_VARARG, line);
      break;
    }
    case '{':
      return constructor_(ls);
    case TK_FUNCTION: {
      lex_next(ls);
      e = newexpr(ls, E_FUNC, line);
      e->u.func = body(ls, 0, line);
      return e;
    }
    default:
      return suffixedexp(ls);
  }
  lex_next(ls);
  return e;
}

static int getunopr(int op) {
  switch (op) {
    case TK_NOT: return OPR_NOT;
    case '-': return OPR_MINUS;
    case '~': return OPR_BNOT;
    case '#': return OPR_LEN;
    default: return OPR_NOUNOPR;
  }
}

static int getbinopr(int op) {
  switch (op) {
    case '+': return OPR_ADD;
    case '-': return OPR_SUB;
    case '*': return OPR_MUL;
    case '%': return OPR_MOD;
    case '^': return OPR_POW;
    case '/': return OPR_DIV;
    case TK_IDIV: return OPR_IDIV;
    case '&': return OPR_BAND;
    case '|': return OPR_BOR;
    case '~': return OPR_BXOR;
    case TK_SHL: return OPR_SHL;
    case TK_SHR: return OPR_SHR;
    case TK_CONCAT: return OPR_CONCAT;
    case TK_NE: return OPR_NE;
    case TK_EQ: return OPR_EQ;
    case '<': return OPR_LT;
    case TK_LE: return OPR_LE;
    case '>': return OPR_GT;
    case TK_GE: return OPR_GE;
    case TK_AND: return OPR_AND;
    case TK_OR: return OPR_OR;
    default: return OPR_NOBINOPR;
  }
}

static const struct { uint8_t left, right; } priority[] = {
  {10, 10}, {10, 10},
  {11, 11}, {11, 11},
  {14, 13},
  {11, 11}, {11, 11},
  {6, 6}, {4, 4}, {5, 5},
  {7, 7}, {7, 7},
  {9, 8},
  {3, 3}, {3, 3}, {3, 3},
  {3, 3}, {3, 3}, {3, 3},
  {2, 2}, {1, 1}
};

#define UNARY_PRIORITY 12

static Expr *subexpr(Lex *ls, int limit) {
  Expr *e;
  int op;
  int uop;
  enterlevel(ls);
  uop = getunopr(ls->t.token);
  if (uop != OPR_NOUNOPR) {
    int line = ls->linenumber;
    Expr *operand;
    lex_next(ls);
    operand = subexpr(ls, UNARY_PRIORITY);
    e = newexpr(ls, E_UN, line);
    e->op = (uint8_t)uop;
    e->u.bin.a = operand;
  } else
    e = simpleexp(ls);
  op = getbinopr(ls->t.token);
  while (op != OPR_NOBINOPR && priority[op].left > limit) {
    Expr *e2, *ne;
    int nextop;
    int line = ls->linenumber;
    lex_next(ls);
    e2 = subexpr(ls, priority[op].right);
    nextop = getbinopr(ls->t.token);
    if (op == OPR_AND) ne = newexpr(ls, E_AND, line);
    else if (op == OPR_OR) ne = newexpr(ls, E_OR, line);
    else {
      ne = newexpr(ls, E_BIN, line);
      ne->op = (uint8_t)op;
    }
    ne->u.bin.a = e;
    ne->u.bin.b = e2;
    e = ne;
    op = nextop;
  }
  leavelevel(ls);
  return e;
}

static Expr *expr(Lex *ls) {
  return subexpr(ls, 0);
}

/* ---------------- statements ---------------- */

static int isvarexp(Expr *e) {
  return e->k == E_LOCAL || e->k == E_UPVAL || e->k == E_GLOBAL || e->k == E_INDEX;
}

static Stat *exprstat(Lex *ls) {
  int line = ls->linenumber;
  Expr *v = suffixedexp(ls);
  if (ls->t.token == '=' || ls->t.token == ',') {
    PVec targets = {0}, exprs = {0};
    Stat *s = newstat(ls, S_ASSIGN, line);
    check_condition(ls, isvarexp(v), "syntax error");
    check_readonly(ls, v);
    pv_push(&targets, v);
    while (testnext(ls, ',')) {
      Expr *t = suffixedexp(ls);
      check_condition(ls, isvarexp(t), "syntax error");
      check_readonly(ls, t);
      pv_push(&targets, t);
    }
    checknext(ls, '=');
    s->line2 = ls->linenumber;
    explist(ls, &exprs);
    s->u.assign.nt = targets.n;
    s->u.assign.targets = (Expr **)pv_finish(ls, &targets);
    s->u.assign.ne = exprs.n;
    s->u.assign.exprs = (Expr **)pv_finish(ls, &exprs);
    return s;
  } else {
    Stat *s;
    check_condition(ls, v->k == E_CALL || v->k == E_METHCALL, "syntax error");
    s = newstat(ls, S_CALL, line);
    s->u.call = v;
    return s;
  }
}

static Stat *retstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_RETURN, line);
  PVec exprs = {0};
  if (!(block_follow(ls, 1) || ls->t.token == ';'))
    explist(ls, &exprs);
  testnext(ls, ';');
  s->u.ret.n = exprs.n;
  s->u.ret.exprs = (Expr **)pv_finish(ls, &exprs);
  return s;
}

static Expr *cond(Lex *ls) {
  Expr *e = expr(ls);
  if (e->k == E_NIL) e->k = E_FALSE;
  return e;
}

static Stat *whilestat(Lex *ls, int line) {
  PBlock bl;
  Stat *s = newstat(ls, S_WHILE, line);
  lex_next(ls);
  s->u.loop.cond = cond(ls);
  enterblock(ls, &bl, 1);
  checknext(ls, TK_DO);
  s->u.loop.body = block(ls);
  check_match(ls, TK_END, TK_WHILE, line);
  leaveblock(ls);
  return s;
}

static Stat *repeatstat(Lex *ls, int line) {
  PBlock bl1, bl2;
  Stat *s = newstat(ls, S_REPEAT, line);
  Block *b = NEW(ls, Block);
  enterblock(ls, &bl1, 1);
  enterblock(ls, &bl2, 0);
  lex_next(ls);
  statlist(ls, b);
  check_match(ls, TK_UNTIL, TK_REPEAT, line);
  s->u.loop.cond = cond(ls);
  s->u.loop.body = b;
  leaveblock(ls);
  leaveblock(ls);
  return s;
}

static Stat *fornum(Lex *ls, Str *varname, int line) {
  PBlock bl;
  Stat *s = newstat(ls, S_NUMFOR, line);
  VarDesc *vd;
  int i;
  for (i = 0; i < 3; i++) {
    s->u.numfor.hidden[i] = new_vardesc(ls, str_newc(ls->L, "(for state)"), VD_REG);
    push_actvar(ls, s->u.numfor.hidden[i]);
  }
  vd = new_vardesc(ls, varname, VD_CONST);
  s->u.numfor.var = vd;
  checknext(ls, '=');
  s->u.numfor.start = expr(ls);
  checknext(ls, ',');
  s->u.numfor.limit = expr(ls);
  if (testnext(ls, ','))
    s->u.numfor.step = expr(ls);
  checknext(ls, TK_DO);
  s->line2 = ls->lastline;
  enterblock(ls, &bl, 0);
  push_actvar(ls, vd);
  s->u.numfor.body = block(ls);
  leaveblock(ls);
  return s;
}

static Stat *forlist(Lex *ls, Str *indexname, int line) {
  PBlock bl;
  Stat *s = newstat(ls, S_GENFOR, line);
  PVec vars = {0}, exprs = {0};
  int i;
  for (i = 0; i < 4; i++) {
    s->u.genfor.hidden[i] = new_vardesc(ls, str_newc(ls->L, "(for state)"), VD_REG);
    push_actvar(ls, s->u.genfor.hidden[i]);
  }
  pv_push(&vars, new_vardesc(ls, indexname, VD_CONST));
  while (testnext(ls, ','))
    pv_push(&vars, new_vardesc(ls, str_checkname(ls), VD_REG));
  checknext(ls, TK_IN);
  explist(ls, &exprs);
  checknext(ls, TK_DO);
  s->line2 = ls->lastline;
  s->u.genfor.nvars = vars.n;
  s->u.genfor.vars = (VarDesc **)pv_finish(ls, &vars);
  s->u.genfor.nexprs = exprs.n;
  s->u.genfor.exprs = (Expr **)pv_finish(ls, &exprs);
  enterblock(ls, &bl, 0);
  for (i = 0; i < s->u.genfor.nvars; i++) push_actvar(ls, s->u.genfor.vars[i]);
  s->u.genfor.body = block(ls);
  leaveblock(ls);
  return s;
}

static Stat *forstat(Lex *ls, int line) {
  PBlock bl;
  Str *varname;
  Stat *s;
  enterblock(ls, &bl, 1);
  lex_next(ls);
  varname = str_checkname(ls);
  switch (ls->t.token) {
    case '=': s = fornum(ls, varname, line); break;
    case ',': case TK_IN: s = forlist(ls, varname, line); break;
    default: lex_syntaxerror(ls, "'=' or 'in' expected");
  }
  check_match(ls, TK_END, TK_FOR, line);
  leaveblock(ls);
  return s;
}

static Stat *ifstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_IF, line);
  PVec conds = {0}, blocks = {0};
  /* IF cond THEN block {ELSEIF cond THEN block} [ELSE block] END */
  do {
    lex_next(ls);  /* skip IF or ELSEIF */
    pv_push(&conds, cond(ls));
    checknext(ls, TK_THEN);
    pv_push(&blocks, block(ls));
  } while (ls->t.token == TK_ELSEIF);
  if (testnext(ls, TK_ELSE))
    s->u.ifs.elseb = block(ls);
  check_match(ls, TK_END, TK_IF, line);
  s->u.ifs.n = conds.n;
  s->u.ifs.conds = (Expr **)pv_finish(ls, &conds);
  s->u.ifs.blocks = (Block **)pv_finish(ls, &blocks);
  return s;
}

static int getattrib(Lex *ls, int def) {
  if (testnext(ls, '<')) {
    Str *ts = str_checkname(ls);
    const char *attr = getstr(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0)
      return VD_CONST;
    else if (strcmp(attr, "close") == 0)
      return VD_CLOSE;
    else
      lex_semerror(ls, pushfstring(ls->L, "unknown attribute '%s'", attr));
  }
  return def;
}

static Stat *localfunc(Lex *ls, int line) {
  Stat *s = newstat(ls, S_LOCALFUNC, line);
  VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_REG);
  push_actvar(ls, vd);
  s->u.localfunc.var = vd;
  s->u.localfunc.f = body(ls, 0, line);
  return s;
}

static Stat *localstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_LOCAL, line);
  PVec vars = {0}, exprs = {0};
  int i, nclose = 0;
  int defkind = getattrib(ls, VD_REG);
  do {
    VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_REG);
    int kind = getattrib(ls, defkind);
    vd->kind = (uint8_t)kind;
    if (kind == VD_CLOSE) {
      if (nclose++ > 0)
        lex_semerror(ls, "multiple to-be-closed variables in local list");
    }
    pv_push(&vars, vd);
  } while (testnext(ls, ','));
  if (testnext(ls, '='))
    explist(ls, &exprs);
  s->u.local.nvars = vars.n;
  s->u.local.vars = (VarDesc **)pv_finish(ls, &vars);
  s->u.local.nexprs = exprs.n;
  s->u.local.exprs = (Expr **)pv_finish(ls, &exprs);
  for (i = 0; i < s->u.local.nvars; i++) push_actvar(ls, s->u.local.vars[i]);
  return s;
}

static int getglobalattrib(Lex *ls, int def) {
  int k = getattrib(ls, def == VD_GCONST ? VD_CONST : VD_REG);
  if (k == VD_CLOSE)
    lex_semerror(ls, "global variables cannot be to-be-closed");
  return k == VD_CONST ? VD_GCONST : VD_GLOBAL;
}

static Stat *globalstat(Lex *ls, int line) {
  /* 'global' already skipped */
  int defkind = getglobalattrib(ls, VD_GLOBAL);
  if (testnext(ls, '*')) {
    VarDesc *vd = new_vardesc(ls, NULL, defkind);
    push_actvar(ls, vd);
    return NULL;
  } else {
    PVec names = {0}, exprs = {0};
    Stat *s = NULL;
    int i;
    do {
      Str *name = str_checkname(ls);
      int kind = getglobalattrib(ls, defkind);
      VarDesc *vd = new_vardesc(ls, name, kind);
      pv_push(&names, vd);
    } while (testnext(ls, ','));
    for (i = 0; i < names.n; i++) push_actvar(ls, (VarDesc *)names.items[i]);
    if (testnext(ls, '=')) {
      PVec targets = {0};
      s = newstat(ls, S_GLOBAL, line);
      for (i = 0; i < names.n; i++) {
        VarDesc *vd = (VarDesc *)names.items[i];
        Expr *t = singlevar_name(ls, vd->name, line);
        pv_push(&targets, t);
      }
      explist(ls, &exprs);
      s->u.global.nt = targets.n;
      s->u.global.targets = (Expr **)pv_finish(ls, &targets);
      s->u.global.ne = exprs.n;
      s->u.global.exprs = (Expr **)pv_finish(ls, &exprs);
    }
    free(names.items);
    return s;
  }
}

static Stat *globalfunc(Lex *ls, int line) {
  /* 'global function' already skipped */
  Stat *s = newstat(ls, S_GLOBALFUNC, line);
  Str *name = str_checkname(ls);
  VarDesc *vd = new_vardesc(ls, name, VD_GLOBAL);
  push_actvar(ls, vd);
  s->u.globalfunc.target = singlevar_name(ls, name, line);
  s->u.globalfunc.f = body(ls, 0, line);
  return s;
}

static Stat *funcstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_ASSIGN, line);
  Expr *v, *fe;
  int ismethod = 0;
  int nline;
  lex_next(ls);  /* skip FUNCTION */
  nline = ls->linenumber;
  v = singlevar_name(ls, str_checkname(ls), nline);
  while (ls->t.token == '.') {
    Expr *k, *ix;
    lex_next(ls);
    k = newexpr(ls, E_STR, ls->linenumber);
    k->u.sval = str_checkname(ls);
    ix = newexpr(ls, E_INDEX, ls->lastline);
    ix->u.idx.obj = v;
    ix->u.idx.key = k;
    v = ix;
  }
  if (ls->t.token == ':') {
    Expr *k, *ix;
    lex_next(ls);
    k = newexpr(ls, E_STR, ls->linenumber);
    k->u.sval = str_checkname(ls);
    ix = newexpr(ls, E_INDEX, ls->lastline);
    ix->u.idx.obj = v;
    ix->u.idx.key = k;
    v = ix;
    ismethod = 1;
  }
  check_readonly(ls, v);
  fe = newexpr(ls, E_FUNC, line);
  fe->u.func = body(ls, ismethod, line);
  s->u.assign.nt = 1;
  s->u.assign.targets = arena_alloc(ls->arena, sizeof(Expr *));
  s->u.assign.targets[0] = v;
  s->u.assign.ne = 1;
  s->u.assign.exprs = arena_alloc(ls->arena, sizeof(Expr *));
  s->u.assign.exprs[0] = fe;
  s->line2 = line;
  return s;
}

static Stat *statement(Lex *ls) {
  int line = ls->linenumber;
  Stat *s = NULL;
  enterlevel(ls);
  switch (ls->t.token) {
    case ';':
      lex_next(ls);
      break;
    case TK_IF:
      s = ifstat(ls, line);
      break;
    case TK_WHILE:
      s = whilestat(ls, line);
      break;
    case TK_DO: {
      lex_next(ls);
      s = newstat(ls, S_DO, line);
      s->u.blk.body = block(ls);
      check_match(ls, TK_END, TK_DO, line);
      break;
    }
    case TK_FOR:
      s = forstat(ls, line);
      break;
    case TK_REPEAT:
      s = repeatstat(ls, line);
      break;
    case TK_FUNCTION:
      s = funcstat(ls, line);
      break;
    case TK_LOCAL:
      lex_next(ls);
      if (testnext(ls, TK_FUNCTION))
        s = localfunc(ls, line);
      else
        s = localstat(ls, line);
      break;
    case TK_DBCOLON: {
      Str *name;
      lex_next(ls);
      name = str_checkname(ls);
      checknext(ls, TK_DBCOLON);
      s = newstat(ls, S_LABEL, line);
      s->u.label.name = name;
      break;
    }
    case TK_RETURN:
      lex_next(ls);
      s = retstat(ls, line);
      break;
    case TK_BREAK: {
      PBlock *bl = ls->fs->bl;
      while (bl && !bl->isloop) bl = bl->prev;
      if (bl == NULL)
        lex_syntaxerror(ls, "break outside loop");
      lex_next(ls);
      s = newstat(ls, S_BREAK, line);
      break;
    }
    case TK_GOTO: {
      lex_next(ls);
      s = newstat(ls, S_GOTO, line);
      s->u.label.name = str_checkname(ls);
      break;
    }
    case TK_NAME: {
      if (strcmp(getstr(ls->t.seminfo.ts), "global") == 0) {
        int la = lex_lookahead(ls);
        if (la == TK_NAME || la == '<' || la == '*') {
          lex_next(ls);
          s = globalstat(ls, line);
          break;
        } else if (la == TK_FUNCTION) {
          lex_next(ls);
          lex_next(ls);
          s = globalfunc(ls, line);
          break;
        }
      }
      s = exprstat(ls);
      break;
    }
    default:
      s = exprstat(ls);
      break;
  }
  leavelevel(ls);
  return s;
}

/* ---------------- main ---------------- */

typedef struct ParseCtx {
  Lex ls;
  Arena arena;
} ParseCtx;

static FuncAST *mainfunc(Lex *ls) {
  PFunc fs;
  PBlock bl;
  FuncAST *f = NEW(ls, FuncAST);
  f->line = 0;
  f->is_vararg = 1;
  open_func(ls, &fs, f, &bl);
  newupvalue(ls, &fs, ls->envn, 1, NULL, 0, VD_REG);
  lex_next(ls);
  f->body = NEW(ls, Block);
  statlist(ls, f->body);
  check(ls, TK_EOS);
  f->lastline = ls->linenumber;
  f->endline = ls->linenumber;
  close_func(ls);
  return f;
}

static ParseCtx *curctx = NULL;

LClosure *parse_chunk(State *L, const char *buff, size_t size, const char *name) {
  ParseCtx ctx;
  ParseCtx *prevctx = curctx;
  LongJmp lj;
  LClosure *cl;
  Proto *p;
  Str *source = str_newc(L, name);
  memset(&ctx, 0, sizeof(ctx));
  ctx.ls.arena = &ctx.arena;
  /* protect to free resources on error */
  lj.prev = L->errjmp;
  lj.status = TS_OK;
  L->errjmp = &lj;
  curctx = &ctx;
  if (setjmp(lj.b) == 0) {
    FuncAST *f;
    lex_setinput(L, &ctx.ls, buff, size, source);
    f = mainfunc(&ctx.ls);
    p = codegen_main(L, f, source, &ctx.arena);
  }
  L->errjmp = lj.prev;
  curctx = prevctx;
  free(ctx.ls.buf);
  free(ctx.ls.actvar);
  arena_free(&ctx.arena);
  if (lj.status != TS_OK)
    d_throw(L, lj.status);
  cl = lcl_new(L, p->sizeup);
  cl->p = p;
  {
    int i;
    for (i = 0; i < p->sizeup; i++) cl->up[i] = NULL;
  }
  return cl;
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > parse.c <<'EOF'
/* parser: builds an AST with resolved variable references */
#include "lex.h"

#define MAXVARS 200
#define MAXUPVAL 255

typedef struct PBlock {
  struct PBlock *prev;
  int nactvar;
  int isloop;
} PBlock;

typedef struct PFunc {
  struct PFunc *prev;
  FuncAST *f;
  PBlock *bl;
  int firstlocal;
  int nregvars;   /* active register variables */
} PFunc;

/* ---------------- arena ---------------- */
typedef struct ArenaBlk { struct ArenaBlk *next; } ArenaBlk;

void *arena_alloc(Arena *a, size_t sz) {
  void *p;
  sz = (sz + 15) & ~(size_t)15;
  if (a->chunk == NULL || a->used + sz > a->cap) {
    size_t cap = 64 * 1024;
    ArenaBlk *b;
    if (sz + 16 > cap) cap = sz + 16;
    b = malloc(cap + 16);
    if (!b) abort();
    b->next = a->blocks;
    a->blocks = b;
    a->chunk = (char *)b + 16;
    a->cap = cap;
    a->used = 0;
  }
  p = a->chunk + a->used;
  a->used += sz;
  memset(p, 0, sz);
  return p;
}

void arena_free(Arena *a) {
  ArenaBlk *b = a->blocks;
  while (b) {
    ArenaBlk *n = b->next;
    free(b);
    b = n;
  }
  a->blocks = NULL;
  a->chunk = NULL;
  a->used = a->cap = 0;
}

/* growable pointer vector */
typedef struct PVec { void **items; int n, cap; } PVec;
static void pv_push(PVec *v, void *p) {
  if (v->n >= v->cap) {
    v->cap = v->cap ? v->cap * 2 : 8;
    v->items = realloc(v->items, sizeof(void *) * v->cap);
  }
  v->items[v->n++] = p;
}
static void **pv_finish(Lex *ls, PVec *v) {
  void **res = NULL;
  if (v->n > 0) {
    res = arena_alloc(ls->arena, sizeof(void *) * v->n);
    memcpy(res, v->items, sizeof(void *) * v->n);
  }
  free(v->items);
  v->items = NULL;
  return res;
}

#define NEW(ls, T) ((T *)arena_alloc((ls)->arena, sizeof(T)))

static Expr *newexpr(Lex *ls, int k, int line) {
  Expr *e = NEW(ls, Expr);
  e->k = (uint8_t)k;
  e->line = line;
  return e;
}

static Stat *newstat(Lex *ls, int k, int line) {
  Stat *s = NEW(ls, Stat);
  s->k = (uint8_t)k;
  s->line = line;
  return s;
}

/* ---------------- error helpers ---------------- */

static void error_expected(Lex *ls, int token) __attribute__((noreturn));
static void error_expected(Lex *ls, int token) {
  lex_syntaxerror(ls, pushfstring(ls->L, "%s expected", lex_token2str(ls, token)));
}

static void errorlimit(Lex *ls, PFunc *fs, int limit, const char *what) __attribute__((noreturn));
static void errorlimit(Lex *ls, PFunc *fs, int limit, const char *what) {
  int line = fs->f->line;
  const char *where = (line == 0) ? "main function" : pushfstring(ls->L, "function at line %d", line);
  const char *msg = pushfstring(ls->L, "too many %s (limit is %d) in %s", what, limit, where);
  lex_syntaxerror(ls, msg);
}

static int testnext(Lex *ls, int c) {
  if (ls->t.token == c) {
    lex_next(ls);
    return 1;
  }
  return 0;
}

static void check(Lex *ls, int c) {
  if (ls->t.token != c) error_expected(ls, c);
}

static void checknext(Lex *ls, int c) {
  check(ls, c);
  lex_next(ls);
}

#define check_condition(ls, c, msg) { if (!(c)) lex_syntaxerror(ls, msg); }

static void check_match(Lex *ls, int what, int who, int where) {
  if (ls->t.token != what) {
    if (where == ls->linenumber)
      error_expected(ls, what);
    else {
      lex_syntaxerror(ls, pushfstring(ls->L, "%s expected (to close %s at line %d)",
                      lex_token2str(ls, what), lex_token2str(ls, who), where));
    }
  }
  lex_next(ls);
}

static Str *str_checkname(Lex *ls) {
  Str *ts;
  check(ls, TK_NAME);
  ts = ls->t.seminfo.ts;
  lex_next(ls);
  return ts;
}

static void enterlevel(Lex *ls) {
  if (++ls->level + ls->L->nCcalls >= MAXCCALLS) {
    pushfstring(ls->L, "C stack overflow");
    d_throw(ls->L, TS_ERRSYNTAX);
  }
}
#define leavelevel(ls) ((ls)->level--)

/* ---------------- variables ---------------- */

static VarDesc *new_vardesc(Lex *ls, Str *name, int kind) {
  VarDesc *vd = NEW(ls, VarDesc);
  vd->name = name;
  vd->kind = (uint8_t)kind;
  vd->isglobal = (kind == VD_GLOBAL || kind == VD_GCONST);
  vd->reg = -1;
  return vd;
}

static void push_actvar(Lex *ls, VarDesc *vd) {
  if (ls->nactvar >= ls->sizeactvar) {
    ls->sizeactvar = ls->sizeactvar ? ls->sizeactvar * 2 : 64;
    ls->actvar = realloc(ls->actvar, sizeof(VarDesc *) * ls->sizeactvar);
  }
  ls->actvar[ls->nactvar++] = vd;
  if (!vd->isglobal) {
    PFunc *fs = ls->fs;
    fs->nregvars++;
    if (fs->nregvars > MAXVARS) errorlimit(ls, fs, MAXVARS, "local variables");
  }
}

static void removevars(Lex *ls, int tolevel) {
  PFunc *fs = ls->fs;
  while (ls->nactvar > tolevel) {
    VarDesc *vd = ls->actvar[--ls->nactvar];
    if (!vd->isglobal) fs->nregvars--;
  }
}

static int searchupvalue(PFunc *fs, Str *name) {
  int i;
  FuncAST *f = fs->f;
  for (i = 0; i < f->nups; i++) {
    if (f->ups[i].name == name) return i;
  }
  return -1;
}

static int newupvalue(Lex *ls, PFunc *fs, Str *name, int instack, VarDesc *pvar, int pidx, int kind) {
  FuncAST *f = fs->f;
  UpvalAST *up;
  if (f->nups >= MAXUPVAL) errorlimit(ls, fs, MAXUPVAL, "upvalues");
  if (f->nups >= f->sizeups) {
    int ns = f->sizeups ? f->sizeups * 2 : 8;
    UpvalAST *nu = arena_alloc(ls->arena, sizeof(UpvalAST) * ns);
    if (f->nups) memcpy(nu, f->ups, sizeof(UpvalAST) * f->nups);
    f->ups = nu;
    f->sizeups = ns;
  }
  up = &f->ups[f->nups];
  up->name = name;
  up->instack = (uint8_t)instack;
  up->pvar = pvar;
  up->pidx = pidx;
  up->kind = (uint8_t)kind;
  return f->nups++;
}

/* resolution results */
#define R_NONE 0
#define R_LOCAL 1
#define R_UPVAL 2
#define R_GLOBAL 3

typedef struct Resolved {
  int kind;
  VarDesc *var;
  int idx;
  int vkind;  /* VD_* */
} Resolved;

static void singlevaraux(Lex *ls, PFunc *fs, Str *n, Resolved *r, int base) {
  int i;
  for (i = ls->nactvar - 1; i >= fs->firstlocal; i--) {
    VarDesc *vd = ls->actvar[i];
    if (vd->name == n) {
      if (vd->isglobal) {
        r->kind = R_GLOBAL;
        r->vkind = vd->kind;
      } else {
        r->kind = R_LOCAL;
        r->var = vd;
        r->vkind = vd->kind;
        if (!base) vd->captured = 1;
      }
      return;
    }
  }
  {
    int idx = searchupvalue(fs, n);
    if (idx >= 0) {
      r->kind = R_UPVAL;
      r->idx = idx;
      r->vkind = fs->f->ups[idx].kind;
      return;
    }
  }
  if (fs->prev == NULL) {
    r->kind = R_NONE;
    return;
  }
  singlevaraux(ls, fs->prev, n, r, 0);
  if (r->kind == R_LOCAL) {
    r->idx = newupvalue(ls, fs, n, 1, r->var, 0, r->vkind);
    r->kind = R_UPVAL;
  } else if (r->kind == R_UPVAL) {
    r->idx = newupvalue(ls, fs, n, 0, NULL, r->idx, r->vkind);
  }
}

static Expr *resolved2expr(Lex *ls, Resolved *r, Str *name, int line) {
  Expr *e;
  if (r->kind == R_LOCAL) {
    e = newexpr(ls, E_LOCAL, line);
    e->u.var = r->var;
  } else {
    e = newexpr(ls, E_UPVAL, line);
    e->u.up.idx = r->idx;
    e->u.up.name = name;
  }
  return e;
}

static Expr *singlevar_name(Lex *ls, Str *varname, int line) {
  Resolved r;
  memset(&r, 0, sizeof(r));
  singlevaraux(ls, ls->fs, varname, &r, 1);
  if (r.kind == R_LOCAL || r.kind == R_UPVAL) {
    Expr *e = resolved2expr(ls, &r, varname, line);
    e->op = (uint8_t)r.vkind;  /* remember kind for const checks */
    return e;
  } else {
    Expr *e;
    Resolved er;
    int gkind = VD_GLOBAL;
    if (r.kind == R_NONE) {
      /* look for collective declaration */
      int i, found = 0, anyexplicit = 0;
      for (i = ls->nactvar - 1; i >= 0; i--) {
        VarDesc *vd = ls->actvar[i];
        if (vd->isglobal) {
          if (vd->name == NULL) {
            found = 1;
            gkind = vd->kind;
            break;
          }
          anyexplicit = 1;
        }
      }
      if (!found && anyexplicit) {
        lex_semerror(ls, pushfstring(ls->L, "variable '%s' not declared", getstr(varname)));
      }
    } else
      gkind = r.vkind;
    memset(&er, 0, sizeof(er));
    singlevaraux(ls, ls->fs, ls->envn, &er, 1);
    e = newexpr(ls, E_GLOBAL, line);
    if (er.kind == R_LOCAL || er.kind == R_UPVAL)
      e->u.glb.env = resolved2expr(ls, &er, ls->envn, line);
    else {
      /* _ENV not found as variable: should not happen */
      e->u.glb.env = newexpr(ls, E_NIL, line);
    }
    e->u.glb.name = varname;
    e->u.glb.isconst = (gkind == VD_GCONST);
    return e;
  }
}

static void check_readonly(Lex *ls, Expr *e) {
  Str *varname = NULL;
  switch (e->k) {
    case E_LOCAL:
      if (e->u.var->kind != VD_REG) varname = e->u.var->name;
      break;
    case E_UPVAL:
      if (e->op != VD_REG) varname = e->u.up.name;
      break;
    case E_GLOBAL:
      if (e->u.glb.isconst) varname = e->u.glb.name;
      break;
    default:
      return;
  }
  if (varname)
    lex_semerror(ls, pushfstring(ls->L, "attempt to assign to const variable '%s'", getstr(varname)));
}

/* ---------------- blocks ---------------- */

static void enterblock(Lex *ls, PBlock *bl, int isloop) {
  PFunc *fs = ls->fs;
  bl->prev = fs->bl;
  bl->nactvar = ls->nactvar;
  bl->isloop = isloop;
  fs->bl = bl;
}

static void leaveblock(Lex *ls) {
  PFunc *fs = ls->fs;
  PBlock *bl = fs->bl;
  removevars(ls, bl->nactvar);
  fs->bl = bl->prev;
}

static int block_follow(Lex *ls, int withuntil) {
  switch (ls->t.token) {
    case TK_ELSE: case TK_ELSEIF:
    case TK_END: case TK_EOS:
      return 1;
    case TK_UNTIL: return withuntil;
    default: return 0;
  }
}

static Stat *statement(Lex *ls);
static Expr *expr(Lex *ls);
static Expr *subexpr(Lex *ls, int limit);

static void addstat(Block *b, Stat *s) {
  if (s == NULL) return;
  if (b->last) b->last->next = s;
  else b->first = s;
  b->last = s;
}

static void statlist(Lex *ls, Block *b) {
  while (!block_follow(ls, 1)) {
    if (ls->t.token == TK_RETURN) {
      addstat(b, statement(ls));
      return;
    }
    addstat(b, statement(ls));
  }
}

static Block *block(Lex *ls) {
  PBlock bl;
  Block *b = NEW(ls, Block);
  enterblock(ls, &bl, 0);
  statlist(ls, b);
  leaveblock(ls);
  return b;
}

/* ---------------- functions ---------------- */

static void open_func(Lex *ls, PFunc *fs, FuncAST *f, PBlock *bl) {
  fs->prev = ls->fs;
  fs->f = f;
  fs->firstlocal = ls->nactvar;
  fs->nregvars = 0;
  fs->bl = NULL;
  ls->fs = fs;
  enterblock(ls, bl, 0);
}

static void close_func(Lex *ls) {
  PFunc *fs = ls->fs;
  leaveblock(ls);
  ls->fs = fs->prev;
}

static void parlist(Lex *ls, FuncAST *f, PVec *params) {
  int isvararg = 0;
  if (ls->t.token != ')') {
    do {
      switch (ls->t.token) {
        case TK_NAME: {
          VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_REG);
          pv_push(params, vd);
          push_actvar(ls, vd);
          break;
        }
        case TK_DOTS: {
          lex_next(ls);
          isvararg = 1;
          if (ls->t.token == TK_NAME) {
            VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_CONST);
            f->vartab = vd;
            isvararg = 2;
          }
          break;
        }
        default:
          lex_syntaxerror(ls, "<name> or '...' expected");
      }
    } while (!isvararg && testnext(ls, ','));
  }
  f->is_vararg = isvararg;
}

static FuncAST *body(Lex *ls, int ismethod, int line) {
  PFunc nfs;
  PBlock bl;
  PVec params = {0};
  FuncAST *f = NEW(ls, FuncAST);
  f->line = line;
  f->ismethod = ismethod;
  open_func(ls, &nfs, f, &bl);
  checknext(ls, '(');
  if (ismethod) {
    VarDesc *vd = new_vardesc(ls, str_newc(ls->L, "self"), VD_REG);
    pv_push(&params, vd);
    push_actvar(ls, vd);
  }
  parlist(ls, f, &params);
  f->nparams = params.n;
  f->params = (VarDesc **)pv_finish(ls, &params);
  if (f->vartab) push_actvar(ls, f->vartab);
  checknext(ls, ')');
  f->body = NEW(ls, Block);
  statlist(ls, f->body);
  f->lastline = ls->linenumber;
  check_match(ls, TK_END, TK_FUNCTION, line);
  f->endline = ls->linenumber;
  close_func(ls);
  return f;
}

/* ---------------- expressions ---------------- */

static int explist(Lex *ls, PVec *v) {
  int n = 1;
  pv_push(v, expr(ls));
  while (testnext(ls, ',')) {
    pv_push(v, expr(ls));
    n++;
  }
  return n;
}

static Expr *funcargs(Lex *ls, Expr *f, Str *mname, int line) {
  PVec args = {0};
  Expr *e;
  switch (ls->t.token) {
    case '(': {
      lex_next(ls);
      if (ls->t.token != ')')
        explist(ls, &args);
      check_match(ls, ')', '(', line);
      break;
    }
    case '{': {
      extern Expr *constructor_(Lex *ls);
      pv_push(&args, constructor_(ls));
      break;
    }
    case TK_STRING: {
      Expr *s = newexpr(ls, E_STR, ls->linenumber);
      s->u.sval = ls->t.seminfo.ts;
      pv_push(&args, s);
      lex_next(ls);
      break;
    }
    default:
      lex_syntaxerror(ls, "function arguments expected");
  }
  e = newexpr(ls, mname ? E_METHCALL : E_CALL, line);
  e->u.call.fn = f;
  e->u.call.mname = mname;
  e->u.call.nargs = args.n;
  e->u.call.args = (Expr **)pv_finish(ls, &args);
  return e;
}

static Expr *primaryexp(Lex *ls) {
  switch (ls->t.token) {
    case '(': {
      int line = ls->linenumber;
      Expr *e, *inner;
      lex_next(ls);
      inner = expr(ls);
      check_match(ls, ')', '(', line);
      e = newexpr(ls, E_PAREN, line);
      e->u.bin.a = inner;
      return e;
    }
    case TK_NAME: {
      int line = ls->linenumber;
      Str *name = str_checkname(ls);
      return singlevar_name(ls, name, line);
    }
    default:
      lex_syntaxerror(ls, "unexpected symbol");
  }
}

static Expr *suffixedexp(Lex *ls) {
  int line = ls->linenumber;
  Expr *e = primaryexp(ls);
  for (;;) {
    switch (ls->t.token) {
      case '.': {
        Expr *k, *ix;
        lex_next(ls);
        k = newexpr(ls, E_STR, ls->linenumber);
        k->u.sval = str_checkname(ls);
        ix = newexpr(ls, E_INDEX, ls->lastline);
        ix->u.idx.obj = e;
        ix->u.idx.key = k;
        e = ix;
        break;
      }
      case '[': {
        Expr *k, *ix;
        lex_next(ls);
        k = expr(ls);
        checknext(ls, ']');
        ix = newexpr(ls, E_INDEX, ls->lastline);
        ix->u.idx.obj = e;
        ix->u.idx.key = k;
        e = ix;
        break;
      }
      case ':': {
        Str *mname;
        lex_next(ls);
        mname = str_checkname(ls);
        e = funcargs(ls, e, mname, line);
        break;
      }
      case '(': case TK_STRING: case '{': {
        e = funcargs(ls, e, NULL, line);
        break;
      }
      default:
        return e;
    }
  }
}

Expr *constructor_(Lex *ls) {
  int line = ls->linenumber;
  PVec fields = {0};
  int narr = 0, nhash = 0, i;
  Expr *t = newexpr(ls, E_TABLE, line);
  TField *tf;
  checknext(ls, '{');
  do {
    TField *f;
    if (ls->t.token == '}') break;
    f = NEW(ls, TField);
    f->line = ls->linenumber;
    switch (ls->t.token) {
      case TK_NAME: {
        if (lex_lookahead(ls) != '=') {
          f->val = expr(ls);
          narr++;
        } else {
          Expr *k = newexpr(ls, E_STR, ls->linenumber);
          k->u.sval = str_checkname(ls);
          checknext(ls, '=');
          f->key = k;
          f->val = expr(ls);
          nhash++;
        }
        break;
      }
      case '[': {
        lex_next(ls);
        f->key = expr(ls);
        checknext(ls, ']');
        checknext(ls, '=');
        f->val = expr(ls);
        nhash++;
        break;
      }
      default: {
        f->val = expr(ls);
        narr++;
        break;
      }
    }
    pv_push(&fields, f);
  } while (testnext(ls, ',') || testnext(ls, ';'));
  check_match(ls, '}', '{', line);
  t->u.tab.n = fields.n;
  tf = fields.n ? arena_alloc(ls->arena, sizeof(TField) * fields.n) : NULL;
  for (i = 0; i < fields.n; i++) tf[i] = *(TField *)fields.items[i];
  free(fields.items);
  t->u.tab.f = tf;
  t->u.tab.narr = narr;
  t->u.tab.nhash = nhash;
  return t;
}

static Expr *simpleexp(Lex *ls) {
  Expr *e;
  int line = ls->linenumber;
  switch (ls->t.token) {
    case TK_FLT:
      e = newexpr(ls, E_FLT, line);
      e->u.nval = ls->t.seminfo.r;
      break;
    case TK_INT:
      e = newexpr(ls, E_INT, line);
      e->u.ival = ls->t.seminfo.i;
      break;
    case TK_STRING:
      e = newexpr(ls, E_STR, line);
      e->u.sval = ls->t.seminfo.ts;
      break;
    case TK_NIL:
      e = newexpr(ls, E_NIL, line);
      break;
    case TK_TRUE:
      e = newexpr(ls, E_TRUE, line);
      break;
    case TK_FALSE:
      e = newexpr(ls, E_FALSE, line);
      break;
    case TK_DOTS: {
      check_condition(ls, ls->fs->f->is_vararg, "cannot use '...' outside a vararg function");
      e = newexpr(ls, E_VARARG, line);
      break;
    }
    case '{':
      return constructor_(ls);
    case TK_FUNCTION: {
      lex_next(ls);
      e = newexpr(ls, E_FUNC, line);
      e->u.func = body(ls, 0, line);
      return e;
    }
    default:
      return suffixedexp(ls);
  }
  lex_next(ls);
  return e;
}

static int getunopr(int op) {
  switch (op) {
    case TK_NOT: return OPR_NOT;
    case '-': return OPR_MINUS;
    case '~': return OPR_BNOT;
    case '#': return OPR_LEN;
    default: return OPR_NOUNOPR;
  }
}

static int getbinopr(int op) {
  switch (op) {
    case '+': return OPR_ADD;
    case '-': return OPR_SUB;
    case '*': return OPR_MUL;
    case '%': return OPR_MOD;
    case '^': return OPR_POW;
    case '/': return OPR_DIV;
    case TK_IDIV: return OPR_IDIV;
    case '&': return OPR_BAND;
    case '|': return OPR_BOR;
    case '~': return OPR_BXOR;
    case TK_SHL: return OPR_SHL;
    case TK_SHR: return OPR_SHR;
    case TK_CONCAT: return OPR_CONCAT;
    case TK_NE: return OPR_NE;
    case TK_EQ: return OPR_EQ;
    case '<': return OPR_LT;
    case TK_LE: return OPR_LE;
    case '>': return OPR_GT;
    case TK_GE: return OPR_GE;
    case TK_AND: return OPR_AND;
    case TK_OR: return OPR_OR;
    default: return OPR_NOBINOPR;
  }
}

static const struct { uint8_t left, right; } priority[] = {
  {10, 10}, {10, 10},
  {11, 11}, {11, 11},
  {14, 13},
  {11, 11}, {11, 11},
  {6, 6}, {4, 4}, {5, 5},
  {7, 7}, {7, 7},
  {9, 8},
  {3, 3}, {3, 3}, {3, 3},
  {3, 3}, {3, 3}, {3, 3},
  {2, 2}, {1, 1}
};

#define UNARY_PRIORITY 12

static Expr *subexpr(Lex *ls, int limit) {
  Expr *e;
  int op;
  int uop;
  enterlevel(ls);
  uop = getunopr(ls->t.token);
  if (uop != OPR_NOUNOPR) {
    int line = ls->linenumber;
    Expr *operand;
    lex_next(ls);
    operand = subexpr(ls, UNARY_PRIORITY);
    e = newexpr(ls, E_UN, line);
    e->op = (uint8_t)uop;
    e->u.bin.a = operand;
  } else
    e = simpleexp(ls);
  op = getbinopr(ls->t.token);
  while (op != OPR_NOBINOPR && priority[op].left > limit) {
    Expr *e2, *ne;
    int nextop;
    int line = ls->linenumber;
    lex_next(ls);
    e2 = subexpr(ls, priority[op].right);
    nextop = getbinopr(ls->t.token);
    if (op == OPR_AND) ne = newexpr(ls, E_AND, line);
    else if (op == OPR_OR) ne = newexpr(ls, E_OR, line);
    else {
      ne = newexpr(ls, E_BIN, line);
      ne->op = (uint8_t)op;
    }
    ne->u.bin.a = e;
    ne->u.bin.b = e2;
    e = ne;
    op = nextop;
  }
  leavelevel(ls);
  return e;
}

static Expr *expr(Lex *ls) {
  return subexpr(ls, 0);
}

/* ---------------- statements ---------------- */

static int isvarexp(Expr *e) {
  return e->k == E_LOCAL || e->k == E_UPVAL || e->k == E_GLOBAL || e->k == E_INDEX;
}

static Stat *exprstat(Lex *ls) {
  int line = ls->linenumber;
  Expr *v = suffixedexp(ls);
  if (ls->t.token == '=' || ls->t.token == ',') {
    PVec targets = {0}, exprs = {0};
    Stat *s = newstat(ls, S_ASSIGN, line);
    check_condition(ls, isvarexp(v), "syntax error");
    check_readonly(ls, v);
    pv_push(&targets, v);
    while (testnext(ls, ',')) {
      Expr *t = suffixedexp(ls);
      check_condition(ls, isvarexp(t), "syntax error");
      check_readonly(ls, t);
      pv_push(&targets, t);
    }
    checknext(ls, '=');
    s->line2 = ls->linenumber;
    explist(ls, &exprs);
    s->u.assign.nt = targets.n;
    s->u.assign.targets = (Expr **)pv_finish(ls, &targets);
    s->u.assign.ne = exprs.n;
    s->u.assign.exprs = (Expr **)pv_finish(ls, &exprs);
    return s;
  } else {
    Stat *s;
    check_condition(ls, v->k == E_CALL || v->k == E_METHCALL, "syntax error");
    s = newstat(ls, S_CALL, line);
    s->u.call = v;
    return s;
  }
}

static Stat *retstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_RETURN, line);
  PVec exprs = {0};
  if (!(block_follow(ls, 1) || ls->t.token == ';'))
    explist(ls, &exprs);
  testnext(ls, ';');
  s->u.ret.n = exprs.n;
  s->u.ret.exprs = (Expr **)pv_finish(ls, &exprs);
  return s;
}

static Expr *cond(Lex *ls) {
  Expr *e = expr(ls);
  if (e->k == E_NIL) e->k = E_FALSE;
  return e;
}

static Stat *whilestat(Lex *ls, int line) {
  PBlock bl;
  Stat *s = newstat(ls, S_WHILE, line);
  lex_next(ls);
  s->u.loop.cond = cond(ls);
  enterblock(ls, &bl, 1);
  checknext(ls, TK_DO);
  s->u.loop.body = block(ls);
  check_match(ls, TK_END, TK_WHILE, line);
  leaveblock(ls);
  return s;
}

static Stat *repeatstat(Lex *ls, int line) {
  PBlock bl1, bl2;
  Stat *s = newstat(ls, S_REPEAT, line);
  Block *b = NEW(ls, Block);
  enterblock(ls, &bl1, 1);
  enterblock(ls, &bl2, 0);
  lex_next(ls);
  statlist(ls, b);
  check_match(ls, TK_UNTIL, TK_REPEAT, line);
  s->u.loop.cond = cond(ls);
  s->u.loop.body = b;
  leaveblock(ls);
  leaveblock(ls);
  return s;
}

static Stat *fornum(Lex *ls, Str *varname, int line) {
  PBlock bl;
  Stat *s = newstat(ls, S_NUMFOR, line);
  VarDesc *vd;
  int i;
  for (i = 0; i < 3; i++) {
    s->u.numfor.hidden[i] = new_vardesc(ls, str_newc(ls->L, "(for state)"), VD_REG);
    push_actvar(ls, s->u.numfor.hidden[i]);
  }
  vd = new_vardesc(ls, varname, VD_CONST);
  s->u.numfor.var = vd;
  checknext(ls, '=');
  s->u.numfor.start = expr(ls);
  checknext(ls, ',');
  s->u.numfor.limit = expr(ls);
  if (testnext(ls, ','))
    s->u.numfor.step = expr(ls);
  checknext(ls, TK_DO);
  s->line2 = ls->lastline;
  enterblock(ls, &bl, 0);
  push_actvar(ls, vd);
  s->u.numfor.body = block(ls);
  leaveblock(ls);
  return s;
}

static Stat *forlist(Lex *ls, Str *indexname, int line) {
  PBlock bl;
  Stat *s = newstat(ls, S_GENFOR, line);
  PVec vars = {0}, exprs = {0};
  int i;
  for (i = 0; i < 4; i++) {
    s->u.genfor.hidden[i] = new_vardesc(ls, str_newc(ls->L, "(for state)"), VD_REG);
    push_actvar(ls, s->u.genfor.hidden[i]);
  }
  pv_push(&vars, new_vardesc(ls, indexname, VD_CONST));
  while (testnext(ls, ','))
    pv_push(&vars, new_vardesc(ls, str_checkname(ls), VD_REG));
  checknext(ls, TK_IN);
  explist(ls, &exprs);
  checknext(ls, TK_DO);
  s->line2 = ls->lastline;
  s->u.genfor.nvars = vars.n;
  s->u.genfor.vars = (VarDesc **)pv_finish(ls, &vars);
  s->u.genfor.nexprs = exprs.n;
  s->u.genfor.exprs = (Expr **)pv_finish(ls, &exprs);
  enterblock(ls, &bl, 0);
  for (i = 0; i < s->u.genfor.nvars; i++) push_actvar(ls, s->u.genfor.vars[i]);
  s->u.genfor.body = block(ls);
  leaveblock(ls);
  return s;
}

static Stat *forstat(Lex *ls, int line) {
  PBlock bl;
  Str *varname;
  Stat *s;
  enterblock(ls, &bl, 1);
  lex_next(ls);
  varname = str_checkname(ls);
  switch (ls->t.token) {
    case '=': s = fornum(ls, varname, line); break;
    case ',': case TK_IN: s = forlist(ls, varname, line); break;
    default: lex_syntaxerror(ls, "'=' or 'in' expected");
  }
  check_match(ls, TK_END, TK_FOR, line);
  leaveblock(ls);
  return s;
}

static Stat *ifstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_IF, line);
  PVec conds = {0}, blocks = {0};
  /* IF cond THEN block {ELSEIF cond THEN block} [ELSE block] END */
  do {
    lex_next(ls);  /* skip IF or ELSEIF */
    pv_push(&conds, cond(ls));
    checknext(ls, TK_THEN);
    pv_push(&blocks, block(ls));
  } while (ls->t.token == TK_ELSEIF);
  if (testnext(ls, TK_ELSE))
    s->u.ifs.elseb = block(ls);
  check_match(ls, TK_END, TK_IF, line);
  s->u.ifs.n = conds.n;
  s->u.ifs.conds = (Expr **)pv_finish(ls, &conds);
  s->u.ifs.blocks = (Block **)pv_finish(ls, &blocks);
  return s;
}

static int getattrib(Lex *ls, int def) {
  if (testnext(ls, '<')) {
    Str *ts = str_checkname(ls);
    const char *attr = getstr(ts);
    checknext(ls, '>');
    if (strcmp(attr, "const") == 0)
      return VD_CONST;
    else if (strcmp(attr, "close") == 0)
      return VD_CLOSE;
    else
      lex_semerror(ls, pushfstring(ls->L, "unknown attribute '%s'", attr));
  }
  return def;
}

static Stat *localfunc(Lex *ls, int line) {
  Stat *s = newstat(ls, S_LOCALFUNC, line);
  VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_REG);
  push_actvar(ls, vd);
  s->u.localfunc.var = vd;
  s->u.localfunc.f = body(ls, 0, line);
  return s;
}

static Stat *localstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_LOCAL, line);
  PVec vars = {0}, exprs = {0};
  int i, nclose = 0;
  int defkind = getattrib(ls, VD_REG);
  do {
    VarDesc *vd = new_vardesc(ls, str_checkname(ls), VD_REG);
    int kind = getattrib(ls, defkind);
    vd->kind = (uint8_t)kind;
    if (kind == VD_CLOSE) {
      if (nclose++ > 0)
        lex_semerror(ls, "multiple to-be-closed variables in local list");
    }
    pv_push(&vars, vd);
  } while (testnext(ls, ','));
  if (testnext(ls, '='))
    explist(ls, &exprs);
  s->u.local.nvars = vars.n;
  s->u.local.vars = (VarDesc **)pv_finish(ls, &vars);
  s->u.local.nexprs = exprs.n;
  s->u.local.exprs = (Expr **)pv_finish(ls, &exprs);
  for (i = 0; i < s->u.local.nvars; i++) push_actvar(ls, s->u.local.vars[i]);
  return s;
}

static int getglobalattrib(Lex *ls, int def) {
  int k = getattrib(ls, def == VD_GCONST ? VD_CONST : VD_REG);
  if (k == VD_CLOSE)
    lex_semerror(ls, "global variables cannot be to-be-closed");
  return k == VD_CONST ? VD_GCONST : VD_GLOBAL;
}

static Stat *globalstat(Lex *ls, int line) {
  /* 'global' already skipped */
  int defkind = getglobalattrib(ls, VD_GLOBAL);
  if (testnext(ls, '*')) {
    VarDesc *vd = new_vardesc(ls, NULL, defkind);
    push_actvar(ls, vd);
    return NULL;
  } else {
    PVec names = {0}, exprs = {0};
    Stat *s = NULL;
    int i;
    do {
      Str *name = str_checkname(ls);
      int kind = getglobalattrib(ls, defkind);
      VarDesc *vd = new_vardesc(ls, name, kind);
      pv_push(&names, vd);
    } while (testnext(ls, ','));
    for (i = 0; i < names.n; i++) push_actvar(ls, (VarDesc *)names.items[i]);
    if (testnext(ls, '=')) {
      PVec targets = {0};
      s = newstat(ls, S_GLOBAL, line);
      for (i = 0; i < names.n; i++) {
        VarDesc *vd = (VarDesc *)names.items[i];
        Expr *t = singlevar_name(ls, vd->name, line);
        pv_push(&targets, t);
      }
      explist(ls, &exprs);
      s->u.global.nt = targets.n;
      s->u.global.targets = (Expr **)pv_finish(ls, &targets);
      s->u.global.ne = exprs.n;
      s->u.global.exprs = (Expr **)pv_finish(ls, &exprs);
    }
    free(names.items);
    return s;
  }
}

static Stat *globalfunc(Lex *ls, int line) {
  /* 'global function' already skipped */
  Stat *s = newstat(ls, S_GLOBALFUNC, line);
  Str *name = str_checkname(ls);
  VarDesc *vd = new_vardesc(ls, name, VD_GLOBAL);
  push_actvar(ls, vd);
  s->u.globalfunc.target = singlevar_name(ls, name, line);
  s->u.globalfunc.f = body(ls, 0, line);
  return s;
}

static Stat *funcstat(Lex *ls, int line) {
  Stat *s = newstat(ls, S_ASSIGN, line);
  Expr *v, *fe;
  int ismethod = 0;
  int nline;
  lex_next(ls);  /* skip FUNCTION */
  nline = ls->linenumber;
  v = singlevar_name(ls, str_checkname(ls), nline);
  while (ls->t.token == '.') {
    Expr *k, *ix;
    lex_next(ls);
    k = newexpr(ls, E_STR, ls->linenumber);
    k->u.sval = str_checkname(ls);
    ix = newexpr(ls, E_INDEX, ls->lastline);
    ix->u.idx.obj = v;
    ix->u.idx.key = k;
    v = ix;
  }
  if (ls->t.token == ':') {
    Expr *k, *ix;
    lex_next(ls);
    k = newexpr(ls, E_STR, ls->linenumber);
    k->u.sval = str_checkname(ls);
    ix = newexpr(ls, E_INDEX, ls->lastline);
    ix->u.idx.obj = v;
    ix->u.idx.key = k;
    v = ix;
    ismethod = 1;
  }
  check_readonly(ls, v);
  fe = newexpr(ls, E_FUNC, line);
  fe->u.func = body(ls, ismethod, line);
  s->u.assign.nt = 1;
  s->u.assign.targets = arena_alloc(ls->arena, sizeof(Expr *));
  s->u.assign.targets[0] = v;
  s->u.assign.ne = 1;
  s->u.assign.exprs = arena_alloc(ls->arena, sizeof(Expr *));
  s->u.assign.exprs[0] = fe;
  s->line2 = line;
  return s;
}

static Stat *statement(Lex *ls) {
  int line = ls->linenumber;
  Stat *s = NULL;
  enterlevel(ls);
  switch (ls->t.token) {
    case ';':
      lex_next(ls);
      break;
    case TK_IF:
      s = ifstat(ls, line);
      break;
    case TK_WHILE:
      s = whilestat(ls, line);
      break;
    case TK_DO: {
      lex_next(ls);
      s = newstat(ls, S_DO, line);
      s->u.blk.body = block(ls);
      check_match(ls, TK_END, TK_DO, line);
      break;
    }
    case TK_FOR:
      s = forstat(ls, line);
      break;
    case TK_REPEAT:
      s = repeatstat(ls, line);
      break;
    case TK_FUNCTION:
      s = funcstat(ls, line);
      break;
    case TK_LOCAL:
      lex_next(ls);
      if (testnext(ls, TK_FUNCTION))
        s = localfunc(ls, line);
      else
        s = localstat(ls, line);
      break;
    case TK_DBCOLON: {
      Str *name;
      lex_next(ls);
      name = str_checkname(ls);
      checknext(ls, TK_DBCOLON);
      s = newstat(ls, S_LABEL, line);
      s->u.label.name = name;
      break;
    }
    case TK_RETURN:
      lex_next(ls);
      s = retstat(ls, line);
      break;
    case TK_BREAK: {
      PBlock *bl = ls->fs->bl;
      while (bl && !bl->isloop) bl = bl->prev;
      if (bl == NULL)
        lex_syntaxerror(ls, "break outside loop");
      lex_next(ls);
      s = newstat(ls, S_BREAK, line);
      break;
    }
    case TK_GOTO: {
      lex_next(ls);
      s = newstat(ls, S_GOTO, line);
      s->u.label.name = str_checkname(ls);
      break;
    }
    case TK_NAME: {
      if (strcmp(getstr(ls->t.seminfo.ts), "global") == 0) {
        int la = lex_lookahead(ls);
        if (la == TK_NAME || la == '<' || la == '*') {
          lex_next(ls);
          s = globalstat(ls, line);
          break;
        } else if (la == TK_FUNCTION) {
          lex_next(ls);
          lex_next(ls);
          s = globalfunc(ls, line);
          break;
        }
      }
      s = exprstat(ls);
      break;
    }
    default:
      s = exprstat(ls);
      break;
  }
  leavelevel(ls);
  return s;
}

/* ---------------- main ---------------- */

typedef struct ParseCtx {
  Lex ls;
  Arena arena;
} ParseCtx;

static FuncAST *mainfunc(Lex *ls) {
  PFunc fs;
  PBlock bl;
  FuncAST *f = NEW(ls, FuncAST);
  f->line = 0;
  f->is_vararg = 1;
  open_func(ls, &fs, f, &bl);
  newupvalue(ls, &fs, ls->envn, 1, NULL, 0, VD_REG);
  lex_next(ls);
  f->body = NEW(ls, Block);
  statlist(ls, f->body);
  check(ls, TK_EOS);
  f->lastline = ls->linenumber;
  f->endline = ls->linenumber;
  close_func(ls);
  return f;
}

static ParseCtx *curctx = NULL;

LClosure *parse_chunk(State *L, const char *buff, size_t size, const char *name) {
  ParseCtx ctx;
  ParseCtx *prevctx = curctx;
  LongJmp lj;
  LClosure *cl;
  Proto *p;
  Str *source = str_newc(L, name);
  memset(&ctx, 0, sizeof(ctx));
  ctx.ls.arena = &ctx.arena;
  /* protect to free resources on error */
  lj.prev = L->errjmp;
  lj.status = TS_OK;
  L->errjmp = &lj;
  curctx = &ctx;
  if (setjmp(lj.b) == 0) {
    FuncAST *f;
    lex_setinput(L, &ctx.ls, buff, size, source);
    f = mainfunc(&ctx.ls);
    p = codegen_main(L, f, source, &ctx.arena);
  }
  L->errjmp = lj.prev;
  curctx = prevctx;
  free(ctx.ls.buf);
  free(ctx.ls.actvar);
  arena_free(&ctx.arena);
  if (lj.status != TS_OK)
    d_throw(L, lj.status);
  cl = lcl_new(L, p->sizeup);
  cl->p = p;
  {
    int i;
    for (i = 0; i < p->sizeup; i++) cl->up[i] = NULL;
  }
  return cl;
}
EOF
