/* code generator: AST -> bytecode */
#include "ast.h"
#include "lex.h"
#include "opcodes.h"

#define MAXREGS 255

typedef struct CLabel {
  Str *name;
  int pc;
  int line;
  int nactvar;
  int close;
} CLabel;

typedef struct CBlock {
  struct CBlock *prev;
  int firstlabel, firstgoto;
  int nactvar;
  uint8_t upval;
  uint8_t isloop;
  uint8_t insidetbc;
} CBlock;

typedef struct CG {
  State *L;
  Str *source;
  Str *breakname;
  Str *intindex;
  Str *qmark;
  CLabel *labels;
  int nlabels, sizelabels;
  CLabel *gotos;
  int ngotos, sizegotos;
} CG;

typedef struct FS {
  struct FS *prev;
  FuncAST *fa;
  Proto *f;
  State *L;
  CG *cg;
  CBlock *bl;
  int pc;
  int nk;
  Table *kstr, *kint, *kflt;
  int knil, ktrue, kfalse;
  int np;
  int freereg;
  int nactvar;
  VarDesc **actvars;
  int sizeactvars;
  int nvi;
  int nlocvars;
  int firstlabel, firstgoto;
  int maxstack;
} FS;

static void cg_error(FS *fs, const char *msg, int line) __attribute__((noreturn));
static void cg_error(FS *fs, const char *msg, int line) {
  char buff[IDSIZE];
  chunkid(buff, getstr(fs->cg->source), fs->cg->source->len);
  pushfstring(fs->L, "%s:%d: %s", buff, line, msg);
  d_throw(fs->L, TS_ERRSYNTAX);
}

/* ---------------- emission ---------------- */

static int emit(FS *fs, int op, int a, int b, int c, int k, int line) {
  Proto *f = fs->f;
  Instr *i;
  if (fs->pc >= f->sizecode) {
    int ns = f->sizecode ? f->sizecode * 2 : 64;
    f->code = mem_reallocvec(fs->L, f->code, f->sizecode, ns, Instr);
    f->lineinfo = mem_reallocvec(fs->L, f->lineinfo, f->sizecode, ns, int);
    f->sizecode = ns;
  }
  i = &f->code[fs->pc];
  i->op = (uint8_t)op;
  i->k = (uint8_t)k;
  i->a = (uint16_t)a;
  i->u.bc.b = (uint16_t)b;
  i->u.bc.c = (uint16_t)c;
  f->lineinfo[fs->pc] = line;
  return fs->pc++;
}

static int emitx(FS *fs, int op, int a, int32_t sbx, int line) {
  int pc = emit(fs, op, a, 0, 0, 0, line);
  fs->f->code[pc].u.sbx = sbx;
  return pc;
}

static void addvi(FS *fs, int pc, int which, int kind, Str *name) {
  Proto *f = fs->f;
  VarInfo *v;
  if (kind == VK_NONE) return;
  if (fs->nvi >= f->sizevarinfo) {
    int ns = f->sizevarinfo ? f->sizevarinfo * 2 : 16;
    f->varinfo = mem_reallocvec(fs->L, f->varinfo, f->sizevarinfo, ns, VarInfo);
    f->sizevarinfo = ns;
  }
  v = &f->varinfo[fs->nvi++];
  v->pc = pc;
  v->which = (uint8_t)which;
  v->kind = (uint8_t)kind;
  v->name = name;
}

static int isenvexp(Expr *e) {
  if (e->k == E_LOCAL) return strcmp(getstr(e->u.var->name), "_ENV") == 0;
  if (e->k == E_UPVAL) return strcmp(getstr(e->u.up.name), "_ENV") == 0;
  return 0;
}

static int describe(FS *fs, Expr *e, Str **name) {
  while (e->k == E_PAREN) e = e->u.bin.a;
  switch (e->k) {
    case E_LOCAL: *name = e->u.var->name; return VK_LOCAL;
    case E_UPVAL: *name = e->u.up.name; return VK_UPVAL;
    case E_GLOBAL: *name = e->u.glb.name; return VK_GLOBAL;
    case E_INDEX: {
      Expr *key = e->u.idx.key;
      if (key->k == E_STR) {
        *name = key->u.sval;
        return isenvexp(e->u.idx.obj) ? VK_GLOBAL : VK_FIELD;
      }
      if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 255) {
        *name = fs->cg->intindex;
        return VK_FIELD;
      }
      *name = fs->cg->qmark;
      return VK_FIELD;
    }
    case E_STR: *name = e->u.sval; return VK_CONST;
    default: return VK_NONE;
  }
}

static void vinfo(FS *fs, int pc, int which, Expr *e) {
  Str *name = NULL;
  int kind = describe(fs, e, &name);
  addvi(fs, pc, which, kind, name);
}

/* ---------------- jumps ---------------- */

static int getjump(FS *fs, int pc) {
  int offset = fs->f->code[pc].u.sbx;
  if (offset == NO_JUMP) return NO_JUMP;
  return pc + 1 + offset;
}

static void fixjump(FS *fs, int pc, int dest) {
  fs->f->code[pc].u.sbx = dest - (pc + 1);
}

static void concatjl(FS *fs, int *l1, int l2) {
  if (l2 == NO_JUMP) return;
  if (*l1 == NO_JUMP) *l1 = l2;
  else {
    int list = *l1;
    int next;
    while ((next = getjump(fs, list)) != NO_JUMP) list = next;
    fixjump(fs, list, l2);
  }
}

static int jump(FS *fs, int line) {
  return emitx(fs, OP_JMP, 0, NO_JUMP, line);
}

static void patchlist(FS *fs, int list, int target) {
  while (list != NO_JUMP) {
    int next = getjump(fs, list);
    fixjump(fs, list, target);
    list = next;
  }
}

static void patchtohere(FS *fs, int list) {
  patchlist(fs, list, fs->pc);
}

/* ---------------- constants ---------------- */

static int addk(FS *fs, const TValue *v) {
  Proto *f = fs->f;
  int idx = fs->nk;
  if (idx >= f->sizek) {
    int ns = f->sizek ? f->sizek * 2 : 16;
    int i;
    f->k = mem_reallocvec(fs->L, f->k, f->sizek, ns, TValue);
    for (i = f->sizek; i < ns; i++) setnil(&f->k[i]);
    f->sizek = ns;
  }
  f->k[idx] = *v;
  fs->nk++;
  return idx;
}

static int cachedk(FS *fs, Table **cache, const TValue *key, const TValue *v) {
  const TValue *p;
  TValue *slot;
  int idx;
  if (*cache == NULL) *cache = tab_new(fs->L);
  p = tab_get(*cache, key);
  if (!isnil(p)) return (int)ivalue(p);
  idx = addk(fs, v);
  slot = tab_set(fs->L, *cache, key);
  setint(slot, idx);
  return idx;
}

static int stringK(FS *fs, Str *s) {
  TValue v;
  setstr(&v, s);
  return cachedk(fs, &fs->kstr, &v, &v);
}

static int intK(FS *fs, lint i) {
  TValue v;
  setint(&v, i);
  return cachedk(fs, &fs->kint, &v, &v);
}

static int fltK(FS *fs, lnum n) {
  TValue v, key;
  lint bits;
  memcpy(&bits, &n, sizeof(bits));
  setint(&key, bits);
  setflt(&v, n);
  return cachedk(fs, &fs->kflt, &key, &v);
}

static int nilK(FS *fs) {
  if (fs->knil < 0) {
    TValue v;
    setnil(&v);
    fs->knil = addk(fs, &v);
  }
  return fs->knil;
}

static int boolK(FS *fs, int b) {
  int *p = b ? &fs->ktrue : &fs->kfalse;
  if (*p < 0) {
    TValue v;
    setbool(&v, b);
    *p = addk(fs, &v);
  }
  return *p;
}

/* ---------------- registers ---------------- */

static void checkstack(FS *fs, int n, int line) {
  int newstack = fs->freereg + n;
  if (newstack > fs->maxstack) {
    if (newstack >= MAXREGS)
      cg_error(fs, "function or expression needs too many registers", line);
    fs->maxstack = newstack;
  }
}

static void reserveregs(FS *fs, int n, int line) {
  checkstack(fs, n, line);
  fs->freereg += n;
}

/* ---------------- forward decls ---------------- */
static void exp2reg(FS *fs, Expr *e, int reg);
static int exp2anyreg(FS *fs, Expr *e);
static void exp2multi(FS *fs, Expr *e, int nres);
static int condjump(FS *fs, Expr *e, int jumpif);
static void block(FS *fs, Block *b, int isloop);
static Proto *compile_func(FS *parent, FuncAST *fa, Str *source);

static int ismulti(Expr *e) {
  return e->k == E_CALL || e->k == E_METHCALL || e->k == E_VARARG;
}

static void exp2nextreg(FS *fs, Expr *e) {
  int r = fs->freereg;
  reserveregs(fs, 1, e->line);
  exp2reg(fs, e, r);
}

/* constant operand if possible */
static int exp2rk(FS *fs, Expr *e, int *isk) {
  int k = -1;
  switch (e->k) {
    case E_NIL: k = nilK(fs); break;
    case E_TRUE: k = boolK(fs, 1); break;
    case E_FALSE: k = boolK(fs, 0); break;
    case E_INT: k = intK(fs, e->u.ival); break;
    case E_FLT: k = fltK(fs, e->u.nval); break;
    case E_STR: k = stringK(fs, e->u.sval); break;
    default: break;
  }
  if (k >= 0 && k <= 0xffff) {
    *isk = 1;
    return k;
  }
  *isk = 0;
  return exp2anyreg(fs, e);
}

static int exp2anyreg(FS *fs, Expr *e) {
  Expr *ie = e;
  while (ie->k == E_PAREN) ie = ie->u.bin.a;
  if (ie->k == E_LOCAL) return ie->u.var->reg;
  {
    int r = fs->freereg;
    reserveregs(fs, 1, e->line);
    exp2reg(fs, e, r);
    return r;
  }
}

static int istoptemp(FS *fs, int reg) {
  return reg >= fs->nactvar && reg == fs->freereg - 1;
}

/* compile a call expression with function at register base = freereg */
static void codecall(FS *fs, Expr *e, int nres) {
  int base = fs->freereg;
  int nargs, i, pc;
  int line = e->line;
  Expr **args = e->u.call.args;
  int n = e->u.call.nargs;
  if (e->k == E_METHCALL) {
    int obj, isk;
    int k;
    int save;
    reserveregs(fs, 2, line);
    save = fs->freereg;
    obj = exp2anyreg(fs, e->u.call.fn);
    fs->freereg = save;
    k = stringK(fs, e->u.call.mname);
    if (k > 0xffff) {
      int kr = fs->freereg;
      reserveregs(fs, 1, line);
      emitx(fs, OP_LOADK, kr, k, line);
      fs->f->code[fs->pc - 1].u.bx = (uint32_t)k;
      pc = emit(fs, OP_SELF, base, obj, kr, 0, line);
      fs->freereg = save;
    } else {
      pc = emit(fs, OP_SELF, base, obj, k, 2, line);
    }
    vinfo(fs, pc, 1, e->u.call.fn);
    isk = 0;
    (void)isk;
  } else {
    exp2nextreg(fs, e->u.call.fn);
  }
  for (i = 0; i < n; i++) {
    if (i == n - 1 && ismulti(args[i]))
      exp2multi(fs, args[i], -1);
    else
      exp2nextreg(fs, args[i]);
  }
  if (n > 0 && ismulti(args[n - 1]))
    nargs = 0;  /* to top */
  else
    nargs = fs->freereg - base;  /* includes function (and self) */
  pc = emit(fs, OP_CALL, base, nargs, nres + 1, 0, line);
  if (e->k == E_METHCALL)
    addvi(fs, pc, 0, VK_METHOD, e->u.call.mname);
  else
    vinfo(fs, pc, 0, e->u.call.fn);
  fs->freereg = base + (nres > 0 ? nres : 0);
  if (nres > 0) checkstack(fs, 0, line);
}

/* place multiple results of e starting at freereg; nres = -1 means all (to top) */
static void exp2multi(FS *fs, Expr *e, int nres) {
  if (e->k == E_VARARG) {
    int base = fs->freereg;
    emit(fs, OP_VARARG, base, 0, nres + 1, 0, e->line);
    if (nres > 0) reserveregs(fs, nres, e->line);
  } else {
    codecall(fs, e, nres);
    if (nres > 0) checkstack(fs, 0, e->line);
  }
}

static void loadint(FS *fs, int reg, lint i, int line) {
  if (i >= INT32_MIN && i <= INT32_MAX)
    emitx(fs, OP_LOADI, reg, (int32_t)i, line);
  else {
    int k = intK(fs, i);
    int pc = emit(fs, OP_LOADK, reg, 0, 0, 0, line);
    fs->f->code[pc].u.bx = (uint32_t)k;
  }
}

static void loadk(FS *fs, int reg, int k, int line) {
  int pc = emit(fs, OP_LOADK, reg, 0, 0, 0, line);
  fs->f->code[pc].u.bx = (uint32_t)k;
}

static int arithop(int opr) {
  switch (opr) {
    case OPR_ADD: return OP_ADD;
    case OPR_SUB: return OP_SUB;
    case OPR_MUL: return OP_MUL;
    case OPR_MOD: return OP_MOD;
    case OPR_POW: return OP_POW;
    case OPR_DIV: return OP_DIV;
    case OPR_IDIV: return OP_IDIV;
    case OPR_BAND: return OP_BAND;
    case OPR_BOR: return OP_BOR;
    case OPR_BXOR: return OP_BXOR;
    case OPR_SHL: return OP_SHL;
    case OPR_SHR: return OP_SHR;
    default: return -1;
  }
}

static int iscompare(int opr) {
  return opr >= OPR_EQ && opr <= OPR_GE;
}

/* table constructor into register reg (reg must be top temp) */
static void constructor(FS *fs, Expr *e, int reg) {
  int i, pending = 0, nlist = 0;
  int n = e->u.tab.n;
  TField *f = e->u.tab.f;
  int narr = e->u.tab.narr;
  int line = e->line;
  int pc;
  if (n > 0 && f[n - 1].key == NULL && ismulti(f[n - 1].val)) narr--;
  pc = emit(fs, OP_NEWTABLE, reg, narr > 0xffff ? 0xffff : narr,
            e->u.tab.nhash > 0xffff ? 0xffff : e->u.tab.nhash, 0, line);
  if (narr > 0xffff) {
    fs->f->code[pc].k = 1;
    emit(fs, OP_EXTRAARG, 0, 0, 0, 0, line);
    fs->f->code[fs->pc - 1].u.bx = (uint32_t)narr;
  }
  for (i = 0; i < n; i++) {
    TField *fl = &f[i];
    if (fl->key == NULL) {
      if (i == n - 1 && ismulti(fl->val)) {
        exp2multi(fs, fl->val, -1);
        emit(fs, OP_SETLIST, reg, 0, 0, 1, fl->line);
        emit(fs, OP_EXTRAARG, 0, 0, 0, 0, fl->line);
        fs->f->code[fs->pc - 1].u.bx = (uint32_t)nlist;
        fs->freereg = reg + 1;
        pending = 0;
        continue;
      }
      exp2nextreg(fs, fl->val);
      pending++;
      if (pending == LFIELDS_PER_FLUSH) {
        emit(fs, OP_SETLIST, reg, pending, 0, 1, fl->line);
        emit(fs, OP_EXTRAARG, 0, 0, 0, 0, fl->line);
        fs->f->code[fs->pc - 1].u.bx = (uint32_t)nlist;
        nlist += pending;
        pending = 0;
        fs->freereg = reg + 1;
      }
    } else {
      int save = fs->freereg;
      int kk, kv, rkey, rval;
      Expr *key = fl->key;
      if (key->k == E_STR && (rkey = stringK(fs, key->u.sval)) <= 0xffff) {
        rval = exp2rk(fs, fl->val, &kv);
        emit(fs, OP_SETFIELD, reg, rkey, rval, kv ? 2 : 0, fl->line);
      } else if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 0xffff) {
        rval = exp2rk(fs, fl->val, &kv);
        emit(fs, OP_SETI, reg, (int)key->u.ival, rval, kv ? 2 : 0, fl->line);
      } else {
        rkey = exp2rk(fs, key, &kk);
        rval = exp2rk(fs, fl->val, &kv);
        emit(fs, OP_SETTABLE, reg, rkey, rval, (kk ? 1 : 0) | (kv ? 2 : 0), fl->line);
      }
      fs->freereg = save;
    }
  }
  if (pending > 0) {
    emit(fs, OP_SETLIST, reg, pending, 0, 1, line);
    emit(fs, OP_EXTRAARG, 0, 0, 0, 0, line);
    fs->f->code[fs->pc - 1].u.bx = (uint32_t)nlist;
    fs->freereg = reg + 1;
  }
}

static void codeindex(FS *fs, Expr *e, int reg) {
  Expr *obj = e->u.idx.obj;
  Expr *key = e->u.idx.key;
  int save = fs->freereg;
  int line = e->line;
  int pc;
  int ko;
  if (obj->k == E_UPVAL && key->k == E_STR && (ko = stringK(fs, key->u.sval)) <= 0xffff) {
    pc = emit(fs, OP_GETTABUP, reg, obj->u.up.idx, ko, 0, line);
    vinfo(fs, pc, 1, obj);
    return;
  }
  {
    int ro = exp2anyreg(fs, obj);
    if (key->k == E_STR && (ko = stringK(fs, key->u.sval)) <= 0xffff) {
      pc = emit(fs, OP_GETFIELD, reg, ro, ko, 0, line);
    } else if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 255) {
      pc = emit(fs, OP_GETI, reg, ro, (int)key->u.ival, 0, line);
    } else {
      int kk;
      int rk = exp2rk(fs, key, &kk);
      pc = emit(fs, OP_GETTABLE, reg, ro, rk, kk ? 2 : 0, line);
    }
    vinfo(fs, pc, 1, obj);
  }
  fs->freereg = save;
}

static void codeglobal(FS *fs, Expr *e, int reg) {
  Expr *env = e->u.glb.env;
  int k = stringK(fs, e->u.glb.name);
  int pc;
  int line = e->line;
  if (env->k == E_UPVAL && k <= 0xffff) {
    pc = emit(fs, OP_GETTABUP, reg, env->u.up.idx, k, 0, line);
  } else {
    int save = fs->freereg;
    int ro = exp2anyreg(fs, env);
    if (k <= 0xffff)
      pc = emit(fs, OP_GETFIELD, reg, ro, k, 0, line);
    else {
      int kr = fs->freereg;
      reserveregs(fs, 1, line);
      loadk(fs, kr, k, line);
      pc = emit(fs, OP_GETTABLE, reg, ro, kr, 0, line);
    }
    fs->freereg = save;
  }
  vinfo(fs, pc, 1, env);
}

static void exp2reg(FS *fs, Expr *e, int reg) {
  int line = e->line;
  switch (e->k) {
    case E_NIL: emit(fs, OP_LOADNIL, reg, 0, 0, 0, line); break;
    case E_TRUE: emit(fs, OP_LOADTRUE, reg, 0, 0, 0, line); break;
    case E_FALSE: emit(fs, OP_LOADFALSE, reg, 0, 0, 0, line); break;
    case E_INT: loadint(fs, reg, e->u.ival, line); break;
    case E_FLT: loadk(fs, reg, fltK(fs, e->u.nval), line); break;
    case E_STR: loadk(fs, reg, stringK(fs, e->u.sval), line); break;
    case E_VARARG: emit(fs, OP_VARARG, reg, 0, 2, 0, line); break;
    case E_FUNC: {
      Proto *p = compile_func(fs, e->u.func, fs->cg->source);
      Proto *f = fs->f;
      int pc;
      if (fs->np >= f->sizep) {
        int ns = f->sizep ? f->sizep * 2 : 4;
        int i;
        f->p = mem_reallocvec(fs->L, f->p, f->sizep, ns, Proto *);
        for (i = f->sizep; i < ns; i++) f->p[i] = NULL;
        f->sizep = ns;
      }
      f->p[fs->np] = p;
      pc = emit(fs, OP_CLOSURE, reg, 0, 0, 0, e->u.func->endline ? line : line);
      fs->f->code[pc].u.bx = (uint32_t)fs->np;
      fs->np++;
      break;
    }
    case E_TABLE: {
      if (istoptemp(fs, reg)) {
        constructor(fs, e, reg);
      } else {
        int t = fs->freereg;
        reserveregs(fs, 1, line);
        constructor(fs, e, t);
        emit(fs, OP_MOVE, reg, t, 0, 0, line);
        fs->freereg = t;
      }
      break;
    }
    case E_BIN: {
      int op = e->op;
      if (iscompare(op)) {
        int jt = condjump(fs, e, 1);
        emit(fs, OP_LFALSESKIP, reg, 0, 0, 0, line);
        patchtohere(fs, jt);
        emit(fs, OP_LOADTRUE, reg, 0, 0, 0, line);
      } else if (op == OPR_CONCAT) {
        Expr *ops[256];
        Expr **opsv = ops;
        int nops = 0, cap = 256, i, base, pc;
        Expr *cur = e;
        while (cur->k == E_BIN && cur->op == OPR_CONCAT) {
          if (nops >= cap - 1) {
            Expr **nv = malloc(sizeof(Expr *) * cap * 2);
            memcpy(nv, opsv, sizeof(Expr *) * nops);
            if (opsv != ops) free(opsv);
            opsv = nv;
            cap *= 2;
          }
          opsv[nops++] = cur->u.bin.a;
          cur = cur->u.bin.b;
        }
        opsv[nops++] = cur;
        if (istoptemp(fs, reg)) {
          fs->freereg = reg;
          base = reg;
        } else
          base = fs->freereg;
        for (i = 0; i < nops; i++) exp2nextreg(fs, opsv[i]);
        pc = emit(fs, OP_CONCAT, base, nops, 0, 0, line);
        for (i = 0; i < nops && i < 255; i++) vinfo(fs, pc, i, opsv[i]);
        if (opsv != ops) free(opsv);
        fs->freereg = base + 1;
        if (base != reg) {
          emit(fs, OP_MOVE, reg, base, 0, 0, line);
          fs->freereg = base;
        }
      } else {
        int save = fs->freereg;
        int kb, kc, rb, rc, pc;
        rb = exp2rk(fs, e->u.bin.a, &kb);
        rc = exp2rk(fs, e->u.bin.b, &kc);
        fs->freereg = save;
        pc = emit(fs, arithop(op), reg, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line);
        vinfo(fs, pc, 1, e->u.bin.a);
        vinfo(fs, pc, 2, e->u.bin.b);
      }
      break;
    }
    case E_AND: case E_OR: {
      int target = reg;
      int j, pc;
      if (!istoptemp(fs, reg)) {
        target = fs->freereg;
        reserveregs(fs, 1, line);
      }
      exp2reg(fs, e->u.bin.a, target);
      pc = emit(fs, OP_TEST, target, 0, e->k == E_OR ? 1 : 0, 0, line);
      (void)pc;
      j = jump(fs, line);
      exp2reg(fs, e->u.bin.b, target);
      patchtohere(fs, j);
      if (target != reg) {
        emit(fs, OP_MOVE, reg, target, 0, 0, line);
        fs->freereg = target;
      }
      break;
    }
    case E_UN: {
      Expr *a = e->u.bin.a;
      int op = e->op;
      int save = fs->freereg;
      int rb, pc;
      if (op == OPR_MINUS && a->k == E_INT) {
        loadint(fs, reg, (lint)(0u - (luint)a->u.ival), line);
        break;
      }
      if (op == OPR_MINUS && a->k == E_FLT && a->u.nval != 0) {
        loadk(fs, reg, fltK(fs, -a->u.nval), line);
        break;
      }
      if (op == OPR_NOT) {
        switch (a->k) {
          case E_NIL: case E_FALSE:
            emit(fs, OP_LOADTRUE, reg, 0, 0, 0, line);
            return;
          case E_TRUE: case E_INT: case E_FLT: case E_STR:
            emit(fs, OP_LOADFALSE, reg, 0, 0, 0, line);
            return;
          default: break;
        }
      }
      rb = exp2anyreg(fs, a);
      fs->freereg = save;
      pc = emit(fs, op == OPR_MINUS ? OP_UNM : op == OPR_BNOT ? OP_BNOT :
                    op == OPR_NOT ? OP_NOT : OP_LEN, reg, rb, 0, 0, line);
      vinfo(fs, pc, 1, a);
      break;
    }
    case E_LOCAL: {
      if (e->u.var->reg != reg)
        emit(fs, OP_MOVE, reg, e->u.var->reg, 0, 0, line);
      break;
    }
    case E_UPVAL: emit(fs, OP_GETUPVAL, reg, e->u.up.idx, 0, 0, line); break;
    case E_GLOBAL: codeglobal(fs, e, reg); break;
    case E_INDEX: codeindex(fs, e, reg); break;
    case E_CALL: case E_METHCALL: {
      if (istoptemp(fs, reg)) {
        fs->freereg = reg;
        codecall(fs, e, 1);
      } else {
        int base = fs->freereg;
        codecall(fs, e, 1);
        emit(fs, OP_MOVE, reg, base, 0, 0, line);
        fs->freereg = base;
      }
      break;
    }
    case E_PAREN: exp2reg(fs, e->u.bin.a, reg); break;
    default: break;
  }
}

static int condjump(FS *fs, Expr *e, int jumpif) {
  int line = e->line;
  switch (e->k) {
    case E_NIL: case E_FALSE:
      return jumpif ? NO_JUMP : jump(fs, line);
    case E_TRUE: case E_INT: case E_FLT: case E_STR:
      return jumpif ? jump(fs, line) : NO_JUMP;
    case E_PAREN: {
      Expr *in = e->u.bin.a;
      if (!ismulti(in)) return condjump(fs, in, jumpif);
      break;
    }
    case E_UN:
      if (e->op == OPR_NOT) return condjump(fs, e->u.bin.a, !jumpif);
      break;
    case E_AND: {
      if (!jumpif) {
        int j1 = condjump(fs, e->u.bin.a, 0);
        int j2 = condjump(fs, e->u.bin.b, 0);
        concatjl(fs, &j1, j2);
        return j1;
      } else {
        int jf = condjump(fs, e->u.bin.a, 0);
        int jt = condjump(fs, e->u.bin.b, 1);
        patchtohere(fs, jf);
        return jt;
      }
    }
    case E_OR: {
      if (jumpif) {
        int j1 = condjump(fs, e->u.bin.a, 1);
        int j2 = condjump(fs, e->u.bin.b, 1);
        concatjl(fs, &j1, j2);
        return j1;
      } else {
        int jt = condjump(fs, e->u.bin.a, 1);
        int jf = condjump(fs, e->u.bin.b, 0);
        patchtohere(fs, jt);
        return jf;
      }
    }
    case E_BIN: {
      int op = e->op;
      if (iscompare(op)) {
        int save = fs->freereg;
        int kb, kc, rb, rc;
        rb = exp2rk(fs, e->u.bin.a, &kb);
        rc = exp2rk(fs, e->u.bin.b, &kc);
        fs->freereg = save;
        switch (op) {
          case OPR_EQ: emit(fs, OP_EQ, jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_NE: emit(fs, OP_EQ, !jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_LT: emit(fs, OP_LT, jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_LE: emit(fs, OP_LE, jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_GT: emit(fs, OP_LT, jumpif, rc, rb, (kc ? 1 : 0) | (kb ? 2 : 0), line); break;
          case OPR_GE: emit(fs, OP_LE, jumpif, rc, rb, (kc ? 1 : 0) | (kb ? 2 : 0), line); break;
        }
        return jump(fs, line);
      }
      break;
    }
    default: break;
  }
  {
    int save = fs->freereg;
    int r = exp2anyreg(fs, e);
    fs->freereg = save;
    emit(fs, OP_TEST, r, 0, jumpif, 0, line);
    return jump(fs, line);
  }
}

/* ---------------- variables / blocks ---------------- */

static void addlocvar(FS *fs, VarDesc *vd) {
  Proto *f = fs->f;
  if (fs->nlocvars >= f->sizelocvars) {
    int ns = f->sizelocvars ? f->sizelocvars * 2 : 16;
    f->locvars = mem_reallocvec(fs->L, f->locvars, f->sizelocvars, ns, LocVar);
    f->sizelocvars = ns;
  }
  f->locvars[fs->nlocvars].name = vd->name;
  f->locvars[fs->nlocvars].startpc = fs->pc;
  f->locvars[fs->nlocvars].endpc = fs->pc;
  vd->locidx = fs->nlocvars++;
}

/* activate variable at register reg */
static void activate(FS *fs, VarDesc *vd, int reg) {
  vd->reg = reg;
  if (fs->nactvar >= fs->sizeactvars) {
    int ns = fs->sizeactvars ? fs->sizeactvars * 2 : 32;
    fs->actvars = realloc(fs->actvars, sizeof(VarDesc *) * ns);
    fs->sizeactvars = ns;
  }
  fs->actvars[fs->nactvar++] = vd;
  addlocvar(fs, vd);
  if (vd->captured && fs->bl) fs->bl->upval = 1;
}

static void removevars(FS *fs, int tolevel) {
  while (fs->nactvar > tolevel) {
    VarDesc *vd = fs->actvars[--fs->nactvar];
    fs->f->locvars[vd->locidx].endpc = fs->pc;
  }
}

static void addlabel(FS *fs, CLabel **arr, int *n, int *size, Str *name, int pc, int line, int nactvar) {
  if (*n >= *size) {
    *size = *size ? *size * 2 : 16;
    *arr = realloc(*arr, sizeof(CLabel) * (*size));
  }
  (*arr)[*n].name = name;
  (*arr)[*n].pc = pc;
  (*arr)[*n].line = line;
  (*arr)[*n].nactvar = nactvar;
  (*arr)[*n].close = 0;
  (*n)++;
}

static void enterblock(FS *fs, CBlock *bl, int isloop) {
  bl->isloop = (uint8_t)isloop;
  bl->nactvar = fs->nactvar;
  bl->firstlabel = fs->cg->nlabels;
  bl->firstgoto = fs->cg->ngotos;
  bl->upval = 0;
  bl->insidetbc = (fs->bl != NULL && fs->bl->insidetbc);
  bl->prev = fs->bl;
  fs->bl = bl;
}

static void jumpscopeerror(FS *fs, CLabel *gt) {
  const char *varname = getstr(fs->actvars[gt->nactvar]->name);
  const char *msg = pushfstring(fs->L, "<goto %s> at line %d jumps into the scope of '%s'",
                                getstr(gt->name), gt->line, varname);
  cg_error(fs, msg, gt->line);
}

static void solvegoto(FS *fs, int g, CLabel *label) {
  CG *cg = fs->cg;
  CLabel *gt = &cg->gotos[g];
  int i;
  if (gt->nactvar < label->nactvar)
    jumpscopeerror(fs, gt);
  patchlist(fs, gt->pc, label->pc);
  for (i = g; i < cg->ngotos - 1; i++)
    cg->gotos[i] = cg->gotos[i + 1];
  cg->ngotos--;
}

static int solvegotos(FS *fs, CLabel *lb) {
  CG *cg = fs->cg;
  int i = fs->bl->firstgoto;
  int needsclose = 0;
  while (i < cg->ngotos) {
    if (cg->gotos[i].name == lb->name) {
      needsclose |= cg->gotos[i].close;
      solvegoto(fs, i, lb);
    } else
      i++;
  }
  return needsclose;
}

static int createlabel(FS *fs, Str *name, int line, int last) {
  CG *cg = fs->cg;
  CLabel lb;
  addlabel(fs, &cg->labels, &cg->nlabels, &cg->sizelabels, name, fs->pc, line, fs->nactvar);
  if (last)
    cg->labels[cg->nlabels - 1].nactvar = fs->bl->nactvar;
  lb = cg->labels[cg->nlabels - 1];
  if (solvegotos(fs, &lb)) {
    emit(fs, OP_CLOSE, fs->nactvar, 0, 0, 0, line);
    return 1;
  }
  return 0;
}

static void movegotosout(FS *fs, CBlock *bl) {
  CG *cg = fs->cg;
  int i;
  for (i = bl->firstgoto; i < cg->ngotos; i++) {
    CLabel *gt = &cg->gotos[i];
    if (gt->nactvar > bl->nactvar)
      gt->close |= bl->upval;
    gt->nactvar = bl->nactvar;
  }
}

static void undefgoto(FS *fs, CLabel *gt) {
  const char *msg;
  if (gt->name == fs->cg->breakname) {
    msg = pushfstring(fs->L, "break outside a loop at line %d", gt->line);
  } else {
    msg = pushfstring(fs->L, "no visible label '%s' for <goto> at line %d", getstr(gt->name), gt->line);
  }
  cg_error(fs, msg, fs->fa->endline ? fs->fa->endline : gt->line);
}

static void leaveblock(FS *fs, int line) {
  CBlock *bl = fs->bl;
  CG *cg = fs->cg;
  int hasclose = 0;
  int stklevel = bl->nactvar;
  removevars(fs, bl->nactvar);
  if (bl->isloop)
    hasclose = createlabel(fs, cg->breakname, 0, 0);
  if (!hasclose && bl->prev && bl->upval)
    emit(fs, OP_CLOSE, stklevel, 0, 0, 0, line);
  fs->freereg = stklevel;
  cg->nlabels = bl->firstlabel;
  fs->bl = bl->prev;
  if (bl->prev)
    movegotosout(fs, bl);
  else {
    if (bl->firstgoto < cg->ngotos)
      undefgoto(fs, &cg->gotos[bl->firstgoto]);
  }
}

static CLabel *findlabel(FS *fs, Str *name) {
  CG *cg = fs->cg;
  int i;
  for (i = fs->firstlabel; i < cg->nlabels; i++) {
    if (cg->labels[i].name == name) return &cg->labels[i];
  }
  return NULL;
}

/* ---------------- statements ---------------- */

static void adjust_assign(FS *fs, int nvars, Expr **exprs, int nexps, int line) {
  int i;
  for (i = 0; i < nexps; i++) {
    Expr *e = exprs[i];
    if (i == nexps - 1 && ismulti(e)) {
      int needed = nvars - i;
      if (needed < 0) needed = 0;
      exp2multi(fs, e, needed);
      if (needed == 0) {
        /* result discarded */
      }
      return;
    }
    exp2nextreg(fs, e);
  }
  if (nexps < nvars) {
    int r = fs->freereg;
    reserveregs(fs, nvars - nexps, line);
    emit(fs, OP_LOADNIL, r, nvars - nexps - 1, 0, 0, line);
  }
}

static void checktbc(FS *fs, VarDesc *vd, int line) {
  int pc = emit(fs, OP_TBC, vd->reg, 0, 0, 0, line);
  addvi(fs, pc, 0, VK_LOCAL, vd->name);
  fs->bl->upval = 1;
  fs->bl->insidetbc = 1;
}

static void localstat(FS *fs, Stat *s) {
  int nvars = s->u.local.nvars;
  int base = fs->freereg;
  int i;
  int line = s->line;
  adjust_assign(fs, nvars, s->u.local.exprs, s->u.local.nexprs, line);
  fs->freereg = base + nvars;
  checkstack(fs, 0, line);
  for (i = 0; i < nvars; i++) activate(fs, s->u.local.vars[i], base + i);
  for (i = 0; i < nvars; i++) {
    VarDesc *vd = s->u.local.vars[i];
    if (vd->kind == VD_CLOSE) checktbc(fs, vd, line);
  }
}

/* store value in register/constant 'v' into variable target (prefix already evaluated) */
typedef struct LHS {
  Expr *e;
  int kind;   /* 0 local, 1 upval, 2 indexed (reg obj), 3 indexed upvalue obj (tabup) */
  int obj;    /* register of object or upvalue index */
  int key;    /* key: register or constant */
  int keyk;   /* key is constant */
  int keykind;  /* 0 generic, 1 field (string const), 2 integer immediate */
} LHS;

static void prepare_lhs(FS *fs, Expr *t, LHS *l, Stat *s) {
  l->e = t;
  switch (t->k) {
    case E_LOCAL: l->kind = 0; l->obj = t->u.var->reg; break;
    case E_UPVAL: l->kind = 1; l->obj = t->u.up.idx; break;
    case E_GLOBAL: {
      Expr *env = t->u.glb.env;
      int k = stringK(fs, t->u.glb.name);
      if (env->k == E_UPVAL && k <= 0xffff) {
        l->kind = 3;
        l->obj = env->u.up.idx;
        l->key = k;
        l->keyk = 1;
        l->keykind = 1;
      } else {
        l->kind = 2;
        l->obj = exp2anyreg(fs, env);
        if (k <= 0xffff) {
          l->key = k;
          l->keyk = 1;
          l->keykind = 1;
        } else {
          int r = fs->freereg;
          reserveregs(fs, 1, t->line);
          loadk(fs, r, k, t->line);
          l->key = r;
          l->keyk = 0;
          l->keykind = 0;
        }
      }
      break;
    }
    case E_INDEX: {
      Expr *obj = t->u.idx.obj;
      Expr *key = t->u.idx.key;
      int k;
      if (obj->k == E_UPVAL && key->k == E_STR && (k = stringK(fs, key->u.sval)) <= 0xffff) {
        l->kind = 3;
        l->obj = obj->u.up.idx;
        l->key = k;
        l->keyk = 1;
        l->keykind = 1;
        break;
      }
      l->kind = 2;
      {
        /* check for conflict: object local assigned in same statement */
        int conflict = 0;
        int i;
        Expr *o = obj;
        while (o->k == E_PAREN) o = o->u.bin.a;
        if (s && o->k == E_LOCAL) {
          for (i = 0; i < s->u.assign.nt; i++) {
            Expr *tt = s->u.assign.targets[i];
            if (tt->k == E_LOCAL && tt->u.var == o->u.var) conflict = 1;
          }
        }
        if (conflict) {
          l->obj = fs->freereg;
          reserveregs(fs, 1, t->line);
          emit(fs, OP_MOVE, l->obj, o->u.var->reg, 0, 0, t->line);
        } else
          l->obj = exp2anyreg(fs, obj);
      }
      if (key->k == E_STR && (k = stringK(fs, key->u.sval)) <= 0xffff) {
        l->key = k;
        l->keyk = 1;
        l->keykind = 1;
      } else if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 0xffff) {
        l->key = (int)key->u.ival;
        l->keyk = 0;
        l->keykind = 2;
      } else {
        int conflict = 0;
        int i;
        Expr *o = key;
        while (o->k == E_PAREN) o = o->u.bin.a;
        if (s && o->k == E_LOCAL) {
          for (i = 0; i < s->u.assign.nt; i++) {
            Expr *tt = s->u.assign.targets[i];
            if (tt->k == E_LOCAL && tt->u.var == o->u.var) conflict = 1;
          }
        }
        if (conflict) {
          l->key = fs->freereg;
          reserveregs(fs, 1, t->line);
          emit(fs, OP_MOVE, l->key, o->u.var->reg, 0, 0, t->line);
          l->keyk = 0;
        } else
          l->key = exp2rk(fs, key, &l->keyk);
        l->keykind = 0;
      }
      break;
    }
    default: break;
  }
}

static void store_lhs(FS *fs, LHS *l, int v, int vk, int line) {
  int pc;
  Expr *t = l->e;
  switch (l->kind) {
    case 0:
      if (vk) loadk(fs, l->obj, v, line);
      else if (v != l->obj) emit(fs, OP_MOVE, l->obj, v, 0, 0, line);
      break;
    case 1: {
      if (vk) {
        int r = fs->freereg;
        reserveregs(fs, 1, line);
        loadk(fs, r, v, line);
        v = r;
        fs->freereg--;
      }
      emit(fs, OP_SETUPVAL, v, l->obj, 0, 0, line);
      break;
    }
    case 3:
      pc = emit(fs, OP_SETTABUP, l->obj, l->key, v, vk ? 2 : 0, line);
      if (t->k == E_GLOBAL) vinfo(fs, pc, 0, t->u.glb.env);
      else vinfo(fs, pc, 0, t->u.idx.obj);
      break;
    case 2:
      if (l->keykind == 1)
        pc = emit(fs, OP_SETFIELD, l->obj, l->key, v, vk ? 2 : 0, line);
      else if (l->keykind == 2)
        pc = emit(fs, OP_SETI, l->obj, l->key, v, vk ? 2 : 0, line);
      else
        pc = emit(fs, OP_SETTABLE, l->obj, l->key, v, (l->keyk ? 1 : 0) | (vk ? 2 : 0), line);
      if (t->k == E_GLOBAL) vinfo(fs, pc, 0, t->u.glb.env);
      else vinfo(fs, pc, 0, t->u.idx.obj);
      break;
  }
}

static void assignstat(FS *fs, Stat *s) {
  int nt = s->u.assign.nt;
  int ne = s->u.assign.ne;
  int line = s->line;
  int sline = s->line2 ? s->line2 : line;
  int save = fs->freereg;
  if (nt == 1 && ne == 1) {
    Expr *t = s->u.assign.targets[0];
    Expr *e = s->u.assign.exprs[0];
    LHS l;
    if (t->k == E_LOCAL) {
      int reg = t->u.var->reg;
      switch (e->k) {
        case E_TABLE: case E_CALL: case E_METHCALL: case E_AND: case E_OR: {
          int tmp = fs->freereg;
          reserveregs(fs, 1, line);
          exp2reg(fs, e, tmp);
          emit(fs, OP_MOVE, reg, tmp, 0, 0, line);
          break;
        }
        case E_BIN:
          if (e->op == OPR_CONCAT || iscompare(e->op)) {
            int tmp = fs->freereg;
            reserveregs(fs, 1, line);
            exp2reg(fs, e, tmp);
            emit(fs, OP_MOVE, reg, tmp, 0, 0, line);
            break;
          }
          exp2reg(fs, e, reg);
          break;
        default:
          exp2reg(fs, e, reg);
          break;
      }
      fs->freereg = save;
      return;
    }
    prepare_lhs(fs, t, &l, NULL);
    {
      int vk;
      int v = exp2rk(fs, e, &vk);
      store_lhs(fs, &l, v, vk, sline);
    }
    fs->freereg = save;
    return;
  }
  {
    LHS lhsbuf[16];
    LHS *lhs = nt <= 16 ? lhsbuf : malloc(sizeof(LHS) * nt);
    int i, base;
    for (i = 0; i < nt; i++) prepare_lhs(fs, s->u.assign.targets[i], &lhs[i], s);
    base = fs->freereg;
    adjust_assign(fs, nt, s->u.assign.exprs, ne, line);
    fs->freereg = base + nt;
    checkstack(fs, 0, line);
    for (i = nt - 1; i >= 0; i--)
      store_lhs(fs, &lhs[i], base + i, 0, sline);
    if (lhs != lhsbuf) free(lhs);
    fs->freereg = save;
  }
}

static void globalstat(FS *fs, Stat *s) {
  int nt = s->u.global.nt;
  int save = fs->freereg;
  int line = s->line;
  int base = fs->freereg;
  int i;
  adjust_assign(fs, nt, s->u.global.exprs, s->u.global.ne, line);
  fs->freereg = base + nt;
  for (i = 0; i < nt; i++) {
    Expr *t = s->u.global.targets[i];
    LHS l;
    int s2 = fs->freereg;
    int tmp = fs->freereg;
    int pc;
    if (t->k == E_GLOBAL) {
      reserveregs(fs, 1, line);
      codeglobal(fs, t, tmp);
      pc = emit(fs, OP_ERRNNIL, tmp, 0, 0, 0, line);
      fs->f->code[pc].u.bx = (uint32_t)stringK(fs, t->u.glb.name);
      fs->freereg = s2;
    }
    prepare_lhs(fs, t, &l, NULL);
    store_lhs(fs, &l, base + i, 0, line);
    fs->freereg = s2;
  }
  fs->freereg = save;
}

static void globalfuncstat(FS *fs, Stat *s) {
  int save = fs->freereg;
  int line = s->line;
  Expr *t = s->u.globalfunc.target;
  Expr fe;
  LHS l;
  int tmp = fs->freereg;
  int pc;
  if (t->k == E_GLOBAL) {
    reserveregs(fs, 1, line);
    codeglobal(fs, t, tmp);
    pc = emit(fs, OP_ERRNNIL, tmp, 0, 0, 0, line);
    fs->f->code[pc].u.bx = (uint32_t)stringK(fs, t->u.glb.name);
    fs->freereg = save;
  }
  memset(&fe, 0, sizeof(fe));
  fe.k = E_FUNC;
  fe.line = line;
  fe.u.func = s->u.globalfunc.f;
  prepare_lhs(fs, t, &l, NULL);
  tmp = fs->freereg;
  reserveregs(fs, 1, line);
  exp2reg(fs, &fe, tmp);
  store_lhs(fs, &l, tmp, 0, line);
  fs->freereg = save;
}

static void retstat(FS *fs, Stat *s) {
  int n = s->u.ret.n;
  Expr **es = s->u.ret.exprs;
  int line = s->line;
  int first = fs->nactvar;
  int nret;
  if (n == 0) {
    emit(fs, OP_RETURN0, first, 1, 0, 0, line);
    return;
  }
  if (n == 1 && !ismulti(es[0])) {
    int save = fs->freereg;
    int r = exp2anyreg(fs, es[0]);
    emit(fs, OP_RETURN1, r, 2, 0, 0, line);
    fs->freereg = save;
    return;
  }
  first = fs->freereg;
  if (n == 1 && (es[0]->k == E_CALL || es[0]->k == E_METHCALL) && !fs->bl->insidetbc) {
    codecall(fs, es[0], -1);
    fs->f->code[fs->pc - 1].op = OP_TAILCALL;
    emit(fs, OP_RETURN, first, 0, 0, 0, line);
    fs->freereg = first;
    return;
  }
  {
    int i;
    for (i = 0; i < n; i++) {
      if (i == n - 1 && ismulti(es[i])) exp2multi(fs, es[i], -1);
      else exp2nextreg(fs, es[i]);
    }
    if (ismulti(es[n - 1])) nret = 0;
    else nret = n + 1;
    emit(fs, OP_RETURN, first, nret, 0, 0, line);
    fs->freereg = first;
  }
}

static void whilestat(FS *fs, Stat *s) {
  CBlock bl;
  int whileinit = fs->pc;
  int condexit = condjump(fs, s->u.loop.cond, 0);
  enterblock(fs, &bl, 1);
  block(fs, s->u.loop.body, 0);
  patchlist(fs, jump(fs, s->line), whileinit);
  leaveblock(fs, s->line);
  patchtohere(fs, condexit);
}

static void stmtlist(FS *fs, Block *b);

static void repeatstat(FS *fs, Stat *s) {
  CBlock bl1, bl2;
  int repeat_init = fs->pc;
  int condexit;
  enterblock(fs, &bl1, 1);
  enterblock(fs, &bl2, 0);
  stmtlist(fs, s->u.loop.body);
  condexit = condjump(fs, s->u.loop.cond, 0);
  leaveblock(fs, s->line);
  if (bl2.upval) {
    int exit = jump(fs, s->line);
    patchtohere(fs, condexit);
    emit(fs, OP_CLOSE, bl2.nactvar, 0, 0, 0, s->line);
    condexit = jump(fs, s->line);
    patchtohere(fs, exit);
  }
  patchlist(fs, condexit, repeat_init);
  leaveblock(fs, s->line);
}

static void numforstat(FS *fs, Stat *s) {
  CBlock bl, inner;
  int base, prep, i;
  int line = s->line;
  enterblock(fs, &bl, 1);
  base = fs->freereg;
  exp2nextreg(fs, s->u.numfor.start);
  exp2nextreg(fs, s->u.numfor.limit);
  if (s->u.numfor.step) exp2nextreg(fs, s->u.numfor.step);
  else {
    int r = fs->freereg;
    reserveregs(fs, 1, line);
    loadint(fs, r, 1, line);
  }
  for (i = 0; i < 3; i++) activate(fs, s->u.numfor.hidden[i], base + i);
  prep = emitx(fs, OP_FORPREP, base, 0, s->line2 ? s->line2 : line);
  enterblock(fs, &inner, 0);
  reserveregs(fs, 1, line);
  activate(fs, s->u.numfor.var, base + 3);
  block(fs, s->u.numfor.body, 0);
  leaveblock(fs, line);
  {
    int endfor = emitx(fs, OP_FORLOOP, base, 0, line);
    fs->f->code[endfor].u.sbx = (prep + 1) - (endfor + 1);
    fs->f->code[prep].u.sbx = (endfor + 1) - (prep + 1);
  }
  leaveblock(fs, line);
}

static void genforstat(FS *fs, Stat *s) {
  CBlock bl, inner;
  int base, prep, i, nvars;
  int line = s->line;
  enterblock(fs, &bl, 1);
  base = fs->freereg;
  adjust_assign(fs, 4, s->u.genfor.exprs, s->u.genfor.nexprs, line);
  fs->freereg = base + 4;
  checkstack(fs, 3, line);
  for (i = 0; i < 4; i++) activate(fs, s->u.genfor.hidden[i], base + i);
  bl.upval = 1;
  bl.insidetbc = 1;
  prep = emitx(fs, OP_TFORPREP, base, 0, s->line2 ? s->line2 : line);
  nvars = s->u.genfor.nvars;
  enterblock(fs, &inner, 0);
  reserveregs(fs, nvars, line);
  for (i = 0; i < nvars; i++) activate(fs, s->u.genfor.vars[i], base + 4 + i);
  block(fs, s->u.genfor.body, 0);
  leaveblock(fs, line);
  fs->f->code[prep].u.sbx = fs->pc - (prep + 1);
  {
    int pc = emit(fs, OP_TFORCALL, base, 0, nvars, 0, line);
    int endfor;
    addvi(fs, pc, 0, VK_FORITER, str_newc(fs->L, "for iterator"));
    endfor = emitx(fs, OP_TFORLOOP, base, 0, line);
    fs->f->code[endfor].u.sbx = (prep + 1) - (endfor + 1);
  }
  leaveblock(fs, line);
}

static void ifstat(FS *fs, Stat *s) {
  int escape = NO_JUMP;
  int i;
  int n = s->u.ifs.n;
  for (i = 0; i < n; i++) {
    int jf = condjump(fs, s->u.ifs.conds[i], 0);
    block(fs, s->u.ifs.blocks[i], 0);
    if (i < n - 1 || s->u.ifs.elseb) {
      Block *b = s->u.ifs.blocks[i];
      /* avoid jump after unconditional return/break? keep simple */
      (void)b;
      concatjl(fs, &escape, jump(fs, s->line));
    }
    patchtohere(fs, jf);
  }
  if (s->u.ifs.elseb) block(fs, s->u.ifs.elseb, 0);
  patchtohere(fs, escape);
}

static void gotostat(FS *fs, Str *name, int line) {
  CLabel *lb = findlabel(fs, name);
  if (lb == NULL) {
    int pc = jump(fs, line);
    addlabel(fs, &fs->cg->gotos, &fs->cg->ngotos, &fs->cg->sizegotos, name, pc, line, fs->nactvar);
  } else {
    int lblevel = lb->nactvar;
    if (fs->nactvar > lblevel)
      emit(fs, OP_CLOSE, lblevel, 0, 0, 0, line);
    patchlist(fs, jump(fs, line), lb->pc);
  }
}

static int isvoidstat(Stat *s) {
  return s == NULL || s->k == S_LABEL;
}

static void labelstat(FS *fs, Stat *s) {
  Str *name = s->u.label.name;
  CLabel *lb = findlabel(fs, name);
  Stat *nx;
  int last = 1;
  if (lb != NULL) {
    const char *msg = pushfstring(fs->L, "label '%s' already defined on line %d", getstr(name), lb->line);
    cg_error(fs, msg, s->line);
  }
  /* label is 'last' if followed only by void statements (other labels) until block end */
  for (nx = s->next; nx != NULL; nx = nx->next) {
    if (!isvoidstat(nx)) { last = 0; break; }
  }
  createlabel(fs, name, s->line, last);
}

static void statement(FS *fs, Stat *s) {
  switch (s->k) {
    case S_CALL: {
      int save = fs->freereg;
      codecall(fs, s->u.call, 0);
      fs->freereg = save;
      break;
    }
    case S_LOCAL: localstat(fs, s); break;
    case S_ASSIGN: assignstat(fs, s); break;
    case S_DO: block(fs, s->u.blk.body, 0); break;
    case S_WHILE: whilestat(fs, s); break;
    case S_REPEAT: repeatstat(fs, s); break;
    case S_IF: ifstat(fs, s); break;
    case S_NUMFOR: numforstat(fs, s); break;
    case S_GENFOR: genforstat(fs, s); break;
    case S_RETURN: retstat(fs, s); break;
    case S_BREAK: {
      int pc = jump(fs, s->line);
      addlabel(fs, &fs->cg->gotos, &fs->cg->ngotos, &fs->cg->sizegotos, fs->cg->breakname, pc, s->line, fs->nactvar);
      break;
    }
    case S_GOTO: gotostat(fs, s->u.label.name, s->line); break;
    case S_LABEL: labelstat(fs, s); break;
    case S_LOCALFUNC: {
      int reg = fs->freereg;
      Expr fe;
      reserveregs(fs, 1, s->line);
      activate(fs, s->u.localfunc.var, reg);
      memset(&fe, 0, sizeof(fe));
      fe.k = E_FUNC;
      fe.line = s->line;
      fe.u.func = s->u.localfunc.f;
      exp2reg(fs, &fe, reg);
      fs->f->locvars[s->u.localfunc.var->locidx].startpc = fs->pc;
      break;
    }
    case S_GLOBAL: globalstat(fs, s); break;
    case S_GLOBALFUNC: globalfuncstat(fs, s); break;
  }
  fs->freereg = fs->nactvar;
}

static void stmtlist(FS *fs, Block *b) {
  Stat *s;
  for (s = b->first; s; s = s->next) statement(fs, s);
}

static void block(FS *fs, Block *b, int isloop) {
  CBlock bl;
  int line = b->last ? b->last->line : 0;
  enterblock(fs, &bl, isloop);
  stmtlist(fs, b);
  leaveblock(fs, line);
}

/* ---------------- functions ---------------- */

static void finish_proto(FS *fs) {
  Proto *f = fs->f;
  State *L = fs->L;
  f->code = mem_reallocvec(L, f->code, f->sizecode, fs->pc, Instr);
  f->lineinfo = mem_reallocvec(L, f->lineinfo, f->sizecode, fs->pc, int);
  f->sizecode = fs->pc;
  f->k = mem_reallocvec(L, f->k, f->sizek, fs->nk, TValue);
  f->sizek = fs->nk;
  f->p = mem_reallocvec(L, f->p, f->sizep, fs->np, Proto *);
  f->sizep = fs->np;
  f->locvars = mem_reallocvec(L, f->locvars, f->sizelocvars, fs->nlocvars, LocVar);
  f->sizelocvars = fs->nlocvars;
  f->varinfo = mem_reallocvec(L, f->varinfo, f->sizevarinfo, fs->nvi, VarInfo);
  f->sizevarinfo = fs->nvi;
  f->maxstack = (uint16_t)(fs->maxstack + 2);
}

static Proto *compile_func(FS *parent, FuncAST *fa, Str *source) {
  FS fs;
  CBlock bl;
  Proto *f;
  State *L = parent ? parent->L : NULL;
  int i;
  memset(&fs, 0, sizeof(fs));
  fs.prev = parent;
  fs.fa = fa;
  fs.L = L;
  fs.cg = parent->cg;
  fs.knil = fs.ktrue = fs.kfalse = -1;
  f = proto_new(L);
  fs.f = f;
  f->source = source;
  f->linedefined = fa->line;
  f->lastlinedefined = fa->lastline;
  f->numparams = (uint8_t)fa->nparams;
  f->is_vararg = (uint8_t)fa->is_vararg;
  /* upvalues */
  f->sizeup = fa->nups;
  if (fa->nups > 0) {
    f->upvals = mem_newvec(L, fa->nups, UpvalDesc);
    for (i = 0; i < fa->nups; i++) {
      UpvalAST *u = &fa->ups[i];
      f->upvals[i].name = u->name;
      f->upvals[i].instack = u->instack;
      f->upvals[i].kind = u->kind;
      f->upvals[i].idx = (uint16_t)(u->instack ? (u->pvar ? u->pvar->reg : 0) : u->pidx);
    }
  }
  fs.firstlabel = fs.cg->nlabels;
  fs.firstgoto = fs.cg->ngotos;
  enterblock(&fs, &bl, 0);
  for (i = 0; i < fa->nparams; i++) {
    reserveregs(&fs, 1, fa->line);
    activate(&fs, fa->params[i], i);
  }
  if (fa->vartab) {
    reserveregs(&fs, 1, fa->line);
    activate(&fs, fa->vartab, fa->nparams);
  }
  stmtlist(&fs, fa->body);
  emit(&fs, OP_RETURN0, fs.nactvar, 1, 0, 0, fa->lastline);
  leaveblock(&fs, fa->lastline);
  finish_proto(&fs);
  free(fs.actvars);
  return f;
}

Proto *codegen_main(State *L, FuncAST *fa, Str *source, Arena *ar) {
  CG cg;
  FS root;
  Proto *p;
  (void)ar;
  memset(&cg, 0, sizeof(cg));
  cg.L = L;
  cg.source = source;
  cg.breakname = str_newc(L, "break");
  cg.intindex = str_newc(L, "integer index");
  cg.qmark = str_newc(L, "?");
  memset(&root, 0, sizeof(root));
  root.L = L;
  root.cg = &cg;
  /* compile main with a dummy parent */
  {
    FS *parent = &root;
    LongJmp lj;
    lj.prev = L->errjmp;
    lj.status = TS_OK;
    L->errjmp = &lj;
    if (setjmp(lj.b) == 0) {
      p = compile_func(parent, fa, source);
    }
    L->errjmp = lj.prev;
    free(cg.labels);
    free(cg.gotos);
    if (lj.status != TS_OK) d_throw(L, lj.status);
  }
  return p;
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > code.c <<'EOF'
/* code generator: AST -> bytecode */
#include "ast.h"
#include "lex.h"
#include "opcodes.h"

#define MAXREGS 255

typedef struct CLabel {
  Str *name;
  int pc;
  int line;
  int nactvar;
  int close;
} CLabel;

typedef struct CBlock {
  struct CBlock *prev;
  int firstlabel, firstgoto;
  int nactvar;
  uint8_t upval;
  uint8_t isloop;
  uint8_t insidetbc;
} CBlock;

typedef struct CG {
  State *L;
  Str *source;
  Str *breakname;
  Str *intindex;
  Str *qmark;
  CLabel *labels;
  int nlabels, sizelabels;
  CLabel *gotos;
  int ngotos, sizegotos;
} CG;

typedef struct FS {
  struct FS *prev;
  FuncAST *fa;
  Proto *f;
  State *L;
  CG *cg;
  CBlock *bl;
  int pc;
  int nk;
  Table *kstr, *kint, *kflt;
  int knil, ktrue, kfalse;
  int np;
  int freereg;
  int nactvar;
  VarDesc **actvars;
  int sizeactvars;
  int nvi;
  int nlocvars;
  int firstlabel, firstgoto;
  int maxstack;
} FS;

static void cg_error(FS *fs, const char *msg, int line) __attribute__((noreturn));
static void cg_error(FS *fs, const char *msg, int line) {
  char buff[IDSIZE];
  chunkid(buff, getstr(fs->cg->source), fs->cg->source->len);
  pushfstring(fs->L, "%s:%d: %s", buff, line, msg);
  d_throw(fs->L, TS_ERRSYNTAX);
}

/* ---------------- emission ---------------- */

static int emit(FS *fs, int op, int a, int b, int c, int k, int line) {
  Proto *f = fs->f;
  Instr *i;
  if (fs->pc >= f->sizecode) {
    int ns = f->sizecode ? f->sizecode * 2 : 64;
    f->code = mem_reallocvec(fs->L, f->code, f->sizecode, ns, Instr);
    f->lineinfo = mem_reallocvec(fs->L, f->lineinfo, f->sizecode, ns, int);
    f->sizecode = ns;
  }
  i = &f->code[fs->pc];
  i->op = (uint8_t)op;
  i->k = (uint8_t)k;
  i->a = (uint16_t)a;
  i->u.bc.b = (uint16_t)b;
  i->u.bc.c = (uint16_t)c;
  f->lineinfo[fs->pc] = line;
  return fs->pc++;
}

static int emitx(FS *fs, int op, int a, int32_t sbx, int line) {
  int pc = emit(fs, op, a, 0, 0, 0, line);
  fs->f->code[pc].u.sbx = sbx;
  return pc;
}

static void addvi(FS *fs, int pc, int which, int kind, Str *name) {
  Proto *f = fs->f;
  VarInfo *v;
  if (kind == VK_NONE) return;
  if (fs->nvi >= f->sizevarinfo) {
    int ns = f->sizevarinfo ? f->sizevarinfo * 2 : 16;
    f->varinfo = mem_reallocvec(fs->L, f->varinfo, f->sizevarinfo, ns, VarInfo);
    f->sizevarinfo = ns;
  }
  v = &f->varinfo[fs->nvi++];
  v->pc = pc;
  v->which = (uint8_t)which;
  v->kind = (uint8_t)kind;
  v->name = name;
}

static int isenvexp(Expr *e) {
  if (e->k == E_LOCAL) return strcmp(getstr(e->u.var->name), "_ENV") == 0;
  if (e->k == E_UPVAL) return strcmp(getstr(e->u.up.name), "_ENV") == 0;
  return 0;
}

static int describe(FS *fs, Expr *e, Str **name) {
  while (e->k == E_PAREN) e = e->u.bin.a;
  switch (e->k) {
    case E_LOCAL: *name = e->u.var->name; return VK_LOCAL;
    case E_UPVAL: *name = e->u.up.name; return VK_UPVAL;
    case E_GLOBAL: *name = e->u.glb.name; return VK_GLOBAL;
    case E_INDEX: {
      Expr *key = e->u.idx.key;
      if (key->k == E_STR) {
        *name = key->u.sval;
        return isenvexp(e->u.idx.obj) ? VK_GLOBAL : VK_FIELD;
      }
      if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 255) {
        *name = fs->cg->intindex;
        return VK_FIELD;
      }
      *name = fs->cg->qmark;
      return VK_FIELD;
    }
    case E_STR: *name = e->u.sval; return VK_CONST;
    default: return VK_NONE;
  }
}

static void vinfo(FS *fs, int pc, int which, Expr *e) {
  Str *name = NULL;
  int kind = describe(fs, e, &name);
  addvi(fs, pc, which, kind, name);
}

/* ---------------- jumps ---------------- */

static int getjump(FS *fs, int pc) {
  int offset = fs->f->code[pc].u.sbx;
  if (offset == NO_JUMP) return NO_JUMP;
  return pc + 1 + offset;
}

static void fixjump(FS *fs, int pc, int dest) {
  fs->f->code[pc].u.sbx = dest - (pc + 1);
}

static void concatjl(FS *fs, int *l1, int l2) {
  if (l2 == NO_JUMP) return;
  if (*l1 == NO_JUMP) *l1 = l2;
  else {
    int list = *l1;
    int next;
    while ((next = getjump(fs, list)) != NO_JUMP) list = next;
    fixjump(fs, list, l2);
  }
}

static int jump(FS *fs, int line) {
  return emitx(fs, OP_JMP, 0, NO_JUMP, line);
}

static void patchlist(FS *fs, int list, int target) {
  while (list != NO_JUMP) {
    int next = getjump(fs, list);
    fixjump(fs, list, target);
    list = next;
  }
}

static void patchtohere(FS *fs, int list) {
  patchlist(fs, list, fs->pc);
}

/* ---------------- constants ---------------- */

static int addk(FS *fs, const TValue *v) {
  Proto *f = fs->f;
  int idx = fs->nk;
  if (idx >= f->sizek) {
    int ns = f->sizek ? f->sizek * 2 : 16;
    int i;
    f->k = mem_reallocvec(fs->L, f->k, f->sizek, ns, TValue);
    for (i = f->sizek; i < ns; i++) setnil(&f->k[i]);
    f->sizek = ns;
  }
  f->k[idx] = *v;
  fs->nk++;
  return idx;
}

static int cachedk(FS *fs, Table **cache, const TValue *key, const TValue *v) {
  const TValue *p;
  TValue *slot;
  int idx;
  if (*cache == NULL) *cache = tab_new(fs->L);
  p = tab_get(*cache, key);
  if (!isnil(p)) return (int)ivalue(p);
  idx = addk(fs, v);
  slot = tab_set(fs->L, *cache, key);
  setint(slot, idx);
  return idx;
}

static int stringK(FS *fs, Str *s) {
  TValue v;
  setstr(&v, s);
  return cachedk(fs, &fs->kstr, &v, &v);
}

static int intK(FS *fs, lint i) {
  TValue v;
  setint(&v, i);
  return cachedk(fs, &fs->kint, &v, &v);
}

static int fltK(FS *fs, lnum n) {
  TValue v, key;
  lint bits;
  memcpy(&bits, &n, sizeof(bits));
  setint(&key, bits);
  setflt(&v, n);
  return cachedk(fs, &fs->kflt, &key, &v);
}

static int nilK(FS *fs) {
  if (fs->knil < 0) {
    TValue v;
    setnil(&v);
    fs->knil = addk(fs, &v);
  }
  return fs->knil;
}

static int boolK(FS *fs, int b) {
  int *p = b ? &fs->ktrue : &fs->kfalse;
  if (*p < 0) {
    TValue v;
    setbool(&v, b);
    *p = addk(fs, &v);
  }
  return *p;
}

/* ---------------- registers ---------------- */

static void checkstack(FS *fs, int n, int line) {
  int newstack = fs->freereg + n;
  if (newstack > fs->maxstack) {
    if (newstack >= MAXREGS)
      cg_error(fs, "function or expression needs too many registers", line);
    fs->maxstack = newstack;
  }
}

static void reserveregs(FS *fs, int n, int line) {
  checkstack(fs, n, line);
  fs->freereg += n;
}

/* ---------------- forward decls ---------------- */
static void exp2reg(FS *fs, Expr *e, int reg);
static int exp2anyreg(FS *fs, Expr *e);
static void exp2multi(FS *fs, Expr *e, int nres);
static int condjump(FS *fs, Expr *e, int jumpif);
static void block(FS *fs, Block *b, int isloop);
static Proto *compile_func(FS *parent, FuncAST *fa, Str *source);

static int ismulti(Expr *e) {
  return e->k == E_CALL || e->k == E_METHCALL || e->k == E_VARARG;
}

static void exp2nextreg(FS *fs, Expr *e) {
  int r = fs->freereg;
  reserveregs(fs, 1, e->line);
  exp2reg(fs, e, r);
}

/* constant operand if possible */
static int exp2rk(FS *fs, Expr *e, int *isk) {
  int k = -1;
  switch (e->k) {
    case E_NIL: k = nilK(fs); break;
    case E_TRUE: k = boolK(fs, 1); break;
    case E_FALSE: k = boolK(fs, 0); break;
    case E_INT: k = intK(fs, e->u.ival); break;
    case E_FLT: k = fltK(fs, e->u.nval); break;
    case E_STR: k = stringK(fs, e->u.sval); break;
    default: break;
  }
  if (k >= 0 && k <= 0xffff) {
    *isk = 1;
    return k;
  }
  *isk = 0;
  return exp2anyreg(fs, e);
}

static int exp2anyreg(FS *fs, Expr *e) {
  Expr *ie = e;
  while (ie->k == E_PAREN) ie = ie->u.bin.a;
  if (ie->k == E_LOCAL) return ie->u.var->reg;
  {
    int r = fs->freereg;
    reserveregs(fs, 1, e->line);
    exp2reg(fs, e, r);
    return r;
  }
}

static int istoptemp(FS *fs, int reg) {
  return reg >= fs->nactvar && reg == fs->freereg - 1;
}

/* compile a call expression with function at register base = freereg */
static void codecall(FS *fs, Expr *e, int nres) {
  int base = fs->freereg;
  int nargs, i, pc;
  int line = e->line;
  Expr **args = e->u.call.args;
  int n = e->u.call.nargs;
  if (e->k == E_METHCALL) {
    int obj, isk;
    int k;
    int save;
    reserveregs(fs, 2, line);
    save = fs->freereg;
    obj = exp2anyreg(fs, e->u.call.fn);
    fs->freereg = save;
    k = stringK(fs, e->u.call.mname);
    if (k > 0xffff) {
      int kr = fs->freereg;
      reserveregs(fs, 1, line);
      emitx(fs, OP_LOADK, kr, k, line);
      fs->f->code[fs->pc - 1].u.bx = (uint32_t)k;
      pc = emit(fs, OP_SELF, base, obj, kr, 0, line);
      fs->freereg = save;
    } else {
      pc = emit(fs, OP_SELF, base, obj, k, 2, line);
    }
    vinfo(fs, pc, 1, e->u.call.fn);
    isk = 0;
    (void)isk;
  } else {
    exp2nextreg(fs, e->u.call.fn);
  }
  for (i = 0; i < n; i++) {
    if (i == n - 1 && ismulti(args[i]))
      exp2multi(fs, args[i], -1);
    else
      exp2nextreg(fs, args[i]);
  }
  if (n > 0 && ismulti(args[n - 1]))
    nargs = 0;  /* to top */
  else
    nargs = fs->freereg - base;  /* includes function (and self) */
  pc = emit(fs, OP_CALL, base, nargs, nres + 1, 0, line);
  if (e->k == E_METHCALL)
    addvi(fs, pc, 0, VK_METHOD, e->u.call.mname);
  else
    vinfo(fs, pc, 0, e->u.call.fn);
  fs->freereg = base + (nres > 0 ? nres : 0);
  if (nres > 0) checkstack(fs, 0, line);
}

/* place multiple results of e starting at freereg; nres = -1 means all (to top) */
static void exp2multi(FS *fs, Expr *e, int nres) {
  if (e->k == E_VARARG) {
    int base = fs->freereg;
    emit(fs, OP_VARARG, base, 0, nres + 1, 0, e->line);
    if (nres > 0) reserveregs(fs, nres, e->line);
  } else {
    codecall(fs, e, nres);
    if (nres > 0) checkstack(fs, 0, e->line);
  }
}

static void loadint(FS *fs, int reg, lint i, int line) {
  if (i >= INT32_MIN && i <= INT32_MAX)
    emitx(fs, OP_LOADI, reg, (int32_t)i, line);
  else {
    int k = intK(fs, i);
    int pc = emit(fs, OP_LOADK, reg, 0, 0, 0, line);
    fs->f->code[pc].u.bx = (uint32_t)k;
  }
}

static void loadk(FS *fs, int reg, int k, int line) {
  int pc = emit(fs, OP_LOADK, reg, 0, 0, 0, line);
  fs->f->code[pc].u.bx = (uint32_t)k;
}

static int arithop(int opr) {
  switch (opr) {
    case OPR_ADD: return OP_ADD;
    case OPR_SUB: return OP_SUB;
    case OPR_MUL: return OP_MUL;
    case OPR_MOD: return OP_MOD;
    case OPR_POW: return OP_POW;
    case OPR_DIV: return OP_DIV;
    case OPR_IDIV: return OP_IDIV;
    case OPR_BAND: return OP_BAND;
    case OPR_BOR: return OP_BOR;
    case OPR_BXOR: return OP_BXOR;
    case OPR_SHL: return OP_SHL;
    case OPR_SHR: return OP_SHR;
    default: return -1;
  }
}

static int iscompare(int opr) {
  return opr >= OPR_EQ && opr <= OPR_GE;
}

/* table constructor into register reg (reg must be top temp) */
static void constructor(FS *fs, Expr *e, int reg) {
  int i, pending = 0, nlist = 0;
  int n = e->u.tab.n;
  TField *f = e->u.tab.f;
  int narr = e->u.tab.narr;
  int line = e->line;
  int pc;
  if (n > 0 && f[n - 1].key == NULL && ismulti(f[n - 1].val)) narr--;
  pc = emit(fs, OP_NEWTABLE, reg, narr > 0xffff ? 0xffff : narr,
            e->u.tab.nhash > 0xffff ? 0xffff : e->u.tab.nhash, 0, line);
  if (narr > 0xffff) {
    fs->f->code[pc].k = 1;
    emit(fs, OP_EXTRAARG, 0, 0, 0, 0, line);
    fs->f->code[fs->pc - 1].u.bx = (uint32_t)narr;
  }
  for (i = 0; i < n; i++) {
    TField *fl = &f[i];
    if (fl->key == NULL) {
      if (i == n - 1 && ismulti(fl->val)) {
        exp2multi(fs, fl->val, -1);
        emit(fs, OP_SETLIST, reg, 0, 0, 1, fl->line);
        emit(fs, OP_EXTRAARG, 0, 0, 0, 0, fl->line);
        fs->f->code[fs->pc - 1].u.bx = (uint32_t)nlist;
        fs->freereg = reg + 1;
        pending = 0;
        continue;
      }
      exp2nextreg(fs, fl->val);
      pending++;
      if (pending == LFIELDS_PER_FLUSH) {
        emit(fs, OP_SETLIST, reg, pending, 0, 1, fl->line);
        emit(fs, OP_EXTRAARG, 0, 0, 0, 0, fl->line);
        fs->f->code[fs->pc - 1].u.bx = (uint32_t)nlist;
        nlist += pending;
        pending = 0;
        fs->freereg = reg + 1;
      }
    } else {
      int save = fs->freereg;
      int kk, kv, rkey, rval;
      Expr *key = fl->key;
      if (key->k == E_STR && (rkey = stringK(fs, key->u.sval)) <= 0xffff) {
        rval = exp2rk(fs, fl->val, &kv);
        emit(fs, OP_SETFIELD, reg, rkey, rval, kv ? 2 : 0, fl->line);
      } else if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 0xffff) {
        rval = exp2rk(fs, fl->val, &kv);
        emit(fs, OP_SETI, reg, (int)key->u.ival, rval, kv ? 2 : 0, fl->line);
      } else {
        rkey = exp2rk(fs, key, &kk);
        rval = exp2rk(fs, fl->val, &kv);
        emit(fs, OP_SETTABLE, reg, rkey, rval, (kk ? 1 : 0) | (kv ? 2 : 0), fl->line);
      }
      fs->freereg = save;
    }
  }
  if (pending > 0) {
    emit(fs, OP_SETLIST, reg, pending, 0, 1, line);
    emit(fs, OP_EXTRAARG, 0, 0, 0, 0, line);
    fs->f->code[fs->pc - 1].u.bx = (uint32_t)nlist;
    fs->freereg = reg + 1;
  }
}

static void codeindex(FS *fs, Expr *e, int reg) {
  Expr *obj = e->u.idx.obj;
  Expr *key = e->u.idx.key;
  int save = fs->freereg;
  int line = e->line;
  int pc;
  int ko;
  if (obj->k == E_UPVAL && key->k == E_STR && (ko = stringK(fs, key->u.sval)) <= 0xffff) {
    pc = emit(fs, OP_GETTABUP, reg, obj->u.up.idx, ko, 0, line);
    vinfo(fs, pc, 1, obj);
    return;
  }
  {
    int ro = exp2anyreg(fs, obj);
    if (key->k == E_STR && (ko = stringK(fs, key->u.sval)) <= 0xffff) {
      pc = emit(fs, OP_GETFIELD, reg, ro, ko, 0, line);
    } else if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 255) {
      pc = emit(fs, OP_GETI, reg, ro, (int)key->u.ival, 0, line);
    } else {
      int kk;
      int rk = exp2rk(fs, key, &kk);
      pc = emit(fs, OP_GETTABLE, reg, ro, rk, kk ? 2 : 0, line);
    }
    vinfo(fs, pc, 1, obj);
  }
  fs->freereg = save;
}

static void codeglobal(FS *fs, Expr *e, int reg) {
  Expr *env = e->u.glb.env;
  int k = stringK(fs, e->u.glb.name);
  int pc;
  int line = e->line;
  if (env->k == E_UPVAL && k <= 0xffff) {
    pc = emit(fs, OP_GETTABUP, reg, env->u.up.idx, k, 0, line);
  } else {
    int save = fs->freereg;
    int ro = exp2anyreg(fs, env);
    if (k <= 0xffff)
      pc = emit(fs, OP_GETFIELD, reg, ro, k, 0, line);
    else {
      int kr = fs->freereg;
      reserveregs(fs, 1, line);
      loadk(fs, kr, k, line);
      pc = emit(fs, OP_GETTABLE, reg, ro, kr, 0, line);
    }
    fs->freereg = save;
  }
  vinfo(fs, pc, 1, env);
}

static void exp2reg(FS *fs, Expr *e, int reg) {
  int line = e->line;
  switch (e->k) {
    case E_NIL: emit(fs, OP_LOADNIL, reg, 0, 0, 0, line); break;
    case E_TRUE: emit(fs, OP_LOADTRUE, reg, 0, 0, 0, line); break;
    case E_FALSE: emit(fs, OP_LOADFALSE, reg, 0, 0, 0, line); break;
    case E_INT: loadint(fs, reg, e->u.ival, line); break;
    case E_FLT: loadk(fs, reg, fltK(fs, e->u.nval), line); break;
    case E_STR: loadk(fs, reg, stringK(fs, e->u.sval), line); break;
    case E_VARARG: emit(fs, OP_VARARG, reg, 0, 2, 0, line); break;
    case E_FUNC: {
      Proto *p = compile_func(fs, e->u.func, fs->cg->source);
      Proto *f = fs->f;
      int pc;
      if (fs->np >= f->sizep) {
        int ns = f->sizep ? f->sizep * 2 : 4;
        int i;
        f->p = mem_reallocvec(fs->L, f->p, f->sizep, ns, Proto *);
        for (i = f->sizep; i < ns; i++) f->p[i] = NULL;
        f->sizep = ns;
      }
      f->p[fs->np] = p;
      pc = emit(fs, OP_CLOSURE, reg, 0, 0, 0, e->u.func->endline ? line : line);
      fs->f->code[pc].u.bx = (uint32_t)fs->np;
      fs->np++;
      break;
    }
    case E_TABLE: {
      if (istoptemp(fs, reg)) {
        constructor(fs, e, reg);
      } else {
        int t = fs->freereg;
        reserveregs(fs, 1, line);
        constructor(fs, e, t);
        emit(fs, OP_MOVE, reg, t, 0, 0, line);
        fs->freereg = t;
      }
      break;
    }
    case E_BIN: {
      int op = e->op;
      if (iscompare(op)) {
        int jt = condjump(fs, e, 1);
        emit(fs, OP_LFALSESKIP, reg, 0, 0, 0, line);
        patchtohere(fs, jt);
        emit(fs, OP_LOADTRUE, reg, 0, 0, 0, line);
      } else if (op == OPR_CONCAT) {
        Expr *ops[256];
        Expr **opsv = ops;
        int nops = 0, cap = 256, i, base, pc;
        Expr *cur = e;
        while (cur->k == E_BIN && cur->op == OPR_CONCAT) {
          if (nops >= cap - 1) {
            Expr **nv = malloc(sizeof(Expr *) * cap * 2);
            memcpy(nv, opsv, sizeof(Expr *) * nops);
            if (opsv != ops) free(opsv);
            opsv = nv;
            cap *= 2;
          }
          opsv[nops++] = cur->u.bin.a;
          cur = cur->u.bin.b;
        }
        opsv[nops++] = cur;
        if (istoptemp(fs, reg)) {
          fs->freereg = reg;
          base = reg;
        } else
          base = fs->freereg;
        for (i = 0; i < nops; i++) exp2nextreg(fs, opsv[i]);
        pc = emit(fs, OP_CONCAT, base, nops, 0, 0, line);
        for (i = 0; i < nops && i < 255; i++) vinfo(fs, pc, i, opsv[i]);
        if (opsv != ops) free(opsv);
        fs->freereg = base + 1;
        if (base != reg) {
          emit(fs, OP_MOVE, reg, base, 0, 0, line);
          fs->freereg = base;
        }
      } else {
        int save = fs->freereg;
        int kb, kc, rb, rc, pc;
        rb = exp2rk(fs, e->u.bin.a, &kb);
        rc = exp2rk(fs, e->u.bin.b, &kc);
        fs->freereg = save;
        pc = emit(fs, arithop(op), reg, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line);
        vinfo(fs, pc, 1, e->u.bin.a);
        vinfo(fs, pc, 2, e->u.bin.b);
      }
      break;
    }
    case E_AND: case E_OR: {
      int target = reg;
      int j, pc;
      if (!istoptemp(fs, reg)) {
        target = fs->freereg;
        reserveregs(fs, 1, line);
      }
      exp2reg(fs, e->u.bin.a, target);
      pc = emit(fs, OP_TEST, target, 0, e->k == E_OR ? 1 : 0, 0, line);
      (void)pc;
      j = jump(fs, line);
      exp2reg(fs, e->u.bin.b, target);
      patchtohere(fs, j);
      if (target != reg) {
        emit(fs, OP_MOVE, reg, target, 0, 0, line);
        fs->freereg = target;
      }
      break;
    }
    case E_UN: {
      Expr *a = e->u.bin.a;
      int op = e->op;
      int save = fs->freereg;
      int rb, pc;
      if (op == OPR_MINUS && a->k == E_INT) {
        loadint(fs, reg, (lint)(0u - (luint)a->u.ival), line);
        break;
      }
      if (op == OPR_MINUS && a->k == E_FLT && a->u.nval != 0) {
        loadk(fs, reg, fltK(fs, -a->u.nval), line);
        break;
      }
      if (op == OPR_NOT) {
        switch (a->k) {
          case E_NIL: case E_FALSE:
            emit(fs, OP_LOADTRUE, reg, 0, 0, 0, line);
            return;
          case E_TRUE: case E_INT: case E_FLT: case E_STR:
            emit(fs, OP_LOADFALSE, reg, 0, 0, 0, line);
            return;
          default: break;
        }
      }
      rb = exp2anyreg(fs, a);
      fs->freereg = save;
      pc = emit(fs, op == OPR_MINUS ? OP_UNM : op == OPR_BNOT ? OP_BNOT :
                    op == OPR_NOT ? OP_NOT : OP_LEN, reg, rb, 0, 0, line);
      vinfo(fs, pc, 1, a);
      break;
    }
    case E_LOCAL: {
      if (e->u.var->reg != reg)
        emit(fs, OP_MOVE, reg, e->u.var->reg, 0, 0, line);
      break;
    }
    case E_UPVAL: emit(fs, OP_GETUPVAL, reg, e->u.up.idx, 0, 0, line); break;
    case E_GLOBAL: codeglobal(fs, e, reg); break;
    case E_INDEX: codeindex(fs, e, reg); break;
    case E_CALL: case E_METHCALL: {
      if (istoptemp(fs, reg)) {
        fs->freereg = reg;
        codecall(fs, e, 1);
      } else {
        int base = fs->freereg;
        codecall(fs, e, 1);
        emit(fs, OP_MOVE, reg, base, 0, 0, line);
        fs->freereg = base;
      }
      break;
    }
    case E_PAREN: exp2reg(fs, e->u.bin.a, reg); break;
    default: break;
  }
}

static int condjump(FS *fs, Expr *e, int jumpif) {
  int line = e->line;
  switch (e->k) {
    case E_NIL: case E_FALSE:
      return jumpif ? NO_JUMP : jump(fs, line);
    case E_TRUE: case E_INT: case E_FLT: case E_STR:
      return jumpif ? jump(fs, line) : NO_JUMP;
    case E_PAREN: {
      Expr *in = e->u.bin.a;
      if (!ismulti(in)) return condjump(fs, in, jumpif);
      break;
    }
    case E_UN:
      if (e->op == OPR_NOT) return condjump(fs, e->u.bin.a, !jumpif);
      break;
    case E_AND: {
      if (!jumpif) {
        int j1 = condjump(fs, e->u.bin.a, 0);
        int j2 = condjump(fs, e->u.bin.b, 0);
        concatjl(fs, &j1, j2);
        return j1;
      } else {
        int jf = condjump(fs, e->u.bin.a, 0);
        int jt = condjump(fs, e->u.bin.b, 1);
        patchtohere(fs, jf);
        return jt;
      }
    }
    case E_OR: {
      if (jumpif) {
        int j1 = condjump(fs, e->u.bin.a, 1);
        int j2 = condjump(fs, e->u.bin.b, 1);
        concatjl(fs, &j1, j2);
        return j1;
      } else {
        int jt = condjump(fs, e->u.bin.a, 1);
        int jf = condjump(fs, e->u.bin.b, 0);
        patchtohere(fs, jt);
        return jf;
      }
    }
    case E_BIN: {
      int op = e->op;
      if (iscompare(op)) {
        int save = fs->freereg;
        int kb, kc, rb, rc;
        rb = exp2rk(fs, e->u.bin.a, &kb);
        rc = exp2rk(fs, e->u.bin.b, &kc);
        fs->freereg = save;
        switch (op) {
          case OPR_EQ: emit(fs, OP_EQ, jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_NE: emit(fs, OP_EQ, !jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_LT: emit(fs, OP_LT, jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_LE: emit(fs, OP_LE, jumpif, rb, rc, (kb ? 1 : 0) | (kc ? 2 : 0), line); break;
          case OPR_GT: emit(fs, OP_LT, jumpif, rc, rb, (kc ? 1 : 0) | (kb ? 2 : 0), line); break;
          case OPR_GE: emit(fs, OP_LE, jumpif, rc, rb, (kc ? 1 : 0) | (kb ? 2 : 0), line); break;
        }
        return jump(fs, line);
      }
      break;
    }
    default: break;
  }
  {
    int save = fs->freereg;
    int r = exp2anyreg(fs, e);
    fs->freereg = save;
    emit(fs, OP_TEST, r, 0, jumpif, 0, line);
    return jump(fs, line);
  }
}

/* ---------------- variables / blocks ---------------- */

static void addlocvar(FS *fs, VarDesc *vd) {
  Proto *f = fs->f;
  if (fs->nlocvars >= f->sizelocvars) {
    int ns = f->sizelocvars ? f->sizelocvars * 2 : 16;
    f->locvars = mem_reallocvec(fs->L, f->locvars, f->sizelocvars, ns, LocVar);
    f->sizelocvars = ns;
  }
  f->locvars[fs->nlocvars].name = vd->name;
  f->locvars[fs->nlocvars].startpc = fs->pc;
  f->locvars[fs->nlocvars].endpc = fs->pc;
  vd->locidx = fs->nlocvars++;
}

/* activate variable at register reg */
static void activate(FS *fs, VarDesc *vd, int reg) {
  vd->reg = reg;
  if (fs->nactvar >= fs->sizeactvars) {
    int ns = fs->sizeactvars ? fs->sizeactvars * 2 : 32;
    fs->actvars = realloc(fs->actvars, sizeof(VarDesc *) * ns);
    fs->sizeactvars = ns;
  }
  fs->actvars[fs->nactvar++] = vd;
  addlocvar(fs, vd);
  if (vd->captured && fs->bl) fs->bl->upval = 1;
}

static void removevars(FS *fs, int tolevel) {
  while (fs->nactvar > tolevel) {
    VarDesc *vd = fs->actvars[--fs->nactvar];
    fs->f->locvars[vd->locidx].endpc = fs->pc;
  }
}

static void addlabel(FS *fs, CLabel **arr, int *n, int *size, Str *name, int pc, int line, int nactvar) {
  if (*n >= *size) {
    *size = *size ? *size * 2 : 16;
    *arr = realloc(*arr, sizeof(CLabel) * (*size));
  }
  (*arr)[*n].name = name;
  (*arr)[*n].pc = pc;
  (*arr)[*n].line = line;
  (*arr)[*n].nactvar = nactvar;
  (*arr)[*n].close = 0;
  (*n)++;
}

static void enterblock(FS *fs, CBlock *bl, int isloop) {
  bl->isloop = (uint8_t)isloop;
  bl->nactvar = fs->nactvar;
  bl->firstlabel = fs->cg->nlabels;
  bl->firstgoto = fs->cg->ngotos;
  bl->upval = 0;
  bl->insidetbc = (fs->bl != NULL && fs->bl->insidetbc);
  bl->prev = fs->bl;
  fs->bl = bl;
}

static void jumpscopeerror(FS *fs, CLabel *gt) {
  const char *varname = getstr(fs->actvars[gt->nactvar]->name);
  const char *msg = pushfstring(fs->L, "<goto %s> at line %d jumps into the scope of '%s'",
                                getstr(gt->name), gt->line, varname);
  cg_error(fs, msg, gt->line);
}

static void solvegoto(FS *fs, int g, CLabel *label) {
  CG *cg = fs->cg;
  CLabel *gt = &cg->gotos[g];
  int i;
  if (gt->nactvar < label->nactvar)
    jumpscopeerror(fs, gt);
  patchlist(fs, gt->pc, label->pc);
  for (i = g; i < cg->ngotos - 1; i++)
    cg->gotos[i] = cg->gotos[i + 1];
  cg->ngotos--;
}

static int solvegotos(FS *fs, CLabel *lb) {
  CG *cg = fs->cg;
  int i = fs->bl->firstgoto;
  int needsclose = 0;
  while (i < cg->ngotos) {
    if (cg->gotos[i].name == lb->name) {
      needsclose |= cg->gotos[i].close;
      solvegoto(fs, i, lb);
    } else
      i++;
  }
  return needsclose;
}

static int createlabel(FS *fs, Str *name, int line, int last) {
  CG *cg = fs->cg;
  CLabel lb;
  addlabel(fs, &cg->labels, &cg->nlabels, &cg->sizelabels, name, fs->pc, line, fs->nactvar);
  if (last)
    cg->labels[cg->nlabels - 1].nactvar = fs->bl->nactvar;
  lb = cg->labels[cg->nlabels - 1];
  if (solvegotos(fs, &lb)) {
    emit(fs, OP_CLOSE, fs->nactvar, 0, 0, 0, line);
    return 1;
  }
  return 0;
}

static void movegotosout(FS *fs, CBlock *bl) {
  CG *cg = fs->cg;
  int i;
  for (i = bl->firstgoto; i < cg->ngotos; i++) {
    CLabel *gt = &cg->gotos[i];
    if (gt->nactvar > bl->nactvar)
      gt->close |= bl->upval;
    gt->nactvar = bl->nactvar;
  }
}

static void undefgoto(FS *fs, CLabel *gt) {
  const char *msg;
  if (gt->name == fs->cg->breakname) {
    msg = pushfstring(fs->L, "break outside a loop at line %d", gt->line);
  } else {
    msg = pushfstring(fs->L, "no visible label '%s' for <goto> at line %d", getstr(gt->name), gt->line);
  }
  cg_error(fs, msg, fs->fa->endline ? fs->fa->endline : gt->line);
}

static void leaveblock(FS *fs, int line) {
  CBlock *bl = fs->bl;
  CG *cg = fs->cg;
  int hasclose = 0;
  int stklevel = bl->nactvar;
  removevars(fs, bl->nactvar);
  if (bl->isloop)
    hasclose = createlabel(fs, cg->breakname, 0, 0);
  if (!hasclose && bl->prev && bl->upval)
    emit(fs, OP_CLOSE, stklevel, 0, 0, 0, line);
  fs->freereg = stklevel;
  cg->nlabels = bl->firstlabel;
  fs->bl = bl->prev;
  if (bl->prev)
    movegotosout(fs, bl);
  else {
    if (bl->firstgoto < cg->ngotos)
      undefgoto(fs, &cg->gotos[bl->firstgoto]);
  }
}

static CLabel *findlabel(FS *fs, Str *name) {
  CG *cg = fs->cg;
  int i;
  for (i = fs->firstlabel; i < cg->nlabels; i++) {
    if (cg->labels[i].name == name) return &cg->labels[i];
  }
  return NULL;
}

/* ---------------- statements ---------------- */

static void adjust_assign(FS *fs, int nvars, Expr **exprs, int nexps, int line) {
  int i;
  for (i = 0; i < nexps; i++) {
    Expr *e = exprs[i];
    if (i == nexps - 1 && ismulti(e)) {
      int needed = nvars - i;
      if (needed < 0) needed = 0;
      exp2multi(fs, e, needed);
      if (needed == 0) {
        /* result discarded */
      }
      return;
    }
    exp2nextreg(fs, e);
  }
  if (nexps < nvars) {
    int r = fs->freereg;
    reserveregs(fs, nvars - nexps, line);
    emit(fs, OP_LOADNIL, r, nvars - nexps - 1, 0, 0, line);
  }
}

static void checktbc(FS *fs, VarDesc *vd, int line) {
  int pc = emit(fs, OP_TBC, vd->reg, 0, 0, 0, line);
  addvi(fs, pc, 0, VK_LOCAL, vd->name);
  fs->bl->upval = 1;
  fs->bl->insidetbc = 1;
}

static void localstat(FS *fs, Stat *s) {
  int nvars = s->u.local.nvars;
  int base = fs->freereg;
  int i;
  int line = s->line;
  adjust_assign(fs, nvars, s->u.local.exprs, s->u.local.nexprs, line);
  fs->freereg = base + nvars;
  checkstack(fs, 0, line);
  for (i = 0; i < nvars; i++) activate(fs, s->u.local.vars[i], base + i);
  for (i = 0; i < nvars; i++) {
    VarDesc *vd = s->u.local.vars[i];
    if (vd->kind == VD_CLOSE) checktbc(fs, vd, line);
  }
}

/* store value in register/constant 'v' into variable target (prefix already evaluated) */
typedef struct LHS {
  Expr *e;
  int kind;   /* 0 local, 1 upval, 2 indexed (reg obj), 3 indexed upvalue obj (tabup) */
  int obj;    /* register of object or upvalue index */
  int key;    /* key: register or constant */
  int keyk;   /* key is constant */
  int keykind;  /* 0 generic, 1 field (string const), 2 integer immediate */
} LHS;

static void prepare_lhs(FS *fs, Expr *t, LHS *l, Stat *s) {
  l->e = t;
  switch (t->k) {
    case E_LOCAL: l->kind = 0; l->obj = t->u.var->reg; break;
    case E_UPVAL: l->kind = 1; l->obj = t->u.up.idx; break;
    case E_GLOBAL: {
      Expr *env = t->u.glb.env;
      int k = stringK(fs, t->u.glb.name);
      if (env->k == E_UPVAL && k <= 0xffff) {
        l->kind = 3;
        l->obj = env->u.up.idx;
        l->key = k;
        l->keyk = 1;
        l->keykind = 1;
      } else {
        l->kind = 2;
        l->obj = exp2anyreg(fs, env);
        if (k <= 0xffff) {
          l->key = k;
          l->keyk = 1;
          l->keykind = 1;
        } else {
          int r = fs->freereg;
          reserveregs(fs, 1, t->line);
          loadk(fs, r, k, t->line);
          l->key = r;
          l->keyk = 0;
          l->keykind = 0;
        }
      }
      break;
    }
    case E_INDEX: {
      Expr *obj = t->u.idx.obj;
      Expr *key = t->u.idx.key;
      int k;
      if (obj->k == E_UPVAL && key->k == E_STR && (k = stringK(fs, key->u.sval)) <= 0xffff) {
        l->kind = 3;
        l->obj = obj->u.up.idx;
        l->key = k;
        l->keyk = 1;
        l->keykind = 1;
        break;
      }
      l->kind = 2;
      {
        /* check for conflict: object local assigned in same statement */
        int conflict = 0;
        int i;
        Expr *o = obj;
        while (o->k == E_PAREN) o = o->u.bin.a;
        if (s && o->k == E_LOCAL) {
          for (i = 0; i < s->u.assign.nt; i++) {
            Expr *tt = s->u.assign.targets[i];
            if (tt->k == E_LOCAL && tt->u.var == o->u.var) conflict = 1;
          }
        }
        if (conflict) {
          l->obj = fs->freereg;
          reserveregs(fs, 1, t->line);
          emit(fs, OP_MOVE, l->obj, o->u.var->reg, 0, 0, t->line);
        } else
          l->obj = exp2anyreg(fs, obj);
      }
      if (key->k == E_STR && (k = stringK(fs, key->u.sval)) <= 0xffff) {
        l->key = k;
        l->keyk = 1;
        l->keykind = 1;
      } else if (key->k == E_INT && key->u.ival >= 0 && key->u.ival <= 0xffff) {
        l->key = (int)key->u.ival;
        l->keyk = 0;
        l->keykind = 2;
      } else {
        int conflict = 0;
        int i;
        Expr *o = key;
        while (o->k == E_PAREN) o = o->u.bin.a;
        if (s && o->k == E_LOCAL) {
          for (i = 0; i < s->u.assign.nt; i++) {
            Expr *tt = s->u.assign.targets[i];
            if (tt->k == E_LOCAL && tt->u.var == o->u.var) conflict = 1;
          }
        }
        if (conflict) {
          l->key = fs->freereg;
          reserveregs(fs, 1, t->line);
          emit(fs, OP_MOVE, l->key, o->u.var->reg, 0, 0, t->line);
          l->keyk = 0;
        } else
          l->key = exp2rk(fs, key, &l->keyk);
        l->keykind = 0;
      }
      break;
    }
    default: break;
  }
}

static void store_lhs(FS *fs, LHS *l, int v, int vk, int line) {
  int pc;
  Expr *t = l->e;
  switch (l->kind) {
    case 0:
      if (vk) loadk(fs, l->obj, v, line);
      else if (v != l->obj) emit(fs, OP_MOVE, l->obj, v, 0, 0, line);
      break;
    case 1: {
      if (vk) {
        int r = fs->freereg;
        reserveregs(fs, 1, line);
        loadk(fs, r, v, line);
        v = r;
        fs->freereg--;
      }
      emit(fs, OP_SETUPVAL, v, l->obj, 0, 0, line);
      break;
    }
    case 3:
      pc = emit(fs, OP_SETTABUP, l->obj, l->key, v, vk ? 2 : 0, line);
      if (t->k == E_GLOBAL) vinfo(fs, pc, 0, t->u.glb.env);
      else vinfo(fs, pc, 0, t->u.idx.obj);
      break;
    case 2:
      if (l->keykind == 1)
        pc = emit(fs, OP_SETFIELD, l->obj, l->key, v, vk ? 2 : 0, line);
      else if (l->keykind == 2)
        pc = emit(fs, OP_SETI, l->obj, l->key, v, vk ? 2 : 0, line);
      else
        pc = emit(fs, OP_SETTABLE, l->obj, l->key, v, (l->keyk ? 1 : 0) | (vk ? 2 : 0), line);
      if (t->k == E_GLOBAL) vinfo(fs, pc, 0, t->u.glb.env);
      else vinfo(fs, pc, 0, t->u.idx.obj);
      break;
  }
}

static void assignstat(FS *fs, Stat *s) {
  int nt = s->u.assign.nt;
  int ne = s->u.assign.ne;
  int line = s->line;
  int sline = s->line2 ? s->line2 : line;
  int save = fs->freereg;
  if (nt == 1 && ne == 1) {
    Expr *t = s->u.assign.targets[0];
    Expr *e = s->u.assign.exprs[0];
    LHS l;
    if (t->k == E_LOCAL) {
      int reg = t->u.var->reg;
      switch (e->k) {
        case E_TABLE: case E_CALL: case E_METHCALL: case E_AND: case E_OR: {
          int tmp = fs->freereg;
          reserveregs(fs, 1, line);
          exp2reg(fs, e, tmp);
          emit(fs, OP_MOVE, reg, tmp, 0, 0, line);
          break;
        }
        case E_BIN:
          if (e->op == OPR_CONCAT || iscompare(e->op)) {
            int tmp = fs->freereg;
            reserveregs(fs, 1, line);
            exp2reg(fs, e, tmp);
            emit(fs, OP_MOVE, reg, tmp, 0, 0, line);
            break;
          }
          exp2reg(fs, e, reg);
          break;
        default:
          exp2reg(fs, e, reg);
          break;
      }
      fs->freereg = save;
      return;
    }
    prepare_lhs(fs, t, &l, NULL);
    {
      int vk;
      int v = exp2rk(fs, e, &vk);
      store_lhs(fs, &l, v, vk, sline);
    }
    fs->freereg = save;
    return;
  }
  {
    LHS lhsbuf[16];
    LHS *lhs = nt <= 16 ? lhsbuf : malloc(sizeof(LHS) * nt);
    int i, base;
    for (i = 0; i < nt; i++) prepare_lhs(fs, s->u.assign.targets[i], &lhs[i], s);
    base = fs->freereg;
    adjust_assign(fs, nt, s->u.assign.exprs, ne, line);
    fs->freereg = base + nt;
    checkstack(fs, 0, line);
    for (i = nt - 1; i >= 0; i--)
      store_lhs(fs, &lhs[i], base + i, 0, sline);
    if (lhs != lhsbuf) free(lhs);
    fs->freereg = save;
  }
}

static void globalstat(FS *fs, Stat *s) {
  int nt = s->u.global.nt;
  int save = fs->freereg;
  int line = s->line;
  int base = fs->freereg;
  int i;
  adjust_assign(fs, nt, s->u.global.exprs, s->u.global.ne, line);
  fs->freereg = base + nt;
  for (i = 0; i < nt; i++) {
    Expr *t = s->u.global.targets[i];
    LHS l;
    int s2 = fs->freereg;
    int tmp = fs->freereg;
    int pc;
    if (t->k == E_GLOBAL) {
      reserveregs(fs, 1, line);
      codeglobal(fs, t, tmp);
      pc = emit(fs, OP_ERRNNIL, tmp, 0, 0, 0, line);
      fs->f->code[pc].u.bx = (uint32_t)stringK(fs, t->u.glb.name);
      fs->freereg = s2;
    }
    prepare_lhs(fs, t, &l, NULL);
    store_lhs(fs, &l, base + i, 0, line);
    fs->freereg = s2;
  }
  fs->freereg = save;
}

static void globalfuncstat(FS *fs, Stat *s) {
  int save = fs->freereg;
  int line = s->line;
  Expr *t = s->u.globalfunc.target;
  Expr fe;
  LHS l;
  int tmp = fs->freereg;
  int pc;
  if (t->k == E_GLOBAL) {
    reserveregs(fs, 1, line);
    codeglobal(fs, t, tmp);
    pc = emit(fs, OP_ERRNNIL, tmp, 0, 0, 0, line);
    fs->f->code[pc].u.bx = (uint32_t)stringK(fs, t->u.glb.name);
    fs->freereg = save;
  }
  memset(&fe, 0, sizeof(fe));
  fe.k = E_FUNC;
  fe.line = line;
  fe.u.func = s->u.globalfunc.f;
  prepare_lhs(fs, t, &l, NULL);
  tmp = fs->freereg;
  reserveregs(fs, 1, line);
  exp2reg(fs, &fe, tmp);
  store_lhs(fs, &l, tmp, 0, line);
  fs->freereg = save;
}

static void retstat(FS *fs, Stat *s) {
  int n = s->u.ret.n;
  Expr **es = s->u.ret.exprs;
  int line = s->line;
  int first = fs->nactvar;
  int nret;
  if (n == 0) {
    emit(fs, OP_RETURN0, first, 1, 0, 0, line);
    return;
  }
  if (n == 1 && !ismulti(es[0])) {
    int save = fs->freereg;
    int r = exp2anyreg(fs, es[0]);
    emit(fs, OP_RETURN1, r, 2, 0, 0, line);
    fs->freereg = save;
    return;
  }
  first = fs->freereg;
  if (n == 1 && (es[0]->k == E_CALL || es[0]->k == E_METHCALL) && !fs->bl->insidetbc) {
    codecall(fs, es[0], -1);
    fs->f->code[fs->pc - 1].op = OP_TAILCALL;
    emit(fs, OP_RETURN, first, 0, 0, 0, line);
    fs->freereg = first;
    return;
  }
  {
    int i;
    for (i = 0; i < n; i++) {
      if (i == n - 1 && ismulti(es[i])) exp2multi(fs, es[i], -1);
      else exp2nextreg(fs, es[i]);
    }
    if (ismulti(es[n - 1])) nret = 0;
    else nret = n + 1;
    emit(fs, OP_RETURN, first, nret, 0, 0, line);
    fs->freereg = first;
  }
}

static void whilestat(FS *fs, Stat *s) {
  CBlock bl;
  int whileinit = fs->pc;
  int condexit = condjump(fs, s->u.loop.cond, 0);
  enterblock(fs, &bl, 1);
  block(fs, s->u.loop.body, 0);
  patchlist(fs, jump(fs, s->line), whileinit);
  leaveblock(fs, s->line);
  patchtohere(fs, condexit);
}

static void stmtlist(FS *fs, Block *b);

static void repeatstat(FS *fs, Stat *s) {
  CBlock bl1, bl2;
  int repeat_init = fs->pc;
  int condexit;
  enterblock(fs, &bl1, 1);
  enterblock(fs, &bl2, 0);
  stmtlist(fs, s->u.loop.body);
  condexit = condjump(fs, s->u.loop.cond, 0);
  leaveblock(fs, s->line);
  if (bl2.upval) {
    int exit = jump(fs, s->line);
    patchtohere(fs, condexit);
    emit(fs, OP_CLOSE, bl2.nactvar, 0, 0, 0, s->line);
    condexit = jump(fs, s->line);
    patchtohere(fs, exit);
  }
  patchlist(fs, condexit, repeat_init);
  leaveblock(fs, s->line);
}

static void numforstat(FS *fs, Stat *s) {
  CBlock bl, inner;
  int base, prep, i;
  int line = s->line;
  enterblock(fs, &bl, 1);
  base = fs->freereg;
  exp2nextreg(fs, s->u.numfor.start);
  exp2nextreg(fs, s->u.numfor.limit);
  if (s->u.numfor.step) exp2nextreg(fs, s->u.numfor.step);
  else {
    int r = fs->freereg;
    reserveregs(fs, 1, line);
    loadint(fs, r, 1, line);
  }
  for (i = 0; i < 3; i++) activate(fs, s->u.numfor.hidden[i], base + i);
  prep = emitx(fs, OP_FORPREP, base, 0, s->line2 ? s->line2 : line);
  enterblock(fs, &inner, 0);
  reserveregs(fs, 1, line);
  activate(fs, s->u.numfor.var, base + 3);
  block(fs, s->u.numfor.body, 0);
  leaveblock(fs, line);
  {
    int endfor = emitx(fs, OP_FORLOOP, base, 0, line);
    fs->f->code[endfor].u.sbx = (prep + 1) - (endfor + 1);
    fs->f->code[prep].u.sbx = (endfor + 1) - (prep + 1);
  }
  leaveblock(fs, line);
}

static void genforstat(FS *fs, Stat *s) {
  CBlock bl, inner;
  int base, prep, i, nvars;
  int line = s->line;
  enterblock(fs, &bl, 1);
  base = fs->freereg;
  adjust_assign(fs, 4, s->u.genfor.exprs, s->u.genfor.nexprs, line);
  fs->freereg = base + 4;
  checkstack(fs, 3, line);
  for (i = 0; i < 4; i++) activate(fs, s->u.genfor.hidden[i], base + i);
  bl.upval = 1;
  bl.insidetbc = 1;
  prep = emitx(fs, OP_TFORPREP, base, 0, s->line2 ? s->line2 : line);
  nvars = s->u.genfor.nvars;
  enterblock(fs, &inner, 0);
  reserveregs(fs, nvars, line);
  for (i = 0; i < nvars; i++) activate(fs, s->u.genfor.vars[i], base + 4 + i);
  block(fs, s->u.genfor.body, 0);
  leaveblock(fs, line);
  fs->f->code[prep].u.sbx = fs->pc - (prep + 1);
  {
    int pc = emit(fs, OP_TFORCALL, base, 0, nvars, 0, line);
    int endfor;
    addvi(fs, pc, 0, VK_FORITER, str_newc(fs->L, "for iterator"));
    endfor = emitx(fs, OP_TFORLOOP, base, 0, line);
    fs->f->code[endfor].u.sbx = (prep + 1) - (endfor + 1);
  }
  leaveblock(fs, line);
}

static void ifstat(FS *fs, Stat *s) {
  int escape = NO_JUMP;
  int i;
  int n = s->u.ifs.n;
  for (i = 0; i < n; i++) {
    int jf = condjump(fs, s->u.ifs.conds[i], 0);
    block(fs, s->u.ifs.blocks[i], 0);
    if (i < n - 1 || s->u.ifs.elseb) {
      Block *b = s->u.ifs.blocks[i];
      /* avoid jump after unconditional return/break? keep simple */
      (void)b;
      concatjl(fs, &escape, jump(fs, s->line));
    }
    patchtohere(fs, jf);
  }
  if (s->u.ifs.elseb) block(fs, s->u.ifs.elseb, 0);
  patchtohere(fs, escape);
}

static void gotostat(FS *fs, Str *name, int line) {
  CLabel *lb = findlabel(fs, name);
  if (lb == NULL) {
    int pc = jump(fs, line);
    addlabel(fs, &fs->cg->gotos, &fs->cg->ngotos, &fs->cg->sizegotos, name, pc, line, fs->nactvar);
  } else {
    int lblevel = lb->nactvar;
    if (fs->nactvar > lblevel)
      emit(fs, OP_CLOSE, lblevel, 0, 0, 0, line);
    patchlist(fs, jump(fs, line), lb->pc);
  }
}

static int isvoidstat(Stat *s) {
  return s == NULL || s->k == S_LABEL;
}

static void labelstat(FS *fs, Stat *s) {
  Str *name = s->u.label.name;
  CLabel *lb = findlabel(fs, name);
  Stat *nx;
  int last = 1;
  if (lb != NULL) {
    const char *msg = pushfstring(fs->L, "label '%s' already defined on line %d", getstr(name), lb->line);
    cg_error(fs, msg, s->line);
  }
  /* label is 'last' if followed only by void statements (other labels) until block end */
  for (nx = s->next; nx != NULL; nx = nx->next) {
    if (!isvoidstat(nx)) { last = 0; break; }
  }
  createlabel(fs, name, s->line, last);
}

static void statement(FS *fs, Stat *s) {
  switch (s->k) {
    case S_CALL: {
      int save = fs->freereg;
      codecall(fs, s->u.call, 0);
      fs->freereg = save;
      break;
    }
    case S_LOCAL: localstat(fs, s); break;
    case S_ASSIGN: assignstat(fs, s); break;
    case S_DO: block(fs, s->u.blk.body, 0); break;
    case S_WHILE: whilestat(fs, s); break;
    case S_REPEAT: repeatstat(fs, s); break;
    case S_IF: ifstat(fs, s); break;
    case S_NUMFOR: numforstat(fs, s); break;
    case S_GENFOR: genforstat(fs, s); break;
    case S_RETURN: retstat(fs, s); break;
    case S_BREAK: {
      int pc = jump(fs, s->line);
      addlabel(fs, &fs->cg->gotos, &fs->cg->ngotos, &fs->cg->sizegotos, fs->cg->breakname, pc, s->line, fs->nactvar);
      break;
    }
    case S_GOTO: gotostat(fs, s->u.label.name, s->line); break;
    case S_LABEL: labelstat(fs, s); break;
    case S_LOCALFUNC: {
      int reg = fs->freereg;
      Expr fe;
      reserveregs(fs, 1, s->line);
      activate(fs, s->u.localfunc.var, reg);
      memset(&fe, 0, sizeof(fe));
      fe.k = E_FUNC;
      fe.line = s->line;
      fe.u.func = s->u.localfunc.f;
      exp2reg(fs, &fe, reg);
      fs->f->locvars[s->u.localfunc.var->locidx].startpc = fs->pc;
      break;
    }
    case S_GLOBAL: globalstat(fs, s); break;
    case S_GLOBALFUNC: globalfuncstat(fs, s); break;
  }
  fs->freereg = fs->nactvar;
}

static void stmtlist(FS *fs, Block *b) {
  Stat *s;
  for (s = b->first; s; s = s->next) statement(fs, s);
}

static void block(FS *fs, Block *b, int isloop) {
  CBlock bl;
  int line = b->last ? b->last->line : 0;
  enterblock(fs, &bl, isloop);
  stmtlist(fs, b);
  leaveblock(fs, line);
}

/* ---------------- functions ---------------- */

static void finish_proto(FS *fs) {
  Proto *f = fs->f;
  State *L = fs->L;
  f->code = mem_reallocvec(L, f->code, f->sizecode, fs->pc, Instr);
  f->lineinfo = mem_reallocvec(L, f->lineinfo, f->sizecode, fs->pc, int);
  f->sizecode = fs->pc;
  f->k = mem_reallocvec(L, f->k, f->sizek, fs->nk, TValue);
  f->sizek = fs->nk;
  f->p = mem_reallocvec(L, f->p, f->sizep, fs->np, Proto *);
  f->sizep = fs->np;
  f->locvars = mem_reallocvec(L, f->locvars, f->sizelocvars, fs->nlocvars, LocVar);
  f->sizelocvars = fs->nlocvars;
  f->varinfo = mem_reallocvec(L, f->varinfo, f->sizevarinfo, fs->nvi, VarInfo);
  f->sizevarinfo = fs->nvi;
  f->maxstack = (uint16_t)(fs->maxstack + 2);
}

static Proto *compile_func(FS *parent, FuncAST *fa, Str *source) {
  FS fs;
  CBlock bl;
  Proto *f;
  State *L = parent ? parent->L : NULL;
  int i;
  memset(&fs, 0, sizeof(fs));
  fs.prev = parent;
  fs.fa = fa;
  fs.L = L;
  fs.cg = parent->cg;
  fs.knil = fs.ktrue = fs.kfalse = -1;
  f = proto_new(L);
  fs.f = f;
  f->source = source;
  f->linedefined = fa->line;
  f->lastlinedefined = fa->lastline;
  f->numparams = (uint8_t)fa->nparams;
  f->is_vararg = (uint8_t)fa->is_vararg;
  /* upvalues */
  f->sizeup = fa->nups;
  if (fa->nups > 0) {
    f->upvals = mem_newvec(L, fa->nups, UpvalDesc);
    for (i = 0; i < fa->nups; i++) {
      UpvalAST *u = &fa->ups[i];
      f->upvals[i].name = u->name;
      f->upvals[i].instack = u->instack;
      f->upvals[i].kind = u->kind;
      f->upvals[i].idx = (uint16_t)(u->instack ? (u->pvar ? u->pvar->reg : 0) : u->pidx);
    }
  }
  fs.firstlabel = fs.cg->nlabels;
  fs.firstgoto = fs.cg->ngotos;
  enterblock(&fs, &bl, 0);
  for (i = 0; i < fa->nparams; i++) {
    reserveregs(&fs, 1, fa->line);
    activate(&fs, fa->params[i], i);
  }
  if (fa->vartab) {
    reserveregs(&fs, 1, fa->line);
    activate(&fs, fa->vartab, fa->nparams);
  }
  stmtlist(&fs, fa->body);
  emit(&fs, OP_RETURN0, fs.nactvar, 1, 0, 0, fa->lastline);
  leaveblock(&fs, fa->lastline);
  finish_proto(&fs);
  free(fs.actvars);
  return f;
}

Proto *codegen_main(State *L, FuncAST *fa, Str *source, Arena *ar) {
  CG cg;
  FS root;
  Proto *p;
  (void)ar;
  memset(&cg, 0, sizeof(cg));
  cg.L = L;
  cg.source = source;
  cg.breakname = str_newc(L, "break");
  cg.intindex = str_newc(L, "integer index");
  cg.qmark = str_newc(L, "?");
  memset(&root, 0, sizeof(root));
  root.L = L;
  root.cg = &cg;
  /* compile main with a dummy parent */
  {
    FS *parent = &root;
    LongJmp lj;
    lj.prev = L->errjmp;
    lj.status = TS_OK;
    L->errjmp = &lj;
    if (setjmp(lj.b) == 0) {
      p = compile_func(parent, fa, source);
    }
    L->errjmp = lj.prev;
    free(cg.labels);
    free(cg.gotos);
    if (lj.status != TS_OK) d_throw(L, lj.status);
  }
  return p;
}
