UpVal *upval_find(State *L, TValue *level) {
  UpVal **pp = &L->openupval;
  UpVal *p;
  UpVal *uv;
  while ((p = *pp) != NULL && p->v >= level) {
    if (p->v == level) return p;
    pp = &p->opennext;
  }
  uv = (UpVal *)gc_new(L, T_UPVAL, sizeof(UpVal));
  uv->v = level;
  uv->tbc = 0;
  uv->opennext = *pp;
  setnil(&uv->value);
  *pp = uv;
  return uv;
}

void upval_close(State *L, TValue *level) {
  UpVal *uv;
  while ((uv = L->openupval) != NULL && uv->v >= level) {
    L->openupval = uv->opennext;
    uv->value = *uv->v;
    uv->v = &uv->value;
  }
}

