void tbc_new(State *L, TValue *obj) {
  if (isfalsy(obj)) return;
  if (tm_byobj(L, obj, TM_CLOSE) == NULL || isnil(tm_byobj(L, obj, TM_CLOSE))) {
    /* error: variable got a non-closable value */
    CallInfo *ci = L->ci;
    const char *vname = "?";
    if (isLua(ci)) {
      const char *n = getlocalname(ci_func(ci)->p, (int)(obj - (ci->func + 1)) + 1, currentpc(ci));
      if (n) vname = n;
    }
    dbg_runerror(L, "variable '%s' got a non-closable value", vname);
  }
  if (L->ntbc >= L->sizetbc) {
    int ns = L->sizetbc ? L->sizetbc * 2 : 8;
    L->tbclist = realloc(L->tbclist, sizeof(TValue *) * ns);
    L->sizetbc = ns;
  }
  L->tbclist[L->ntbc++] = obj;
}

static void callclosemethod(State *L, TValue *obj, TValue *err) {
  TValue *top = L->top;
  const TValue *tm = tm_byobj(L, obj, TM_CLOSE);
  TValue tmv;
  if (tm) tmv = *tm; else setnil(&tmv);
  checkstack(L, 4);
  top = L->top;
  setobj(top, &tmv);
  setobj(top + 1, obj);
  setobj(top + 2, err);
  L->top = top + 3;
  d_call(L, top, 0);
}

/* close upvalues and to-be-closed variables down to 'level'.
   status < 0 : normal close (error object nil); otherwise error object at
   L->top - 1 is passed (and may be replaced). */
void func_close(State *L, TValue *level, int status) {
  upval_close(L, level);
  while (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= level) {
    TValue *tbc = L->tbclist[--L->ntbc];
    TValue errv;
    if (status < 0) {
      setnil(&errv);
      callclosemethod(L, tbc, &errv);
    } else {
      errv = *(L->top - 1);
      callclosemethod(L, tbc, &errv);
    }
  }
}

const char *getlocalname(const Proto *f, int local_number, int pc) {
  int i;
  for (i = 0; i < f->sizelocvars && f->locvars[i].startpc <= pc; i++) {
    if (pc < f->locvars[i].endpc) {
      local_number--;
      if (local_number == 0)
        return getstr(f->locvars[i].name);
    }
  }
  return NULL;
}
