{"command":"cd /workspace/src && cat > gc.c <<'EOF'
/* garbage collector: stop-the-world mark & sweep */
#include "core.h"
#include <sys/mman.h>

#define MARKBIT 1
#define FIXEDBIT 4
#define FINOBJBIT 8     /* object is in 'finobj' list */
#define FINALIZEDBIT 16 /* finalizer already called/scheduled */

#define ismarked(o) ((o)->marked & (MARKBIT | FIXEDBIT))

void *mem_realloc(State *L, void *block, size_t osize, size_t nsize) {
  Global *g = G(L);
  void *nb;
  if (nsize == 0) {
    free(block);
    g->totalbytes -= osize;
    return NULL;
  }
  nb = realloc(block, nsize);
  if (nb == NULL) {
    if (g->gcrunning && !g->gcingc) {
      gc_fullgc(L, 1);
      nb = realloc(block, nsize);
    }
    if (nb == NULL) {
      setstr(L->top, g->memerrmsg);
      L->top++;
      d_throw(L, TS_ERRMEM);
    }
  }
  g->totalbytes += nsize;
  g->totalbytes -= osize;
  return nb;
}

void *mem_growvec(State *L, void *block, int *size, int needed, size_t elsize, int limit, const char *what) {
  int newsize = *size * 2;
  if (newsize < 4) newsize = 4;
  if (newsize < needed) newsize = needed;
  if (newsize > limit) {
    if (needed > limit) dbg_runerror(L, "too many %s (limit is %d)", what, limit);
    newsize = limit;
  }
  block = mem_realloc(L, block, (size_t)*size * elsize, (size_t)newsize * elsize);
  *size = newsize;
  return block;
}

GCObj *gc_new(State *L, int tt, size_t sz) {
  Global *g = G(L);
  GCObj *o = (GCObj *)mem_alloc(L, sz);
  o->tt = (uint8_t)tt;
  o->marked = 0;
  o->gcnext = g->allgc;
  g->allgc = o;
  return o;
}

void gc_fix(State *L, GCObj *o) {
  o->marked |= FIXEDBIT;
}

/* ---------------- marking ---------------- */

static void pushgray(Global *g, GCObj *o) {
  if (g->graytop >= g->graysize) {
    int ns = g->graysize ? g->graysize * 2 : 1024;
    g->graystack = realloc(g->graystack, sizeof(GCObj *) * ns);
    g->graysize = ns;
  }
  g->graystack[g->graytop++] = o;
}

static void markobj(Global *g, GCObj *o) {
  if (o->marked & MARKBIT) return;
  o->marked |= MARKBIT;
  if (o->tt == T_STR) return;
  pushgray(g, o);
}

#define markvalue(g, v) do { if (iscollectable(v)) markobj(g, gcvalue(v)); } while (0)
#define markobjN(g, o) do { if (o) markobj(g, (GCObj *)(o)); } while (0)

/* weak tables lists */
typedef struct WeakLists {
  Table **weakv;   /* weak values only */
  int nweakv, sweakv;
  Table **ephem;   /* weak keys only */
  int nephem, sephem;
  Table **allweak; /* weak keys and values */
  int nallweak, sallweak;
} WeakLists;

static WeakLists wl;

static void addweak(Table ***arr, int *n, int *sz, Table *t) {
  if (*n >= *sz) {
    *sz = *sz ? *sz * 2 : 16;
    *arr = realloc(*arr, sizeof(Table *) * (*sz));
  }
  (*arr)[(*n)++] = t;
}

static int iscleared(const TValue *o) {
  if (!iscollectable(o)) return 0;
  if (o->tt == T_STR) {
    gcvalue(o)->marked |= MARKBIT;
    return 0;
  }
  return !ismarked(gcvalue(o));
}

static int iscleared_key(const Node *n) {
  if (n->key.tt < T_STR) return 0;
  if (n->key.tt == T_STR) {
    n->key.v.gc->marked |= MARKBIT;
    return 0;
  }
  return !ismarked(n->key.v.gc);
}

static void clearkey(Node *n) {
  if (n->key.tt >= T_STR) n->key.tt = T_DEADKEY;
}

static const char *getmode(Global *g, Table *t) {
  const TValue *mode;
  if (t->meta == NULL) return NULL;
  mode = tab_getshortstr(t->meta, g->tmname[TM_MODE]);
  if (mode->tt == T_STR) return getstr(strvalue(mode));
  return NULL;
}

static void traversestrongtable(Global *g, Table *t) {
  unsigned int i;
  unsigned int size = sizenode(t);
  for (i = 0; i < t->asize; i++) markvalue(g, &t->array[i]);
  if (t->lastfree == NULL) return;
  for (i = 0; i < size; i++) {
    Node *n = &t->node[i];
    if (isnil(&n->val)) clearkey(n);
    else {
      if (n->key.tt >= T_STR && n->key.tt != T_DEADKEY) markobj(g, n->key.v.gc);
      markvalue(g, &n->val);
    }
  }
}

static void traverseweakvalue(Global *g, Table *t) {
  unsigned int i;
  unsigned int size = sizenode(t);
  if (t->lastfree == NULL) {
    addweak(&wl.weakv, &wl.nweakv, &wl.sweakv, t);
    return;
  }
  for (i = 0; i < size; i++) {
    Node *n = &t->node[i];
    if (isnil(&n->val)) clearkey(n);
    else if (n->key.tt >= T_STR && n->key.tt != T_DEADKEY) markobj(g, n->key.v.gc);
  }
  addweak(&wl.weakv, &wl.nweakv, &wl.sweakv, t);
}

/* returns 1 if it marked something */
static int traverseephemeron(Global *g, Table *t) {
  int marked = 0;
  unsigned int i;
  unsigned int size = sizenode(t);
  for (i = 0; i < t->asize; i++) {
    if (iscollectable(&t->array[i]) && !ismarked(gcvalue(&t->array[i]))) {
      marked = 1;
      markobj(g, gcvalue(&t->array[i]));
    }
  }
  if (t->lastfree == NULL) return marked;
  for (i = 0; i < size; i++) {
    Node *n = &t->node[i];
    if (isnil(&n->val)) clearkey(n);
    else if (iscleared_key(n)) {
      /* key not marked yet: value may be marked later */
    } else if (iscollectable(&n->val) && !ismarked(gcvalue(&n->val))) {
      marked = 1;
      markobj(g, gcvalue(&n->val));
    }
  }
  return marked;
}

static void traversetable(Global *g, Table *t) {
  const char *weakkey, *weakvalue;
  const char *mode = getmode(g, t);
  markobjN(g, t->meta);
  if (mode && ((weakkey = strchr(mode, 'k')), (weakvalue = strchr(mode, 'v')), (weakkey || weakvalue))) {
    if (!weakkey) traverseweakvalue(g, t);
    else if (!weakvalue) {
      traverseephemeron(g, t);
      addweak(&wl.ephem, &wl.nephem, &wl.sephem, t);
    } else {
      addweak(&wl.allweak, &wl.nallweak, &wl.sallweak, t);
    }
  } else
    traversestrongtable(g, t);
}

static void traverseproto(Global *g, Proto *f) {
  int i;
  markobjN(g, f->source);
  for (i = 0; i < f->sizek; i++) markvalue(g, &f->k[i]);
  for (i = 0; i < f->sizeup; i++) markobjN(g, f->upvals[i].name);
  for (i = 0; i < f->sizep; i++) markobjN(g, f->p[i]);
  for (i = 0; i < f->sizelocvars; i++) markobjN(g, f->locvars[i].name);
  for (i = 0; i < f->sizevarinfo; i++) markobjN(g, f->varinfo[i].name);
}

static void traverseupval(Global *g, UpVal *uv) {
  markvalue(g, uv->v);
}

static void traverselclosure(Global *g, LClosure *cl) {
  int i;
  markobjN(g, cl->p);
  for (i = 0; i < cl->nup; i++) markobjN(g, cl->up[i]);
}

static void traversecclosure(Global *g, CClosure *cl) {
  int i;
  for (i = 0; i < cl->nup; i++) markvalue(g, &cl->up[i]);
}

static void traverseudata(Global *g, Udata *u) {
  int i;
  markobjN(g, u->meta);
  for (i = 0; i < u->nuv; i++) markvalue(g, &u->uv[i]);
}

static TValue *thread_hwm(State *th);

static void traversethread(Global *g, State *th) {
  TValue *o;
  UpVal *uv;
  int i;
  if (th->stack == NULL) return;
  for (o = th->stack; o < th->top; o++) markvalue(g, o);
  for (uv = th->openupval; uv != NULL; uv = uv->opennext) markobj(g, (GCObj *)uv);
  for (i = 0; i < th->ntbc; i++) markvalue(g, th->tbclist[i]);
  markvalue(g, &th->hook);
  /* clear dead part of the stack */
  {
    TValue *lim = thread_hwm(th);
    for (o = th->top; o < lim; o++) setnil(o);
  }
}

static void propagate(Global *g) {
  while (g->graytop > 0) {
    GCObj *o = g->graystack[--g->graytop];
    switch (o->tt) {
      case T_TAB: traversetable(g, (Table *)o); break;
      case T_LCL: traverselclosure(g, (LClosure *)o); break;
      case T_CCL: traversecclosure(g, (CClosure *)o); break;
      case T_UD: traverseudata(g, (Udata *)o); break;
      case T_THR: traversethread(g, (State *)o); break;
      case T_PROTO: traverseproto(g, (Proto *)o); break;
      case T_UPVAL: traverseupval(g, (UpVal *)o); break;
      default: break;
    }
  }
}

static void convergeephemerons(Global *g) {
  int changed;
  do {
    int i;
    changed = 0;
    for (i = 0; i < wl.nephem; i++) {
      if (traverseephemeron(g, wl.ephem[i])) {
        propagate(g);
        changed = 1;
      }
    }
  } while (changed);
}

static void clearbyvalues(Table **arr, int from, int to) {
  int k;
  for (k = from; k < to; k++) {
    Table *t = arr[k];
    unsigned int i;
    unsigned int size = sizenode(t);
    for (i = 0; i < t->asize; i++) {
      if (iscleared(&t->array[i])) setnil(&t->array[i]);
    }
    if (t->lastfree == NULL) continue;
    for (i = 0; i < size; i++) {
      Node *n = &t->node[i];
      if (iscleared(&n->val)) setnil(&n->val);
      if (isnil(&n->val)) clearkey(n);
    }
  }
}

static void clearbykeys(Table **arr, int n) {
  int k;
  for (k = 0; k < n; k++) {
    Table *t = arr[k];
    unsigned int i;
    unsigned int size = sizenode(t);
    if (t->lastfree == NULL) continue;
    for (i = 0; i < size; i++) {
      Node *nd = &t->node[i];
      if (iscleared_key(nd)) setnil(&nd->val);
      if (isnil(&nd->val)) clearkey(nd);
    }
  }
}

/* ---------------- freeing ---------------- */

void thread_free(State *L, State *L1);

static void freeobj(State *L, GCObj *o) {
  switch (o->tt) {
    case T_STR: {
      Str *s = (Str *)o;
      mem_free(L, s, offsetof(Str, data) + s->len + 1);
      break;
    }
    case T_TAB: tab_free(L, (Table *)o); break;
    case T_LCL: {
      LClosure *c = (LClosure *)o;
      mem_free(L, c, offsetof(LClosure, up) + sizeof(UpVal *) * (c->nup > 0 ? c->nup : 1));
      break;
    }
    case T_CCL: {
      CClosure *c = (CClosure *)o;
      mem_free(L, c, offsetof(CClosure, up) + sizeof(TValue) * (c->nup > 0 ? c->nup : 1));
      break;
    }
    case T_UD: {
      Udata *u = (Udata *)o;
      if (u->nuv > 0) mem_freevec(L, u->uv, u->nuv, TValue);
      mem_free(L, u, offsetof(Udata, data) + u->len);
      break;
    }
    case T_THR: thread_free(L, (State *)o); break;
    case T_PROTO: proto_free(L, (Proto *)o); break;
    case T_UPVAL: {
      UpVal *uv = (UpVal *)o;
      mem_free(L, uv, sizeof(UpVal));
      break;
    }
    default: break;
  }
}

static void sweeplist(State *L, GCObj **p) {
  GCObj *curr;
  while ((curr = *p) != NULL) {
    if (curr->marked & (MARKBIT | FIXEDBIT)) {
      curr->marked &= ~MARKBIT;
      p = &curr->gcnext;
    } else {
      *p = curr->gcnext;
      freeobj(L, curr);
    }
  }
}

static void sweepstrings(State *L) {
  StrTab *tb = &G(L)->strt;
  int i;
  for (i = 0; i < tb->size; i++) {
    Str **p = &tb->hash[i];
    Str *s;
    while ((s = *p) != NULL) {
      if (s->marked & (MARKBIT | FIXEDBIT)) {
        s->marked &= ~MARKBIT;
        p = &s->hnext;
      } else {
        *p = s->hnext;
        tb->nuse--;
        mem_free(L, s, offsetof(Str, data) + s->len + 1);
      }
    }
  }
  if (tb->nuse < tb->size / 4 && tb->size > 128)
    str_resize(L, tb->size / 2);
}

/* ---------------- finalizers ---------------- */

void gc_checkfinalizer(State *L, GCObj *o, Table *mt) {
  Global *g = G(L);
  GCObj **p;
  if ((o->marked & (FINOBJBIT | FINALIZEDBIT)) || mt == NULL)
    return;
  if (isnil(tab_getshortstr(mt, g->tmname[TM_GC])))
    return;
  for (p = &g->allgc; *p != o; p = &(*p)->gcnext) {
    if (*p == NULL) return;
  }
  *p = o->gcnext;
  o->gcnext = g->finobj;
  g->finobj = o;
  o->marked |= FINOBJBIT;
}

static void separatetobefnz(Global *g, int all) {
  GCObj *curr;
  GCObj **p = &g->finobj;
  GCObj **lastnext = &g->tobefnz;
  while (*lastnext != NULL) lastnext = &(*lastnext)->gcnext;
  while ((curr = *p) != NULL) {
    if (!(ismarked(curr) || all)) {
      *p = curr->gcnext;
      curr->gcnext = *lastnext;
      *lastnext = curr;
      lastnext = &curr->gcnext;
    } else
      p = &curr->gcnext;
  }
}

static void markbeingfnz(Global *g) {
  GCObj *o;
  for (o = g->tobefnz; o != NULL; o = o->gcnext) markobj(g, o);
}

static void callonefinalizer(State *L) {
  Global *g = G(L);
  GCObj *o = g->tobefnz;
  TValue v;
  const TValue *tm;
  g->tobefnz = o->gcnext;
  o->gcnext = g->allgc;
  g->allgc = o;
  o->marked &= ~FINOBJBIT;
  o->marked |= FINALIZEDBIT;
  v.v.gc = o;
  v.tt = o->tt;
  tm = tm_byobj(L, &v, TM_GC);
  if (tm != NULL && !isnil(tm) && isfunc(tm)) {
    int status;
    uint8_t oldrunning = g->gcrunning;
    TValue *top;
    checkstack(L, 3);
    top = L->top;
    g->gcrunning = 0;
    setobj(top, tm);
    setobj(top + 1, &v);
    L->top = top + 2;
    status = ls_pcall(L, 1, 0, 0);
    g->gcrunning = oldrunning;
    if (status != TS_OK) {
      const char *msg = ls_tostring(L, -1);
      if (msg == NULL) msg = "error object is not a string";
      ls_warning(L, "error in ", 1);
      ls_warning(L, "__gc", 1);
      ls_warning(L, " (", 1);
      ls_warning(L, msg, 1);
      ls_warning(L, ")", 0);
      ls_pop(L, 1);
    }
  }
}

static int infinalizers = 0;

static void callallpendingfinalizers(State *L) {
  Global *g = G(L);
  if (infinalizers) return;
  infinalizers = 1;
  while (g->tobefnz) callonefinalizer(L);
  infinalizers = 0;
}

/* ---------------- main collection ---------------- */

static TValue *thread_hwm(State *th) {
  extern TValue *thread_gethwm(State *th);
  return thread_gethwm(th);
}

static void markroots(State *L) {
  Global *g = G(L);
  int i;
  State *th;
  markobj(g, (GCObj *)g->mainthread);
  markvalue(g, &g->registry);
  for (i = 0; i < NUMTYPES; i++) markobjN(g, g->mt[i]);
  markvalue(g, &g->warnf);
  for (th = g->running; th != NULL; th = th->resumer) markobj(g, (GCObj *)th);
}

static void atomic(State *L) {
  Global *g = G(L);
  int origweakv, origall;
  wl.nweakv = wl.nephem = wl.nallweak = 0;
  g->graytop = 0;
  markroots(L);
  propagate(g);
  convergeephemerons(g);
  clearbyvalues(wl.weakv, 0, wl.nweakv);
  clearbyvalues(wl.allweak, 0, wl.nallweak);
  origweakv = wl.nweakv;
  origall = wl.nallweak;
  separatetobefnz(g, 0);
  markbeingfnz(g);
  propagate(g);
  convergeephemerons(g);
  clearbykeys(wl.ephem, wl.nephem);
  clearbykeys(wl.allweak, wl.nallweak);
  clearbyvalues(wl.weakv, origweakv, wl.nweakv);
  clearbyvalues(wl.allweak, origall, wl.nallweak);
}

static void fullcycle(State *L) {
  Global *g = G(L);
  GCObj *o;
  g->gcingc = 1;
  atomic(L);
  sweeplist(L, &g->allgc);
  for (o = g->finobj; o; o = o->gcnext) o->marked &= ~MARKBIT;
  for (o = g->tobefnz; o; o = o->gcnext) o->marked &= ~MARKBIT;
  sweepstrings(L);
  g->gcestimate = g->totalbytes;
  {
    size_t th = g->totalbytes / 100 * (size_t)(g->gcpause > 0 ? g->gcpause : 200);
    if (th < 512 * 1024) th = 512 * 1024;
    g->gcthreshold = th;
  }
  g->gcingc = 0;
}

void gc_fullgc(State *L, int isemergency) {
  Global *g = G(L);
  if (g->gcingc) return;
  fullcycle(L);
  if (!isemergency) callallpendingfinalizers(L);
}

void gc_check(State *L) {
  Global *g = G(L);
  if (!g->gcrunning || g->gcstopped || g->gcingc || infinalizers) {
    if (g->totalbytes >= g->gcthreshold)
      g->gcthreshold = g->totalbytes + 1024 * 1024;
    return;
  }
  fullcycle(L);
  callallpendingfinalizers(L);
}

void gc_step(State *L) {
  gc_fullgc(L, 0);
}

size_t gc_count(State *L) {
  return G(L)->totalbytes;
}

void gc_freeall(State *L) {
  Global *g = G(L);
  /* call all finalizers */
  separatetobefnz(g, 1);
  callallpendingfinalizers(L);
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > gc.c <<'EOF'
/* garbage collector: stop-the-world mark & sweep */
#include "core.h"
#include <sys/mman.h>

#define MARKBIT 1
#define FIXEDBIT 4
#define FINOBJBIT 8     /* object is in 'finobj' list */
#define FINALIZEDBIT 16 /* finalizer already called/scheduled */

#define ismarked(o) ((o)->marked & (MARKBIT | FIXEDBIT))

void *mem_realloc(State *L, void *block, size_t osize, size_t nsize) {
  Global *g = G(L);
  void *nb;
  if (nsize == 0) {
    free(block);
    g->totalbytes -= osize;
    return NULL;
  }
  nb = realloc(block, nsize);
  if (nb == NULL) {
    if (g->gcrunning && !g->gcingc) {
      gc_fullgc(L, 1);
      nb = realloc(block, nsize);
    }
    if (nb == NULL) {
      setstr(L->top, g->memerrmsg);
      L->top++;
      d_throw(L, TS_ERRMEM);
    }
  }
  g->totalbytes += nsize;
  g->totalbytes -= osize;
  return nb;
}

void *mem_growvec(State *L, void *block, int *size, int needed, size_t elsize, int limit, const char *what) {
  int newsize = *size * 2;
  if (newsize < 4) newsize = 4;
  if (newsize < needed) newsize = needed;
  if (newsize > limit) {
    if (needed > limit) dbg_runerror(L, "too many %s (limit is %d)", what, limit);
    newsize = limit;
  }
  block = mem_realloc(L, block, (size_t)*size * elsize, (size_t)newsize * elsize);
  *size = newsize;
  return block;
}

GCObj *gc_new(State *L, int tt, size_t sz) {
  Global *g = G(L);
  GCObj *o = (GCObj *)mem_alloc(L, sz);
  o->tt = (uint8_t)tt;
  o->marked = 0;
  o->gcnext = g->allgc;
  g->allgc = o;
  return o;
}

void gc_fix(State *L, GCObj *o) {
  o->marked |= FIXEDBIT;
}

/* ---------------- marking ---------------- */

static void pushgray(Global *g, GCObj *o) {
  if (g->graytop >= g->graysize) {
    int ns = g->graysize ? g->graysize * 2 : 1024;
    g->graystack = realloc(g->graystack, sizeof(GCObj *) * ns);
    g->graysize = ns;
  }
  g->graystack[g->graytop++] = o;
}

static void markobj(Global *g, GCObj *o) {
  if (o->marked & MARKBIT) return;
  o->marked |= MARKBIT;
  if (o->tt == T_STR) return;
  pushgray(g, o);
}

#define markvalue(g, v) do { if (iscollectable(v)) markobj(g, gcvalue(v)); } while (0)
#define markobjN(g, o) do { if (o) markobj(g, (GCObj *)(o)); } while (0)

/* weak tables lists */
typedef struct WeakLists {
  Table **weakv;   /* weak values only */
  int nweakv, sweakv;
  Table **ephem;   /* weak keys only */
  int nephem, sephem;
  Table **allweak; /* weak keys and values */
  int nallweak, sallweak;
} WeakLists;

static WeakLists wl;

static void addweak(Table ***arr, int *n, int *sz, Table *t) {
  if (*n >= *sz) {
    *sz = *sz ? *sz * 2 : 16;
    *arr = realloc(*arr, sizeof(Table *) * (*sz));
  }
  (*arr)[(*n)++] = t;
}

static int iscleared(const TValue *o) {
  if (!iscollectable(o)) return 0;
  if (o->tt == T_STR) {
    gcvalue(o)->marked |= MARKBIT;
    return 0;
  }
  return !ismarked(gcvalue(o));
}

static int iscleared_key(const Node *n) {
  if (n->key.tt < T_STR) return 0;
  if (n->key.tt == T_STR) {
    n->key.v.gc->marked |= MARKBIT;
    return 0;
  }
  return !ismarked(n->key.v.gc);
}

static void clearkey(Node *n) {
  if (n->key.tt >= T_STR) n->key.tt = T_DEADKEY;
}

static const char *getmode(Global *g, Table *t) {
  const TValue *mode;
  if (t->meta == NULL) return NULL;
  mode = tab_getshortstr(t->meta, g->tmname[TM_MODE]);
  if (mode->tt == T_STR) return getstr(strvalue(mode));
  return NULL;
}

static void traversestrongtable(Global *g, Table *t) {
  unsigned int i;
  unsigned int size = sizenode(t);
  for (i = 0; i < t->asize; i++) markvalue(g, &t->array[i]);
  if (t->lastfree == NULL) return;
  for (i = 0; i < size; i++) {
    Node *n = &t->node[i];
    if (isnil(&n->val)) clearkey(n);
    else {
      if (n->key.tt >= T_STR && n->key.tt != T_DEADKEY) markobj(g, n->key.v.gc);
      markvalue(g, &n->val);
    }
  }
}

static void traverseweakvalue(Global *g, Table *t) {
  unsigned int i;
  unsigned int size = sizenode(t);
  if (t->lastfree == NULL) {
    addweak(&wl.weakv, &wl.nweakv, &wl.sweakv, t);
    return;
  }
  for (i = 0; i < size; i++) {
    Node *n = &t->node[i];
    if (isnil(&n->val)) clearkey(n);
    else if (n->key.tt >= T_STR && n->key.tt != T_DEADKEY) markobj(g, n->key.v.gc);
  }
  addweak(&wl.weakv, &wl.nweakv, &wl.sweakv, t);
}

/* returns 1 if it marked something */
static int traverseephemeron(Global *g, Table *t) {
  int marked = 0;
  unsigned int i;
  unsigned int size = sizenode(t);
  for (i = 0; i < t->asize; i++) {
    if (iscollectable(&t->array[i]) && !ismarked(gcvalue(&t->array[i]))) {
      marked = 1;
      markobj(g, gcvalue(&t->array[i]));
    }
  }
  if (t->lastfree == NULL) return marked;
  for (i = 0; i < size; i++) {
    Node *n = &t->node[i];
    if (isnil(&n->val)) clearkey(n);
    else if (iscleared_key(n)) {
      /* key not marked yet: value may be marked later */
    } else if (iscollectable(&n->val) && !ismarked(gcvalue(&n->val))) {
      marked = 1;
      markobj(g, gcvalue(&n->val));
    }
  }
  return marked;
}

static void traversetable(Global *g, Table *t) {
  const char *weakkey, *weakvalue;
  const char *mode = getmode(g, t);
  markobjN(g, t->meta);
  if (mode && ((weakkey = strchr(mode, 'k')), (weakvalue = strchr(mode, 'v')), (weakkey || weakvalue))) {
    if (!weakkey) traverseweakvalue(g, t);
    else if (!weakvalue) {
      traverseephemeron(g, t);
      addweak(&wl.ephem, &wl.nephem, &wl.sephem, t);
    } else {
      addweak(&wl.allweak, &wl.nallweak, &wl.sallweak, t);
    }
  } else
    traversestrongtable(g, t);
}

static void traverseproto(Global *g, Proto *f) {
  int i;
  markobjN(g, f->source);
  for (i = 0; i < f->sizek; i++) markvalue(g, &f->k[i]);
  for (i = 0; i < f->sizeup; i++) markobjN(g, f->upvals[i].name);
  for (i = 0; i < f->sizep; i++) markobjN(g, f->p[i]);
  for (i = 0; i < f->sizelocvars; i++) markobjN(g, f->locvars[i].name);
  for (i = 0; i < f->sizevarinfo; i++) markobjN(g, f->varinfo[i].name);
}

static void traverseupval(Global *g, UpVal *uv) {
  markvalue(g, uv->v);
}

static void traverselclosure(Global *g, LClosure *cl) {
  int i;
  markobjN(g, cl->p);
  for (i = 0; i < cl->nup; i++) markobjN(g, cl->up[i]);
}

static void traversecclosure(Global *g, CClosure *cl) {
  int i;
  for (i = 0; i < cl->nup; i++) markvalue(g, &cl->up[i]);
}

static void traverseudata(Global *g, Udata *u) {
  int i;
  markobjN(g, u->meta);
  for (i = 0; i < u->nuv; i++) markvalue(g, &u->uv[i]);
}

static TValue *thread_hwm(State *th);

static void traversethread(Global *g, State *th) {
  TValue *o;
  UpVal *uv;
  int i;
  if (th->stack == NULL) return;
  for (o = th->stack; o < th->top; o++) markvalue(g, o);
  for (uv = th->openupval; uv != NULL; uv = uv->opennext) markobj(g, (GCObj *)uv);
  for (i = 0; i < th->ntbc; i++) markvalue(g, th->tbclist[i]);
  markvalue(g, &th->hook);
  /* clear dead part of the stack */
  {
    TValue *lim = thread_hwm(th);
    for (o = th->top; o < lim; o++) setnil(o);
  }
}

static void propagate(Global *g) {
  while (g->graytop > 0) {
    GCObj *o = g->graystack[--g->graytop];
    switch (o->tt) {
      case T_TAB: traversetable(g, (Table *)o); break;
      case T_LCL: traverselclosure(g, (LClosure *)o); break;
      case T_CCL: traversecclosure(g, (CClosure *)o); break;
      case T_UD: traverseudata(g, (Udata *)o); break;
      case T_THR: traversethread(g, (State *)o); break;
      case T_PROTO: traverseproto(g, (Proto *)o); break;
      case T_UPVAL: traverseupval(g, (UpVal *)o); break;
      default: break;
    }
  }
}

static void convergeephemerons(Global *g) {
  int changed;
  do {
    int i;
    changed = 0;
    for (i = 0; i < wl.nephem; i++) {
      if (traverseephemeron(g, wl.ephem[i])) {
        propagate(g);
        changed = 1;
      }
    }
  } while (changed);
}

static void clearbyvalues(Table **arr, int from, int to) {
  int k;
  for (k = from; k < to; k++) {
    Table *t = arr[k];
    unsigned int i;
    unsigned int size = sizenode(t);
    for (i = 0; i < t->asize; i++) {
      if (iscleared(&t->array[i])) setnil(&t->array[i]);
    }
    if (t->lastfree == NULL) continue;
    for (i = 0; i < size; i++) {
      Node *n = &t->node[i];
      if (iscleared(&n->val)) setnil(&n->val);
      if (isnil(&n->val)) clearkey(n);
    }
  }
}

static void clearbykeys(Table **arr, int n) {
  int k;
  for (k = 0; k < n; k++) {
    Table *t = arr[k];
    unsigned int i;
    unsigned int size = sizenode(t);
    if (t->lastfree == NULL) continue;
    for (i = 0; i < size; i++) {
      Node *nd = &t->node[i];
      if (iscleared_key(nd)) setnil(&nd->val);
      if (isnil(&nd->val)) clearkey(nd);
    }
  }
}

/* ---------------- freeing ---------------- */

void thread_free(State *L, State *L1);

static void freeobj(State *L, GCObj *o) {
  switch (o->tt) {
    case T_STR: {
      Str *s = (Str *)o;
      mem_free(L, s, offsetof(Str, data) + s->len + 1);
      break;
    }
    case T_TAB: tab_free(L, (Table *)o); break;
    case T_LCL: {
      LClosure *c = (LClosure *)o;
      mem_free(L, c, offsetof(LClosure, up) + sizeof(UpVal *) * (c->nup > 0 ? c->nup : 1));
      break;
    }
    case T_CCL: {
      CClosure *c = (CClosure *)o;
      mem_free(L, c, offsetof(CClosure, up) + sizeof(TValue) * (c->nup > 0 ? c->nup : 1));
      break;
    }
    case T_UD: {
      Udata *u = (Udata *)o;
      if (u->nuv > 0) mem_freevec(L, u->uv, u->nuv, TValue);
      mem_free(L, u, offsetof(Udata, data) + u->len);
      break;
    }
    case T_THR: thread_free(L, (State *)o); break;
    case T_PROTO: proto_free(L, (Proto *)o); break;
    case T_UPVAL: {
      UpVal *uv = (UpVal *)o;
      mem_free(L, uv, sizeof(UpVal));
      break;
    }
    default: break;
  }
}

static void sweeplist(State *L, GCObj **p) {
  GCObj *curr;
  while ((curr = *p) != NULL) {
    if (curr->marked & (MARKBIT | FIXEDBIT)) {
      curr->marked &= ~MARKBIT;
      p = &curr->gcnext;
    } else {
      *p = curr->gcnext;
      freeobj(L, curr);
    }
  }
}

static void sweepstrings(State *L) {
  StrTab *tb = &G(L)->strt;
  int i;
  for (i = 0; i < tb->size; i++) {
    Str **p = &tb->hash[i];
    Str *s;
    while ((s = *p) != NULL) {
      if (s->marked & (MARKBIT | FIXEDBIT)) {
        s->marked &= ~MARKBIT;
        p = &s->hnext;
      } else {
        *p = s->hnext;
        tb->nuse--;
        mem_free(L, s, offsetof(Str, data) + s->len + 1);
      }
    }
  }
  if (tb->nuse < tb->size / 4 && tb->size > 128)
    str_resize(L, tb->size / 2);
}

/* ---------------- finalizers ---------------- */

void gc_checkfinalizer(State *L, GCObj *o, Table *mt) {
  Global *g = G(L);
  GCObj **p;
  if ((o->marked & (FINOBJBIT | FINALIZEDBIT)) || mt == NULL)
    return;
