  }
  *p = o->gcnext;
  o->gcnext = g->finobj;
  g->finobj = o;
  o->marked |= FINOBJBIT;
}

static void separatetobefnz(Global *g, int all) {
  GCObj *curr;
  GCObj **p = &g->finobj;
  GCObj **lastnext = &g->tobefnz;
  while (*lastnext != NULL) lastnext = &(*lastnext)->gcnext;
  while ((curr = *p) != NULL) {
    if (!(ismarked(curr) || all)) {
      *p = curr->gcnext;
      curr->gcnext = *lastnext;
      *lastnext = curr;
      lastnext = &curr->gcnext;
    } else
      p = &curr->gcnext;
  }
}

static void markbeingfnz(Global *g) {
  GCObj *o;
  for (o = g->tobefnz; o != NULL; o = o->gcnext) markobj(g, o);
}

static void callonefinalizer(State *L) {
  Global *g = G(L);
  GCObj *o = g->tobefnz;
  TValue v;
  const TValue *tm;
  g->tobefnz = o->gcnext;
  o->gcnext = g->allgc;
  g->allgc = o;
  o->marked &= ~FINOBJBIT;
  o->marked |= FINALIZEDBIT;
  v.v.gc = o;
  v.tt = o->tt;
  tm = tm_byobj(L, &v, TM_GC);
  if (tm != NULL && !isnil(tm) && isfunc(tm)) {
    int status;
    uint8_t oldrunning = g->gcrunning;
    TValue *top;
    checkstack(L, 3);
    top = L->top;
    g->gcrunning = 0;
    setobj(top, tm);
    setobj(top + 1, &v);
    L->top = top + 2;
    status = ls_pcall(L, 1, 0, 0);
    g->gcrunning = oldrunning;
    if (status != TS_OK) {
      const char *msg = ls_tostring(L, -1);
      if (msg == NULL) msg = "error object is not a string";
      ls_warning(L, "error in ", 1);
      ls_warning(L, "__gc", 1);
      ls_warning(L, " (", 1);
      ls_warning(L, msg, 1);
      ls_warning(L, ")", 0);
      ls_pop(L, 1);
    }
  }
}

static int infinalizers = 0;

static void callallpendingfinalizers(State *L) {
  Global *g = G(L);
  if (infinalizers) return;
  infinalizers = 1;
  while (g->tobefnz) callonefinalizer(L);
  infinalizers = 0;
}

/* ---------------- main collection ---------------- */

static TValue *thread_hwm(State *th) {
  extern TValue *thread_gethwm(State *th);
