  markbeingfnz(g);
  propagate(g);
  convergeephemerons(g);
  clearbykeys(wl.ephem, wl.nephem);
  clearbykeys(wl.allweak, wl.nallweak);
  clearbyvalues(wl.weakv, origweakv, wl.nweakv);
  clearbyvalues(wl.allweak, origall, wl.nallweak);
}

static void fullcycle(State *L) {
  Global *g = G(L);
  GCObj *o;
  g->gcingc = 1;
  atomic(L);
  sweeplist(L, &g->allgc);
  for (o = g->finobj; o; o = o->gcnext) o->marked &= ~MARKBIT;
  for (o = g->tobefnz; o; o = o->gcnext) o->marked &= ~MARKBIT;
