  {
    size_t th = g->totalbytes / 100 * (size_t)(g->gcpause > 0 ? g->gcpause : 200);
    if (th < 512 * 1024) th = 512 * 1024;
    g->gcthreshold = th;
  }
  g->gcingc = 0;
}

void gc_fullgc(State *L, int isemergency) {
  Global *g = G(L);
  if (g->gcingc) return;
  fullcycle(L);
  if (!isemergency) callallpendingfinalizers(L);
}

void gc_check(State *L) {
  Global *g = G(L);
  if (!g->gcrunning || g->gcstopped || g->gcingc || infinalizers) {
    if (g->totalbytes >= g->gcthreshold)
      g->gcthreshold = g->totalbytes + 1024 * 1024;
    return;
  }
  fullcycle(L);
  callallpendingfinalizers(L);
}

void gc_step(State *L) {
  gc_fullgc(L, 0);
}

size_t gc_count(State *L) {
  return G(L)->totalbytes;
}

void gc_freeall(State *L) {
  Global *g = G(L);
  /* call all finalizers */
  separatetobefnz(g, 1);
  callallpendingfinalizers(L);
}
