static void *ctx_make(void *stack_base, size_t size, void (*fn)(void *), void *arg) {
  uintptr_t top = ((uintptr_t)stack_base + size) & ~(uintptr_t)15;
  void **sp = (void **)(top - 72);
  sp[0] = 0;               /* r15 */
  sp[1] = 0;               /* r14 */
  sp[2] = (void *)fn;      /* r13 */
  sp[3] = arg;             /* r12 */
  sp[4] = 0;               /* rbx */
  sp[5] = 0;               /* rbp */
