static void checkcstack(State *L) {
  if (L->nCcalls == MAXCCALLS)
    dbg_runerror(L, "C stack overflow");
  else if (L->nCcalls >= (MAXCCALLS / 10 * 11))
    d_throw(L, TS_ERRERR);
}

static void callhook(State *L, CallInfo *ci) {
  (void)ci;
  if (L->hookmask & 1) d_hook(L, 0, -1);
