/* prepare a Lua call frame in 'ci' for function at 'func' with args up to L->top */
static void prepluaframe(State *L, CallInfo *ci, TValue *func, Proto *p) {
  int narg = (int)(L->top - func) - 1;
  int nfixparams = p->numparams;
  int fsize = p->maxstack;
  if (L->stack_last - L->top <= fsize + nfixparams + 3 || (p->is_vararg && L->stack_last - L->top <= fsize + narg + nfixparams + 3))
    d_checkstack(L, fsize + narg + nfixparams + 3);
  for (; narg < nfixparams; narg++) {
    setnil(L->top);
    L->top++;
  }
  ci->nextra = 0;
  if (p->is_vararg) {
    int nextra = narg - nfixparams;
    int i;
    TValue *newfunc = L->top;
    *newfunc = *func;
    for (i = 1; i <= nfixparams; i++) {
      newfunc[i] = func[i];
      setnil(func + i);
    }
    ci->nextra = nextra;
    func = newfunc;
    L->top = newfunc + 1 + nfixparams;
    if (p->is_vararg == 2) {
      /* named vararg table */
      Table *t = tab_new(L);
      TValue *slot;
      TValue nk;
      if (nextra > 0) tab_resize(L, t, (unsigned int)nextra, 1);
      else tab_resize(L, t, 0, 1);
      for (i = 0; i < nextra; i++) {
        slot = tab_setint(L, t, i + 1);
        *slot = func[-nextra + i];
      }
      setstr(&nk, str_newc(L, "n"));
      slot = tab_set(L, t, &nk);
      setint(slot, nextra);
      settab(L->top, t);
      L->top++;
    }
  }
  ci->func = func;
  ci->top = func + 1 + fsize;
  if (ci->top > L->hwm) L->hwm = ci->top;
  ci->savedpc = p->code;
  ci->status = CIST_LUA;
  ci->calltm = 0;
  {
    /* clear registers beyond arguments */
    TValue *o;
    for (o = L->top; o < ci->top; o++) setnil(o);
  }
  L->top = ci->top;
