cd /workspace/src && cat > do.c <<'EOF'
/* calls, errors, threads and coroutines */
#include "core.h"
#include "opcodes.h"
#include <sys/mman.h>

#define MINSTACK 20

/* ---------------- context switching (x86-64) ---------------- */
__asm__(
  ".text\n"
  ".globl ctx_switch\n"
  ".type ctx_switch,@function\n"
  "ctx_switch:\n"
  "  pushq %rbp\n"
  "  pushq %rbx\n"
  "  pushq %r12\n"
  "  pushq %r13\n"
  "  pushq %r14\n"
  "  pushq %r15\n"
  "  movq %rsp, (%rdi)\n"
  "  movq %rsi, %rsp\n"
  "  popq %r15\n"
  "  popq %r14\n"
  "  popq %r13\n"
  "  popq %r12\n"
  "  popq %rbx\n"
  "  popq %rbp\n"
  "  ret\n"
  ".size ctx_switch, .-ctx_switch\n"
  ".globl ctx_trampoline\n"
  ".type ctx_trampoline,@function\n"
  "ctx_trampoline:\n"
  "  movq %r12, %rdi\n"
  "  callq *%r13\n"
  "  ud2\n"
  ".size ctx_trampoline, .-ctx_trampoline\n"
);
void ctx_switch(void **save_sp, void *new_sp);
void ctx_trampoline(void);

static void *ctx_make(void *stack_base, size_t size, void (*fn)(void *), void *arg) {
  uintptr_t top = ((uintptr_t)stack_base + size) & ~(uintptr_t)15;
  void **sp = (void **)(top - 72);
  sp[0] = 0;               /* r15 */
  sp[1] = 0;               /* r14 */
  sp[2] = (void *)fn;      /* r13 */
  sp[3] = arg;             /* r12 */
  sp[4] = 0;               /* rbx */
  sp[5] = 0;               /* rbp */
  sp[6] = (void *)ctx_trampoline;
  sp[7] = 0;
  sp[8] = 0;
  return sp;
}

#define CSTACKSIZE (2u * 1024 * 1024)

/* ---------------- errors ---------------- */

void d_seterrorobj(State *L, int status, TValue *oldtop) {
  switch (status) {
    case TS_ERRMEM:
      setstr(oldtop, G(L)->memerrmsg);
      break;
    case TS_ERRERR:
      setstr(oldtop, str_newc(L, "error in error handling"));
      break;
    case TS_OK:
      setnil(oldtop);
      break;
    default:
      *oldtop = *(L->top - 1);
      break;
  }
  L->top = oldtop + 1;
}

void d_throw(State *L, int status) {
  if (L->errjmp) {
    L->errjmp->status = status;
    _longjmp(L->errjmp->b, 1);
  } else {
    Global *g = G(L);
    if (g->panic) {
      g->panic(L);
    }
    {
      const char *msg = (L->top > L->stack && isstr(L->top - 1)) ? getstr(strvalue(L->top - 1)) : "?";
      fprintf(stderr, "PANIC: unprotected error in call to Lua API (%s)\n", msg);
      fflush(stderr);
    }
    abort();
  }
}

int d_rawrunprotected(State *L, void (*f)(State *, void *), void *ud) {
  int oldnCcalls = L->nCcalls;
  LongJmp lj;
  lj.status = TS_OK;
  lj.prev = L->errjmp;
  L->errjmp = &lj;
  if (_setjmp(lj.b) == 0) {
    f(L, ud);
  }
  L->errjmp = lj.prev;
  L->nCcalls = oldnCcalls;
  return lj.status;
}

/* ---------------- stack ---------------- */

void d_checkstack(State *L, int n) {
  if (L->stack_last - L->top <= n) {
    if (L->stackoverflow) {
      /* already using extra space: hard limit */
      if (L->stack_end - L->top <= n + 5) d_throw(L, TS_ERRERR);
      L->stack_last = L->stack_end - 5;
      d_throw(L, TS_ERRERR);
    } else {
      L->stackoverflow = 1;
      L->stack_last = L->stack + MAXSTACK + EXTRASTACK;
      dbg_runerror(L, "stack overflow");
    }
  }
  if (L->top + n > L->hwm) L->hwm = L->top + n;
}

static void resetstackoverflow(State *L) {
  if (L->stackoverflow && L->top < L->stack + MAXSTACK - EXTRASTACK) {
    L->stackoverflow = 0;
    L->stack_last = L->stack + MAXSTACK;
  }
}

TValue *thread_gethwm(State *th) {
  CallInfo *ci;
  TValue *m = th->top;
  TValue *old = th->hwm;
  TValue *o;
  for (ci = th->ci; ci != NULL; ci = ci->prev) {
    if (ci->top > m) m = ci->top;
  }
  if (m > th->stack_end) m = th->stack_end;
  if (old > m) {
    for (o = m; o < old; o++) setnil(o);
  }
  th->hwm = m;
  return m;
}

CallInfo *d_extendci(State *L) {
  CallInfo *ci = (CallInfo *)mem_alloc(L, sizeof(CallInfo));
  L->ci->next = ci;
  ci->prev = L->ci;
  ci->next = NULL;
  ci->status = 0;
  ci->calltm = 0;
  L->nci++;
  return ci;
}

static void freeci(State *L) {
  CallInfo *ci = L->base_ci.next;
  L->base_ci.next = NULL;
  while (ci != NULL) {
    CallInfo *next = ci->next;
    mem_free(L, ci, sizeof(CallInfo));
    L->nci--;
    ci = next;
  }
}

static TValue *allocstack(State *L) {
  Global *g = G(L);
  size_t bytes = (size_t)STACKALLOC * sizeof(TValue);
  void *p;
  if (g->nfreestacks > 0) {
    return (TValue *)g->freestacks[--g->nfreestacks];
  }
  p = mmap(NULL, bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
  if (p == MAP_FAILED) return NULL;
  return (TValue *)p;
}

static void freestack(State *L, TValue *stack, TValue *hwm) {
  Global *g = G(L);
  size_t bytes = (size_t)STACKALLOC * sizeof(TValue);
  if (g->nfreestacks < 16 && hwm - stack < 4096) {
    memset(stack, 0, (size_t)(hwm - stack + 1) * sizeof(TValue));
    g->freestacks[g->nfreestacks++] = stack;
  } else
    munmap(stack, bytes);
}

static void *alloccstack(State *L) {
  Global *g = G(L);
  void *p;
  if (g->nfreecstacks > 0) return g->freecstacks[--g->nfreecstacks];
  p = mmap(NULL, CSTACKSIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE | MAP_STACK, -1, 0);
  if (p == MAP_FAILED) return NULL;
  return p;
}

static void freecstack(State *L, void *p) {
  Global *g = G(L);
  if (g->nfreecstacks < 16)
    g->freecstacks[g->nfreecstacks++] = p;
  else
    munmap(p, CSTACKSIZE);
}

void thread_initstack(State *L1, State *L) {
  L1->stack = allocstack(L);
  if (L1->stack == NULL) {
    setstr(L->top, G(L)->memerrmsg);
    L->top++;
    d_throw(L, TS_ERRMEM);
  }
  L1->stack_last = L1->stack + MAXSTACK;
  L1->stack_end = L1->stack + STACKALLOC - 5;
  L1->top = L1->stack;
  L1->ci = &L1->base_ci;
  L1->base_ci.next = L1->base_ci.prev = NULL;
  L1->base_ci.status = 0;
  L1->base_ci.func = L1->top;
  L1->base_ci.nresults = 0;
  L1->base_ci.calltm = 0;
  setnil(L1->top);
  L1->top++;
  L1->base_ci.top = L1->top + MINSTACK;
  L1->hwm = L1->base_ci.top;
}

void thread_preinit(State *L1, Global *g) {
  L1->g = g;
  L1->stack = NULL;
  L1->ci = NULL;
  L1->nci = 0;
  L1->errjmp = NULL;
  L1->nCcalls = 0;
  L1->openupval = NULL;
  L1->status = TS_OK;
  L1->costatus = 0;
  L1->allowhook = 1;
  L1->errfunc = NULL;
  L1->tbclist = NULL;
  L1->ntbc = L1->sizetbc = 0;
  L1->cstack = NULL;
  L1->ctx_sp = NULL;
  L1->resumer = NULL;
  L1->nargs_xfer = 0;
  setnil(&L1->hook);
  L1->hookmask = 0;
  L1->hookcount = L1->basehookcount = 0;
  L1->oldpc = 0;
  L1->stackoverflow = 0;
  L1->started = 0;
  L1->gclist = NULL;
}

void thread_free(State *L, State *L1) {
  upval_close(L1, L1->stack);
  freeci(L1);
  if (L1->stack) freestack(L, L1->stack, L1->hwm);
  if (L1->cstack) freecstack(L, L1->cstack);
  free(L1->tbclist);
  mem_free(L, L1, sizeof(State));
}

/* ---------------- calls ---------------- */

TValue *d_tryfuncTM(State *L, TValue *func) {
  const TValue *tm;
  TValue *p;
  checkstack(L, 1);
  tm = tm_byobj(L, func, TM_CALL);
  if (tm == NULL || isnil(tm))
    dbg_callerror(L, func);
  for (p = L->top; p > func; p--)
    *p = *(p - 1);
  L->top++;
  *func = *tm;
  return func;
}

static void checkcstack(State *L) {
  if (L->nCcalls == MAXCCALLS)
    dbg_runerror(L, "C stack overflow");
  else if (L->nCcalls >= (MAXCCALLS / 10 * 11))
    d_throw(L, TS_ERRERR);
}

static void callhook(State *L, CallInfo *ci) {
  (void)ci;
  if (L->hookmask & 1) d_hook(L, 0, -1);
}

void d_poscall(State *L, CallInfo *ci, int nres) {
  int wanted = ci->nresults;
  TValue *res = ci->func;
  TValue *firstresult = L->top - nres;
  int i;
  if (L->hookmask & 2) {
    d_hook(L, 1, -1);
    firstresult = L->top - nres;
  }
  L->ci = ci->prev;
  switch (wanted) {
    case 0:
      L->top = res;
      return;
    case 1:
      if (nres == 0) setnil(res);
      else *res = *firstresult;
      L->top = res + 1;
      return;
    case MULTRET:
      for (i = 0; i < nres; i++) res[i] = firstresult[i];
      L->top = res + nres;
      return;
    default:
      if (wanted <= nres) {
        for (i = 0; i < wanted; i++) res[i] = firstresult[i];
      } else {
        for (i = 0; i < nres; i++) res[i] = firstresult[i];
        for (; i < wanted; i++) setnil(res + i);
      }
      L->top = res + wanted;
      return;
  }
}

/* prepare a Lua call frame in 'ci' for function at 'func' with args up to L->top */
static void prepluaframe(State *L, CallInfo *ci, TValue *func, Proto *p) {
  int narg = (int)(L->top - func) - 1;
  int nfixparams = p->numparams;
  int fsize = p->maxstack;
  if (L->stack_last - L->top <= fsize + nfixparams + 3 || (p->is_vararg && L->stack_last - L->top <= fsize + narg + nfixparams + 3))
    d_checkstack(L, fsize + narg + nfixparams + 3);
  for (; narg < nfixparams; narg++) {
    setnil(L->top);
    L->top++;
  }
  ci->nextra = 0;
  if (p->is_vararg) {
    int nextra = narg - nfixparams;
    int i;
    TValue *newfunc = L->top;
    *newfunc = *func;
    for (i = 1; i <= nfixparams; i++) {
      newfunc[i] = func[i];
      setnil(func + i);
    }
    ci->nextra = nextra;
    func = newfunc;
    L->top = newfunc + 1 + nfixparams;
    if (p->is_vararg == 2) {
      /* named vararg table */
      Table *t = tab_new(L);
      TValue *slot;
      TValue nk;
      if (nextra > 0) tab_resize(L, t, (unsigned int)nextra, 1);
      else tab_resize(L, t, 0, 1);
      for (i = 0; i < nextra; i++) {
        slot = tab_setint(L, t, i + 1);
        *slot = func[-nextra + i];
      }
      setstr(&nk, str_newc(L, "n"));
      slot = tab_set(L, t, &nk);
      setint(slot, nextra);
      settab(L->top, t);
      L->top++;
    }
  }
  ci->func = func;
  ci->top = func + 1 + fsize;
  if (ci->top > L->hwm) L->hwm = ci->top;
  ci->savedpc = p->code;
  ci->status = CIST_LUA;
  ci->calltm = 0;
  {
    /* clear registers beyond arguments */
    TValue *o;
    for (o = L->top; o < ci->top; o++) setnil(o);
  }
  L->top = ci->top;
}

CallInfo *d_precall(State *L, TValue *func, int nresults) {
  CFunc f;
  for (;;) {
    switch (func->tt) {
      case T_CCL:
        f = cclvalue(func)->f;
        goto Cfunc;
      case T_LCF:
        f = func->v.f;
      Cfunc: {
        int n;
        CallInfo *ci;
        checkstack(L, MINSTACK);
        ci = next_ci(L);
        ci->nresults = (short)nresults;
        ci->status = 0;
        ci->calltm = 0;
        ci->func = func;
        ci->top = L->top + MINSTACK;
        if (ci->top > L->hwm) L->hwm = ci->top;
        if (L->hookmask & 1) callhook(L, ci);
        n = f(L);
        d_poscall(L, ci, n);
        return NULL;
      }
      case T_LCL: {
        CallInfo *ci;
        Proto *p = lclvalue(func)->p;
        ci = next_ci(L);
        ci->nresults = (short)nresults;
        prepluaframe(L, ci, func, p);
        if (L->hookmask & 1) callhook(L, ci);
        return ci;
      }
      default:
        func = d_tryfuncTM(L, func);
        break;
    }
  }
}

/* tail call: reuse current frame 'ci' for Lua function at 'func' (n = number of func+args) */
int d_pretailcall(State *L, CallInfo *ci, TValue *func, int n) {
  for (;;) {
    switch (func->tt) {
      case T_CCL: case T_LCF: {
        d_precall(L, func, MULTRET);
        return -1;  /* C function already done; results on top from func */
      }
      case T_LCL: {
        Proto *p = lclvalue(func)->p;
        TValue *base = ci->func;
        int i;
        int nres = ci->nresults;
        uint16_t oldstatus = ci->status;
        if (isLua(ci) && ci_func(ci)->p->is_vararg)
          base -= ci->nextra + ci_func(ci)->p->numparams + 1;
        for (i = 0; i < n; i++) base[i] = func[i];
        L->top = base + n;
        prepluaframe(L, ci, base, p);
        ci->nresults = (short)nres;
        ci->status = (uint16_t)(CIST_LUA | CIST_TAIL | (oldstatus & CIST_FRESH));
        return 0;
      }
      default:
        func = d_tryfuncTM(L, func);
        n++;
        break;
    }
  }
}

void d_call(State *L, TValue *func, int nresults) {
  CallInfo *ci;
  L->nCcalls++;
  if (L->nCcalls >= MAXCCALLS) {
    checkstack(L, 0);
    checkcstack(L);
  }
  if ((ci = d_precall(L, func, nresults)) != NULL) {
    ci->status |= CIST_FRESH;
    vm_execute(L, ci);
  }
  L->nCcalls--;
}

void d_callnoyield(State *L, TValue *func, int nresults) {
  d_call(L, func, nresults);
}

/* ---------------- protected calls ---------------- */

typedef struct CloseP {
  TValue *level;
  int status;
} CloseP;

static void closepaux(State *L, void *ud) {
  CloseP *pcl = (CloseP *)ud;
  func_close(L, pcl->level, pcl->status);
}

static int closeprotected(State *L, TValue *level, int status) {
  CallInfo *old_ci = L->ci;
  uint8_t old_allowhooks = L->allowhook;
  for (;;) {
    CloseP pcl;
    pcl.level = level;
    pcl.status = status;
    status = d_rawrunprotected(L, &closepaux, &pcl);
    if (status == TS_OK)
      return pcl.status;
    else {
      L->ci = old_ci;
      L->allowhook = old_allowhooks;
      pcl.status = status;
      status = status;
    }
  }
}

int d_pcall(State *L, void (*f)(State *, void *), void *ud, TValue *oldtop, TValue *ef) {
  int status;
  CallInfo *old_ci = L->ci;
  uint8_t old_allowhooks = L->allowhook;
  TValue *old_errfunc = L->errfunc;
  L->errfunc = ef;
  status = d_rawrunprotected(L, f, ud);
  if (status != TS_OK) {
    L->ci = old_ci;
    L->allowhook = old_allowhooks;
    if (L->openupval || L->ntbc > 0) {
      /* error object must be at top for closing */
      status = closeprotected(L, oldtop, status);
    }
    d_seterrorobj(L, status, oldtop);
    resetstackoverflow(L);
  }
  L->errfunc = old_errfunc;
  return status;
}

/* ---------------- parser entry ---------------- */

typedef struct SParser {
  const char *buff;
  size_t size;
  const char *name;
  const char *mode;
} SParser;

static void checkmode(State *L, const char *mode, const char *x) {
  if (mode && strchr(mode, x[0]) == NULL) {
    pushfstring(L, "attempt to load a %s chunk (mode is '%s')", x, mode);
    d_throw(L, TS_ERRSYNTAX);
  }
}

static void f_parser(State *L, void *ud) {
  LClosure *cl;
  SParser *p = (SParser *)ud;
  if (p->size > 0 && p->buff[0] == '\x1b') {
    Proto *pr;
    checkmode(L, p->mode, "binary");
    pr = undump(L, p->buff, p->size, p->name);
    cl = lcl_new(L, pr->sizeup);
    cl->p = pr;
  } else {
    checkmode(L, p->mode, "text");
    cl = parse_chunk(L, p->buff, p->size, p->name);
  }
  setlcl(L->top, cl);
  L->top++;
  {
    int i;
    for (i = 0; i < cl->nup; i++) {
      UpVal *uv = (UpVal *)gc_new(L, T_UPVAL, sizeof(UpVal));
      uv->v = &uv->value;
      uv->tbc = 0;
      uv->opennext = NULL;
      setnil(&uv->value);
      cl->up[i] = uv;
    }
  }
}

int d_protectedparser(State *L, const char *buff, size_t size, const char *name, const char *mode) {
  SParser p;
  int status;
  p.buff = buff;
  p.size = size;
  p.name = name;
  p.mode = mode;
  L->nCcalls++;
  status = d_pcall(L, f_parser, &p, L->top, L->errfunc);
  L->nCcalls--;
  return status;
}

/* ---------------- hooks ---------------- */

void d_hook(State *L, int event, int line) {
  extern void dbg_callhook(State *L, int event, int line);
  if (L->allowhook && !isnil(&L->hook)) dbg_callhook(L, event, line);
}

/* ---------------- coroutines ---------------- */

typedef struct CoStart {
  State *L;
  int nargs;
} CoStart;

static void resume_body(State *L, void *ud) {
  int n = *(int *)ud;
  TValue *firstArg = L->top - n;
  d_call(L, firstArg - 1, MULTRET);
}

static void co_main(void *arg) {
  State *L = (State *)arg;
  int n = L->nargs_xfer;
  int status;
  L->nCcalls = L->resumer ? L->resumer->nCcalls : 0;
  status = d_rawrunprotected(L, resume_body, &n);
  if (status == TS_OK) {
    L->status = TS_OK;
    L->nargs_xfer = (int)(L->top - (L->ci->func + 1));
  } else {
    L->status = (uint8_t)status;
    L->ci = &L->base_ci;
    /* keep error object on top */
    d_seterrorobj(L, status, L->top);
    L->ci = &L->base_ci;
  }
  L->costatus = 4;  /* dead */
  ctx_switch(&L->ctx_sp, L->resumer->ctx_sp);
}

int ls_resume(State *L, State *from, int nargs, int *nresults) {
  Global *g = G(L);
  if (L->costatus == 4 || (L->costatus != 0 && L->costatus != 2) || L->status > TS_YIELD) {
    const char *msg = (L->costatus == 4 || L->status > TS_YIELD) ? "cannot resume dead coroutine" : "cannot resume non-suspended coroutine";
    L->top -= nargs;
    setstr(L->top, str_newc(L, msg));
    L->top++;
    *nresults = 1;
    return TS_ERRRUN;
  }
  if (L->costatus == 0 && L->started == 0) {
    /* starting: function must be below args */
    if (L->top - nargs - 1 <= L->ci->func) {
      L->top -= nargs;
      setstr(L->top, str_newc(L, "cannot resume dead coroutine"));
      L->top++;
      *nresults = 1;
      return TS_ERRRUN;
    }
  }
  if (from && from->nCcalls >= MAXCCALLS) {
    L->top -= nargs;
    setstr(L->top, str_newc(L, "C stack overflow"));
    L->top++;
    *nresults = 1;
    return TS_ERRRUN;
  }
  L->resumer = from;
  if (from) from->costatus = 3;
  L->costatus = 1;
  g->running = L;
  L->nargs_xfer = nargs;
  if (!L->started) {
    L->started = 1;
    L->cstack = alloccstack(L);
    if (L->cstack == NULL) {
      g->running = from;
      if (from) from->costatus = 1;
      L->costatus = 0;
      L->started = 0;
      L->top -= nargs;
      setstr(L->top, G(L)->memerrmsg);
      L->top++;
      *nresults = 1;
      return TS_ERRMEM;
    }
    L->ctx_sp = ctx_make(L->cstack, CSTACKSIZE, co_main, L);
  }
  L->status = TS_OK;
  ctx_switch(&from->ctx_sp, L->ctx_sp);
  /* back in resumer */
  g->running = from;
  if (from) from->costatus = 1;
  L->resumer = NULL;
  if (L->status == TS_YIELD) {
    L->costatus = 2;
    *nresults = L->nargs_xfer;
    return TS_YIELD;
  } else if (L->status == TS_OK) {
    L->costatus = 4;
    *nresults = L->nargs_xfer;
    if (L->cstack) {
      freecstack(L, L->cstack);
      L->cstack = NULL;
    }
    return TS_OK;
  } else {
    int st = L->status;
    L->costatus = 4;
    *nresults = 1;
    if (L->cstack) {
      freecstack(L, L->cstack);
      L->cstack = NULL;
    }
    return st;
  }
}

int ls_yield(State *L, int nresults) {
  if (L == G(L)->mainthread || L->resumer == NULL) {
    if (L != G(L)->mainthread)
      dbg_runerror(L, "attempt to yield across a C-call boundary");
    else
      dbg_runerror(L, "attempt to yield from outside a coroutine");
  }
  L->status = TS_YIELD;
  L->nargs_xfer = nresults;
  ctx_switch(&L->ctx_sp, L->resumer->ctx_sp);
  /* resumed */
  L->status = TS_OK;
  return L->nargs_xfer;
}

int ls_isyieldable(State *L) {
  return L != G(L)->mainthread;
}

int ls_status(State *L) {
  return L->status;
}

/* close a suspended or dead coroutine: run pending to-be-closed variables */
static void closeco_body(State *L, void *ud) {
  int *st = (int *)ud;
  func_close(L, L->stack + 1, *st);
}

int ls_closethread(State *L, State *from) {
  int status = L->status;
  Global *g = G(L);
  State *oldrunning = g->running;
  L->resumer = from;
  L->ci = &L->base_ci;
  L->errjmp = NULL;
  L->nCcalls = from ? from->nCcalls : 0;
  if (status == TS_YIELD) status = TS_OK;
  L->status = TS_OK;
  if (L->ntbc > 0 || L->openupval) {
    if (status != TS_OK) {
      /* error object on top */
    }
    for (;;) {
      int st = (status == TS_OK) ? -1 : status;
      int r;
      g->running = L;
      r = d_rawrunprotected(L, closeco_body, &st);
      g->running = oldrunning;
      if (r == TS_OK) break;
      status = r;
    }
  }
  upval_close(L, L->stack);
  L->ntbc = 0;
  if (status != TS_OK) {
    TValue err = *(L->top - 1);
    L->top = L->stack + 1;
    *L->top = err;
    L->top++;
  } else
    L->top = L->stack + 1;
  L->ci = &L->base_ci;
  L->costatus = 4;
  L->status = (uint8_t)status;
  L->started = 1;
  if (L->cstack) {
    freecstack(L, L->cstack);
    L->cstack = NULL;
  }
  L->resumer = NULL;
  return status;
}
