{"command":"cd /workspace/src && cat > vm.c <<'EOF'
/* virtual machine */
#include "core.h"
#include "opcodes.h"

#define MAXTAGLOOP 2000

/* ---------------- metamethods ---------------- */

static const char *const tmnames[] = {
  "__index", "__newindex", "__gc", "__mode", "__len", "__eq",
  "__add", "__sub", "__mul", "__mod", "__pow", "__div", "__idiv",
  "__band", "__bor", "__bxor", "__shl", "__shr",
  "__unm", "__bnot", "__lt", "__le", "__concat", "__call", "__close"
};

void tm_init(State *L) {
  int i;
  for (i = 0; i < TM_N; i++) {
    G(L)->tmname[i] = str_newc(L, tmnames[i]);
    G(L)->tmname[i]->marked |= 4;
  }
}

Table *getmetatable_obj(State *L, const TValue *o) {
  switch (o->tt) {
    case T_TAB: return tabvalue(o)->meta;
    case T_UD: return udvalue(o)->meta;
    default: return G(L)->mt[basetype(o->tt)];
  }
}

const TValue *tm_get(State *L, Table *events, int event) {
  const TValue *tm;
  if (events == NULL) return NULL;
  if (event < 8 && (events->flags & (1u << event))) return NULL;
  tm = tab_getshortstr(events, G(L)->tmname[event]);
  if (isnil(tm)) {
    if (event < 8) events->flags |= (uint8_t)(1u << event);
    return NULL;
  }
  return tm;
}

const TValue *tm_byobj(State *L, const TValue *o, int event) {
  Table *mt = getmetatable_obj(L, o);
  const TValue *tm;
  if (mt == NULL) return NULL;
  tm = tab_getshortstr(mt, G(L)->tmname[event]);
  return isnil(tm) ? NULL : tm;
}

const char *obj_typename(State *L, const TValue *o) {
  Table *mt;
  if ((o->tt == T_TAB && (mt = tabvalue(o)->meta) != NULL) ||
      (o->tt == T_UD && (mt = udvalue(o)->meta) != NULL)) {
    const TValue *name = tab_getshortstr(mt, str_newc(L, "__name"));
    if (isstr(name)) return getstr(strvalue(name));
  }
  return ttypename(basetype(o->tt));
}

void tm_callres(State *L, const TValue *f, const TValue *p1, const TValue *p2, TValue *res) {
  TValue *func;
  TValue fv = *f, a = *p1, b = *p2;
  checkstack(L, 3);
  func = L->top;
  func[0] = fv;
  func[1] = a;
  func[2] = b;
  L->top = func + 3;
  d_call(L, func, 1);
  L->top--;
  *res = *L->top;
}

void tm_call(State *L, const TValue *f, const TValue *p1, const TValue *p2, const TValue *p3) {
  TValue *func;
  TValue fv = *f, a = *p1, b = *p2, c = *p3;
  checkstack(L, 4);
  func = L->top;
  func[0] = fv;
  func[1] = a;
  func[2] = b;
  func[3] = c;
  L->top = func + 4;
  d_call(L, func, 0);
}

static int callbinTM(State *L, const TValue *p1, const TValue *p2, TValue *res, int event) {
  const TValue *tm = tm_byobj(L, p1, event);
  if (tm == NULL) tm = tm_byobj(L, p2, event);
  if (tm == NULL) return 0;
  tm_callres(L, tm, p1, p2, res);
  return 1;
}

static void trybinTM(State *L, const TValue *p1, const TValue *p2, TValue *res, int event) {
  if (!callbinTM(L, p1, p2, res, event)) {
    switch (event) {
      case TM_BAND: case TM_BOR: case TM_BXOR:
      case TM_SHL: case TM_SHR: case TM_BNOT: {
        if (isnum(p1) && isnum(p2))
          dbg_tointerror(L, p1, p2);
        else
          dbg_opinterror(L, p1, p2, "perform bitwise operation on");
      }
      /* FALLTHROUGH */
      default:
        dbg_opinterror(L, p1, p2, "perform arithmetic on");
    }
  }
}

static int callorderTM(State *L, const TValue *p1, const TValue *p2, int event) {
  TValue res;
  if (callbinTM(L, p1, p2, &res, event))
    return !isfalsy(&res);
  dbg_ordererror(L, p1, p2);
  return 0;
}

/* ---------------- arithmetic ---------------- */

static const int arith2tm[] = {
  TM_ADD, TM_SUB, TM_MUL, TM_MOD, TM_POW, TM_DIV, TM_IDIV,
  TM_BAND, TM_BOR, TM_BXOR, TM_SHL, TM_SHR, TM_UNM, TM_BNOT
};

void vm_arith(State *L, int op, const TValue *a, const TValue *b, TValue *res) {
  if (!raw_arith(L, op, a, b, res))
    trybinTM(L, a, b, res, arith2tm[op]);
}

/* ---------------- comparisons ---------------- */

static int l_strcmp(const Str *ts1, const Str *ts2) {
  const char *s1 = ts1->data;
  size_t rl1 = ts1->len;
  const char *s2 = ts2->data;
  size_t rl2 = ts2->len;
  for (;;) {
    int temp = strcoll(s1, s2);
    if (temp != 0) return temp;
    else {
      size_t zl1 = strlen(s1);
      size_t zl2 = strlen(s2);
      if (zl2 == rl2) return (zl1 == rl1) ? 0 : 1;
      else if (zl1 == rl1) return -1;
      zl1++; zl2++;
      s1 += zl1; rl1 -= zl1;
      s2 += zl2; rl2 -= zl2;
    }
  }
}

#define l_intfitsf(i) ((luint)((i) + ((lint)1 << 53)) <= ((luint)2 << 53))

static int LTintfloat(lint i, lnum f) {
  if (l_intfitsf(i)) return (lnum)i < f;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 2)) return i < fi;
    else return f > 0;
  }
}

static int LEintfloat(lint i, lnum f) {
  if (l_intfitsf(i)) return (lnum)i <= f;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 1)) return i <= fi;
    else return f > 0;
  }
}

static int LTfloatint(lnum f, lint i) {
  if (l_intfitsf(i)) return f < (lnum)i;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 1)) return fi < i;
    else return f < 0;
  }
}

static int LEfloatint(lnum f, lint i) {
  if (l_intfitsf(i)) return f <= (lnum)i;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 2)) return fi <= i;
    else return f < 0;
  }
}

static int LTnum(const TValue *l, const TValue *r) {
  if (isint(l)) {
    lint li = ivalue(l);
    if (isint(r)) return li < ivalue(r);
    else return LTintfloat(li, fltvalue(r));
  } else {
    lnum lf = fltvalue(l);
    if (isflt(r)) return lf < fltvalue(r);
    else return LTfloatint(lf, ivalue(r));
  }
}

static int LEnum(const TValue *l, const TValue *r) {
  if (isint(l)) {
    lint li = ivalue(l);
    if (isint(r)) return li <= ivalue(r);
    else return LEintfloat(li, fltvalue(r));
  } else {
    lnum lf = fltvalue(l);
    if (isflt(r)) return lf <= fltvalue(r);
    else return LEfloatint(lf, ivalue(r));
  }
}

int vm_lessthan(State *L, const TValue *l, const TValue *r) {
  if (isnum(l) && isnum(r)) return LTnum(l, r);
  if (isstr(l) && isstr(r)) return l_strcmp(strvalue(l), strvalue(r)) < 0;
  return callorderTM(L, l, r, TM_LT);
}

int vm_lessequal(State *L, const TValue *l, const TValue *r) {
  if (isnum(l) && isnum(r)) return LEnum(l, r);
  if (isstr(l) && isstr(r)) return l_strcmp(strvalue(l), strvalue(r)) <= 0;
  return callorderTM(L, l, r, TM_LE);
}

int vm_rawequal(const TValue *t1, const TValue *t2) {
  return vm_equalobj(NULL, t1, t2);
}

int vm_equalobj(State *L, const TValue *t1, const TValue *t2) {
  const TValue *tm;
  if (t1->tt != t2->tt) {
    if (isnum(t1) && isnum(t2)) {
      lint i1, i2;
      return (vm_tointeger(t1, &i1) && vm_tointeger(t2, &i2) && i1 == i2);
    }
    return 0;
  }
  switch (t1->tt) {
    case T_NIL: case T_FALSE: case T_TRUE: return 1;
    case T_INT: return ivalue(t1) == ivalue(t2);
    case T_FLT: return fltvalue(t1) == fltvalue(t2);
    case T_LUD: return t1->v.p == t2->v.p;
    case T_LCF: return t1->v.f == t2->v.f;
    case T_STR: return str_eq(strvalue(t1), strvalue(t2));
    case T_UD: {
      if (udvalue(t1) == udvalue(t2)) return 1;
      else if (L == NULL) return 0;
      tm = tm_get(L, udvalue(t1)->meta, TM_EQ);
      if (tm == NULL) tm = tm_get(L, udvalue(t2)->meta, TM_EQ);
      break;
    }
    case T_TAB: {
      if (tabvalue(t1) == tabvalue(t2)) return 1;
      else if (L == NULL) return 0;
      tm = tm_get(L, tabvalue(t1)->meta, TM_EQ);
      if (tm == NULL) tm = tm_get(L, tabvalue(t2)->meta, TM_EQ);
      break;
    }
    default:
      return gcvalue(t1) == gcvalue(t2);
  }
  if (tm == NULL) return 0;
  {
    TValue res;
    tm_callres(L, tm, t1, t2, &res);
    return !isfalsy(&res);
  }
}

/* ---------------- get / set ---------------- */

void vm_finishget(State *L, const TValue *t, TValue *key, TValue *val, const TValue *slot) {
  int loop;
  const TValue *tm;
  TValue tv;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    if (slot == NULL) {
      tm = tm_byobj(L, t, TM_INDEX);
      if (tm == NULL) dbg_typeerror(L, t, "index");
    } else {
      tm = tm_get(L, tabvalue(t)->meta, TM_INDEX);
      if (tm == NULL) {
        setnil(val);
        return;
      }
    }
    if (isfunc(tm)) {
      tm_callres(L, tm, t, key, val);
      return;
    }
    tv = *tm;
    t = &tv;
    if (istab(t)) {
      slot = tab_get(tabvalue(t), key);
      if (!isnil(slot)) {
        *val = *slot;
        return;
      }
    } else
      slot = NULL;
  }
  dbg_runerror(L, "'__index' chain too long; possibly a loop");
}

void vm_finishset(State *L, const TValue *t, TValue *key, TValue *val, const TValue *slot) {
  int loop;
  TValue tv;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    const TValue *tm;
    if (slot != NULL) {
      Table *h = tabvalue(t);
      tm = tm_get(L, h->meta, TM_NEWINDEX);
      if (tm == NULL) {
        TValue v = *val;
        TValue *s = tab_set(L, h, key);
        *s = v;
        return;
      }
    } else {
      tm = tm_byobj(L, t, TM_NEWINDEX);
      if (tm == NULL) dbg_typeerror(L, t, "index");
    }
    if (isfunc(tm)) {
      tm_call(L, tm, t, key, val);
      return;
    }
    tv = *tm;
    t = &tv;
    if (istab(t)) {
      slot = tab_get(tabvalue(t), key);
      if (!isnil(slot)) {
        *(TValue *)slot = *val;
        return;
      }
    } else
      slot = NULL;
  }
  dbg_runerror(L, "'__newindex' chain too long; possibly a loop");
}

void vm_gettable(State *L, const TValue *t, TValue *key, TValue *val) {
  if (istab(t)) {
    const TValue *slot = tab_get(tabvalue(t), key);
    if (!isnil(slot)) *val = *slot;
    else vm_finishget(L, t, key, val, slot);
  } else
    vm_finishget(L, t, key, val, NULL);
}

void vm_settable(State *L, const TValue *t, TValue *key, TValue *val) {
  if (istab(t)) {
    const TValue *slot = tab_get(tabvalue(t), key);
    if (!isnil(slot)) *(TValue *)slot = *val;
    else vm_finishset(L, t, key, val, slot);
  } else
    vm_finishset(L, t, key, val, NULL);
}

/* ---------------- concat / length ---------------- */

static int tostringable(State *L, TValue *o) {
  if (isstr(o)) return 1;
  if (isnum(o)) {
    obj_tostring(L, o);
    return 1;
  }
  return 0;
}

#define isemptystr(o) (isstr(o) && strvalue(o)->len == 0)

void vm_concat(State *L, int total) {
  if (total == 1) return;
  do {
    TValue *top = L->top;
    int n = 2;
    if (!(isstr(top - 2) || isnum(top - 2)) || !tostringable(L, top - 1)) {
      if (!callbinTM(L, top - 2, top - 1, top - 2, TM_CONCAT))
        dbg_concaterror(L, top - 2, top - 1);
    } else if (isemptystr(top - 1)) {
      tostringable(L, top - 2);
    } else if (isemptystr(top - 2)) {
      *(top - 2) = *(top - 1);
    } else {
      size_t tl = strvalue(top - 1)->len;
      Str *ts;
      char *buf;
      for (n = 1; n < total && tostringable(L, top - n - 1); n++) {
        size_t l = strvalue(top - n - 1)->len;
        if (l >= ((size_t)1 << 62) - tl) {
          L->top = top - total;
          dbg_runerror(L, "string length overflow");
        }
        tl += l;
      }
      if (tl <= MAXSHORTLEN) {
        char tmp[MAXSHORTLEN + 1];
        size_t off = 0;
        int j;
        for (j = n; j > 0; j--) {
          Str *s = strvalue(top - j);
          memcpy(tmp + off, s->data, s->len);
          off += s->len;
        }
        ts = str_new(L, tmp, tl);
      } else {
        size_t off = 0;
        int j;
        ts = str_newlong(L, tl);
        buf = ts->data;
        for (j = n; j > 0; j--) {
          Str *s = strvalue(top - j);
          memcpy(buf + off, s->data, s->len);
          off += s->len;
        }
      }
      setstr(top - n, ts);
    }
    total -= n - 1;
    L->top -= n - 1;
  } while (total > 1);
}

void vm_objlen(State *L, TValue *ra, const TValue *rb) {
  const TValue *tm;
  switch (rb->tt) {
    case T_TAB: {
      Table *h = tabvalue(rb);
      tm = tm_get(L, h->meta, TM_LEN);
      if (tm) break;
      setint(ra, (lint)tab_getn(h));
      return;
    }
    case T_STR:
      setint(ra, (lint)strvalue(rb)->len);
      return;
    default:
      tm = tm_byobj(L, rb, TM_LEN);
      if (tm == NULL) dbg_typeerror(L, rb, "get length of");
      break;
  }
  tm_callres(L, tm, rb, rb, ra);
}

/* ---------------- for loops ---------------- */

static int forlimit(State *L, lint init, const TValue *lim, lint *p, lint step) {
  int ok;
  if (isint(lim)) { *p = ivalue(lim); ok = 1; }
  else if (isflt(lim)) ok = flt_tointeger(fltvalue(lim), p, step < 0 ? 2 : 1);
  else {
    TValue v;
    if (isstr(lim) && str2number(getstr(strvalue(lim)), &v) == strvalue(lim)->len + 1) {
      if (isint(&v)) { *p = ivalue(&v); ok = 1; }
      else ok = flt_tointeger(fltvalue(&v), p, step < 0 ? 2 : 1);
      if (!ok) lim = &v;
    } else
      ok = 0;
    if (!ok) {
      lnum flim;
      if (!obj_tonumber(lim, &flim)) dbg_forerror(L, lim, "limit");
      if (flim > 0) {
        if (step < 0) return 1;
        *p = INT64_MAX;
      } else {
        if (step > 0) return 1;
        *p = INT64_MIN;
      }
      return (step > 0 ? init > *p : init < *p);
    }
  }
  if (!ok) {
    lnum flim;
    if (!obj_tonumber(lim, &flim)) dbg_forerror(L, lim, "limit");
    if (flim > 0) {
      if (step < 0) return 1;
      *p = INT64_MAX;
    } else {
      if (step > 0) return 1;
      *p = INT64_MIN;
    }
  }
  return (step > 0 ? init > *p : init < *p);
}

static int forprep(State *L, TValue *ra) {
  TValue *pinit = ra;
  TValue *plimit = ra + 1;
  TValue *pstep = ra + 2;
  if (isint(pinit) && isint(pstep)) {
    lint init = ivalue(pinit);
    lint step = ivalue(pstep);
    lint limit;
    if (step == 0) dbg_runerror(L, "'for' step is zero");
    ra[3] = *pinit;
    if (forlimit(L, init, plimit, &limit, step))
      return 1;
    else {
      luint count;
      if (step > 0) {
        count = (luint)limit - (luint)init;
        if (step != 1) count /= (luint)step;
      } else {
        count = (luint)init - (luint)limit;
        count /= (luint)(-(step + 1)) + 1u;
      }
      setint(plimit, (lint)count);
    }
  } else {
    lnum init, flimit, step;
    if (!obj_tonumber(plimit, &flimit)) dbg_forerror(L, plimit, "limit");
    if (!obj_tonumber(pstep, &step)) dbg_forerror(L, pstep, "step");
    if (!obj_tonumber(pinit, &init)) dbg_forerror(L, pinit, "initial value");
    if (step == 0) dbg_runerror(L, "'for' step is zero");
    if (step > 0 ? flimit < init : init < flimit)
      return 1;
    setflt(plimit, flimit);
    setflt(pstep, step);
    setflt(ra, init);
    setflt(ra + 3, init);
  }
  return 0;
}

/* ---------------- closures ---------------- */

static void pushclosure(State *L, Proto *p, UpVal **encup, TValue *base, TValue *ra) {
  int nup = p->sizeup;
  UpvalDesc *uv = p->upvals;
  int i;
  LClosure *ncl = lcl_new(L, nup);
  ncl->p = p;
  setlcl(ra, ncl);
  for (i = 0; i < nup; i++) {
    if (uv[i].instack)
      ncl->up[i] = upval_find(L, base + uv[i].idx);
    else
      ncl->up[i] = encup[uv[i].idx];
  }
}

/* ---------------- main interpreter ---------------- */

#define RKB(i) (((i).k & 1) ? k + IB(i) : base + IB(i))
#define RKC(i) (((i).k & 2) ? k + IC(i) : base + IC(i))
#define savepc() (ci->savedpc = pc)
#define savestate() (ci->savedpc = pc, L->top = ci->top)
#define Protect(exp) do { savestate(); exp; } while (0)

#define op_arithI(iop, fop, tm) { \
  TValue *v1 = RKB(i); TValue *v2 = RKC(i); \
  if (isint(v1) && isint(v2)) { lint i1 = ivalue(v1), i2 = ivalue(v2); setint(ra, iop); } \
  else if (isnum(v1) && isnum(v2)) { lnum n1 = nvalue(v1), n2 = nvalue(v2); setflt(ra, fop); } \
  else { Protect(trybinTM(L, v1, v2, ra, tm)); } }

#define op_arithF(fop, tm) { \
  TValue *v1 = RKB(i); TValue *v2 = RKC(i); \
  if (isnum(v1) && isnum(v2)) { lnum n1 = nvalue(v1), n2 = nvalue(v2); setflt(ra, fop); } \
  else { Protect(trybinTM(L, v1, v2, ra, tm)); } }

#define op_bitwise(iop, tm) { \
  TValue *v1 = RKB(i); TValue *v2 = RKC(i); lint i1, i2; \
  if (isint(v1) && isint(v2)) { i1 = ivalue(v1); i2 = ivalue(v2); setint(ra, iop); } \
  else if (vm_tointeger(v1, &i1) && vm_tointeger(v2, &i2)) { setint(ra, iop); } \
  else { Protect(trybinTM(L, v1, v2, ra, tm)); } }

#define dojump(i) (pc += (i).u.sbx)
#define donextjump() { Instr ni = *pc; pc += ni.u.sbx + 1; }

void vm_execute(State *L, CallInfo *ci) {
  LClosure *cl;
  TValue *k;
  TValue *base;
  const Instr *pc;
  int trap;
startfunc:
returning:
  cl = ci_func(ci);
  k = cl->p->k;
  pc = ci->savedpc;
  base = ci->func + 1;
  trap = L->hookmask;
  if (trap && pc == cl->p->code) {
    /* call hook already done in precall; nothing */
  }
  for (;;) {
    Instr i;
    TValue *ra;
    if (trap) {
      extern void dbg_traceexec(State *L, const Instr *pc);
      savestate();
      dbg_traceexec(L, pc);
      trap = L->hookmask;
    }
    i = *pc++;
    ra = base + i.a;
    switch (i.op) {
      case OP_MOVE:
        *ra = base[IB(i)];
        break;
      case OP_LOADK:
        *ra = k[i.u.bx];
        break;
      case OP_LOADI:
        setint(ra, i.u.sbx);
        break;
      case OP_LOADNIL: {
        int b = IB(i);
        do { setnil(ra++); } while (b--);
        break;
      }
      case OP_LOADFALSE:
        setbool(ra, 0);
        break;
      case OP_LOADTRUE:
        setbool(ra, 1);
        break;
      case OP_LFALSESKIP:
        setbool(ra, 0);
        pc++;
        break;
      case OP_GETUPVAL:
        *ra = *cl->up[IB(i)]->v;
        break;
      case OP_SETUPVAL:
        *cl->up[IB(i)]->v = *ra;
        break;
      case OP_GETTABUP: {
        TValue *upval = cl->up[IB(i)]->v;
        TValue *rc = k + IC(i);
        if (istab(upval)) {
          const TValue *slot = tab_getshortstr(tabvalue(upval), strvalue(rc));
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, upval, rc, ra, slot));
        } else
          Protect(vm_finishget(L, upval, rc, ra, NULL));
        break;
      }
      case OP_GETTABLE: {
        TValue *rb = base + IB(i);
        TValue *rc = RKC(i);
        if (istab(rb)) {
          const TValue *slot = isint(rc) ? tab_getint(tabvalue(rb), ivalue(rc)) : tab_get(tabvalue(rb), rc);
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, rb, rc, ra, slot));
        } else
          Protect(vm_finishget(L, rb, rc, ra, NULL));
        break;
      }
      case OP_GETI: {
        TValue *rb = base + IB(i);
        if (istab(rb)) {
          const TValue *slot = tab_getint(tabvalue(rb), IC(i));
          if (!isnil(slot)) { *ra = *slot; break; }
          {
            TValue key;
            setint(&key, IC(i));
            Protect(vm_finishget(L, rb, &key, ra, slot));
          }
        } else {
          TValue key;
          setint(&key, IC(i));
          Protect(vm_finishget(L, rb, &key, ra, NULL));
        }
        break;
      }
      case OP_GETFIELD: {
        TValue *rb = base + IB(i);
        TValue *rc = k + IC(i);
        if (istab(rb)) {
          const TValue *slot = tab_getstr(tabvalue(rb), strvalue(rc));
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, rb, rc, ra, slot));
        } else
          Protect(vm_finishget(L, rb, rc, ra, NULL));
        break;
      }
      case OP_SETTABUP: {
        TValue *upval = cl->up[i.a]->v;
        TValue *rb = k + IB(i);
        TValue *rc = RKC(i);
        if (istab(upval)) {
          const TValue *slot = tab_getshortstr(tabvalue(upval), strvalue(rb));
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          Protect(vm_finishset(L, upval, rb, rc, slot));
        } else
          Protect(vm_finishset(L, upval, rb, rc, NULL));
        break;
      }
      case OP_SETTABLE: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        if (istab(ra)) {
          const TValue *slot = isint(rb) ? tab_getint(tabvalue(ra), ivalue(rb)) : tab_get(tabvalue(ra), rb);
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          Protect(vm_finishset(L, ra, rb, rc, slot));
        } else
          Protect(vm_finishset(L, ra, rb, rc, NULL));
        break;
      }
      case OP_SETI: {
        TValue *rc = RKC(i);
        if (istab(ra)) {
          const TValue *slot = tab_getint(tabvalue(ra), IB(i));
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          {
            TValue key;
            setint(&key, IB(i));
            Protect(vm_finishset(L, ra, &key, rc, slot));
          }
        } else {
          TValue key;
          setint(&key, IB(i));
          Protect(vm_finishset(L, ra, &key, rc, NULL));
        }
        break;
      }
      case OP_SETFIELD: {
        TValue *rb = k + IB(i);
        TValue *rc = RKC(i);
        if (istab(ra)) {
          const TValue *slot = tab_getstr(tabvalue(ra), strvalue(rb));
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          Protect(vm_finishset(L, ra, rb, rc, slot));
        } else
          Protect(vm_finishset(L, ra, rb, rc, NULL));
        break;
      }
      case OP_NEWTABLE: {
        unsigned int b = IB(i);
        unsigned int c = IC(i);
        Table *t;
        if (i.k) b = pc->u.bx;
        if (i.k) pc++;
        savestate();
        t = tab_new(L);
        settab(ra, t);
        if (b != 0 || c != 0) tab_resize(L, t, b, c);
        gc_checkGC(L);
        break;
      }
      case OP_SELF: {
        TValue rb = base[IB(i)];
        TValue *rc = RKC(i);
        ra[1] = rb;
        if (istab(&rb)) {
          const TValue *slot = tab_getstr(tabvalue(&rb), strvalue(rc));
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, base + IB(i) == ra ? ra + 1 : base + IB(i), rc, ra, slot));
        } else
          Protect(vm_finishget(L, base + IB(i) == ra ? ra + 1 : base + IB(i), rc, ra, NULL));
        break;
      }
      case OP_ADD: op_arithI((lint)((luint)i1 + (luint)i2), n1 + n2, TM_ADD); break;
      case OP_SUB: op_arithI((lint)((luint)i1 - (luint)i2), n1 - n2, TM_SUB); break;
      case OP_MUL: op_arithI((lint)((luint)i1 * (luint)i2), n1 * n2, TM_MUL); break;
      case OP_MOD: {
        TValue *v1 = RKB(i); TValue *v2 = RKC(i);
        if (isint(v1) && isint(v2)) {
          savestate();
          setint(ra, int_mod(L, ivalue(v1), ivalue(v2)));
        } else if (isnum(v1) && isnum(v2)) {
          setflt(ra, flt_mod(nvalue(v1), nvalue(v2)));
        } else
          Protect(trybinTM(L, v1, v2, ra, TM_MOD));
        break;
      }
      case OP_IDIV: {
        TValue *v1 = RKB(i); TValue *v2 = RKC(i);
        if (isint(v1) && isint(v2)) {
          savestate();
          setint(ra, int_idiv(L, ivalue(v1), ivalue(v2)));
        } else if (isnum(v1) && isnum(v2)) {
          setflt(ra, floor(nvalue(v1) / nvalue(v2)));
        } else
          Protect(trybinTM(L, v1, v2, ra, TM_IDIV));
        break;
      }
      case OP_POW: op_arithF((n2 == 2) ? n1 * n1 : pow(n1, n2), TM_POW); break;
      case OP_DIV: op_arithF(n1 / n2, TM_DIV); break;
      case OP_BAND: op_bitwise((lint)((luint)i1 & (luint)i2), TM_BAND); break;
      case OP_BOR: op_bitwise((lint)((luint)i1 | (luint)i2), TM_BOR); break;
      case OP_BXOR: op_bitwise((lint)((luint)i1 ^ (luint)i2), TM_BXOR); break;
      case OP_SHL: op_bitwise(shiftl(i1, i2), TM_SHL); break;
      case OP_SHR: op_bitwise(shiftl(i1, (lint)(0u - (luint)i2)), TM_SHR); break;
      case OP_UNM: {
        TValue *rb = base + IB(i);
        if (isint(rb)) {
          setint(ra, (lint)(0u - (luint)ivalue(rb)));
        } else if (isflt(rb)) {
          setflt(ra, -fltvalue(rb));
        } else
          Protect(trybinTM(L, rb, rb, ra, TM_UNM));
        break;
      }
      case OP_BNOT: {
        TValue *rb = base + IB(i);
        lint ib;
        if (vm_tointeger(rb, &ib)) {
          setint(ra, (lint)(~(luint)ib));
        } else
          Protect(trybinTM(L, rb, rb, ra, TM_BNOT));
        break;
      }
      case OP_NOT: {
        TValue *rb = base + IB(i);
        setbool(ra, isfalsy(rb));
        break;
      }
      case OP_LEN: {
        Protect(vm_objlen(L, ra, base + IB(i)));
        break;
      }
      case OP_CONCAT: {
        int n = IB(i);
        savepc();
        L->top = ra + n;
        vm_concat(L, n);
        L->top = ci->top;
        gc_checkGC(L);
        break;
      }
      case OP_CLOSE: {
        Protect(func_close(L, ra, -1));
        break;
      }
      case OP_TBC: {
        Protect(tbc_new(L, ra));
        break;
      }
      case OP_JMP:
        dojump(i);
        break;
      case OP_EQ: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        int cond;
        if (rb->tt == rc->tt && rb->tt == T_INT) cond = ivalue(rb) == ivalue(rc);
        else if (rb->tt == rc->tt && rb->tt == T_STR && strvalue(rb)->isshort) cond = strvalue(rb) == strvalue(rc);
        else {
          Protect(cond = vm_equalobj(L, rb, rc));
        }
        if (cond != i.a) pc++;
        else donextjump();
        break;
      }
      case OP_LT: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        int cond;
        if (isint(rb) && isint(rc)) cond = ivalue(rb) < ivalue(rc);
        else if (isnum(rb) && isnum(rc)) cond = LTnum(rb, rc);
        else Protect(cond = vm_lessthan(L, rb, rc));
        if (cond != i.a) pc++;
        else donextjump();
        break;
      }
      case OP_LE: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        int cond;
        if (isint(rb) && isint(rc)) cond = ivalue(rb) <= ivalue(rc);
        else if (isnum(rb) && isnum(rc)) cond = LEnum(rb, rc);
        else Protect(cond = vm_lessequal(L, rb, rc));
        if (cond != i.a) pc++;
        else donextjump();
        break;
      }
      case OP_TEST: {
        int cond = !isfalsy(ra);
        if (cond != IC(i)) pc++;
        else donextjump();
        break;
      }
      case OP_TESTSET: {
        TValue *rb = base + IB(i);
        if (isfalsy(rb) == IC(i)) pc++;
        else {
          *ra = *rb;
          donextjump();
        }
        break;
      }
      case OP_CALL: {
        int b = IB(i);
        int nresults = IC(i) - 1;
        CallInfo *newci;
        if (b != 0) L->top = ra + b;
        savepc();
        if ((newci = d_precall(L, ra, nresults)) == NULL) {
          if (nresults >= 0) L->top = ci->top;
          trap = L->hookmask;
        } else {
          ci = newci;
          goto startfunc;
        }
        break;
      }
      case OP_TAILCALL: {
        int b = IB(i);
        int r;
        if (b != 0) L->top = ra + b;
        else b = (int)(L->top - ra);
        savepc();
        if (L->openupval && L->openupval->v >= base) upval_close(L, base);
        {
          extern int d_pretailcall(State *L, CallInfo *ci, TValue *func, int n);
          r = d_pretailcall(L, ci, ra, b);
        }
        if (r == 0) goto startfunc;
        /* C function: results from ra to top */
        {
          int n = (int)(L->top - ra);
          if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
          {
            int wanted = ci->nresults;
            d_poscall(L, ci, n);
            if (ci->status & CIST_FRESH) return;
            ci = L->ci;
            if (wanted >= 0) L->top = ci->top;
          }
          goto returning;
        }
      }
      case OP_RETURN: {
        int n = IB(i) - 1;
        int wanted;
        if (n < 0) n = (int)(L->top - ra);
        L->top = ra + n;
        savepc();
        if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base)) {
          func_close(L, base, -1);
          L->top = ra + n;
        }
        if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
        wanted = ci->nresults;
        d_poscall(L, ci, n);
        if (ci->status & CIST_FRESH) return;
        ci = L->ci;
        if (wanted >= 0) L->top = ci->top;
        goto returning;
      }
      case OP_RETURN0: {
        int wanted;
        if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base)) {
          savestate();
          L->top = ra;
          func_close(L, base, -1);
        }
        if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
        L->top = ra;
        wanted = ci->nresults;
        if (L->hookmask) {
          savepc();
          d_poscall(L, ci, 0);
        } else {
          TValue *res = ci->func;
          int j;
          L->ci = ci->prev;
          for (j = 0; j < wanted; j++) setnil(res + j);
          L->top = res + (wanted > 0 ? wanted : 0);
        }
        if (ci->status & CIST_FRESH) return;
        ci = L->ci;
        if (wanted >= 0) L->top = ci->top;
        goto returning;
      }
      case OP_RETURN1: {
        int wanted;
        if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base) || L->hookmask) {
          /* general path */
          L->top = ra + 1;
          savepc();
          if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base)) {
            func_close(L, base, -1);
            L->top = ra + 1;
          }
          if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
          wanted = ci->nresults;
          d_poscall(L, ci, 1);
        } else {
          TValue *res;
          int j;
          if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
          res = ci->func;
          wanted = ci->nresults;
          L->ci = ci->prev;
          if (wanted == 0) L->top = res;
          else {
            *res = *ra;
            for (j = 1; j < wanted; j++) setnil(res + j);
            L->top = res + (wanted < 0 ? 1 : wanted);
          }
        }
        if (ci->status & CIST_FRESH) return;
        ci = L->ci;
        if (wanted >= 0) L->top = ci->top;
        goto returning;
      }
      case OP_FORLOOP: {
        if (isint(ra + 2)) {
          luint count = (luint)ivalue(ra + 1);
          if (count > 0) {
            lint step = ivalue(ra + 2);
            lint idx = ivalue(ra);
            setint(ra + 1, (lint)(count - 1));
            idx = (lint)((luint)idx + (luint)step);
            setint(ra, idx);
            setint(ra + 3, idx);
            dojump(i);
          }
        } else {
          lnum step = fltvalue(ra + 2);
          lnum limit = fltvalue(ra + 1);
          lnum idx = fltvalue(ra);
          idx += step;
          if (step > 0 ? idx <= limit : limit <= idx) {
            setflt(ra, idx);
            setflt(ra + 3, idx);
            dojump(i);
          }
        }
        break;
      }
      case OP_FORPREP: {
        int skip;
        Protect(skip = forprep(L, ra));
        if (skip) dojump(i);
        break;
      }
      case OP_TFORPREP: {
        Protect(tbc_new(L, ra + 3));
        dojump(i);
        break;
      }
      case OP_TFORCALL: {
        ra[4] = ra[0];
        ra[5] = ra[1];
        ra[6] = ra[2];
        L->top = ra + 4 + 3;
        savepc();
        d_call(L, ra + 4, IC(i));
        L->top = ci->top;
        trap = L->hookmask;
        /* next instruction is TFORLOOP */
        i = *pc++;
        ra = base + i.a;
        if (!isnil(ra + 4)) {
          ra[2] = ra[4];
          dojump(i);
        }
        break;
      }
      case OP_TFORLOOP: {
        if (!isnil(ra + 4)) {
          ra[2] = ra[4];
          dojump(i);
        }
        break;
      }
      case OP_SETLIST: {
        int n = IB(i);
        unsigned int last = pc->u.bx;
        Table *h = tabvalue(ra);
        pc++;
        if (n == 0) n = (int)(L->top - ra) - 1;
        L->top = ci->top;
        last += (unsigned int)n;
        if (last > h->asize) {
          savepc();
          tab_resizearray(L, h, last);
        }
        for (; n > 0; n--) {
          h->array[last - 1] = ra[n];
          last--;
        }
        break;
      }
      case OP_CLOSURE: {
        Proto *p = cl->p->p[i.u.bx];
        savestate();
        pushclosure(L, p, cl->up, base, ra);
        gc_checkGC(L);
        break;
      }
      case OP_VARARG: {
        int n = IC(i) - 1;
        int nextra = ci->nextra;
        TValue *src = ci->func - nextra;
        int j;
        if (cl->p->is_vararg == 2) {
          /* named vararg table */
          TValue *tv = base + cl->p->numparams;
          if (istab(tv)) {
            Table *t = tabvalue(tv);
            const TValue *nv = tab_getstr(t, str_newc(L, "n"));
            lint cnt = isint(nv) ? ivalue(nv) : 0;
            if (cnt < 0) cnt = 0;
            if (n < 0) {
              n = (int)cnt;
              savestate();
              checkstack(L, n);
              L->top = ra + n;
            }
            for (j = 0; j < n; j++) {
              if (j < cnt) ra[j] = *tab_getint(t, j + 1);
              else setnil(ra + j);
            }
            break;
          }
        }
        if (n < 0) {
          n = nextra;
          savestate();
          checkstack(L, n);
          L->top = ra + n;
        }
        for (j = 0; j < n && j < nextra; j++) ra[j] = src[j];
        for (; j < n; j++) setnil(ra + j);
        break;
      }
      case OP_ERRNNIL: {
        if (!isnil(ra)) {
          savestate();
          dbg_runerror(L, "global '%s' already defined", getstr(strvalue(&k[i.u.bx])));
        }
        break;
      }
      case OP_EXTRAARG:
        break;
      default:
        break;
    }
  }
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > vm.c <<'EOF'
/* virtual machine */
#include "core.h"
#include "opcodes.h"

#define MAXTAGLOOP 2000

/* ---------------- metamethods ---------------- */

static const char *const tmnames[] = {
  "__index", "__newindex", "__gc", "__mode", "__len", "__eq",
  "__add", "__sub", "__mul", "__mod", "__pow", "__div", "__idiv",
  "__band", "__bor", "__bxor", "__shl", "__shr",
  "__unm", "__bnot", "__lt", "__le", "__concat", "__call", "__close"
};

void tm_init(State *L) {
  int i;
  for (i = 0; i < TM_N; i++) {
    G(L)->tmname[i] = str_newc(L, tmnames[i]);
    G(L)->tmname[i]->marked |= 4;
  }
}

Table *getmetatable_obj(State *L, const TValue *o) {
  switch (o->tt) {
    case T_TAB: return tabvalue(o)->meta;
    case T_UD: return udvalue(o)->meta;
    default: return G(L)->mt[basetype(o->tt)];
  }
}

const TValue *tm_get(State *L, Table *events, int event) {
  const TValue *tm;
  if (events == NULL) return NULL;
  if (event < 8 && (events->flags & (1u << event))) return NULL;
  tm = tab_getshortstr(events, G(L)->tmname[event]);
  if (isnil(tm)) {
    if (event < 8) events->flags |= (uint8_t)(1u << event);
    return NULL;
  }
  return tm;
}

const TValue *tm_byobj(State *L, const TValue *o, int event) {
  Table *mt = getmetatable_obj(L, o);
  const TValue *tm;
  if (mt == NULL) return NULL;
  tm = tab_getshortstr(mt, G(L)->tmname[event]);
  return isnil(tm) ? NULL : tm;
}

const char *obj_typename(State *L, const TValue *o) {
  Table *mt;
  if ((o->tt == T_TAB && (mt = tabvalue(o)->meta) != NULL) ||
      (o->tt == T_UD && (mt = udvalue(o)->meta) != NULL)) {
    const TValue *name = tab_getshortstr(mt, str_newc(L, "__name"));
    if (isstr(name)) return getstr(strvalue(name));
  }
  return ttypename(basetype(o->tt));
}

void tm_callres(State *L, const TValue *f, const TValue *p1, const TValue *p2, TValue *res) {
  TValue *func;
  TValue fv = *f, a = *p1, b = *p2;
  checkstack(L, 3);
  func = L->top;
  func[0] = fv;
  func[1] = a;
  func[2] = b;
  L->top = func + 3;
  d_call(L, func, 1);
  L->top--;
  *res = *L->top;
}

void tm_call(State *L, const TValue *f, const TValue *p1, const TValue *p2, const TValue *p3) {
  TValue *func;
  TValue fv = *f, a = *p1, b = *p2, c = *p3;
  checkstack(L, 4);
  func = L->top;
  func[0] = fv;
  func[1] = a;
  func[2] = b;
  func[3] = c;
  L->top = func + 4;
  d_call(L, func, 0);
}

static int callbinTM(State *L, const TValue *p1, const TValue *p2, TValue *res, int event) {
  const TValue *tm = tm_byobj(L, p1, event);
  if (tm == NULL) tm = tm_byobj(L, p2, event);
  if (tm == NULL) return 0;
  tm_callres(L, tm, p1, p2, res);
  return 1;
}

static void trybinTM(State *L, const TValue *p1, const TValue *p2, TValue *res, int event) {
  if (!callbinTM(L, p1, p2, res, event)) {
    switch (event) {
      case TM_BAND: case TM_BOR: case TM_BXOR:
      case TM_SHL: case TM_SHR: case TM_BNOT: {
        if (isnum(p1) && isnum(p2))
          dbg_tointerror(L, p1, p2);
        else
          dbg_opinterror(L, p1, p2, "perform bitwise operation on");
      }
      /* FALLTHROUGH */
      default:
        dbg_opinterror(L, p1, p2, "perform arithmetic on");
    }
  }
}

static int callorderTM(State *L, const TValue *p1, const TValue *p2, int event) {
  TValue res;
  if (callbinTM(L, p1, p2, &res, event))
    return !isfalsy(&res);
  dbg_ordererror(L, p1, p2);
  return 0;
}

/* ---------------- arithmetic ---------------- */

static const int arith2tm[] = {
  TM_ADD, TM_SUB, TM_MUL, TM_MOD, TM_POW, TM_DIV, TM_IDIV,
  TM_BAND, TM_BOR, TM_BXOR, TM_SHL, TM_SHR, TM_UNM, TM_BNOT
};

void vm_arith(State *L, int op, const TValue *a, const TValue *b, TValue *res) {
  if (!raw_arith(L, op, a, b, res))
    trybinTM(L, a, b, res, arith2tm[op]);
}

/* ---------------- comparisons ---------------- */

static int l_strcmp(const Str *ts1, const Str *ts2) {
  const char *s1 = ts1->data;
  size_t rl1 = ts1->len;
  const char *s2 = ts2->data;
  size_t rl2 = ts2->len;
  for (;;) {
    int temp = strcoll(s1, s2);
    if (temp != 0) return temp;
    else {
      size_t zl1 = strlen(s1);
      size_t zl2 = strlen(s2);
      if (zl2 == rl2) return (zl1 == rl1) ? 0 : 1;
      else if (zl1 == rl1) return -1;
      zl1++; zl2++;
      s1 += zl1; rl1 -= zl1;
      s2 += zl2; rl2 -= zl2;
    }
  }
}

#define l_intfitsf(i) ((luint)((i) + ((lint)1 << 53)) <= ((luint)2 << 53))

static int LTintfloat(lint i, lnum f) {
  if (l_intfitsf(i)) return (lnum)i < f;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 2)) return i < fi;
    else return f > 0;
  }
}

static int LEintfloat(lint i, lnum f) {
  if (l_intfitsf(i)) return (lnum)i <= f;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 1)) return i <= fi;
    else return f > 0;
  }
}

static int LTfloatint(lnum f, lint i) {
  if (l_intfitsf(i)) return f < (lnum)i;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 1)) return fi < i;
    else return f < 0;
  }
}

static int LEfloatint(lnum f, lint i) {
  if (l_intfitsf(i)) return f <= (lnum)i;
  else {
    lint fi;
    if (flt_tointeger(f, &fi, 2)) return fi <= i;
    else return f < 0;
  }
}

static int LTnum(const TValue *l, const TValue *r) {
  if (isint(l)) {
    lint li = ivalue(l);
    if (isint(r)) return li < ivalue(r);
    else return LTintfloat(li, fltvalue(r));
  } else {
    lnum lf = fltvalue(l);
    if (isflt(r)) return lf < fltvalue(r);
    else return LTfloatint(lf, ivalue(r));
  }
}

static int LEnum(const TValue *l, const TValue *r) {
  if (isint(l)) {
    lint li = ivalue(l);
    if (isint(r)) return li <= ivalue(r);
    else return LEintfloat(li, fltvalue(r));
  } else {
    lnum lf = fltvalue(l);
    if (isflt(r)) return lf <= fltvalue(r);
    else return LEfloatint(lf, ivalue(r));
  }
}

int vm_lessthan(State *L, const TValue *l, const TValue *r) {
  if (isnum(l) && isnum(r)) return LTnum(l, r);
  if (isstr(l) && isstr(r)) return l_strcmp(strvalue(l), strvalue(r)) < 0;
  return callorderTM(L, l, r, TM_LT);
}

int vm_lessequal(State *L, const TValue *l, const TValue *r) {
  if (isnum(l) && isnum(r)) return LEnum(l, r);
  if (isstr(l) && isstr(r)) return l_strcmp(strvalue(l), strvalue(r)) <= 0;
  return callorderTM(L, l, r, TM_LE);
}

int vm_rawequal(const TValue *t1, const TValue *t2) {
  return vm_equalobj(NULL, t1, t2);
}

int vm_equalobj(State *L, const TValue *t1, const TValue *t2) {
  const TValue *tm;
  if (t1->tt != t2->tt) {
    if (isnum(t1) && isnum(t2)) {
      lint i1, i2;
      return (vm_tointeger(t1, &i1) && vm_tointeger(t2, &i2) && i1 == i2);
    }
    return 0;
  }
  switch (t1->tt) {
    case T_NIL: case T_FALSE: case T_TRUE: return 1;
    case T_INT: return ivalue(t1) == ivalue(t2);
    case T_FLT: return fltvalue(t1) == fltvalue(t2);
    case T_LUD: return t1->v.p == t2->v.p;
    case T_LCF: return t1->v.f == t2->v.f;
    case T_STR: return str_eq(strvalue(t1), strvalue(t2));
    case T_UD: {
      if (udvalue(t1) == udvalue(t2)) return 1;
      else if (L == NULL) return 0;
      tm = tm_get(L, udvalue(t1)->meta, TM_EQ);
      if (tm == NULL) tm = tm_get(L, udvalue(t2)->meta, TM_EQ);
      break;
    }
    case T_TAB: {
      if (tabvalue(t1) == tabvalue(t2)) return 1;
      else if (L == NULL) return 0;
      tm = tm_get(L, tabvalue(t1)->meta, TM_EQ);
      if (tm == NULL) tm = tm_get(L, tabvalue(t2)->meta, TM_EQ);
      break;
    }
    default:
      return gcvalue(t1) == gcvalue(t2);
  }
  if (tm == NULL) return 0;
  {
    TValue res;
    tm_callres(L, tm, t1, t2, &res);
    return !isfalsy(&res);
  }
}

/* ---------------- get / set ---------------- */

void vm_finishget(State *L, const TValue *t, TValue *key, TValue *val, const TValue *slot) {
  int loop;
  const TValue *tm;
  TValue tv;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    if (slot == NULL) {
      tm = tm_byobj(L, t, TM_INDEX);
      if (tm == NULL) dbg_typeerror(L, t, "index");
    } else {
      tm = tm_get(L, tabvalue(t)->meta, TM_INDEX);
      if (tm == NULL) {
        setnil(val);
        return;
      }
    }
    if (isfunc(tm)) {
      tm_callres(L, tm, t, key, val);
      return;
    }
    tv = *tm;
    t = &tv;
    if (istab(t)) {
      slot = tab_get(tabvalue(t), key);
      if (!isnil(slot)) {
        *val = *slot;
        return;
      }
    } else
      slot = NULL;
  }
  dbg_runerror(L, "'__index' chain too long; possibly a loop");
}

void vm_finishset(State *L, const TValue *t, TValue *key, TValue *val, const TValue *slot) {
  int loop;
  TValue tv;
  for (loop = 0; loop < MAXTAGLOOP; loop++) {
    const TValue *tm;
    if (slot != NULL) {
      Table *h = tabvalue(t);
      tm = tm_get(L, h->meta, TM_NEWINDEX);
      if (tm == NULL) {
        TValue v = *val;
        TValue *s = tab_set(L, h, key);
        *s = v;
        return;
      }
    } else {
      tm = tm_byobj(L, t, TM_NEWINDEX);
      if (tm == NULL) dbg_typeerror(L, t, "index");
    }
    if (isfunc(tm)) {
      tm_call(L, tm, t, key, val);
      return;
    }
    tv = *tm;
    t = &tv;
    if (istab(t)) {
      slot = tab_get(tabvalue(t), key);
      if (!isnil(slot)) {
        *(TValue *)slot = *val;
        return;
      }
    } else
      slot = NULL;
  }
  dbg_runerror(L, "'__newindex' chain too long; possibly a loop");
}

void vm_gettable(State *L, const TValue *t, TValue *key, TValue *val) {
  if (istab(t)) {
    const TValue *slot = tab_get(tabvalue(t), key);
    if (!isnil(slot)) *val = *slot;
    else vm_finishget(L, t, key, val, slot);
  } else
    vm_finishget(L, t, key, val, NULL);
}

void vm_settable(State *L, const TValue *t, TValue *key, TValue *val) {
  if (istab(t)) {
    const TValue *slot = tab_get(tabvalue(t), key);
    if (!isnil(slot)) *(TValue *)slot = *val;
    else vm_finishset(L, t, key, val, slot);
  } else
    vm_finishset(L, t, key, val, NULL);
}

/* ---------------- concat / length ---------------- */

static int tostringable(State *L, TValue *o) {
  if (isstr(o)) return 1;
  if (isnum(o)) {
    obj_tostring(L, o);
    return 1;
  }
  return 0;
}

#define isemptystr(o) (isstr(o) && strvalue(o)->len == 0)

void vm_concat(State *L, int total) {
  if (total == 1) return;
  do {
    TValue *top = L->top;
    int n = 2;
    if (!(isstr(top - 2) || isnum(top - 2)) || !tostringable(L, top - 1)) {
      if (!callbinTM(L, top - 2, top - 1, top - 2, TM_CONCAT))
        dbg_concaterror(L, top - 2, top - 1);
    } else if (isemptystr(top - 1)) {
      tostringable(L, top - 2);
    } else if (isemptystr(top - 2)) {
      *(top - 2) = *(top - 1);
    } else {
      size_t tl = strvalue(top - 1)->len;
      Str *ts;
      char *buf;
      for (n = 1; n < total && tostringable(L, top - n - 1); n++) {
        size_t l = strvalue(top - n - 1)->len;
        if (l >= ((size_t)1 << 62) - tl) {
          L->top = top - total;
          dbg_runerror(L, "string length overflow");
        }
        tl += l;
      }
      if (tl <= MAXSHORTLEN) {
        char tmp[MAXSHORTLEN + 1];
        size_t off = 0;
        int j;
        for (j = n; j > 0; j--) {
          Str *s = strvalue(top - j);
          memcpy(tmp + off, s->data, s->len);
          off += s->len;
        }
        ts = str_new(L, tmp, tl);
      } else {
        size_t off = 0;
        int j;
        ts = str_newlong(L, tl);
        buf = ts->data;
        for (j = n; j > 0; j--) {
          Str *s = strvalue(top - j);
          memcpy(buf + off, s->data, s->len);
          off += s->len;
        }
      }
      setstr(top - n, ts);
    }
    total -= n - 1;
    L->top -= n - 1;
  } while (total > 1);
}

void vm_objlen(State *L, TValue *ra, const TValue *rb) {
  const TValue *tm;
  switch (rb->tt) {
    case T_TAB: {
      Table *h = tabvalue(rb);
      tm = tm_get(L, h->meta, TM_LEN);
      if (tm) break;
      setint(ra, (lint)tab_getn(h));
      return;
    }
    case T_STR:
      setint(ra, (lint)strvalue(rb)->len);
      return;
    default:
      tm = tm_byobj(L, rb, TM_LEN);
      if (tm == NULL) dbg_typeerror(L, rb, "get length of");
      break;
  }
  tm_callres(L, tm, rb, rb, ra);
}

/* ---------------- for loops ---------------- */

static int forlimit(State *L, lint init, const TValue *lim, lint *p, lint step) {
  int ok;
  if (isint(lim)) { *p = ivalue(lim); ok = 1; }
  else if (isflt(lim)) ok = flt_tointeger(fltvalue(lim), p, step < 0 ? 2 : 1);
  else {
    TValue v;
    if (isstr(lim) && str2number(getstr(strvalue(lim)), &v) == strvalue(lim)->len + 1) {
      if (isint(&v)) { *p = ivalue(&v); ok = 1; }
      else ok = flt_tointeger(fltvalue(&v), p, step < 0 ? 2 : 1);
      if (!ok) lim = &v;
    } else
      ok = 0;
    if (!ok) {
      lnum flim;
      if (!obj_tonumber(lim, &flim)) dbg_forerror(L, lim, "limit");
      if (flim > 0) {
        if (step < 0) return 1;
        *p = INT64_MAX;
      } else {
        if (step > 0) return 1;
        *p = INT64_MIN;
      }
      return (step > 0 ? init > *p : init < *p);
    }
  }
  if (!ok) {
    lnum flim;
    if (!obj_tonumber(lim, &flim)) dbg_forerror(L, lim, "limit");
    if (flim > 0) {
      if (step < 0) return 1;
      *p = INT64_MAX;
    } else {
      if (step > 0) return 1;
      *p = INT64_MIN;
    }
  }
  return (step > 0 ? init > *p : init < *p);
}

static int forprep(State *L, TValue *ra) {
  TValue *pinit = ra;
  TValue *plimit = ra + 1;
  TValue *pstep = ra + 2;
  if (isint(pinit) && isint(pstep)) {
    lint init = ivalue(pinit);
    lint step = ivalue(pstep);
    lint limit;
    if (step == 0) dbg_runerror(L, "'for' step is zero");
    ra[3] = *pinit;
    if (forlimit(L, init, plimit, &limit, step))
      return 1;
    else {
      luint count;
      if (step > 0) {
        count = (luint)limit - (luint)init;
        if (step != 1) count /= (luint)step;
      } else {
        count = (luint)init - (luint)limit;
        count /= (luint)(-(step + 1)) + 1u;
      }
      setint(plimit, (lint)count);
    }
  } else {
    lnum init, flimit, step;
    if (!obj_tonumber(plimit, &flimit)) dbg_forerror(L, plimit, "limit");
    if (!obj_tonumber(pstep, &step)) dbg_forerror(L, pstep, "step");
    if (!obj_tonumber(pinit, &init)) dbg_forerror(L, pinit, "initial value");
    if (step == 0) dbg_runerror(L, "'for' step is zero");
    if (step > 0 ? flimit < init : init < flimit)
      return 1;
    setflt(plimit, flimit);
    setflt(pstep, step);
    setflt(ra, init);
    setflt(ra + 3, init);
  }
  return 0;
}

/* ---------------- closures ---------------- */

static void pushclosure(State *L, Proto *p, UpVal **encup, TValue *base, TValue *ra) {
  int nup = p->sizeup;
  UpvalDesc *uv = p->upvals;
  int i;
  LClosure *ncl = lcl_new(L, nup);
  ncl->p = p;
  setlcl(ra, ncl);
  for (i = 0; i < nup; i++) {
    if (uv[i].instack)
      ncl->up[i] = upval_find(L, base + uv[i].idx);
    else
      ncl->up[i] = encup[uv[i].idx];
  }
}

/* ---------------- main interpreter ---------------- */

#define RKB(i) (((i).k & 1) ? k + IB(i) : base + IB(i))
#define RKC(i) (((i).k & 2) ? k + IC(i) : base + IC(i))
#define savepc() (ci->savedpc = pc)
#define savestate() (ci->savedpc = pc, L->top = ci->top)
#define Protect(exp) do { savestate(); exp; } while (0)

#define op_arithI(iop, fop, tm) { \
  TValue *v1 = RKB(i); TValue *v2 = RKC(i); \
  if (isint(v1) && isint(v2)) { lint i1 = ivalue(v1), i2 = ivalue(v2); setint(ra, iop); } \
  else if (isnum(v1) && isnum(v2)) { lnum n1 = nvalue(v1), n2 = nvalue(v2); setflt(ra, fop); } \
  else { Protect(trybinTM(L, v1, v2, ra, tm)); } }

#define op_arithF(fop, tm) { \
  TValue *v1 = RKB(i); TValue *v2 = RKC(i); \
  if (isnum(v1) && isnum(v2)) { lnum n1 = nvalue(v1), n2 = nvalue(v2); setflt(ra, fop); } \
  else { Protect(trybinTM(L, v1, v2, ra, tm)); } }

#define op_bitwise(iop, tm) { \
  TValue *v1 = RKB(i); TValue *v2 = RKC(i); lint i1, i2; \
  if (isint(v1) && isint(v2)) { i1 = ivalue(v1); i2 = ivalue(v2); setint(ra, iop); } \
  else if (vm_tointeger(v1, &i1) && vm_tointeger(v2, &i2)) { setint(ra, iop); } \
  else { Protect(trybinTM(L, v1, v2, ra, tm)); } }

#define dojump(i) (pc += (i).u.sbx)
#define donextjump() { Instr ni = *pc; pc += ni.u.sbx + 1; }

void vm_execute(State *L, CallInfo *ci) {
  LClosure *cl;
  TValue *k;
  TValue *base;
  const Instr *pc;
  int trap;
startfunc:
returning:
  cl = ci_func(ci);
  k = cl->p->k;
  pc = ci->savedpc;
  base = ci->func + 1;
  trap = L->hookmask;
  if (trap && pc == cl->p->code) {
    /* call hook already done in precall; nothing */
  }
  for (;;) {
    Instr i;
    TValue *ra;
    if (trap) {
      extern void dbg_traceexec(State *L, const Instr *pc);
      savestate();
      dbg_traceexec(L, pc);
      trap = L->hookmask;
    }
    i = *pc++;
    ra = base + i.a;
    switch (i.op) {
      case OP_MOVE:
        *ra = base[IB(i)];
        break;
      case OP_LOADK:
        *ra = k[i.u.bx];
        break;
      case OP_LOADI:
        setint(ra, i.u.sbx);
        break;
      case OP_LOADNIL: {
        int b = IB(i);
        do { setnil(ra++); } while (b--);
        break;
      }
      case OP_LOADFALSE:
        setbool(ra, 0);
        break;
      case OP_LOADTRUE:
        setbool(ra, 1);
        break;
      case OP_LFALSESKIP:
        setbool(ra, 0);
        pc++;
        break;
      case OP_GETUPVAL:
        *ra = *cl->up[IB(i)]->v;
        break;
      case OP_SETUPVAL:
        *cl->up[IB(i)]->v = *ra;
        break;
      case OP_GETTABUP: {
        TValue *upval = cl->up[IB(i)]->v;
        TValue *rc = k + IC(i);
        if (istab(upval)) {
          const TValue *slot = tab_getshortstr(tabvalue(upval), strvalue(rc));
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, upval, rc, ra, slot));
        } else
          Protect(vm_finishget(L, upval, rc, ra, NULL));
        break;
      }
      case OP_GETTABLE: {
        TValue *rb = base + IB(i);
        TValue *rc = RKC(i);
        if (istab(rb)) {
          const TValue *slot = isint(rc) ? tab_getint(tabvalue(rb), ivalue(rc)) : tab_get(tabvalue(rb), rc);
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, rb, rc, ra, slot));
        } else
          Protect(vm_finishget(L, rb, rc, ra, NULL));
        break;
      }
      case OP_GETI: {
        TValue *rb = base + IB(i);
        if (istab(rb)) {
          const TValue *slot = tab_getint(tabvalue(rb), IC(i));
          if (!isnil(slot)) { *ra = *slot; break; }
          {
            TValue key;
            setint(&key, IC(i));
            Protect(vm_finishget(L, rb, &key, ra, slot));
          }
        } else {
          TValue key;
          setint(&key, IC(i));
          Protect(vm_finishget(L, rb, &key, ra, NULL));
        }
        break;
      }
      case OP_GETFIELD: {
        TValue *rb = base + IB(i);
        TValue *rc = k + IC(i);
        if (istab(rb)) {
          const TValue *slot = tab_getstr(tabvalue(rb), strvalue(rc));
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, rb, rc, ra, slot));
        } else
          Protect(vm_finishget(L, rb, rc, ra, NULL));
        break;
      }
      case OP_SETTABUP: {
        TValue *upval = cl->up[i.a]->v;
        TValue *rb = k + IB(i);
        TValue *rc = RKC(i);
        if (istab(upval)) {
          const TValue *slot = tab_getshortstr(tabvalue(upval), strvalue(rb));
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          Protect(vm_finishset(L, upval, rb, rc, slot));
        } else
          Protect(vm_finishset(L, upval, rb, rc, NULL));
        break;
      }
      case OP_SETTABLE: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        if (istab(ra)) {
          const TValue *slot = isint(rb) ? tab_getint(tabvalue(ra), ivalue(rb)) : tab_get(tabvalue(ra), rb);
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          Protect(vm_finishset(L, ra, rb, rc, slot));
        } else
          Protect(vm_finishset(L, ra, rb, rc, NULL));
        break;
      }
      case OP_SETI: {
        TValue *rc = RKC(i);
        if (istab(ra)) {
          const TValue *slot = tab_getint(tabvalue(ra), IB(i));
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          {
            TValue key;
            setint(&key, IB(i));
            Protect(vm_finishset(L, ra, &key, rc, slot));
          }
        } else {
          TValue key;
          setint(&key, IB(i));
          Protect(vm_finishset(L, ra, &key, rc, NULL));
        }
        break;
      }
      case OP_SETFIELD: {
        TValue *rb = k + IB(i);
        TValue *rc = RKC(i);
        if (istab(ra)) {
          const TValue *slot = tab_getstr(tabvalue(ra), strvalue(rb));
          if (!isnil(slot)) { *(TValue *)slot = *rc; break; }
          Protect(vm_finishset(L, ra, rb, rc, slot));
        } else
          Protect(vm_finishset(L, ra, rb, rc, NULL));
        break;
      }
      case OP_NEWTABLE: {
        unsigned int b = IB(i);
        unsigned int c = IC(i);
        Table *t;
        if (i.k) b = pc->u.bx;
        if (i.k) pc++;
        savestate();
        t = tab_new(L);
        settab(ra, t);
        if (b != 0 || c != 0) tab_resize(L, t, b, c);
        gc_checkGC(L);
        break;
      }
      case OP_SELF: {
        TValue rb = base[IB(i)];
        TValue *rc = RKC(i);
        ra[1] = rb;
        if (istab(&rb)) {
          const TValue *slot = tab_getstr(tabvalue(&rb), strvalue(rc));
          if (!isnil(slot)) { *ra = *slot; break; }
          Protect(vm_finishget(L, base + IB(i) == ra ? ra + 1 : base + IB(i), rc, ra, slot));
        } else
          Protect(vm_finishget(L, base + IB(i) == ra ? ra + 1 : base + IB(i), rc, ra, NULL));
        break;
      }
      case OP_ADD: op_arithI((lint)((luint)i1 + (luint)i2), n1 + n2, TM_ADD); break;
      case OP_SUB: op_arithI((lint)((luint)i1 - (luint)i2), n1 - n2, TM_SUB); break;
      case OP_MUL: op_arithI((lint)((luint)i1 * (luint)i2), n1 * n2, TM_MUL); break;
      case OP_MOD: {
        TValue *v1 = RKB(i); TValue *v2 = RKC(i);
        if (isint(v1) && isint(v2)) {
          savestate();
          setint(ra, int_mod(L, ivalue(v1), ivalue(v2)));
        } else if (isnum(v1) && isnum(v2)) {
          setflt(ra, flt_mod(nvalue(v1), nvalue(v2)));
        } else
          Protect(trybinTM(L, v1, v2, ra, TM_MOD));
        break;
      }
      case OP_IDIV: {
        TValue *v1 = RKB(i); TValue *v2 = RKC(i);
        if (isint(v1) && isint(v2)) {
          savestate();
          setint(ra, int_idiv(L, ivalue(v1), ivalue(v2)));
        } else if (isnum(v1) && isnum(v2)) {
          setflt(ra, floor(nvalue(v1) / nvalue(v2)));
        } else
          Protect(trybinTM(L, v1, v2, ra, TM_IDIV));
        break;
      }
      case OP_POW: op_arithF((n2 == 2) ? n1 * n1 : pow(n1, n2), TM_POW); break;
      case OP_DIV: op_arithF(n1 / n2, TM_DIV); break;
      case OP_BAND: op_bitwise((lint)((luint)i1 & (luint)i2), TM_BAND); break;
      case OP_BOR: op_bitwise((lint)((luint)i1 | (luint)i2), TM_BOR); break;
      case OP_BXOR: op_bitwise((lint)((luint)i1 ^ (luint)i2), TM_BXOR); break;
      case OP_SHL: op_bitwise(shiftl(i1, i2), TM_SHL); break;
      case OP_SHR: op_bitwise(shiftl(i1, (lint)(0u - (luint)i2)), TM_SHR); break;
      case OP_UNM: {
        TValue *rb = base + IB(i);
        if (isint(rb)) {
          setint(ra, (lint)(0u - (luint)ivalue(rb)));
        } else if (isflt(rb)) {
          setflt(ra, -fltvalue(rb));
        } else
          Protect(trybinTM(L, rb, rb, ra, TM_UNM));
        break;
      }
      case OP_BNOT: {
        TValue *rb = base + IB(i);
        lint ib;
        if (vm_tointeger(rb, &ib)) {
          setint(ra, (lint)(~(luint)ib));
        } else
          Protect(trybinTM(L, rb, rb, ra, TM_BNOT));
        break;
      }
      case OP_NOT: {
        TValue *rb = base + IB(i);
        setbool(ra, isfalsy(rb));
        break;
      }
      case OP_LEN: {
        Protect(vm_objlen(L, ra, base + IB(i)));
        break;
      }
      case OP_CONCAT: {
        int n = IB(i);
        savepc();
        L->top = ra + n;
        vm_concat(L, n);
        L->top = ci->top;
        gc_checkGC(L);
        break;
      }
      case OP_CLOSE: {
        Protect(func_close(L, ra, -1));
        break;
      }
      case OP_TBC: {
        Protect(tbc_new(L, ra));
        break;
      }
      case OP_JMP:
        dojump(i);
        break;
      case OP_EQ: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        int cond;
        if (rb->tt == rc->tt && rb->tt == T_INT) cond = ivalue(rb) == ivalue(rc);
        else if (rb->tt == rc->tt && rb->tt == T_STR && strvalue(rb)->isshort) cond = strvalue(rb) == strvalue(rc);
        else {
          Protect(cond = vm_equalobj(L, rb, rc));
        }
        if (cond != i.a) pc++;
        else donextjump();
        break;
      }
      case OP_LT: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        int cond;
        if (isint(rb) && isint(rc)) cond = ivalue(rb) < ivalue(rc);
        else if (isnum(rb) && isnum(rc)) cond = LTnum(rb, rc);
        else Protect(cond = vm_lessthan(L, rb, rc));
        if (cond != i.a) pc++;
        else donextjump();
        break;
      }
      case OP_LE: {
        TValue *rb = RKB(i);
        TValue *rc = RKC(i);
        int cond;
        if (isint(rb) && isint(rc)) cond = ivalue(rb) <= ivalue(rc);
        else if (isnum(rb) && isnum(rc)) cond = LEnum(rb, rc);
        else Protect(cond = vm_lessequal(L, rb, rc));
        if (cond != i.a) pc++;
        else donextjump();
        break;
      }
      case OP_TEST: {
        int cond = !isfalsy(ra);
        if (cond != IC(i)) pc++;
        else donextjump();
        break;
      }
      case OP_TESTSET: {
        TValue *rb = base + IB(i);
        if (isfalsy(rb) == IC(i)) pc++;
        else {
          *ra = *rb;
          donextjump();
        }
        break;
      }
      case OP_CALL: {
        int b = IB(i);
        int nresults = IC(i) - 1;
        CallInfo *newci;
        if (b != 0) L->top = ra + b;
        savepc();
        if ((newci = d_precall(L, ra, nresults)) == NULL) {
          if (nresults >= 0) L->top = ci->top;
          trap = L->hookmask;
        } else {
          ci = newci;
          goto startfunc;
        }
        break;
      }
      case OP_TAILCALL: {
        int b = IB(i);
        int r;
        if (b != 0) L->top = ra + b;
        else b = (int)(L->top - ra);
        savepc();
        if (L->openupval && L->openupval->v >= base) upval_close(L, base);
        {
          extern int d_pretailcall(State *L, CallInfo *ci, TValue *func, int n);
          r = d_pretailcall(L, ci, ra, b);
        }
        if (r == 0) goto startfunc;
        /* C function: results from ra to top */
        {
          int n = (int)(L->top - ra);
          if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
          {
            int wanted = ci->nresults;
            d_poscall(L, ci, n);
            if (ci->status & CIST_FRESH) return;
            ci = L->ci;
            if (wanted >= 0) L->top = ci->top;
          }
          goto returning;
        }
      }
      case OP_RETURN: {
        int n = IB(i) - 1;
        int wanted;
        if (n < 0) n = (int)(L->top - ra);
        L->top = ra + n;
        savepc();
        if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base)) {
          func_close(L, base, -1);
          L->top = ra + n;
        }
        if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
        wanted = ci->nresults;
        d_poscall(L, ci, n);
        if (ci->status & CIST_FRESH) return;
        ci = L->ci;
        if (wanted >= 0) L->top = ci->top;
        goto returning;
      }
      case OP_RETURN0: {
        int wanted;
        if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base)) {
          savestate();
          L->top = ra;
          func_close(L, base, -1);
        }
        if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
        L->top = ra;
        wanted = ci->nresults;
        if (L->hookmask) {
          savepc();
          d_poscall(L, ci, 0);
        } else {
          TValue *res = ci->func;
          int j;
          L->ci = ci->prev;
          for (j = 0; j < wanted; j++) setnil(res + j);
          L->top = res + (wanted > 0 ? wanted : 0);
        }
        if (ci->status & CIST_FRESH) return;
        ci = L->ci;
        if (wanted >= 0) L->top = ci->top;
        goto returning;
      }
      case OP_RETURN1: {
        int wanted;
        if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base) || L->hookmask) {
          /* general path */
          L->top = ra + 1;
          savepc();
          if ((L->openupval && L->openupval->v >= base) || (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= base)) {
            func_close(L, base, -1);
            L->top = ra + 1;
          }
          if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
          wanted = ci->nresults;
          d_poscall(L, ci, 1);
        } else {
          TValue *res;
          int j;
          if (cl->p->is_vararg) ci->func -= ci->nextra + cl->p->numparams + 1;
          res = ci->func;
          wanted = ci->nresults;
          L->ci = ci->prev;
          if (wanted == 0) L->top = res;
          else {
            *res = *ra;
            for (j = 1; j < wanted; j++) setnil(res + j);
            L->top = res + (wanted < 0 ? 1 : wanted);
          }
        }
        if (ci->status & CIST_FRESH) return;
        ci = L->ci;
        if (wanted >= 0) L->top = ci->top;
        goto returning;
      }
      case OP_FORLOOP: {
        if (isint(ra + 2)) {
          luint count = (luint)ivalue(ra + 1);
          if (count > 0) {
            lint step = ivalue(ra + 2);
            lint idx = ivalue(ra);
            setint(ra + 1, (lint)(count - 1));
            idx = (lint)((luint)idx + (luint)step);
            setint(ra, idx);
            setint(ra + 3, idx);
            dojump(i);
          }
        } else {
          lnum step = fltvalue(ra + 2);
          lnum limit = fltvalue(ra + 1);
          lnum idx = fltvalue(ra);
          idx += step;
          if (step > 0 ? idx <= limit : limit <= idx) {
            setflt(ra, idx);
            setflt(ra + 3, idx);
            dojump(i);
          }
        }
        break;
      }
      case OP_FORPREP: {
        int skip;
        Protect(skip = forprep(L, ra));
        if (skip) dojump(i);
        break;
      }
      case OP_TFORPREP: {
        Protect(tbc_new(L, ra + 3));
        dojump(i);
        break;
      }
      case OP_TFORCALL: {
        ra[4] = ra[0];
        ra[5] = ra[1];
        ra[6] = ra[2];
        L->top = ra + 4 + 3;
        savepc();
        d_call(L, ra + 4, IC(i));
        L->top = ci->top;
        trap = L->hookmask;
        /* next instruction is TFORLOOP */
        i = *pc++;
        ra = base + i.a;
        if (!isnil(ra + 4)) {
          ra[2] = ra[4];
          dojump(i);
        }
        break;
      }
      case OP_TFORLOOP: {
        if (!isnil(ra + 4)) {
          ra[2] = ra[4];
          dojump(i);
        }
        break;
      }
      case OP_SETLIST: {
        int n = IB(i);
        unsigned int last = pc->u.bx;
        Table *h = tabvalue(ra);
        pc++;
        if (n == 0) n = (int)(L->top - ra) - 1;
        L->top = ci->top;
        last += (unsigned int)n;
        if (last > h->asize) {
          savepc();
          tab_resizearray(L, h, last);
        }
        for (; n > 0; n--) {
          h->array[last - 1] = ra[n];
          last--;
        }
        break;
      }
      case OP_CLOSURE: {
        Proto *p = cl->p->p[i.u.bx];
        savestate();
        pushclosure(L, p, cl->up, base, ra);
        gc_checkGC(L);
        break;
      }
      case OP_VARARG: {
        int n = IC(i) - 1;
        int nextra = ci->nextra;
        TValue *src = ci->func - nextra;
        int j;
        if (cl->p->is_vararg == 2) {
          /* named vararg table */
          TValue *tv = base + cl->p->numparams;
          if (istab(tv)) {
            Table *t = tabvalue(tv);
            const TValue *nv = tab_getstr(t, str_newc(L, "n"));
            lint cnt = isint(nv) ? ivalue(nv) : 0;
            if (cnt < 0) cnt = 0;
            if (n < 0) {
              n = (int)cnt;
              savestate();
              checkstack(L, n);
              L->top = ra + n;
            }
            for (j = 0; j < n; j++) {
              if (j < cnt) ra[j] = *tab_getint(t, j + 1);
              else setnil(ra + j);
            }
            break;
          }
        }
        if (n < 0) {
          n = nextra;
          savestate();
          checkstack(L, n);
          L->top = ra + n;
        }
        for (j = 0; j < n && j < nextra; j++) ra[j] = src[j];
        for (; j < n; j++) setnil(ra + j);
        break;
      }
      case OP_ERRNNIL: {
        if (!isnil(ra)) {
          savestate();
          dbg_runerror(L, "global '%s' already defined", getstr(strvalue(&k[i.u.bx])));
        }
        break;
      }
      case OP_EXTRAARG:
        break;
      default:
        break;
    }
  }
}
EOF
echo ok

output.arguments:
{"command":"cd /workspace/src && cat > debug.c <<'EOF'
/* debug support: error messages, stack info, hooks */
#include "core.h"
#include "opcodes.h"

int dbg_getline(const Proto *p, int pc) {
  if (p->lineinfo == NULL || p->sizecode == 0) return -1;
  if (pc < 0) pc = 0;
  if (pc >= p->sizecode) pc = p->sizecode - 1;
  return p->lineinfo[pc];
}

int dbg_currentline(CallInfo *ci) {
  return dbg_getline(ci_func(ci)->p, currentpc(ci));
}

static const char *kindname(int kind) {
  switch (kind) {
    case VK_LOCAL: return "local";
    case VK_GLOBAL: return "global";
    case VK_FIELD: return "field";
    case VK_UPVAL: return "upvalue";
    case VK_METHOD: return "method";
    case VK_CONST: return "constant";
    case VK_FORITER: return "for iterator";
    default: return NULL;
  }
}

static const VarInfo *findvarinfo(const Proto *p, int pc, int which) {
  int lo = 0, hi = p->sizevarinfo - 1;
  int i;
  /* binary search for first entry with pc */
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (p->varinfo[mid].pc < pc) lo = mid + 1;
    else hi = mid - 1;
  }
  for (i = lo; i < p->sizevarinfo && p->varinfo[i].pc == pc; i++) {
    if (p->varinfo[i].which == which) return &p->varinfo[i];
  }
  return NULL;
}

/* figure out which operand of the current instruction 'o' is */
static int whichoperand(State *L, CallInfo *ci, const TValue *o, const Instr *ins) {
  LClosure *cl = ci_func(ci);
  TValue *base = ci->func + 1;
  TValue *k = cl->p->k;
  int isreg = (o >= base && o < ci->top);
  int reg = isreg ? (int)(o - base) : -1;
  switch (ins->op) {
    case OP_GETTABLE: case OP_GETFIELD: case OP_GETI: case OP_SELF:
      if (reg == IB(*ins)) return 1;
      return -1;
    case OP_GETTABUP:
      if (o == cl->up[IB(*ins)]->v) return 1;
      return -1;
    case OP_SETTABUP:
      if (o == cl->up[ins->a]->v) return 0;
      return -1;
    case OP_SETTABLE: case OP_SETFIELD: case OP_SETI:
      if (reg == ins->a) return 0;
      return -1;
    case OP_ADD: case OP_SUB: case OP_MUL: case OP_MOD: case OP_POW:
    case OP_DIV: case OP_IDIV: case OP_BAND: case OP_BOR: case OP_BXOR:
    case OP_SHL: case OP_SHR: {
      if ((ins->k & 1) ? (o == k + IB(*ins)) : (reg == IB(*ins))) return 1;
      if ((ins->k & 2) ? (o == k + IC(*ins)) : (reg == IC(*ins))) return 2;
      return -1;
    }
    case OP_UNM: case OP_BNOT: case OP_LEN: case OP_NOT:
      if (reg == IB(*ins)) return 1;
      return -1;
    case OP_CONCAT:
      if (reg >= ins->a && reg < ins->a + IB(*ins)) return reg - ins->a;
      return -1;
    case OP_CALL: case OP_TAILCALL:
      if (reg == ins->a) return 0;
      return -1;
    case OP_TFORCALL:
      if (reg == ins->a + 4) return 0;
      return -1;
    case OP_TBC:
      if (reg == ins->a) return 0;
      return -1;
    default:
      return -1;
  }
}

static const char *varinfo(State *L, const TValue *o) {
  CallInfo *ci = L->ci;
  if (isLua(ci)) {
    const Proto *p = ci_func(ci)->p;
    int pc = currentpc(ci);
    const Instr *ins;
    int which;
    if (pc < 0 || pc >= p->sizecode) return "";
    ins = &p->code[pc];
    which = whichoperand(L, ci, o, ins);
    if (which >= 0) {
      const VarInfo *vi = findvarinfo(p, pc, which);
      if (vi) {
        return pushfstring(L, " (%s '%s')", kindname(vi->kind), getstr(vi->name));
      }
    }
  }
  return "";
}

void dbg_addinfo(State *L, const char *msg, Str *src, int line) {
  char buff[IDSIZE];
  if (src) chunkid(buff, getstr(src), src->len);
  else {
    buff[0] = '?';
    buff[1] = '\0';
  }
  pushfstring(L, "%s:%d: %s", buff, line, msg);
}

void dbg_errormsg(State *L) {
  if (L->errfunc != NULL) {
    TValue *errfunc = L->errfunc;
    checkstack(L, 2);
    *L->top = *(L->top - 1);
    *(L->top - 1) = *errfunc;
    L->top++;
    d_callnoyield(L, L->top - 2, 1);
  }
  d_throw(L, TS_ERRRUN);
}

void dbg_runerror(State *L, const char *fmt, ...) {
  CallInfo *ci = L->ci;
  const char *msg;
  va_list argp;
  if (L->stack_end - L->top < 10) d_throw(L, TS_ERRERR);
  va_start(argp, fmt);
  msg = pushvfstring(L, fmt, argp);
  va_end(argp);
  if (isLua(ci)) {
    dbg_addinfo(L, msg, ci_func(ci)->p->source, dbg_currentline(ci));
    L->top[-2] = L->top[-1];
    L->top--;
  }
  dbg_errormsg(L);
}

static void typeerror(State *L, const TValue *o, const char *op, const char *extra) {
  const char *t = obj_typename(L, o);
  dbg_runerror(L, "attempt to %s a %s value%s", op, t, extra);
}

void dbg_typeerror(State *L, const TValue *o, const char *op) {
  typeerror(L, o, op, varinfo(L, o));
}

void dbg_callerror(State *L, const TValue *o) {
  typeerror(L, o, "call", varinfo(L, o));
}

void dbg_forerror(State *L, const TValue *o, const char *what) {
  dbg_runerror(L, "bad 'for' %s (number expected, got %s)", what, obj_typename(L, o));
}

void dbg_concaterror(State *L, const TValue *p1, const TValue *p2) {
  if (isstr(p1) || isnum(p1)) p1 = p2;
  dbg_typeerror(L, p1, "concatenate");
}

void dbg_opinterror(State *L, const TValue *p1, const TValue *p2, const char *msg) {
  if (!isnum(p1)) p2 = p1;
  dbg_typeerror(L, p2, msg);
}

void dbg_tointerror(State *L, const TValue *p1, const TValue *p2) {
  lint temp;
  if (!obj_tointeger(p1, &temp, 0) || isstr(p1)) p2 = p1;
  dbg_runerror(L, "number%s has no integer representation", varinfo(L, p2));
}

void dbg_ordererror(State *L, const TValue *p1, const TValue *p2) {
  const char *t1 = obj_typename(L, p1);
  const char *t2 = obj_typename(L, p2);
  if (strcmp(t1, t2) == 0)
    dbg_runerror(L, "attempt to compare two %s values", t1);
  else
    dbg_runerror(L, "attempt to compare %s with %s", t1, t2);
}

/* ---------------- function names ---------------- */

static const char *funcnamefromcode(State *L, const Proto *p, int pc, const char **name) {
  int tm = 0;
  const Instr *i;
  if (pc < 0 || pc >= p->sizecode) return NULL;
  i = &p->code[pc];
  switch (i->op) {
    case OP_CALL: case OP_TAILCALL: {
      const VarInfo *vi = findvarinfo(p, pc, 0);
      if (vi) {
        *name = getstr(vi->name);
        return kindname(vi->kind);
      }
      return NULL;
    }
    case OP_TFORCALL:
      *name = "for iterator";
      return "for iterator";
    case OP_SELF: case OP_GETTABUP: case OP_GETTABLE: case OP_GETI: case OP_GETFIELD:
      tm = TM_INDEX; break;
    case OP_SETTABUP: case OP_SETTABLE: case OP_SETI: case OP_SETFIELD:
      tm = TM_NEWINDEX; break;
    case OP_ADD: tm = TM_ADD; break;
    case OP_SUB: tm = TM_SUB; break;
    case OP_MUL: tm = TM_MUL; break;
    case OP_MOD: tm = TM_MOD; break;
    case OP_POW: tm = TM_POW; break;
    case OP_DIV: tm = TM_DIV; break;
    case OP_IDIV: tm = TM_IDIV; break;
    case OP_BAND: tm = TM_BAND; break;
    case OP_BOR: tm = TM_BOR; break;
    case OP_BXOR: tm = TM_BXOR; break;
    case OP_SHL: tm = TM_SHL; break;
    case OP_SHR: tm = TM_SHR; break;
    case OP_UNM: tm = TM_UNM; break;
    case OP_BNOT: tm = TM_BNOT; break;
    case OP_LEN: tm = TM_LEN; break;
    case OP_CONCAT: tm = TM_CONCAT; break;
    case OP_EQ: tm = TM_EQ; break;
    case OP_LT: tm = TM_LT; break;
    case OP_LE: tm = TM_LE; break;
    case OP_CLOSE: case OP_RETURN: case OP_RETURN0: case OP_RETURN1: tm = TM_CLOSE; break;
    default:
      return NULL;
  }
  *name = getstr(G(L)->tmname[tm]) + 2;
  return "metamethod";
}

static const char *funcnamefromcall(State *L, CallInfo *ci, const char **name) {
  if (ci->status & CIST_HOOKED) {
    *name = "?";
    return "hook";
  } else if (ci->status & CIST_FIN) {
    *name = "__gc";
    return "metamethod";
  } else if (isLua(ci))
    return funcnamefromcode(L, ci_func(ci)->p, currentpc(ci), name);
  else
    return NULL;
}

static const char *getfuncname(State *L, CallInfo *ci, const char **name) {
  if (ci != NULL && !(ci->status & CIST_TAIL) && ci->prev != NULL)
    return funcnamefromcall(L, ci->prev, name);
  return NULL;
}

/* ---------------- getstack / getinfo ---------------- */

int ls_getstack(State *L, int level, DebugInfo *ar) {
  CallInfo *ci;
  if (level < 0) return 0;
  for (ci = L->ci; level > 0 && ci != &L->base_ci; ci = ci->prev)
    level--;
  if (level == 0 && ci != &L->base_ci) {
    ar->i_ci = ci;
    return 1;
  }
  return 0;
}

static void funcinfo(DebugInfo *ar, const TValue *f) {
  if (f->tt != T_LCL) {
    ar->source = "=[C]";
    ar->srclen = 4;
    ar->linedefined = -1;
    ar->lastlinedefined = -1;
    ar->what = "C";
  } else {
    const Proto *p = lclvalue(f)->p;
    if (p->source) {
      ar->source = getstr(p->source);
      ar->srclen = p->source->len;
    } else {
      ar->source = "=?";
      ar->srclen = 2;
    }
    ar->linedefined = p->linedefined;
    ar->lastlinedefined = p->lastlinedefined;
    ar->what = (ar->linedefined == 0) ? "main" : "Lua";
  }
  chunkid(ar->short_src, ar->source, ar->srclen);
}

static void collectvalidlines(State *L, const TValue *f) {
  if (f->tt != T_LCL) {
    setnil(L->top);
    L->top++;
  } else {
    const Proto *p = lclvalue(f)->p;
    Table *t = tab_new(L);
    int i;
    TValue v;
    settab(L->top, t);
    L->top++;
    setbool(&v, 1);
    for (i = 0; i < p->sizecode; i++) {
      TValue *slot = tab_setint(L, t, p->lineinfo[i]);
      *slot = v;
    }
  }
}

int ls_getinfo(State *L, const char *what, DebugInfo *ar) {
  int status = 1;
  TValue *func;
  CallInfo *ci;
  TValue fv;
  if (*what == '>') {
    ci = NULL;
    fv = *(L->top - 1);
    func = &fv;
    what++;
    L->top--;
  } else {
    ci = ar->i_ci;
    func = ci->func;
  }
  {
    const char *w;
    for (w = what; *w; w++) {
      switch (*w) {
        case 'S':
          funcinfo(ar, func);
          break;
        case 'l':
          ar->currentline = (ci && isLua(ci)) ? dbg_currentline(ci) : -1;
          break;
        case 'u':
          if (func->tt == T_LCL) {
            ar->nups = lclvalue(func)->nup;
            ar->isvararg = lclvalue(func)->p->is_vararg ? 1 : 0;
            ar->nparams = lclvalue(func)->p->numparams;
          } else {
            ar->nups = func->tt == T_CCL ? cclvalue(func)->nup : 0;
            ar->isvararg = 1;
            ar->nparams = 0;
          }
          break;
        case 't':
          ar->istailcall = (ci) ? (ci->status & CIST_TAIL) != 0 : 0;
          break;
        case 'n':
          ar->namewhat = getfuncname(L, ci, &ar->name);
          if (ar->namewhat == NULL) {
            ar->namewhat = "";
            ar->name = NULL;
          }
          break;
        case 'r':
          ar->ftransfer = ar->ntransfer = 0;
          break;
        case 'L': case 'f':
          break;
        default:
          status = 0;
      }
    }
  }
  if (strchr(what, 'f')) {
    *L->top = *func;
    L->top++;
  }
  if (strchr(what, 'L'))
    collectvalidlines(L, func);
  return status;
}

static const char *findvararg(CallInfo *ci, int n, TValue **pos) {
  if (isLua(ci) && ci_func(ci)->p->is_vararg) {
    int nextra = ci->nextra;
    if (n >= -nextra) {
      *pos = ci->func - nextra - (n + 1);
      return "(vararg)";
    }
  }
  return NULL;
}

static const char *findlocal(State *L, CallInfo *ci, int n, TValue **pos) {
  TValue *base = ci->func + 1;
  const char *name = NULL;
  if (isLua(ci)) {
    if (n < 0)
      return findvararg(ci, n, pos);
    else
      name = getlocalname(ci_func(ci)->p, n, currentpc(ci));
  }
  if (name == NULL) {
    TValue *limit = (ci == L->ci) ? L->top : ci->next->func;
    if (limit - base >= n && n > 0)
      name = isLua(ci) ? "(temporary)" : "(C temporary)";
    else
      return NULL;
  }
  if (pos) *pos = base + (n - 1);
  return name;
}

const char *ls_getlocal(State *L, const DebugInfo *ar, int n) {
  const char *name;
  if (ar == NULL) {
    if (L->top[-1].tt != T_LCL) name = NULL;
    else name = getlocalname(lclvalue(L->top - 1)->p, n, 0);
  } else {
    TValue *pos = NULL;
    name = findlocal(L, ar->i_ci, n, &pos);
    if (name) {
      *L->top = *pos;
      L->top++;
    }
  }
  return name;
}

const char *ls_setlocal(State *L, const DebugInfo *ar, int n) {
  TValue *pos = NULL;
  const char *name = findlocal(L, ar->i_ci, n, &pos);
  if (name) {
    *pos = *(L->top - 1);
    L->top--;
  }
  return name;
}

/* ---------------- hooks ---------------- */

static const char *const hooknames[] = {"call", "return", "line", "count", "tail call"};

void dbg_callhook(State *L, int event, int line) {
  CallInfo *ci = L->ci;
  TValue *top = L->top;
  TValue *citop = ci->top;
  TValue hookf = L->hook;
  checkstack(L, 4);
  if (isLua(ci) && L->top < ci->top) L->top = ci->top;
  L->allowhook = 0;
  ci->status |= CIST_HOOKED;
  *L->top = hookf;
  L->top++;
  setstr(L->top, str_newc(L, hooknames[event]));
  L->top++;
  if (line >= 0) setint(L->top, line);
  else setnil(L->top);
  L->top++;
  d_call(L, L->top - 3, 0);
  ci->status &= ~CIST_HOOKED;
  L->allowhook = 1;
  ci->top = citop;
  L->top = top;
}

#define MASKCALL 1
#define MASKRET 2
#define MASKLINE 4
#define MASKCOUNT 8

void dbg_traceexec(State *L, const Instr *pc) {
  CallInfo *ci = L->ci;
  int mask = L->hookmask;
  const Proto *p = ci_func(ci)->p;
  int npci = (int)(pc - p->code);
  if (!L->allowhook) return;
  if (mask & MASKCOUNT) {
    if (--L->hookcount == 0) {
      L->hookcount = L->basehookcount;
      ci->savedpc = pc + 1;
      d_hook(L, 3, -1);
    }
  }
  if (mask & MASKLINE) {
    int newline = dbg_getline(p, npci);
    int oldpc = L->oldpc;
    if (oldpc < 0 || oldpc >= p->sizecode || npci <= oldpc || newline != dbg_getline(p, oldpc) || npci == 0) {
      ci->savedpc = pc + 1;
      d_hook(L, 2, newline);
    }
    L->oldpc = npci;
  }
}
EOF
