void ls_settable(State *L, int idx) {
  TValue t = *index2value(L, idx);
  vm_settable(L, &t, L->top - 2, L->top - 1);
  L->top -= 2;
}

void ls_setfield(State *L, int idx, const char *k) {
  TValue t = *index2value(L, idx);
  auxsetstr(L, &t, k);
}

void ls_seti(State *L, int idx, lint n) {
  TValue t = *index2value(L, idx);
  TValue key;
  setint(&key, n);
  vm_settable(L, &t, &key, L->top - 1);
  L->top--;
}

void ls_rawset(State *L, int idx) {
  Table *t = tabvalue(index2value(L, idx));
  TValue *slot = tab_set(L, t, L->top - 2);
  *slot = *(L->top - 1);
  L->top -= 2;
}

void ls_rawseti(State *L, int idx, lint n) {
  Table *t = tabvalue(index2value(L, idx));
  TValue *slot = tab_setint(L, t, n);
  *slot = *(L->top - 1);
  L->top--;
}

void ls_rawsetp(State *L, int idx, const void *p) {
  Table *t = tabvalue(index2value(L, idx));
  TValue k;
  TValue *slot;
  setlud(&k, (void *)p);
  slot = tab_set(L, t, &k);
  *slot = *(L->top - 1);
  L->top--;
}

int ls_setmetatable(State *L, int objindex) {
  TValue *obj = index2value(L, objindex);
  Table *mt;
  if (isnil(L->top - 1)) mt = NULL;
  else mt = tabvalue(L->top - 1);
  switch (obj->tt) {
    case T_TAB:
      tabvalue(obj)->meta = mt;
      if (mt) gc_checkfinalizer(L, gcvalue(obj), mt);
      break;
    case T_UD:
      udvalue(obj)->meta = mt;
      if (mt) gc_checkfinalizer(L, gcvalue(obj), mt);
      break;
    default:
      G(L)->mt[basetype(obj->tt)] = mt;
      break;
  }
  L->top--;
  return 1;
}

int ls_setiuservalue(State *L, int idx, int n) {
  TValue *o = index2value(L, idx);
  int res;
  if (!((unsigned int)(n) - 1u < (unsigned int)udvalue(o)->nuv))
    res = 0;
  else {
    udvalue(o)->uv[n - 1] = *(L->top - 1);
    res = 1;
  }
  L->top--;
  return res;
}

/* ---------------- calls ---------------- */

void ls_call(State *L, int nargs, int nresults) {
  TValue *func = L->top - (nargs + 1);
  d_call(L, func, nresults);
  if (nresults < 0 && L->ci->top < L->top) L->ci->top = L->top;
}

typedef struct CallS {
  TValue *func;
  int nresults;
} CallS;

static void f_call(State *L, void *ud) {
  CallS *c = (CallS *)ud;
  d_call(L, c->func, c->nresults);
}

int ls_pcall(State *L, int nargs, int nresults, int errfunc) {
  CallS c;
  int status;
  TValue *func = NULL;
  if (errfunc != 0) func = index2value(L, errfunc);
  c.func = L->top - (nargs + 1);
  c.nresults = nresults;
  status = d_pcall(L, f_call, &c, c.func, func);
  if (nresults < 0 && L->ci->top < L->top) L->ci->top = L->top;
  return status;
}

int ls_load(State *L, const char *buff, size_t size, const char *chunkname, const char *mode) {
  int status;
  if (!chunkname) chunkname = "?";
  status = d_protectedparser(L, buff, size, chunkname, mode);
  if (status == TS_OK) {
    LClosure *f = lclvalue(L->top - 1);
    if (f->nup >= 1) {
      const TValue *gt = tab_getint(tabvalue(&G(L)->registry), RIDX_GLOBALS);
      f->up[0]->value = *gt;
      f->up[0]->v = &f->up[0]->value;
    }
  }
  gc_checkGC(L);
  return status;
}

int ls_error(State *L) {
  TValue *errobj = L->top - 1;
  if (isstr(errobj) && strvalue(errobj) == G(L)->memerrmsg)
    d_throw(L, TS_ERRMEM);
  else
    dbg_errormsg(L);
}

int ls_next(State *L, int idx) {
  Table *t = tabvalue(index2value(L, idx));
  int more = tab_next(L, t, L->top - 1);
  if (more) api_incr_top(L);
  else L->top -= 1;
  return more;
}

void ls_toclose(State *L, int idx) {
  TValue *o = index2value(L, idx);
  tbc_new(L, o);
}

void ls_closeslot(State *L, int idx) {
  TValue *level = index2value(L, idx);
  func_close(L, level, -1);
  setnil(level);
}

void ls_concat(State *L, int n) {
  if (n > 0) vm_concat(L, n);
  else {
    setstr(L->top, str_new(L, "", 0));
    api_incr_top(L);
  }
  gc_checkGC(L);
}

void ls_len(State *L, int idx) {
  TValue t = *index2value(L, idx);
  vm_objlen(L, L->top, &t);
  api_incr_top(L);
}

/* ---------------- upvalues ---------------- */

static const char *aux_upvalue(TValue *fi, int n, TValue **val, GCObj **owner) {
  switch (fi->tt) {
    case T_CCL: {
      CClosure *f = cclvalue(fi);
      if (!((unsigned int)n - 1u < (unsigned int)f->nup)) return NULL;
      *val = &f->up[n - 1];
      if (owner) *owner = (GCObj *)f;
      return "";
    }
    case T_LCL: {
      LClosure *f = lclvalue(fi);
      Str *name;
      Proto *p = f->p;
      if (!((unsigned int)n - 1u < (unsigned int)p->sizeup)) return NULL;
      *val = f->up[n - 1]->v;
      if (owner) *owner = (GCObj *)f->up[n - 1];
      name = p->upvals[n - 1].name;
      return (name == NULL) ? "(no name)" : getstr(name);
    }
    default:
      return NULL;
  }
}

const char *ls_getupvalue(State *L, int funcindex, int n) {
  const char *name;
  TValue *val = NULL;
  name = aux_upvalue(index2value(L, funcindex), n, &val, NULL);
  if (name) {
    *L->top = *val;
    api_incr_top(L);
  }
  return name;
}

const char *ls_setupvalue(State *L, int funcindex, int n) {
  const char *name;
  TValue *val = NULL;
  TValue *fi = index2value(L, funcindex);
  name = aux_upvalue(fi, n, &val, NULL);
  if (name) {
    L->top--;
    *val = *L->top;
  }
  return name;
}

void *ls_upvalueid(State *L, int fidx, int n) {
  TValue *fi = index2value(L, fidx);
  switch (fi->tt) {
    case T_LCL: {
      LClosure *f = lclvalue(fi);
      if (1 <= n && n <= f->p->sizeup) return f->up[n - 1];
      return NULL;
    }
    case T_CCL: {
      CClosure *f = cclvalue(fi);
      if (1 <= n && n <= f->nup) return &f->up[n - 1];
      return NULL;
    }
    default:
      return NULL;
  }
}

void ls_upvaluejoin(State *L, int fidx1, int n1, int fidx2, int n2) {
  LClosure *f1 = lclvalue(index2value(L, fidx1));
  LClosure *f2 = lclvalue(index2value(L, fidx2));
  f1->up[n1 - 1] = f2->up[n2 - 1];
}

/* ---------------- warnings ---------------- */

void ls_warning(State *L, const char *msg, int tocont) {
  Global *g = G(L);
  /* default warning function behaviour */
  if (g->warnstate == 0) {
    /* off: check control messages */
    if (!tocont && msg[0] == '@') {
      if (strcmp(msg, "@on") == 0) g->warnstate = 1;
    }
    return;
  }
  if (g->warnstate == 1) {
    if (!tocont && msg[0] == '@') {
      if (strcmp(msg, "@off") == 0) g->warnstate = 0;
      return;
    }
    fprintf(stderr, "Lua warning: ");
  }
  fprintf(stderr, "%s", msg);
  if (tocont) g->warnstate = 2;
  else {
    fprintf(stderr, "\n");
    g->warnstate = 1;
  }
  fflush(stderr);
}

/* ---------------- GC control ---------------- */

int ls_gc(State *L, int what, ...) {
  (void)L; (void)what;
  return 0;
}

/* ================= auxiliary library ================= */

static int findfield(State *L, int objidx, int level) {
  if (level == 0 || !ls_istable(L, -1))
    return 0;
  ls_pushnil(L);
  while (ls_next(L, -2)) {
    if (ls_type(L, -2) == TY_STR) {
      if (ls_rawequal(L, objidx, -1)) {
        ls_pop(L, 1);
        return 1;
      } else if (findfield(L, objidx, level - 1)) {
        ls_pushliteral(L, ".");
        ls_replace(L, -3);
        ls_concat(L, 3);
        return 1;
      }
    }
    ls_pop(L, 1);
  }
  return 0;
}

static int pushglobalfuncname(State *L, DebugInfo *ar) {
  int top = ls_gettop(L);
  ls_getinfo(L, "f", ar);
  ls_getfield(L, REGISTRYINDEX, "_LOADED");
  if (findfield(L, top + 1, 2)) {
    const char *name = ls_tostring(L, -1);
    if (strncmp(name, "_G.", 3) == 0) {
      ls_pushstring(L, name + 3);
      ls_remove(L, -2);
    }
    ls_copy(L, -1, top + 1);
    ls_settop(L, top + 1);
    return 1;
  } else {
    ls_settop(L, top);
    return 0;
  }
}

static void pushfuncname(State *L, DebugInfo *ar) {
  if (*ar->namewhat != '\0')
    ls_pushfstring(L, "%s '%s'", ar->namewhat, ar->name);
  else if (pushglobalfuncname(L, ar)) {
    ls_pushfstring(L, "function '%s'", ls_tostring(L, -1));
    ls_remove(L, -2);
  } else if (*ar->what == 'm')
    ls_pushliteral(L, "main chunk");
  else if (*ar->what != 'C')
    ls_pushfstring(L, "function <%s:%d>", ar->short_src, ar->linedefined);
  else
    ls_pushliteral(L, "?");
}

static int lastlevel(State *L) {
  DebugInfo ar;
  int li = 1, le = 1;
  while (ls_getstack(L, le, &ar)) {
    li = le;
    le *= 2;
  }
  while (li < le) {
    int m = (li + le) / 2;
    if (ls_getstack(L, m, &ar)) li = m + 1;
    else le = m;
  }
  return le - 1;
}

#define LEVELS1 10
#define LEVELS2 11

void la_traceback(State *L, State *L1, const char *msg, int level) {
  Buffer b;
  DebugInfo ar;
  int last = lastlevel(L1);
  int limit2show = (last - level > LEVELS1 + LEVELS2) ? LEVELS1 : -1;
  la_buffinit(L, &b);
  if (msg) {
    la_addstring(&b, msg);
    la_addchar(&b, '\n');
  }
  la_addstring(&b, "stack traceback:");
  while (ls_getstack(L1, level++, &ar)) {
    if (limit2show-- == 0) {
      int n = last - level - LEVELS2 + 1;
      ls_pushfstring(L, "\n\t...\t(skipping %d levels)", n);
      la_addvalue(&b);
      level += n;
    } else {
      ls_getinfo(L1, "Slnt", &ar);
      if (ar.currentline <= 0)
        ls_pushfstring(L, "\n\t%s: in ", ar.short_src);
      else
        ls_pushfstring(L, "\n\t%s:%d: in ", ar.short_src, ar.currentline);
      la_addvalue(&b);
      pushfuncname(L, &ar);
      la_addvalue(&b);
      if (ar.istailcall)
        la_addstring(&b, "\n\t(...tail calls...)");
    }
  }
  la_pushresult(&b);
}

int la_argerror(State *L, int arg, const char *extramsg) {
  DebugInfo ar;
  if (!ls_getstack(L, 0, &ar))
    la_error(L, "bad argument #%d (%s)", arg, extramsg);
  ls_getinfo(L, "n", &ar);
  if (strcmp(ar.namewhat, "method") == 0) {
    arg--;
    if (arg == 0)
      la_error(L, "calling '%s' on bad self (%s)", ar.name, extramsg);
  }
  if (ar.name == NULL)
    ar.name = (pushglobalfuncname(L, &ar)) ? ls_tostring(L, -1) : "?";
  la_error(L, "bad argument #%d to '%s' (%s)", arg, ar.name, extramsg);
}

int la_typeerror(State *L, int arg, const char *tname) {
  const char *msg;
  const char *typearg;
  if (la_getmetafield(L, arg, "__name") == TY_STR)
    typearg = ls_tostring(L, -1);
  else if (ls_type(L, arg) == TY_LUD)
    typearg = "light userdata";
  else
    typearg = la_typename(L, arg);
  msg = ls_pushfstring(L, "%s expected, got %s", tname, typearg);
  la_argerror(L, arg, msg);
}

static void tag_error(State *L, int arg, int tag) {
  la_typeerror(L, arg, ls_typename(L, tag));
}

void la_where(State *L, int level) {
  DebugInfo ar;
  if (ls_getstack(L, level, &ar)) {
    ls_getinfo(L, "Sl", &ar);
    if (ar.currentline > 0) {
      ls_pushfstring(L, "%s:%d: ", ar.short_src, ar.currentline);
      return;
    }
  }
  ls_pushfstring(L, "");
}

int la_error(State *L, const char *fmt, ...) {
  va_list argp;
  va_start(argp, fmt);
  la_where(L, 1);
  ls_pushvfstring(L, fmt, argp);
  va_end(argp);
  ls_concat(L, 2);
  ls_error(L);
}

int la_fileresult(State *L, int stat, const char *fname) {
  int en = errno;
  if (stat) {
    ls_pushboolean(L, 1);
    return 1;
  } else {
    const char *msg;
    ls_pushnil(L);
    msg = (en != 0) ? strerror(en) : "(no extra info)";
    if (fname)
      ls_pushfstring(L, "%s: %s", fname, msg);
    else
      ls_pushstring(L, msg);
    ls_pushinteger(L, en);
    return 3;
  }
}

#include <sys/wait.h>

int la_execresult(State *L, int stat) {
  if (stat != 0 && errno != 0)
    return la_fileresult(L, 0, NULL);
  else {
    const char *what = "exit";
    if (WIFEXITED(stat)) {
      stat = WEXITSTATUS(stat);
    } else if (WIFSIGNALED(stat)) {
      stat = WTERMSIG(stat);
      what = "signal";
    }
    if (*what == 'e' && stat == 0)
      ls_pushboolean(L, 1);
    else
      ls_pushnil(L);
    ls_pushstring(L, what);
    ls_pushinteger(L, stat);
    return 3;
  }
}

int la_newmetatable(State *L, const char *tname) {
  if (la_getmetatable(L, tname) != TY_NIL)
    return 0;
  ls_pop(L, 1);
  ls_createtable(L, 0, 2);
  ls_pushstring(L, tname);
  ls_setfield(L, -2, "__name");
  ls_pushvalue(L, -1);
  ls_setfield(L, REGISTRYINDEX, tname);
  return 1;
}

void la_setmetatable(State *L, const char *tname) {
  la_getmetatable(L, tname);
  ls_setmetatable(L, -2);
}

void *la_testudata(State *L, int ud, const char *tname) {
  void *p = ls_touserdata(L, ud);
  if (p != NULL && ls_type(L, ud) == TY_UD) {
    if (ls_getmetatable(L, ud)) {
      la_getmetatable(L, tname);
      if (!ls_rawequal(L, -1, -2))
        p = NULL;
      ls_pop(L, 2);
      return p;
    }
  }
  return NULL;
}

void *la_checkudata(State *L, int ud, const char *tname) {
  void *p = la_testudata(L, ud, tname);
  if (p == NULL) la_typeerror(L, ud, tname);
  return p;
}

int la_checkoption(State *L, int arg, const char *def, const char *const lst[]) {
  const char *name = (def) ? la_optstring(L, arg, def) : la_checkstring(L, arg);
  int i;
  for (i = 0; lst[i]; i++)
    if (strcmp(lst[i], name) == 0)
      return i;
  la_argerror(L, arg, ls_pushfstring(L, "invalid option '%s'", name));
}

void la_checkstack(State *L, int space, const char *msg) {
  if (!ls_checkstack(L, space)) {
    if (msg)
      la_error(L, "stack overflow (%s)", msg);
    else
      la_error(L, "stack overflow");
  }
}

void la_checktype(State *L, int arg, int t) {
  if (ls_type(L, arg) != t)
    tag_error(L, arg, t);
}

void la_checkany(State *L, int arg) {
  if (ls_type(L, arg) == TY_NONE)
    la_argerror(L, arg, "value expected");
}

const char *la_checklstring(State *L, int arg, size_t *len) {
  const char *s = ls_tolstring(L, arg, len);
  if (!s) tag_error(L, arg, TY_STR);
  return s;
}

const char *la_optlstring(State *L, int arg, const char *def, size_t *len) {
  if (ls_isnoneornil(L, arg)) {
    if (len)
      *len = (def ? strlen(def) : 0);
    return def;
  } else
    return la_checklstring(L, arg, len);
}

lnum la_checknumber(State *L, int arg) {
  int isnum;
  lnum d = ls_tonumberx(L, arg, &isnum);
  if (!isnum)
    tag_error(L, arg, TY_NUM);
  return d;
}

lnum la_optnumber(State *L, int arg, lnum def) {
  return la_opt(L, la_checknumber, arg, def);
}

static void interror(State *L, int arg) {
  if (ls_isnumber(L, arg))
    la_argerror(L, arg, "number has no integer representation");
  else
    tag_error(L, arg, TY_NUM);
}

lint la_checkinteger(State *L, int arg) {
  int isnum;
  lint d = ls_tointegerx(L, arg, &isnum);
  if (!isnum) interror(L, arg);
  return d;
}

lint la_optinteger(State *L, int arg, lint def) {
  return la_opt(L, la_checkinteger, arg, def);
}

/* ---------------- buffers ---------------- */

void la_buffinit(State *L, Buffer *B) {
  B->L = L;
  B->b = B->init;
  B->n = 0;
  B->size = BUFSZ;
  B->boxidx = 0;
  ls_pushlightuserdata(L, (void *)B);  /* placeholder */
}

static int boxgc(State *L) {
  void **box = (void **)ls_touserdata(L, 1);
  if (box && *box) {
    free(*box);
    *box = NULL;
  }
  return 0;
}

char *la_prepbuffsize(Buffer *B, size_t sz) {
  if (B->size - B->n >= sz)
    return B->b + B->n;
  else {
    State *L = B->L;
    size_t newsize = (B->size / 2) * 3;
    if (newsize < B->n + sz) newsize = B->n + sz;
    if (newsize < 64) newsize = 64;
    if (B->b == B->init) {
      /* create box */
      void **box;
      char *nb = malloc(newsize);
      if (nb == NULL) la_error(L, "not enough memory");
      memcpy(nb, B->b, B->n);
      /* replace placeholder with a box userdata */
      box = (void **)ls_newuserdatauv(L, sizeof(void *), 0);
      *box = nb;
      if (la_newmetatable(L, "_BUFBOX")) {
        ls_pushcfunction(L, boxgc);
        ls_setfield(L, -2, "__gc");
      }
      ls_setmetatable(L, -2);
      /* find placeholder: it is the light userdata pointing to B */
      {
        int top = ls_gettop(L);
        int i;
        for (i = top - 1; i >= 1; i--) {
          if (ls_type(L, i) == TY_LUD && ls_touserdata(L, i) == (void *)B) {
            ls_replace(L, i);
            B->boxidx = i;
            break;
          }
        }
        if (B->boxidx == 0) {
          ls_pop(L, 1);
          la_error(L, "buffer error");
        }
      }
      B->b = nb;
    } else {
      void **box = (void **)ls_touserdata(L, B->boxidx);
      char *nb = realloc(B->b, newsize);
      if (nb == NULL) la_error(L, "not enough memory");
      *box = nb;
      B->b = nb;
    }
    B->size = newsize;
    return B->b + B->n;
  }
}

void la_addlstring(Buffer *B, const char *s, size_t l) {
  if (l > 0) {
    char *b = la_prepbuffsize(B, l);
    memcpy(b, s, l);
    la_addsize(B, l);
  }
}

void la_addstring(Buffer *B, const char *s) {
  la_addlstring(B, s, strlen(s));
}

void la_pushresult(Buffer *B) {
  State *L = B->L;
  ls_pushlstring(L, B->b, B->n);
  if (B->b != B->init) {
    void **box = (void **)ls_touserdata(L, B->boxidx);
    free(B->b);
    if (box) *box = NULL;
    B->b = B->init;
  }
  ls_remove(L, -2);
}

void la_pushresultsize(Buffer *B, size_t sz) {
  la_addsize(B, sz);
  la_pushresult(B);
}

void la_addvalue(Buffer *B) {
  State *L = B->L;
  size_t len;
  const char *s = ls_tolstring(L, -1, &len);
  char *b = la_prepbuffsize(B, len);
  memcpy(b, s, len);
  la_addsize(B, len);
  ls_pop(L, 1);
}

char *la_buffinitsize(State *L, Buffer *B, size_t sz) {
  la_buffinit(L, B);
  return la_prepbuffsize(B, sz);
}

/* ---------------- misc aux ---------------- */

int la_getmetafield(State *L, int obj, const char *event) {
  if (!ls_getmetatable(L, obj))
    return TY_NIL;
  else {
    int tt;
    ls_pushstring(L, event);
    tt = ls_rawget(L, -2);
    if (tt == TY_NIL)
      ls_pop(L, 2);
    else
      ls_remove(L, -2);
    return tt;
  }
}

int la_callmeta(State *L, int obj, const char *event) {
  obj = ls_absindex(L, obj);
  if (la_getmetafield(L, obj, event) == TY_NIL)
    return 0;
  ls_pushvalue(L, obj);
  ls_call(L, 1, 1);
  return 1;
}

lint la_len(State *L, int idx) {
  lint l;
  int isnum;
  ls_len(L, idx);
  l = ls_tointegerx(L, -1, &isnum);
  if (!isnum)
    la_error(L, "object length is not an integer");
  ls_pop(L, 1);
  return l;
}

const char *la_tolstring(State *L, int idx, size_t *len) {
  idx = ls_absindex(L, idx);
  if (la_callmeta(L, idx, "__tostring")) {
    if (!ls_isstring(L, -1))
      la_error(L, "'__tostring' must return a string");
  } else {
    switch (ls_type(L, idx)) {
      case TY_NUM: {
        char buff[64];
        int l = num_tostrbuf(index2value(L, idx), buff);
        ls_pushlstring(L, buff, (size_t)l);
        break;
      }
      case TY_STR:
        ls_pushvalue(L, idx);
        break;
      case TY_BOOL:
        ls_pushstring(L, (ls_toboolean(L, idx) ? "true" : "false"));
        break;
      case TY_NIL:
        ls_pushliteral(L, "nil");
        break;
      default: {
        int tt = la_getmetafield(L, idx, "__name");
        const char *kind = (tt == TY_STR) ? ls_tostring(L, -1) : la_typename(L, idx);
        ls_pushfstring(L, "%s: %p", kind, ls_topointer(L, idx));
        if (tt != TY_NIL)
          ls_remove(L, -2);
        break;
      }
    }
  }
  return ls_tolstring(L, -1, len);
}

void la_setfuncs(State *L, const Reg *l, int nup) {
  la_checkstack(L, nup, "too many upvalues");
  for (; l->name != NULL; l++) {
    if (l->func == NULL)
      ls_pushboolean(L, 0);
    else {
      int i;
      for (i = 0; i < nup; i++)
        ls_pushvalue(L, -nup);
      ls_pushcclosure(L, l->func, nup);
    }
    ls_setfield(L, -(nup + 2), l->name);
  }
  ls_pop(L, nup);
}

void la_newlib(State *L, const Reg *l) {
  int n = 0;
  const Reg *p;
  for (p = l; p->name; p++) n++;
  ls_createtable(L, 0, n);
  la_setfuncs(L, l, 0);
}

int la_getsubtable(State *L, int idx, const char *fname) {
  if (ls_getfield(L, idx, fname) == TY_TAB)
    return 1;
  else {
    ls_pop(L, 1);
    idx = ls_absindex(L, idx);
    ls_newtable(L);
    ls_pushvalue(L, -1);
    ls_setfield(L, idx, fname);
    return 0;
  }
}

void la_requiref(State *L, const char *modname, CFunc openf, int glb) {
  la_getsubtable(L, REGISTRYINDEX, "_LOADED");
  ls_getfield(L, -1, modname);
  if (!ls_toboolean(L, -1)) {
    ls_pop(L, 1);
    ls_pushcfunction(L, openf);
    ls_pushstring(L, modname);
    ls_call(L, 1, 1);
    ls_pushvalue(L, -1);
    ls_setfield(L, -3, modname);
  }
  ls_remove(L, -2);
  if (glb) {
    ls_pushvalue(L, -1);
    ls_setglobal(L, modname);
  }
}

const char *la_gsub(State *L, const char *s, const char *p, const char *r) {
  const char *wild;
  size_t l = strlen(p);
  Buffer b;
  la_buffinit(L, &b);
  while ((wild = strstr(s, p)) != NULL) {
    la_addlstring(&b, s, (size_t)(wild - s));
    la_addstring(&b, r);
    s = wild + l;
  }
  la_addstring(&b, s);
  la_pushresult(&b);
  return ls_tostring(L, -1);
}

/* ---------------- loading ---------------- */

int la_loadbufferx(State *L, const char *buff, size_t size, const char *name, const char *mode) {
  return ls_load(L, buff, size, name, mode);
}

int la_loadstring(State *L, const char *s) {
  return la_loadbufferx(L, s, strlen(s), s, NULL);
}

static int errfile(State *L, const char *what, int fnameindex) {
  int err = errno;
  const char *filename = ls_tostring(L, fnameindex) + 1;
  if (err != 0)
    ls_pushfstring(L, "cannot %s %s: %s", what, filename, strerror(err));
  else
    ls_pushfstring(L, "cannot %s %s", what, filename);
  ls_remove(L, fnameindex);
  return TS_ERRSYNTAX + 3;  /* file error */
}

int la_loadfilex(State *L, const char *filename, const char *mode) {
  int status;
  int fnameindex = ls_gettop(L) + 1;
  FILE *f;
  char *data = NULL;
  size_t n = 0, cap = 0;
  size_t start = 0;
  if (filename == NULL) {
    ls_pushliteral(L, "=stdin");
    f = stdin;
  } else {
    ls_pushfstring(L, "@%s", filename);
    errno = 0;
    f = fopen(filename, "r");
    if (f == NULL) return errfile(L, "open", fnameindex);
  }
  {
    char tmp[8192];
    size_t r;
    while ((r = fread(tmp, 1, sizeof(tmp), f)) > 0) {
      if (n + r > cap) {
        cap = (cap + r) * 2;
        data = realloc(data, cap);
      }
      memcpy(data + n, tmp, r);
      n += r;
    }
  }
  if (ferror(f)) {
    free(data);
    if (filename) fclose(f);
    ls_settop(L, fnameindex);
    return errfile(L, "read", fnameindex);
  }
  if (filename) fclose(f);
  /* skip shebang line */
  if (n > 0 && data[0] == '#') {
    while (start < n && data[start] != '\n') start++;
    /* keep the newline so line numbers stay right */
  } else if (n >= 3 && (unsigned char)data[0] == 0xEF && (unsigned char)data[1] == 0xBB && (unsigned char)data[2] == 0xBF) {
    start = 3;
    if (n > 3 && data[3] == '#') {
      while (start < n && data[start] != '\n') start++;
    }
  }
  status = ls_load(L, data ? data + start : "", n - start, ls_tostring(L, fnameindex), mode);
  free(data);
  ls_remove(L, fnameindex);
  return status;
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat > api.c <<'EOF'
/* stack API and auxiliary library */
#include "core.h"
#include "opcodes.h"
#include <errno.h>

static const TValue nonevalue_ = {{0}, T_NIL};
#define nonevalue ((TValue *)&nonevalue_)
static TValue nilvalue_ = {{0}, T_NIL};

TValue *ls_index2value(State *L, int idx) {
  CallInfo *ci = L->ci;
  if (idx > 0) {
    TValue *o = ci->func + idx;
    if (o >= L->top) return nonevalue;
    return o;
  } else if (idx > REGISTRYINDEX) {
    return L->top + idx;
  } else if (idx == REGISTRYINDEX)
    return &G(L)->registry;
  else {
    idx = REGISTRYINDEX - idx;
    if (ci->func->tt == T_CCL) {
      CClosure *f = cclvalue(ci->func);
      return (idx <= f->nup) ? &f->up[idx - 1] : nonevalue;
    }
    setnil(&nilvalue_);
    return nonevalue;
  }
}

#define index2value ls_index2value
#define api_incr_top(L) ((L)->top++)

int ls_absindex(State *L, int idx) {
  return (idx > 0 || idx <= REGISTRYINDEX) ? idx : (int)(L->top - L->ci->func) + idx;
}

int ls_gettop(State *L) {
  return (int)(L->top - (L->ci->func + 1));
}

void ls_settop(State *L, int idx) {
  CallInfo *ci = L->ci;
  TValue *func = ci->func;
  TValue *newtop;
  if (idx >= 0) {
    newtop = func + 1 + idx;
    while (L->top < newtop) {
      setnil(L->top);
      L->top++;
    }
  } else {
    newtop = L->top + idx + 1;
  }
  if (L->ntbc > 0 && L->tbclist[L->ntbc - 1] >= newtop) {
    func_close(L, newtop, -1);
  }
  L->top = newtop;
}

static void reverse(TValue *from, TValue *to) {
  for (; from < to; from++, to--) {
    TValue temp = *from;
    *from = *to;
    *to = temp;
  }
}

void ls_rotate(State *L, int idx, int n) {
  TValue *p, *t, *m;
  t = L->top - 1;
  p = index2value(L, idx);
  m = (n >= 0 ? t - n : p - n - 1);
  reverse(p, m);
  reverse(m + 1, t);
  reverse(p, t);
}

void ls_copy(State *L, int fromidx, int toidx) {
  TValue *fr = index2value(L, fromidx);
  TValue *to = index2value(L, toidx);
  *to = *fr;
}

void ls_pushvalue(State *L, int idx) {
  *L->top = *index2value(L, idx);
  api_incr_top(L);
}

int ls_checkstack(State *L, int n) {
  if (L->stack_last - L->top > n) {
    if (L->top + n > L->hwm) L->hwm = L->top + n;
    if (L->ci->top < L->top + n) L->ci->top = L->top + n;
    return 1;
  }
  if (L->top + n > L->stack + MAXSTACK) return 0;
  d_checkstack(L, n);
  if (L->ci->top < L->top + n) L->ci->top = L->top + n;
  return 1;
}

void ls_xmove(State *from, State *to, int n) {
  int i;
  if (from == to) return;
  checkstack(to, n);
  from->top -= n;
  for (i = 0; i < n; i++) {
    *to->top = from->top[i];
    to->top++;
  }
}

/* ---------------- access ---------------- */

int ls_type(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  return (o == nonevalue) ? TY_NONE : basetype(o->tt);
}

const char *ls_typename(State *L, int t) {
  (void)L;
  return ttypename(t);
}

int ls_iscfunction(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  return o->tt == T_LCF || o->tt == T_CCL;
}

int ls_isinteger(State *L, int idx) {
  return isint(index2value(L, idx));
}

int ls_isnumber(State *L, int idx) {
  lnum n;
  return obj_tonumber(index2value(L, idx), &n);
}

int ls_isstring(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  return isstr(o) || isnum(o);
}

int ls_isuserdata(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  return o->tt == T_UD || o->tt == T_LUD;
}

int ls_rawequal(State *L, int index1, int index2) {
  const TValue *o1 = index2value(L, index1);
  const TValue *o2 = index2value(L, index2);
  return (o1 != nonevalue && o2 != nonevalue) ? vm_rawequal(o1, o2) : 0;
}

void ls_arith(State *L, int op) {
  if (op == OPARITH_UNM || op == OPARITH_BNOT) {
    *L->top = *(L->top - 1);
    api_incr_top(L);
  }
  vm_arith(L, op, L->top - 2, L->top - 1, L->top - 2);
  L->top--;
}

int ls_compare(State *L, int index1, int index2, int op) {
  const TValue *o1 = index2value(L, index1);
  const TValue *o2 = index2value(L, index2);
  int i = 0;
  if (o1 != nonevalue && o2 != nonevalue) {
    TValue a = *o1, b = *o2;
    switch (op) {
      case OPCMP_EQ: i = vm_equalobj(L, &a, &b); break;
      case OPCMP_LT: i = vm_lessthan(L, &a, &b); break;
      case OPCMP_LE: i = vm_lessequal(L, &a, &b); break;
    }
  }
  return i;
}

size_t ls_stringtonumber(State *L, const char *s) {
  size_t sz = str2number(s, L->top);
  if (sz != 0) api_incr_top(L);
  return sz;
}

lnum ls_tonumberx(State *L, int idx, int *pisnum) {
  lnum n = 0;
  const TValue *o = index2value(L, idx);
  int isnum = obj_tonumber(o, &n);
  if (pisnum) *pisnum = isnum;
  return n;
}

lint ls_tointegerx(State *L, int idx, int *pisnum) {
  lint res = 0;
  const TValue *o = index2value(L, idx);
  int isnum = obj_tointeger(o, &res, 0);
  if (pisnum) *pisnum = isnum;
  return res;
}

int ls_toboolean(State *L, int idx) {
  return !isfalsy(index2value(L, idx));
}

const char *ls_tolstring(State *L, int idx, size_t *len) {
  TValue *o = index2value(L, idx);
  if (!isstr(o)) {
    if (!isnum(o)) {
      if (len != NULL) *len = 0;
      return NULL;
    }
    obj_tostring(L, o);
    gc_checkGC(L);
    o = index2value(L, idx);
  }
  if (len != NULL) *len = strvalue(o)->len;
  return getstr(strvalue(o));
}

luint ls_rawlen(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  switch (o->tt) {
    case T_STR: return strvalue(o)->len;
    case T_UD: return udvalue(o)->len;
    case T_TAB: return tab_getn(tabvalue(o));
    default: return 0;
  }
}

CFunc ls_tocfunction(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  if (o->tt == T_LCF) return o->v.f;
  else if (o->tt == T_CCL) return cclvalue(o)->f;
  else return NULL;
}

void *ls_touserdata(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  switch (o->tt) {
    case T_UD: return udmem(udvalue(o));
    case T_LUD: return o->v.p;
    default: return NULL;
  }
}

State *ls_tothread(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  return (o->tt != T_THR) ? NULL : thrvalue(o);
}

const void *ls_topointer(State *L, int idx) {
  const TValue *o = index2value(L, idx);
  switch (o->tt) {
    case T_LCF: return (void *)(uintptr_t)o->v.f;
    case T_UD: return udmem(udvalue(o));
    case T_LUD: return o->v.p;
    default:
      if (iscollectable(o)) return gcvalue(o);
      return NULL;
  }
}

/* ---------------- push ---------------- */

void ls_pushnil(State *L) {
  setnil(L->top);
  api_incr_top(L);
}

void ls_pushnumber(State *L, lnum n) {
  setflt(L->top, n);
  api_incr_top(L);
}

void ls_pushinteger(State *L, lint n) {
  setint(L->top, n);
  api_incr_top(L);
}

const char *ls_pushlstring(State *L, const char *s, size_t len) {
  Str *ts = (len == 0) ? str_new(L, "", 0) : str_new(L, s, len);
  setstr(L->top, ts);
  api_incr_top(L);
  gc_checkGC(L);
  return getstr(ts);
}

const char *ls_pushstring(State *L, const char *s) {
  if (s == NULL) {
    setnil(L->top);
    api_incr_top(L);
    return NULL;
  } else {
    Str *ts = str_newc(L, s);
    setstr(L->top, ts);
    api_incr_top(L);
    gc_checkGC(L);
    return getstr(ts);
  }
}

void ls_pushstrobj(State *L, Str *s) {
  setstr(L->top, s);
  api_incr_top(L);
}

const char *ls_pushvfstring(State *L, const char *fmt, va_list argp) {
  const char *ret = pushvfstring(L, fmt, argp);
  gc_checkGC(L);
  return ret;
}

const char *ls_pushfstring(State *L, const char *fmt, ...) {
  const char *ret;
  va_list argp;
  va_start(argp, fmt);
  ret = pushvfstring(L, fmt, argp);
  va_end(argp);
  gc_checkGC(L);
  return ret;
}

void ls_pushcclosure(State *L, CFunc fn, int n) {
  if (n == 0) {
    setlcf(L->top, fn);
    api_incr_top(L);
  } else {
    CClosure *cl = ccl_new(L, n);
    cl->f = fn;
    L->top -= n;
    while (n--) cl->up[n] = L->top[n];
    setccl(L->top, cl);
    api_incr_top(L);
    gc_checkGC(L);
  }
}

void ls_pushboolean(State *L, int b) {
  setbool(L->top, b);
  api_incr_top(L);
}

void ls_pushlightuserdata(State *L, void *p) {
  setlud(L->top, p);
  api_incr_top(L);
}

int ls_pushthread(State *L) {
  setthr(L->top, L);
  api_incr_top(L);
  return (G(L)->mainthread == L);
}

/* ---------------- get ---------------- */

static int auxgetstr(State *L, const TValue *t, const char *k) {
  TValue key;
  Str *str = str_newc(L, k);
  setstr(&key, str);
  *L->top = key;
  api_incr_top(L);
  vm_gettable(L, t, L->top - 1, L->top - 1);
  return basetype((L->top - 1)->tt);
}

int ls_getglobal(State *L, const char *name) {
  const TValue *gt = tab_getint(tabvalue(&G(L)->registry), RIDX_GLOBALS);
  TValue g = *gt;
  return auxgetstr(L, &g, name);
}

int ls_gettable(State *L, int idx) {
  TValue t = *index2value(L, idx);
  vm_gettable(L, &t, L->top - 1, L->top - 1);
  return basetype((L->top - 1)->tt);
}

int ls_getfield(State *L, int idx, const char *k) {
  TValue t = *index2value(L, idx);
  return auxgetstr(L, &t, k);
}

int ls_geti(State *L, int idx, lint n) {
  TValue t = *index2value(L, idx);
  TValue key;
  setint(&key, n);
  if (istab(&t)) {
    const TValue *slot = tab_getint(tabvalue(&t), n);
    if (!isnil(slot)) {
      *L->top = *slot;
      api_incr_top(L);
      return basetype((L->top - 1)->tt);
    }
  }
  *L->top = key;
  api_incr_top(L);
  vm_gettable(L, &t, L->top - 1, L->top - 1);
  return basetype((L->top - 1)->tt);
}

int ls_rawget(State *L, int idx) {
  Table *t = tabvalue(index2value(L, idx));
  const TValue *val = tab_get(t, L->top - 1);
  *(L->top - 1) = *val;
  return basetype(val->tt);
}

int ls_rawgeti(State *L, int idx, lint n) {
  Table *t = tabvalue(index2value(L, idx));
  const TValue *val = tab_getint(t, n);
  *L->top = *val;
  api_incr_top(L);
  return basetype(val->tt);
}

int ls_rawgetp(State *L, int idx, const void *p) {
  Table *t = tabvalue(index2value(L, idx));
  TValue k;
  const TValue *val;
  setlud(&k, (void *)p);
  val = tab_get(t, &k);
  *L->top = *val;
  api_incr_top(L);
  return basetype(val->tt);
}

void ls_createtable(State *L, int narray, int nrec) {
  Table *t = tab_new(L);
  settab(L->top, t);
  api_incr_top(L);
  if (narray > 0 || nrec > 0)
    tab_resize(L, t, (unsigned int)narray, (unsigned int)nrec);
  gc_checkGC(L);
}

int ls_getmetatable(State *L, int objindex) {
  const TValue *obj = index2value(L, objindex);
  Table *mt = getmetatable_obj(L, obj);
  if (mt != NULL) {
    settab(L->top, mt);
    api_incr_top(L);
    return 1;
  }
  return 0;
}

int ls_getiuservalue(State *L, int idx, int n) {
  TValue *o = index2value(L, idx);
  int t;
  if (n <= 0 || n > udvalue(o)->nuv) {
    setnil(L->top);
    t = TY_NONE;
  } else {
    *L->top = udvalue(o)->uv[n - 1];
    t = basetype(L->top->tt);
  }
  api_incr_top(L);
  return t;
}

void *ls_newuserdatauv(State *L, size_t size, int nuvalue) {
  Udata *u = ud_new(L, size, nuvalue);
  setud(L->top, u);
  api_incr_top(L);
  gc_checkGC(L);
  return udmem(u);
}

/* ---------------- set ---------------- */

static void auxsetstr(State *L, const TValue *t, const char *k) {
  Str *str = str_newc(L, k);
  TValue key;
  setstr(&key, str);
  *L->top = key;
  api_incr_top(L);
  vm_settable(L, t, L->top - 1, L->top - 2);
  L->top -= 2;
}

void ls_setglobal(State *L, const char *name) {
  TValue g = *tab_getint(tabvalue(&G(L)->registry), RIDX_GLOBALS);
  auxsetstr(L, &g, name);
}

void ls_settable(State *L, int idx) {
  TValue t = *index2value(L, idx);
  vm_settable(L, &t, L->top - 2, L->top - 1);
  L->top -= 2;
}

void ls_setfield(State *L, int idx, const char *k) {
  TValue t = *index2value(L, idx);
  auxsetstr(L, &t, k);
}

void ls_seti(State *L, int idx, lint n) {
  TValue t = *index2value(L, idx);
  TValue key;
  setint(&key, n);
  vm_settable(L, &t, &key, L->top - 1);
  L->top--;
}

void ls_rawset(State *L, int idx) {
  Table *t = tabvalue(index2value(L, idx));
  TValue *slot = tab_set(L, t, L->top - 2);
  *slot = *(L->top - 1);
  L->top -= 2;
}

void ls_rawseti(State *L, int idx, lint n) {
  Table *t = tabvalue(index2value(L, idx));
  TValue *slot = tab_setint(L, t, n);
  *slot = *(L->top - 1);
  L->top--;
}

void ls_rawsetp(State *L, int idx, const void *p) {
  Table *t = tabvalue(index2value(L, idx));
  TValue k;
  TValue *slot;
  setlud(&k, (void *)p);
  slot = tab_set(L, t, &k);
  *slot = *(L->top - 1);
  L->top--;
}

int ls_setmetatable(State *L, int objindex) {
  TValue *obj = index2value(L, objindex);
  Table *mt;
  if (isnil(L->top - 1)) mt = NULL;
  else mt = tabvalue(L->top - 1);
  switch (obj->tt) {
    case T_TAB:
      tabvalue(obj)->meta = mt;
      if (mt) gc_checkfinalizer(L, gcvalue(obj), mt);
      break;
    case T_UD:
      udvalue(obj)->meta = mt;
      if (mt) gc_checkfinalizer(L, gcvalue(obj), mt);
      break;
    default:
      G(L)->mt[basetype(obj->tt)] = mt;
      break;
  }
  L->top--;
  return 1;
}

int ls_setiuservalue(State *L, int idx, int n) {
  TValue *o = index2value(L, idx);
  int res;
  if (!((unsigned int)(n) - 1u < (unsigned int)udvalue(o)->nuv))
    res = 0;
  else {
    udvalue(o)->uv[n - 1] = *(L->top - 1);
    res = 1;
  }
  L->top--;
  return res;
}

/* ---------------- calls ---------------- */

void ls_call(State *L, int nargs, int nresults) {
  TValue *func = L->top - (nargs + 1);
  d_call(L, func, nresults);
  if (nresults < 0 && L->ci->top < L->top) L->ci->top = L->top;
}

typedef struct CallS {
  TValue *func;
  int nresults;
} CallS;

static void f_call(State *L, void *ud) {
  CallS *c = (CallS *)ud;
  d_call(L, c->func, c->nresults);
}

int ls_pcall(State *L, int nargs, int nresults, int errfunc) {
  CallS c;
  int status;
  TValue *func = NULL;
  if (errfunc != 0) func = index2value(L, errfunc);
  c.func = L->top - (nargs + 1);
  c.nresults = nresults;
  status = d_pcall(L, f_call, &c, c.func, func);
  if (nresults < 0 && L->ci->top < L->top) L->ci->top = L->top;
  return status;
}

int ls_load(State *L, const char *buff, size_t size, const char *chunkname, const char *mode) {
  int status;
  if (!chunkname) chunkname = "?";
  status = d_protectedparser(L, buff, size, chunkname, mode);
  if (status == TS_OK) {
    LClosure *f = lclvalue(L->top - 1);
    if (f->nup >= 1) {
      const TValue *gt = tab_getint(tabvalue(&G(L)->registry), RIDX_GLOBALS);
      f->up[0]->value = *gt;
      f->up[0]->v = &f->up[0]->value;
    }
  }
  gc_checkGC(L);
  return status;
}

int ls_error(State *L) {
  TValue *errobj = L->top - 1;
  if (isstr(errobj) && strvalue(errobj) == G(L)->memerrmsg)
    d_throw(L, TS_ERRMEM);
  else
    dbg_errormsg(L);
}

int ls_next(State *L, int idx) {
  Table *t = tabvalue(index2value(L, idx));
  int more = tab_next(L, t, L->top - 1);
  if (more) api_incr_top(L);
  else L->top -= 1;
  return more;
}

void ls_toclose(State *L, int idx) {
  TValue *o = index2value(L, idx);
  tbc_new(L, o);
}

void ls_closeslot(State *L, int idx) {
  TValue *level = index2value(L, idx);
  func_close(L, level, -1);
  setnil(level);
}

void ls_concat(State *L, int n) {
  if (n > 0) vm_concat(L, n);
  else {
    setstr(L->top, str_new(L, "", 0));
    api_incr_top(L);
  }
  gc_checkGC(L);
}

void ls_len(State *L, int idx) {
  TValue t = *index2value(L, idx);
  vm_objlen(L, L->top, &t);
  api_incr_top(L);
}

/* ---------------- upvalues ---------------- */

static const char *aux_upvalue(TValue *fi, int n, TValue **val, GCObj **owner) {
  switch (fi->tt) {
    case T_CCL: {
      CClosure *f = cclvalue(fi);
      if (!((unsigned int)n - 1u < (unsigned int)f->nup)) return NULL;
      *val = &f->up[n - 1];
      if (owner) *owner = (GCObj *)f;
      return "";
    }
    case T_LCL: {
      LClosure *f = lclvalue(fi);
      Str *name;
      Proto *p = f->p;
      if (!((unsigned int)n - 1u < (unsigned int)p->sizeup)) return NULL;
      *val = f->up[n - 1]->v;
      if (owner) *owner = (GCObj *)f->up[n - 1];
      name = p->upvals[n - 1].name;
      return (name == NULL) ? "(no name)" : getstr(name);
    }
    default:
      return NULL;
  }
}

const char *ls_getupvalue(State *L, int funcindex, int n) {
  const char *name;
  TValue *val = NULL;
  name = aux_upvalue(index2value(L, funcindex), n, &val, NULL);
  if (name) {
    *L->top = *val;
    api_incr_top(L);
  }
  return name;
}

const char *ls_setupvalue(State *L, int funcindex, int n) {
  const char *name;
  TValue *val = NULL;
  TValue *fi = index2value(L, funcindex);
  name = aux_upvalue(fi, n, &val, NULL);
  if (name) {
    L->top--;
    *val = *L->top;
  }
  return name;
}

void *ls_upvalueid(State *L, int fidx, int n) {
  TValue *fi = index2value(L, fidx);
  switch (fi->tt) {
    case T_LCL: {
      LClosure *f = lclvalue(fi);
      if (1 <= n && n <= f->p->sizeup) return f->up[n - 1];
      return NULL;
    }
    case T_CCL: {
      CClosure *f = cclvalue(fi);
      if (1 <= n && n <= f->nup) return &f->up[n - 1];
      return NULL;
    }
    default:
      return NULL;
  }
}

void ls_upvaluejoin(State *L, int fidx1, int n1, int fidx2, int n2) {
  LClosure *f1 = lclvalue(index2value(L, fidx1));
  LClosure *f2 = lclvalue(index2value(L, fidx2));
  f1->up[n1 - 1] = f2->up[n2 - 1];
}

/* ---------------- warnings ---------------- */

void ls_warning(State *L, const char *msg, int tocont) {
  Global *g = G(L);
  /* default warning function behaviour */
  if (g->warnstate == 0) {
    /* off: check control messages */
    if (!tocont && msg[0] == '@') {
      if (strcmp(msg, "@on") == 0) g->warnstate = 1;
    }
    return;
  }
  if (g->warnstate == 1) {
    if (!tocont && msg[0] == '@') {
      if (strcmp(msg, "@off") == 0) g->warnstate = 0;
      return;
    }
    fprintf(stderr, "Lua warning: ");
  }
  fprintf(stderr, "%s", msg);
  if (tocont) g->warnstate = 2;
  else {
    fprintf(stderr, "\n");
    g->warnstate = 1;
  }
  fflush(stderr);
}

/* ---------------- GC control ---------------- */

int ls_gc(State *L, int what, ...) {
  (void)L; (void)what;
  return 0;
}

/* ================= auxiliary library ================= */

static int findfield(State *L, int objidx, int level) {
  if (level == 0 || !ls_istable(L, -1))
    return 0;
  ls_pushnil(L);
  while (ls_next(L, -2)) {
    if (ls_type(L, -2) == TY_STR) {
      if (ls_rawequal(L, objidx, -1)) {
        ls_pop(L, 1);
        return 1;
      } else if (findfield(L, objidx, level - 1)) {
        ls_pushliteral(L, ".");
        ls_replace(L, -3);
        ls_concat(L, 3);
        return 1;
      }
    }
    ls_pop(L, 1);
  }
  return 0;
}

static int pushglobalfuncname(State *L, DebugInfo *ar) {
  int top = ls_gettop(L);
  ls_getinfo(L, "f", ar);
  ls_getfield(L, REGISTRYINDEX, "_LOADED");
  if (findfield(L, top + 1, 2)) {
    const char *name = ls_tostring(L, -1);
    if (strncmp(name, "_G.", 3) == 0) {
      ls_pushstring(L, name + 3);
      ls_remove(L, -2);
    }
    ls_copy(L, -1, top + 1);
    ls_settop(L, top + 1);
    return 1;
  } else {
    ls_settop(L, top);
    return 0;
  }
}

static void pushfuncname(State *L, DebugInfo *ar) {
  if (*ar->namewhat != '\0')
    ls_pushfstring(L, "%s '%s'", ar->namewhat, ar->name);
  else if (pushglobalfuncname(L, ar)) {
    ls_pushfstring(L, "function '%s'", ls_tostring(L, -1));
    ls_remove(L, -2);
  } else if (*ar->what == 'm')
    ls_pushliteral(L, "main chunk");
  else if (*ar->what != 'C')
    ls_pushfstring(L, "function <%s:%d>", ar->short_src, ar->linedefined);
  else
    ls_pushliteral(L, "?");
}

static int lastlevel(State *L) {
  DebugInfo ar;
  int li = 1, le = 1;
  while (ls_getstack(L, le, &ar)) {
    li = le;
    le *= 2;
  }
  while (li < le) {
    int m = (li + le) / 2;
    if (ls_getstack(L, m, &ar)) li = m + 1;
    else le = m;
  }
  return le - 1;
}

#define LEVELS1 10
#define LEVELS2 11

void la_traceback(State *L, State *L1, const char *msg, int level) {
  Buffer b;
  DebugInfo ar;
  int last = lastlevel(L1);
  int limit2show = (last - level > LEVELS1 + LEVELS2) ? LEVELS1 : -1;
  la_buffinit(L, &b);
  if (msg) {
    la_addstring(&b, msg);
    la_addchar(&b, '\n');
  }
  la_addstring(&b, "stack traceback:");
  while (ls_getstack(L1, level++, &ar)) {
    if (limit2show-- == 0) {
      int n = last - level - LEVELS2 + 1;
      ls_pushfstring(L, "\n\t...\t(skipping %d levels)", n);
      la_addvalue(&b);
      level += n;
    } else {
      ls_getinfo(L1, "Slnt", &ar);
      if (ar.currentline <= 0)
        ls_pushfstring(L, "\n\t%s: in ", ar.short_src);
      else
        ls_pushfstring(L, "\n\t%s:%d: in ", ar.short_src, ar.currentline);
      la_addvalue(&b);
      pushfuncname(L, &ar);
      la_addvalue(&b);
      if (ar.istailcall)
        la_addstring(&b, "\n\t(...tail calls...)");
    }
  }
  la_pushresult(&b);
}

int la_argerror(State *L, int arg, const char *extramsg) {
  DebugInfo ar;
  if (!ls_getstack(L, 0, &ar))
    la_error(L, "bad argument #%d (%s)", arg, extramsg);
  ls_getinfo(L, "n", &ar);
  if (strcmp(ar.namewhat, "method") == 0) {
    arg--;
    if (arg == 0)
      la_error(L, "calling '%s' on bad self (%s)", ar.name, extramsg);
  }
  if (ar.name == NULL)
    ar.name = (pushglobalfuncname(L, &ar)) ? ls_tostring(L, -1) : "?";
  la_error(L, "bad argument #%d to '%s' (%s)", arg, ar.name, extramsg);
}

int la_typeerror(State *L, int arg, const char *tname) {
  const char *msg;
  const char *typearg;
  if (la_getmetafield(L, arg, "__name") == TY_STR)
    typearg = ls_tostring(L, -1);
  else if (ls_type(L, arg) == TY_LUD)
    typearg = "light userdata";
  else
    typearg = la_typename(L, arg);
  msg = ls_pushfstring(L, "%s expected, got %s", tname, typearg);
  la_argerror(L, arg, msg);
}

static void tag_error(State *L, int arg, int tag) {
  la_typeerror(L, arg, ls_typename(L, tag));
}

void la_where(State *L, int level) {
  DebugInfo ar;
  if (ls_getstack(L, level, &ar)) {
    ls_getinfo(L, "Sl", &ar);
    if (ar.currentline > 0) {
      ls_pushfstring(L, "%s:%d: ", ar.short_src, ar.currentline);
      return;
    }
  }
  ls_pushfstring(L, "");
}

int la_error(State *L, const char *fmt, ...) {
  va_list argp;
  va_start(argp, fmt);
  la_where(L, 1);
  ls_pushvfstring(L, fmt, argp);
  va_end(argp);
  ls_concat(L, 2);
  ls_error(L);
}

int la_fileresult(State *L, int stat, const char *fname) {
  int en = errno;
  if (stat) {
    ls_pushboolean(L, 1);
    return 1;
  } else {
    const char *msg;
    ls_pushnil(L);
    msg = (en != 0) ? strerror(en) : "(no extra info)";
    if (fname)
      ls_pushfstring(L, "%s: %s", fname, msg);
    else
      ls_pushstring(L, msg);
    ls_pushinteger(L, en);
    return 3;
  }
}

#include <sys/wait.h>

int la_execresult(State *L, int stat) {
  if (stat != 0 && errno != 0)
    return la_fileresult(L, 0, NULL);
  else {
    const char *what = "exit";
    if (WIFEXITED(stat)) {
      stat = WEXITSTATUS(stat);
    } else if (WIFSIGNALED(stat)) {
      stat = WTERMSIG(stat);
      what = "signal";
    }
    if (*what == 'e' && stat == 0)
      ls_pushboolean(L, 1);
    else
      ls_pushnil(L);
    ls_pushstring(L, what);
    ls_pushinteger(L, stat);
    return 3;
  }
}

int la_newmetatable(State *L, const char *tname) {
  if (la_getmetatable(L, tname) != TY_NIL)
    return 0;
  ls_pop(L, 1);
  ls_createtable(L, 0, 2);
  ls_pushstring(L, tname);
  ls_setfield(L, -2, "__name");
  ls_pushvalue(L, -1);
  ls_setfield(L, REGISTRYINDEX, tname);
  return 1;
}

void la_setmetatable(State *L, const char *tname) {
  la_getmetatable(L, tname);
  ls_setmetatable(L, -2);
}

void *la_testudata(State *L, int ud, const char *tname) {
  void *p = ls_touserdata(L, ud);
  if (p != NULL && ls_type(L, ud) == TY_UD) {
    if (ls_getmetatable(L, ud)) {
      la_getmetatable(L, tname);
      if (!ls_rawequal(L, -1, -2))
        p = NULL;
      ls_pop(L, 2);
      return p;
    }
  }
  return NULL;
}

void *la_checkudata(State *L, int ud, const char *tname) {
  void *p = la_testudata(L, ud, tname);
  if (p == NULL) la_typeerror(L, ud, tname);
  return p;
}

int la_checkoption(State *L, int arg, const char *def, const char *const lst[]) {
  const char *name = (def) ? la_optstring(L, arg, def) : la_checkstring(L, arg);
  int i;
  for (i = 0; lst[i]; i++)
    if (strcmp(lst[i], name) == 0)
      return i;
  la_argerror(L, arg, ls_pushfstring(L, "invalid option '%s'", name));
}

void la_checkstack(State *L, int space, const char *msg) {
  if (!ls_checkstack(L, space)) {
    if (msg)
      la_error(L, "stack overflow (%s)", msg);
    else
      la_error(L, "stack overflow");
  }
}

void la_checktype(State *L, int arg, int t) {
  if (ls_type(L, arg) != t)
    tag_error(L, arg, t);
}

void la_checkany(State *L, int arg) {
  if (ls_type(L, arg) == TY_NONE)
    la_argerror(L, arg, "value expected");
}

const char *la_checklstring(State *L, int arg, size_t *len) {
  const char *s = ls_tolstring(L, arg, len);
  if (!s) tag_error(L, arg, TY_STR);
  return s;
}

const char *la_optlstring(State *L, int arg, const char *def, size_t *len) {
  if (ls_isnoneornil(L, arg)) {
    if (len)
      *len = (def ? strlen(def) : 0);
    return def;
  } else
    return la_checklstring(L, arg, len);
}

lnum la_checknumber(State *L, int arg) {
  int isnum;
  lnum d = ls_tonumberx(L, arg, &isnum);
  if (!isnum)
    tag_error(L, arg, TY_NUM);
  return d;
}

lnum la_optnumber(State *L, int arg, lnum def) {
  return la_opt(L, la_checknumber, arg, def);
}

static void interror(State *L, int arg) {
  if (ls_isnumber(L, arg))
    la_argerror(L, arg, "number has no integer representation");
  else
    tag_error(L, arg, TY_NUM);
}

lint la_checkinteger(State *L, int arg) {
  int isnum;
  lint d = ls_tointegerx(L, arg, &isnum);
  if (!isnum) interror(L, arg);
  return d;
}

lint la_optinteger(State *L, int arg, lint def) {
  return la_opt(L, la_checkinteger, arg, def);
}

/* ---------------- buffers ---------------- */

void la_buffinit(State *L, Buffer *B) {
  B->L = L;
  B->b = B->init;
  B->n = 0;
  B->size = BUFSZ;
  B->boxidx = 0;
  ls_pushlightuserdata(L, (void *)B);  /* placeholder */
}

static int boxgc(State *L) {
  void **box = (void **)ls_touserdata(L, 1);
  if (box && *box) {
    free(*box);
    *box = NULL;
  }
  return 0;
}

char *la_prepbuffsize(Buffer *B, size_t sz) {
  if (B->size - B->n >= sz)
    return B->b + B->n;
  else {
    State *L = B->L;
    size_t newsize = (B->size / 2) * 3;
    if (newsize < B->n + sz) newsize = B->n + sz;
    if (newsize < 64) newsize = 64;
    if (B->b == B->init) {
      /* create box */
      void **box;
      char *nb = malloc(newsize);
      if (nb == NULL) la_error(L, "not enough memory");
      memcpy(nb, B->b, B->n);
      /* replace placeholder with a box userdata */
      box = (void **)ls_newuserdatauv(L, sizeof(void *), 0);
      *box = nb;
      if (la_newmetatable(L, "_BUFBOX")) {
        ls_pushcfunction(L, boxgc);
        ls_setfield(L, -2, "__gc");
      }
      ls_setmetatable(L, -2);
      /* find placeholder: it is the light userdata pointing to B */
      {
        int top = ls_gettop(L);
        int i;
        for (i = top - 1; i >= 1; i--) {
          if (ls_type(L, i) == TY_LUD && ls_touserdata(L, i) == (void *)B) {
            ls_replace(L, i);
            B->boxidx = i;
            break;
          }
        }
        if (B->boxidx == 0) {
          ls_pop(L, 1);
          la_error(L, "buffer error");
        }
      }
      B->b = nb;
    } else {
      void **box = (void **)ls_touserdata(L, B->boxidx);
      char *nb = realloc(B->b, newsize);
      if (nb == NULL) la_error(L, "not enough memory");
      *box = nb;
      B->b = nb;
    }
    B->size = newsize;
    return B->b + B->n;
  }
}

void la_addlstring(Buffer *B, const char *s, size_t l) {
  if (l > 0) {
    char *b = la_prepbuffsize(B, l);
    memcpy(b, s, l);
    la_addsize(B, l);
  }
}

void la_addstring(Buffer *B, const char *s) {
  la_addlstring(B, s, strlen(s));
}

void la_pushresult(Buffer *B) {
  State *L = B->L;
  ls_pushlstring(L, B->b, B->n);
  if (B->b != B->init) {
    void **box = (void **)ls_touserdata(L, B->boxidx);
    free(B->b);
    if (box) *box = NULL;
    B->b = B->init;
  }
  ls_remove(L, -2);
}

void la_pushresultsize(Buffer *B, size_t sz) {
  la_addsize(B, sz);
  la_pushresult(B);
}

void la_addvalue(Buffer *B) {
  State *L = B->L;
  size_t len;
  const char *s = ls_tolstring(L, -1, &len);
  char *b = la_prepbuffsize(B, len);
  memcpy(b, s, len);
  la_addsize(B, len);
  ls_pop(L, 1);
}

char *la_buffinitsize(State *L, Buffer *B, size_t sz) {
  la_buffinit(L, B);
  return la_prepbuffsize(B, sz);
}

/* ---------------- misc aux ---------------- */

int la_getmetafield(State *L, int obj, const char *event) {
  if (!ls_getmetatable(L, obj))
    return TY_NIL;
  else {
    int tt;
    ls_pushstring(L, event);
    tt = ls_rawget(L, -2);
    if (tt == TY_NIL)
      ls_pop(L, 2);
    else
      ls_remove(L, -2);
    return tt;
  }
}

int la_callmeta(State *L, int obj, const char *event) {
  obj = ls_absindex(L, obj);
  if (la_getmetafield(L, obj, event) == TY_NIL)
    return 0;
  ls_pushvalue(L, obj);
  ls_call(L, 1, 1);
  return 1;
}

lint la_len(State *L, int idx) {
  lint l;
  int isnum;
  ls_len(L, idx);
  l = ls_tointegerx(L, -1, &isnum);
  if (!isnum)
    la_error(L, "object length is not an integer");
  ls_pop(L, 1);
  return l;
}

const char *la_tolstring(State *L, int idx, size_t *len) {
  idx = ls_absindex(L, idx);
  if (la_callmeta(L, idx, "__tostring")) {
    if (!ls_isstring(L, -1))
      la_error(L, "'__tostring' must return a string");
  } else {
    switch (ls_type(L, idx)) {
      case TY_NUM: {
        char buff[64];
        int l = num_tostrbuf(index2value(L, idx), buff);
        ls_pushlstring(L, buff, (size_t)l);
        break;
      }
      case TY_STR:
        ls_pushvalue(L, idx);
        break;
      case TY_BOOL:
        ls_pushstring(L, (ls_toboolean(L, idx) ? "true" : "false"));
        break;
      case TY_NIL:
        ls_pushliteral(L, "nil");
        break;
      default: {
        int tt = la_getmetafield(L, idx, "__name");
        const char *kind = (tt == TY_STR) ? ls_tostring(L, -1) : la_typename(L, idx);
        ls_pushfstring(L, "%s: %p", kind, ls_topointer(L, idx));
        if (tt != TY_NIL)
          ls_remove(L, -2);
        break;
      }
    }
  }
  return ls_tolstring(L, -1, len);
}

void la_setfuncs(State *L, const Reg *l, int nup) {
  la_checkstack(L, nup, "too many upvalues");
  for (; l->name != NULL; l++) {
    if (l->func == NULL)
      ls_pushboolean(L, 0);
    else {
      int i;
      for (i = 0; i < nup; i++)
        ls_pushvalue(L, -nup);
      ls_pushcclosure(L, l->func, nup);
    }
    ls_setfield(L, -(nup + 2), l->name);
  }
  ls_pop(L, nup);
}

void la_newlib(State *L, const Reg *l) {
  int n = 0;
  const Reg *p;
  for (p = l; p->name; p++) n++;
  ls_createtable(L, 0, n);
  la_setfuncs(L, l, 0);
}

int la_getsubtable(State *L, int idx, const char *fname) {
  if (ls_getfield(L, idx, fname) == TY_TAB)
    return 1;
  else {
    ls_pop(L, 1);
    idx = ls_absindex(L, idx);
    ls_newtable(L);
    ls_pushvalue(L, -1);
    ls_setfield(L, idx, fname);
    return 0;
  }
}

void la_requiref(State *L, const char *modname, CFunc openf, int glb) {
  la_getsubtable(L, REGISTRYINDEX, "_LOADED");
  ls_getfield(L, -1, modname);
  if (!ls_toboolean(L, -1)) {
    ls_pop(L, 1);
    ls_pushcfunction(L, openf);
    ls_pushstring(L, modname);
    ls_call(L, 1, 1);
    ls_pushvalue(L, -1);
    ls_setfield(L, -3, modname);
  }
  ls_remove(L, -2);
  if (glb) {
    ls_pushvalue(L, -1);
    ls_setglobal(L, modname);
  }
}

const char *la_gsub(State *L, const char *s, const char *p, const char *r) {
  const char *wild;
  size_t l = strlen(p);
  Buffer b;
  la_buffinit(L, &b);
  while ((wild = strstr(s, p)) != NULL) {
    la_addlstring(&b, s, (size_t)(wild - s));
    la_addstring(&b, r);
    s = wild + l;
  }
  la_addstring(&b, s);
  la_pushresult(&b);
  return ls_tostring(L, -1);
}

/* ---------------- loading ---------------- */

int la_loadbufferx(State *L, const char *buff, size_t size, const char *name, const char *mode) {
  return ls_load(L, buff, size, name, mode);
}

int la_loadstring(State *L, const char *s) {
  return la_loadbufferx(L, s, strlen(s), s, NULL);
}

static int errfile(State *L, const char *what, int fnameindex) {
  int err = errno;
  const char *filename = ls_tostring(L, fnameindex) + 1;
  if (err != 0)
    ls_pushfstring(L, "cannot %s %s: %s", what, filename, strerror(err));
  else
    ls_pushfstring(L, "cannot %s %s", what, filename);
  ls_remove(L, fnameindex);
  return TS_ERRSYNTAX + 3;  /* file error */
}

int la_loadfilex(State *L, const char *filename, const char *mode) {
  int status;
  int fnameindex = ls_gettop(L) + 1;
  FILE *f;
  char *data = NULL;
  size_t n = 0, cap = 0;
  size_t start = 0;
  if (filename == NULL) {
    ls_pushliteral(L, "=stdin");
    f = stdin;
  } else {
    ls_pushfstring(L, "@%s", filename);
    errno = 0;
    f = fopen(filename, "r");
    if (f == NULL) return errfile(L, "open", fnameindex);
  }
  {
    char tmp[8192];
    size_t r;
    while ((r = fread(tmp, 1, sizeof(tmp), f)) > 0) {
      if (n + r > cap) {
        cap = (cap + r) * 2;
        data = realloc(data, cap);
      }
      memcpy(data + n, tmp, r);
      n += r;
    }
  }
  if (ferror(f)) {
    free(data);
    if (filename) fclose(f);
    ls_settop(L, fnameindex);
    return errfile(L, "read", fnameindex);
  }
  if (filename) fclose(f);
  /* skip shebang line */
  if (n > 0 && data[0] == '#') {
    while (start < n && data[start] != '\n') start++;
    /* keep the newline so line numbers stay right */
  } else if (n >= 3 && (unsigned char)data[0] == 0xEF && (unsigned char)data[1] == 0xBB && (unsigned char)data[2] == 0xBF) {
    start = 3;
    if (n > 3 && data[3] == '#') {
      while (start < n && data[start] != '\n') start++;
    }
  }
  status = ls_load(L, data ? data + start : "", n - start, ls_tostring(L, fnameindex), mode);
  free(data);
  ls_remove(L, fnameindex);
  return status;
}
