    ls_pushboolean(L, 0);
    ls_insert(L, -2);
    return 2;
  } else {
    ls_pushboolean(L, 1);
    ls_insert(L, -(r + 1));
    return r + 1;
  }
}

static int auxwrap(State *L) {
  State *co = ls_tothread(L, upvalueindex(1));
  int r = auxresume(L, co, ls_gettop(L));
  if (r < 0) {
    int stat = ls_status(co);
    if (stat != TS_OK && stat != TS_YIELD) {
      stat = ls_closethread(co, L);
      ls_xmove(co, L, 1);
    }
    if (stat != TS_ERRMEM && ls_type(L, -1) == TY_STR) {
      la_where(L, 1);
      ls_insert(L, -2);
      ls_concat(L, 2);
    }
    ls_error(L);
  }
  return r;
}

