/* ---------------- coroutine library ---------------- */

static State *getco(State *L) {
  State *co = ls_tothread(L, 1);
  la_argexpected(L, co, 1, "coroutine");
  return co;
}

static int auxresume(State *L, State *co, int narg) {
  int status, nres;
  if (!ls_checkstack(co, narg)) {
    ls_pushliteral(L, "too many arguments to resume");
    return -1;
  }
  ls_xmove(L, co, narg);
  status = ls_resume(co, L, narg, &nres);
  if (status == TS_OK || status == TS_YIELD) {
    if (!ls_checkstack(L, nres + 1)) {
      ls_pop(co, nres);
      ls_pushliteral(L, "too many results to resume");
      return -1;
    }
    ls_xmove(co, L, nres);
    return nres;
  } else {
    ls_xmove(co, L, 1);
    return -1;
  }
}

static int luaB_coresume(State *L) {
  State *co = getco(L);
  int r;
  r = auxresume(L, co, ls_gettop(L) - 1);
  if (r < 0) {
    ls_pushboolean(L, 0);
    ls_insert(L, -2);
    return 2;
  } else {
    ls_pushboolean(L, 1);
    ls_insert(L, -(r + 1));
    return r + 1;
  }
}

static int auxwrap(State *L) {
  State *co = ls_tothread(L, upvalueindex(1));
  int r = auxresume(L, co, ls_gettop(L));
  if (r < 0) {
    int stat = ls_status(co);
    if (stat != TS_OK && stat != TS_YIELD) {
      stat = ls_closethread(co, L);
      ls_xmove(co, L, 1);
    }
    if (stat != TS_ERRMEM && ls_type(L, -1) == TY_STR) {
      la_where(L, 1);
      ls_insert(L, -2);
      ls_concat(L, 2);
    }
    ls_error(L);
  }
  return r;
}

static int luaB_cocreate(State *L) {
  State *NL;
  la_checktype(L, 1, TY_FUNC);
  NL = ls_newthread(L);
  ls_pushvalue(L, 1);
  ls_xmove(L, NL, 1);
  return 1;
}

static int luaB_cowrap(State *L) {
  luaB_cocreate(L);
  ls_pushcclosure(L, auxwrap, 1);
  return 1;
}

static int luaB_yield(State *L) {
  return ls_yield(L, ls_gettop(L));
}

#define COS_RUN 0
#define COS_DEAD 1
#define COS_YIELD 2
#define COS_NORM 3

static const char *const statname[] = {"running", "dead", "suspended", "normal"};

static int auxstatus(State *L, State *co) {
  if (L == co) return COS_RUN;
  switch (co->costatus) {
    case 0: return (co->top - co->stack > 1) ? COS_YIELD : COS_DEAD;
    case 1: return COS_RUN;
    case 2: return COS_YIELD;
    case 3: return COS_NORM;
    default: return COS_DEAD;
  }
}

static int luaB_costatus(State *L) {
  State *co = getco(L);
  ls_pushstring(L, statname[auxstatus(L, co)]);
  return 1;
}

static int luaB_yieldable(State *L) {
  State *co = ls_isnone(L, 1) ? L : getco(L);
  ls_pushboolean(L, ls_isyieldable(co));
  return 1;
}

static int luaB_corunning(State *L) {
  int ismain = ls_pushthread(L);
  ls_pushboolean(L, ismain);
  return 2;
}

static int luaB_close(State *L) {
  State *co = getco(L);
  int status = auxstatus(L, co);
  switch (status) {
    case COS_DEAD: case COS_YIELD: {
      status = ls_closethread(co, L);
      if (status == TS_OK) {
        ls_pushboolean(L, 1);
        return 1;
      } else {
        ls_pushboolean(L, 0);
        ls_xmove(co, L, 1);
        return 2;
      }
    }
    default:
      la_error(L, "cannot close a %s coroutine", statname[status]);
  }
  return 0;
}

static const Reg co_funcs[] = {
  {"create", luaB_cocreate},
  {"resume", luaB_coresume},
  {"running", luaB_corunning},
  {"status", luaB_costatus},
  {"wrap", luaB_cowrap},
  {"yield", luaB_yield},
  {"isyieldable", luaB_yieldable},
  {"close", luaB_close},
  {NULL, NULL}
};

int open_coroutine(State *L) {
  la_newlib(L, co_funcs);
  return 1;
}
