    la_error(L, "resulting string too large");
  else {
    size_t totallen = (size_t)n * l + (size_t)(n - 1) * lsep;
    Buffer b;
    char *p = la_buffinitsize(L, &b, totallen);
    while (n-- > 1) {
      memcpy(p, s, l);
      p += l;
      if (lsep > 0) {
        memcpy(p, sep, lsep);
        p += lsep;
      }
    }
    memcpy(p, s, l);
    la_pushresultsize(&b, totallen);
  }
  return 1;
}

static int str_byte(State *L) {
  size_t l;
  const char *s = la_checklstring(L, 1, &l);
  lint pi = la_optinteger(L, 2, 1);
  size_t posi = posrelatI(pi, l);
  size_t pose = getendpos(L, 3, pi, l);
  int n, i;
  if (posi > pose) return 0;
  if (pose - posi >= (size_t)INT_MAX)
    la_error(L, "string slice too long");
  n = (int)(pose - posi) + 1;
  la_checkstack(L, n, "string slice too long");
  for (i = 0; i < n; i++)
    ls_pushinteger(L, uchar(s[posi + i - 1]));
  return n;
}

static int str_char(State *L) {
  int n = ls_gettop(L);
  int i;
  Buffer b;
  char *p = la_buffinitsize(L, &b, (size_t)n);
  for (i = 1; i <= n; i++) {
    luint c = (luint)la_checkinteger(L, i);
    la_argcheck(L, c <= (luint)UCHAR_MAX, i, "value out of range");
    p[i - 1] = (char)uchar(c);
  }
  la_pushresultsize(&b, (size_t)n);
  return 1;
}

/* ---------------- dump ---------------- */

static void writer(State *L, const void *b, size_t size, void *ud) {
  Buffer *B = (Buffer *)ud;
  (void)L;
  la_addlstring(B, (const char *)b, size);
}

static int str_dump(State *L) {
  Buffer b;
  int strip = ls_toboolean(L, 2);
  TValue *f;
  la_checktype(L, 1, TY_FUNC);
  ls_settop(L, 1);
  f = ls_index2value(L, 1);
  if (f->tt != T_LCL)
    la_error(L, "unable to dump given function");
  la_buffinit(L, &b);
  dump_proto(L, lclvalue(f)->p, strip, writer, &b);
  la_pushresult(&b);
  return 1;
}

