echo ok"}

actions.command:
cd /workspace/src && cat > lstr.c <<'EOF'
/* string library */
#include "core.h"
#include <ctype.h>
#include <float.h>

#define uchar(c) ((unsigned char)(c))
#define MAXSIZE ((size_t)INT64_MAX < (size_t)-1 ? (size_t)INT64_MAX : (size_t)-1)

static int str_len(State *L) {
  size_t l;
  la_checklstring(L, 1, &l);
  ls_pushinteger(L, (lint)l);
  return 1;
}

static size_t posrelatI(lint pos, size_t len) {
  if (pos > 0) return (size_t)pos;
  else if (pos == 0) return 1;
  else if (pos < -(lint)len) return 1;
  else return len + (size_t)pos + 1;
}

static size_t getendpos(State *L, int arg, lint def, size_t len) {
  lint pos = la_optinteger(L, arg, def);
  if (pos > (lint)len) return len;
  else if (pos >= 0) return (size_t)pos;
  else if (pos < -(lint)len) return 0;
  else return len + (size_t)pos + 1;
}

static int str_sub(State *L) {
  size_t l;
  const char *s = la_checklstring(L, 1, &l);
  size_t start = posrelatI(la_checkinteger(L, 2), l);
  size_t end = getendpos(L, 3, -1, l);
  if (start <= end)
    ls_pushlstring(L, s + start - 1, (end - start) + 1);
  else
    ls_pushliteral(L, "");
  return 1;
}

static int str_reverse(State *L) {
  size_t l, i;
  Buffer b;
  const char *s = la_checklstring(L, 1, &l);
  char *p = la_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++) p[i] = s[l - i - 1];
  la_pushresultsize(&b, l);
  return 1;
}

static int str_lower(State *L) {
  size_t l, i;
  Buffer b;
  const char *s = la_checklstring(L, 1, &l);
  char *p = la_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++) p[i] = (char)tolower(uchar(s[i]));
  la_pushresultsize(&b, l);
  return 1;
}

static int str_upper(State *L) {
  size_t l, i;
  Buffer b;
  const char *s = la_checklstring(L, 1, &l);
  char *p = la_buffinitsize(L, &b, l);
  for (i = 0; i < l; i++) p[i] = (char)toupper(uchar(s[i]));
  la_pushresultsize(&b, l);
  return 1;
}

static int str_rep(State *L) {
  size_t l, lsep;
  const char *s = la_checklstring(L, 1, &l);
  lint n = la_checkinteger(L, 2);
  const char *sep = la_optlstring(L, 3, "", &lsep);
  if (n <= 0)
    ls_pushliteral(L, "");
  else if (l + lsep < l || l + lsep > MAXSIZE / (size_t)n || (l + lsep) * (size_t)n > ((size_t)1 << 40))
    la_error(L, "resulting string too large");
  else {
    size_t totallen = (size_t)n * l + (size_t)(n - 1) * lsep;
    Buffer b;
    char *p = la_buffinitsize(L, &b, totallen);
    while (n-- > 1) {
      memcpy(p, s, l);
      p += l;
      if (lsep > 0) {
        memcpy(p, sep, lsep);
        p += lsep;
      }
    }
    memcpy(p, s, l);
    la_pushresultsize(&b, totallen);
  }
  return 1;
}

static int str_byte(State *L) {
  size_t l;
  const char *s = la_checklstring(L, 1, &l);
  lint pi = la_optinteger(L, 2, 1);
  size_t posi = posrelatI(pi, l);
  size_t pose = getendpos(L, 3, pi, l);
  int n, i;
  if (posi > pose) return 0;
  if (pose - posi >= (size_t)INT_MAX)
    la_error(L, "string slice too long");
  n = (int)(pose - posi) + 1;
  la_checkstack(L, n, "string slice too long");
  for (i = 0; i < n; i++)
    ls_pushinteger(L, uchar(s[posi + i - 1]));
  return n;
}

static int str_char(State *L) {
  int n = ls_gettop(L);
  int i;
  Buffer b;
  char *p = la_buffinitsize(L, &b, (size_t)n);
  for (i = 1; i <= n; i++) {
    luint c = (luint)la_checkinteger(L, i);
    la_argcheck(L, c <= (luint)UCHAR_MAX, i, "value out of range");
    p[i - 1] = (char)uchar(c);
  }
  la_pushresultsize(&b, (size_t)n);
  return 1;
}

/* ---------------- dump ---------------- */

static void writer(State *L, const void *b, size_t size, void *ud) {
  Buffer *B = (Buffer *)ud;
  (void)L;
  la_addlstring(B, (const char *)b, size);
}

static int str_dump(State *L) {
  Buffer b;
  int strip = ls_toboolean(L, 2);
  TValue *f;
  la_checktype(L, 1, TY_FUNC);
  ls_settop(L, 1);
  f = ls_index2value(L, 1);
  if (f->tt != T_LCL)
    la_error(L, "unable to dump given function");
  la_buffinit(L, &b);
  dump_proto(L, lclvalue(f)->p, strip, writer, &b);
  la_pushresult(&b);
  return 1;
}

/* ---------------- arithmetic metamethods ---------------- */

static int tonum(State *L, int arg) {
  if (ls_type(L, arg) == TY_NUM) {
    ls_pushvalue(L, arg);
    return 1;
  } else {
    size_t len;
    const char *s = ls_tolstring(L, arg, &len);
    return (s != NULL && ls_stringtonumber(L, s) == len + 1);
  }
}

static void trymt(State *L, const char *mtname) {
  ls_settop(L, 2);
  if (ls_type(L, 2) == TY_STR || !la_getmetafield(L, 2, mtname))
    la_error(L, "attempt to %s a '%s' with a '%s'", mtname + 2,
             la_typename(L, -2), la_typename(L, -1));
  ls_insert(L, -3);
  ls_call(L, 2, 1);
}

static int arith(State *L, int op, const char *mtname) {
  if (tonum(L, 1) && tonum(L, 2))
    ls_arith(L, op);
  else
    trymt(L, mtname);
  return 1;
}

static int arith_add(State *L) { return arith(L, OPARITH_ADD, "__add"); }
static int arith_sub(State *L) { return arith(L, OPARITH_SUB, "__sub"); }
static int arith_mul(State *L) { return arith(L, OPARITH_MUL, "__mul"); }
static int arith_mod(State *L) { return arith(L, OPARITH_MOD, "__mod"); }
static int arith_pow(State *L) { return arith(L, OPARITH_POW, "__pow"); }
static int arith_div(State *L) { return arith(L, OPARITH_DIV, "__div"); }
static int arith_idiv(State *L) { return arith(L, OPARITH_IDIV, "__idiv"); }
static int arith_unm(State *L) { return arith(L, OPARITH_UNM, "__unm"); }

