/* ---------------- pattern matching ---------------- */

#define MAXCAPTURES 32
#define CAP_UNFINISHED (-1)
#define CAP_POSITION (-2)
#define L_ESC '%'
#define SPECIALS "^$*+?.([%-"
#define MAXMATCHDEPTH 200

typedef struct MatchState {
  const char *src_init;
  const char *src_end;
  const char *p_end;
  State *L;
  int matchdepth;
  int level;
  struct {
    const char *init;
    ptrdiff_t len;
  } capture[MAXCAPTURES];
} MatchState;

static const char *match(MatchState *ms, const char *s, const char *p);

static int check_capture(MatchState *ms, int l) {
  l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNFINISHED)
    la_error(ms->L, "invalid capture index %%%d in pattern", l + 1);
  return l;
}

static int capture_to_close(MatchState *ms) {
  int level = ms->level;
  for (level--; level >= 0; level--)
    if (ms->capture[level].len == CAP_UNFINISHED) return level;
  la_error(ms->L, "invalid pattern capture");
}

static const char *classEnd(MatchState *ms, const char *p) {
  switch (*p++) {
    case L_ESC: {
      if (p == ms->p_end)
        la_error(ms->L, "malformed pattern (ends with '%%')");
      return p + 1;
    }
    case '[': {
      if (*p == '^') p++;
      do {
        if (p == ms->p_end)
          la_error(ms->L, "malformed pattern (missing ']')");
        if (*(p++) == L_ESC && p < ms->p_end)
          p++;
      } while (*p != ']');
      return p + 1;
    }
    default:
      return p;
  }
}

static int match_class(int c, int cl) {
  int res;
  switch (tolower(cl)) {
    case 'a': res = isalpha(c); break;
    case 'c': res = iscntrl(c); break;
    case 'd': res = isdigit(c); break;
    case 'g': res = isgraph(c); break;
    case 'l': res = islower(c); break;
    case 'p': res = ispunct(c); break;
    case 's': res = isspace(c); break;
    case 'u': res = isupper(c); break;
    case 'w': res = isalnum(c); break;
    case 'x': res = isxdigit(c); break;
    default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res;
}

static int matchbracketclass(int c, const char *p, const char *ec) {
  int sig = 1;
  if (*(p + 1) == '^') {
    sig = 0;
    p++;
  }
  while (++p < ec) {
    if (*p == L_ESC) {
      p++;
      if (match_class(c, uchar(*p)))
        return sig;
    } else if (*(p + 1) == '-' && (p + 2 < ec)) {
      p += 2;
      if (uchar(*(p - 2)) <= c && c <= uchar(*p))
        return sig;
    } else if (uchar(*p) == c)
      return sig;
  }
  return !sig;
}

static int singlematch(MatchState *ms, const char *s, const char *p, const char *ep) {
  if (s >= ms->src_end)
    return 0;
  else {
    int c = uchar(*s);
    switch (*p) {
      case '.': return 1;
      case L_ESC: return match_class(c, uchar(*(p + 1)));
      case '[': return matchbracketclass(c, p, ep - 1);
      default: return (uchar(*p) == c);
    }
  }
}

static const char *matchbalance(MatchState *ms, const char *s, const char *p) {
  if (p >= ms->p_end - 1)
    la_error(ms->L, "malformed pattern (missing arguments to '%%b')");
  if (*s != *p) return NULL;
  else {
    int b = *p;
    int e = *(p + 1);
    int cont = 1;
    while (++s < ms->src_end) {
      if (*s == e) {
        if (--cont == 0) return s + 1;
      } else if (*s == b)
        cont++;
    }
  }
  return NULL;
}

static const char *max_expand(MatchState *ms, const char *s, const char *p, const char *ep) {
  ptrdiff_t i = 0;
  while (singlematch(ms, s + i, p, ep))
    i++;
  while (i >= 0) {
    const char *res = match(ms, (s + i), ep + 1);
    if (res) return res;
    i--;
  }
  return NULL;
}

static const char *min_expand(MatchState *ms, const char *s, const char *p, const char *ep) {
  for (;;) {
    const char *res = match(ms, s, ep + 1);
    if (res != NULL)
      return res;
    else if (singlematch(ms, s, p, ep))
      s++;
    else
      return NULL;
  }
}

static const char *start_capture(MatchState *ms, const char *s, const char *p, int what) {
  const char *res;
  int level = ms->level;
  if (level >= MAXCAPTURES) la_error(ms->L, "too many captures");
  ms->capture[level].init = s;
  ms->capture[level].len = what;
  ms->level = level + 1;
  if ((res = match(ms, s, p)) == NULL)
    ms->level--;
  return res;
}

static const char *end_capture(MatchState *ms, const char *s, const char *p) {
  int l = capture_to_close(ms);
  const char *res;
  ms->capture[l].len = s - ms->capture[l].init;
  if ((res = match(ms, s, p)) == NULL)
    ms->capture[l].len = CAP_UNFINISHED;
  return res;
}

static const char *match_capture(MatchState *ms, const char *s, int l) {
  size_t len;
  l = check_capture(ms, l);
  len = (size_t)ms->capture[l].len;
  if ((size_t)(ms->src_end - s) >= len && memcmp(ms->capture[l].init, s, len) == 0)
    return s + len;
  else
    return NULL;
}

static const char *match(MatchState *ms, const char *s, const char *p) {
  if (ms->matchdepth-- == 0)
    la_error(ms->L, "pattern too complex");
  while (1) {
    if (p != ms->p_end) {
      switch (*p) {
        case '(': {
          if (*(p + 1) == ')')
            s = start_capture(ms, s, p + 2, CAP_POSITION);
          else
            s = start_capture(ms, s, p + 1, CAP_UNFINISHED);
          break;
        }
        case ')': {
          s = end_capture(ms, s, p + 1);
          break;
        }
        case '$': {
          if ((p + 1) != ms->p_end)
            goto dflt;
          s = (s == ms->src_end) ? s : NULL;
          break;
        }
        case L_ESC: {
          switch (*(p + 1)) {
            case 'b': {
              s = matchbalance(ms, s, p + 2);
              if (s != NULL) {
                p += 4;
                continue;
              }
              break;
            }
            case 'f': {
              const char *ep;
              char previous;
              p += 2;
              if (*p != '[')
                la_error(ms->L, "missing '[' after '%%f' in pattern");
              ep = classEnd(ms, p);
              previous = (s == ms->src_init) ? '\0' : *(s - 1);
              if (!matchbracketclass(uchar(previous), p, ep - 1) &&
                  matchbracketclass(uchar(*s), p, ep - 1)) {
                p = ep;
                continue;
              }
              s = NULL;
              break;
            }
            case '0': case '1': case '2': case '3':
            case '4': case '5': case '6': case '7':
            case '8': case '9': {
              s = match_capture(ms, s, uchar(*(p + 1)));
              if (s != NULL) {
                p += 2;
                continue;
              }
              break;
            }
            default:
              goto dflt;
          }
          break;
        }
        default:
        dflt: {
          const char *ep = classEnd(ms, p);
          if (!singlematch(ms, s, p, ep)) {
            if (*ep == '*' || *ep == '?' || *ep == '-') {
              p = ep + 1;
              continue;
            } else
              s = NULL;
          } else {
            switch (*ep) {
              case '?': {
                const char *res;
                if ((res = match(ms, s + 1, ep + 1)) != NULL)
                  s = res;
                else {
                  p = ep + 1;
                  continue;
                }
                break;
              }
              case '+':
                s = max_expand(ms, s + 1, p, ep);
                break;
              case '*':
                s = max_expand(ms, s, p, ep);
                break;
              case '-':
                s = min_expand(ms, s, p, ep);
                break;
              default:
                s++;
                p = ep;
                continue;
            }
          }
          break;
        }
      }
    }
    ms->matchdepth++;
    return s;
  }
}

static const char *lmemfind(const char *s1, size_t l1, const char *s2, size_t l2) {
  if (l2 == 0) return s1;
  else if (l2 > l1) return NULL;
  else {
    const char *init;
    l2--;
    l1 = l1 - l2;
    while (l1 > 0 && (init = (const char *)memchr(s1, *s2, l1)) != NULL) {
      init++;
      if (memcmp(init, s2 + 1, l2) == 0)
        return init - 1;
      else {
        l1 -= (size_t)(init - s1);
        s1 = init;
      }
    }
    return NULL;
  }
}

static size_t get_onecapture(MatchState *ms, int i, const char *s, const char *e, const char **cap) {
  if (i >= ms->level) {
    if (i != 0)
      la_error(ms->L, "invalid capture index %%%d", i + 1);
    *cap = s;
    return (size_t)(e - s);
  } else {
    ptrdiff_t capl = ms->capture[i].len;
    *cap = ms->capture[i].init;
    if (capl == CAP_UNFINISHED)
      la_error(ms->L, "unfinished capture");
    else if (capl == CAP_POSITION)
      ls_pushinteger(ms->L, (ms->capture[i].init - ms->src_init) + 1);
    return (size_t)capl;
  }
}

static void push_onecapture(MatchState *ms, int i, const char *s, const char *e) {
  const char *cap;
  ptrdiff_t l = (ptrdiff_t)get_onecapture(ms, i, s, e, &cap);
  if (l != CAP_POSITION)
    ls_pushlstring(ms->L, cap, (size_t)l);
}

static int push_captures(MatchState *ms, const char *s, const char *e) {
  int i;
  int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  la_checkstack(ms->L, nlevels, "too many captures");
  for (i = 0; i < nlevels; i++)
    push_onecapture(ms, i, s, e);
  return nlevels;
}

static int nospecials(const char *p, size_t l) {
  size_t upto = 0;
  do {
    if (strpbrk(p + upto, SPECIALS))
      return 0;
    upto += strlen(p + upto) + 1;
  } while (upto <= l);
  return 1;
}

static void prepstate(MatchState *ms, State *L, const char *s, size_t ls, const char *p, size_t lp) {
  ms->L = L;
  ms->matchdepth = MAXMATCHDEPTH;
  ms->src_init = s;
  ms->src_end = s + ls;
  ms->p_end = p + lp;
}

static void reprepstate(MatchState *ms) {
  ms->level = 0;
  ms->matchdepth = MAXMATCHDEPTH;
}

static int str_find_aux(State *L, int find) {
  size_t ls, lp;
  const char *s = la_checklstring(L, 1, &ls);
  const char *p = la_checklstring(L, 2, &lp);
  size_t init = posrelatI(la_optinteger(L, 3, 1), ls) - 1;
  if (init > ls) {
    ls_pushnil(L);
    return 1;
  }
  if (find && (ls_toboolean(L, 4) || nospecials(p, lp))) {
    const char *s2 = lmemfind(s + init, ls - init, p, lp);
    if (s2) {
      ls_pushinteger(L, (s2 - s) + 1);
      ls_pushinteger(L, (lint)((s2 - s) + lp));
      return 2;
    }
  } else {
    MatchState ms;
    const char *s1 = s + init;
    int anchor = (*p == '^');
    if (anchor) {
      p++;
      lp--;
    }
    prepstate(&ms, L, s, ls, p, lp);
    do {
      const char *res;
      reprepstate(&ms);
      if ((res = match(&ms, s1, p)) != NULL) {
        if (find) {
          ls_pushinteger(L, (s1 - s) + 1);
          ls_pushinteger(L, res - s);
          return push_captures(&ms, NULL, 0) + 2;
        } else
          return push_captures(&ms, s1, res);
      }
    } while (s1++ < ms.src_end && !anchor);
  }
  ls_pushnil(L);
  return 1;
}

static int str_find(State *L) { return str_find_aux(L, 1); }
static int str_match(State *L) { return str_find_aux(L, 0); }

typedef struct GMatchState {
  const char *src;
  const char *p;
  const char *lastmatch;
  MatchState ms;
} GMatchState;

static int gmatch_aux(State *L) {
  GMatchState *gm = (GMatchState *)ls_touserdata(L, upvalueindex(3));
  const char *src;
  gm->ms.L = L;
  for (src = gm->src; src <= gm->ms.src_end; src++) {
    const char *e;
    reprepstate(&gm->ms);
    if ((e = match(&gm->ms, src, gm->p)) != NULL && e != gm->lastmatch) {
      gm->src = gm->lastmatch = e;
      return push_captures(&gm->ms, src, e);
    }
  }
  return 0;
}

static int gmatch(State *L) {
  size_t ls, lp;
  const char *s = la_checklstring(L, 1, &ls);
  const char *p = la_checklstring(L, 2, &lp);
  size_t init = posrelatI(la_optinteger(L, 3, 1), ls) - 1;
  GMatchState *gm;
  ls_settop(L, 2);
  gm = (GMatchState *)ls_newuserdatauv(L, sizeof(GMatchState), 0);
  if (init > ls) init = ls + 1;
  prepstate(&gm->ms, L, s, ls, p, lp);
  gm->src = s + init;
  gm->p = p;
  gm->lastmatch = NULL;
  ls_pushcclosure(L, gmatch_aux, 3);
  return 1;
}

static void add_s(MatchState *ms, Buffer *b, const char *s, const char *e) {
  size_t l;
  State *L = ms->L;
  const char *news = ls_tolstring(L, 3, &l);
  const char *p;
  while ((p = (char *)memchr(news, L_ESC, l)) != NULL) {
    la_addlstring(b, news, (size_t)(p - news));
    p++;
    if (*p == L_ESC)
      la_addchar(b, *p);
    else if (isdigit(uchar(*p))) {
      const char *cap;
      ptrdiff_t resl = (ptrdiff_t)get_onecapture(ms, *p - '1', s, e, &cap);
      if (resl == CAP_POSITION)
        la_addvalue(b);
      else
        la_addlstring(b, cap, (size_t)resl);
    } else
      la_error(L, "invalid use of '%c' in replacement string", L_ESC);
    l -= (size_t)(p + 1 - news);
    news = p + 1;
  }
  la_addlstring(b, news, l);
}

static int add_value(MatchState *ms, Buffer *b, const char *s, const char *e, int tr) {
  State *L = ms->L;
  switch (tr) {
    case TY_FUNC: {
      int n;
      ls_pushvalue(L, 3);
      n = push_captures(ms, s, e);
      ls_call(L, n, 1);
      break;
    }
    case TY_TAB: {
      push_onecapture(ms, 0, s, e);
      ls_gettable(L, 3);
      break;
    }
    default: {
      add_s(ms, b, s, e);
      return 1;
    }
  }
  if (!ls_toboolean(L, -1)) {
    ls_pop(L, 1);
    la_addlstring(b, s, (size_t)(e - s));
    return 0;
  } else if (!ls_isstring(L, -1))
    la_error(L, "invalid replacement value (a %s)", la_typename(L, -1));
  else {
    la_addvalue(b);
    return 1;
  }
}

static int str_gsub(State *L) {
  size_t srcl, lp;
  const char *src = la_checklstring(L, 1, &srcl);
  const char *p = la_checklstring(L, 2, &lp);
  const char *lastmatch = NULL;
  int tr = ls_type(L, 3);
  lint max_s = la_optinteger(L, 4, (lint)srcl + 1);
  int anchor = (*p == '^');
  lint n = 0;
  int changed = 0;
  MatchState ms;
  Buffer b;
  la_argexpected(L, tr == TY_NUM || tr == TY_STR || tr == TY_FUNC || tr == TY_TAB, 3,
                 "string/function/table");
  la_buffinit(L, &b);
  if (anchor) {
    p++;
    lp--;
  }
  prepstate(&ms, L, src, srcl, p, lp);
  while (n < max_s) {
    const char *e;
    reprepstate(&ms);
    if ((e = match(&ms, src, p)) != NULL && e != lastmatch) {
      n++;
      changed = add_value(&ms, &b, src, e, tr) | changed;
      src = lastmatch = e;
    } else if (src < ms.src_end)
      la_addchar(&b, *src++);
    else
      break;
    if (anchor) break;
  }
  if (!changed)
    ls_pushvalue(L, 1);
  else {
    la_addlstring(&b, src, (size_t)(ms.src_end - src));
    la_pushresult(&b);
  }
  if (!changed) {
    /* remove buffer placeholder */
    ls_remove(L, -2);
  }
  ls_pushinteger(L, n);
  return 2;
}

/* ---------------- format ---------------- */

#define L_FMTFLAGSF "-+ #0"
#define L_FMTFLAGSX "-#0"
#define L_FMTFLAGSI "-+ 0"
#define L_FMTFLAGSU "-0"
#define L_FMTFLAGSC "-"
#define MAX_ITEMF (110 + DBL_MAX_10_EXP)
#define MAX_ITEM 120
#define MAX_FORMAT 32

static void addquoted(Buffer *b, const char *s, size_t len) {
  la_addchar(b, '"');
  while (len--) {
    if (*s == '"' || *s == '\\' || *s == '\n') {
      la_addchar(b, '\\');
      la_addchar(b, *s);
    } else if (iscntrl(uchar(*s))) {
      char buff[10];
      if (!isdigit(uchar(*(s + 1))))
        snprintf(buff, sizeof(buff), "\\%d", (int)uchar(*s));
      else
        snprintf(buff, sizeof(buff), "\\%03d", (int)uchar(*s));
      la_addstring(b, buff);
    } else
      la_addchar(b, *s);
    s++;
  }
  la_addchar(b, '"');
}

static int quotefloat(State *L, char *buff, lnum n) {
  (void)L;
  if (n == (lnum)HUGE_VAL) return snprintf(buff, MAX_ITEM, "1e9999");
  else if (n == -(lnum)HUGE_VAL) return snprintf(buff, MAX_ITEM, "-1e9999");
  else if (n != n) return snprintf(buff, MAX_ITEM, "(0/0)");
  else {
    int nb = snprintf(buff, MAX_ITEM, "%a", n);
    if (memchr(buff, '.', (size_t)nb) == NULL) {
      char point = '.';
      char *ppoint = (char *)memchr(buff, point, (size_t)nb);
      (void)ppoint;
    }
    return nb;
  }
}

static void addliteral(State *L, Buffer *b, int arg) {
  switch (ls_type(L, arg)) {
    case TY_STR: {
      size_t len;
      const char *s = ls_tolstring(L, arg, &len);
      addquoted(b, s, len);
      break;
    }
    case TY_NUM: {
      char *buff = la_prepbuffsize(b, MAX_ITEM);
      int nb;
      if (!ls_isinteger(L, arg))
        nb = quotefloat(L, buff, ls_tonumber(L, arg));
      else {
        lint n = ls_tointeger(L, arg);
        const char *format = (n == INT64_MIN) ? "0x%llx" : "%lld";
        nb = snprintf(buff, MAX_ITEM, format, (long long)n);
      }
      la_addsize(b, (size_t)nb);
      break;
    }
    case TY_NIL: case TY_BOOL: {
      la_tolstring(L, arg, NULL);
      la_addvalue(b);
      break;
    }
    default: {
      la_argerror(L, arg, "value has no literal form");
    }
  }
}

static const char *get2digits(const char *s) {
  if (isdigit(uchar(*s))) {
    s++;
    if (isdigit(uchar(*s))) s++;
  }
  return s;
}

static void checkformat(State *L, const char *form, const char *flags, int precision) {
  const char *spec = form + 1;
  spec += strspn(spec, flags);
  if (*spec != '0') {
    spec = get2digits(spec);
    if (*spec == '.' && precision) {
      spec++;
      spec = get2digits(spec);
    }
  }
  if (!isalpha(uchar(*spec)))
    la_error(L, "invalid conversion specification: '%s'", form);
}

static const char *getformat(State *L, const char *strfrmt, char *form) {
  size_t len = strspn(strfrmt, L_FMTFLAGSF "123456789");
  len++;
  if (len >= MAX_FORMAT - 10)
    la_error(L, "invalid format string to 'format'");
  *(form++) = '%';
  memcpy(form, strfrmt, len);
  *(form + len) = '\0';
  return strfrmt + len - 1;
}

static void addlenmod(char *form, const char *lenmod) {
  size_t l = strlen(form);
  size_t lm = strlen(lenmod);
  char spec = form[l - 1];
  strcpy(form + l - 1, lenmod);
  form[l + lm - 1] = spec;
  form[l + lm] = '\0';
}

static int str_format(State *L) {
  int top = ls_gettop(L);
  int arg = 1;
  size_t sfl;
  const char *strfrmt = la_checklstring(L, arg, &sfl);
  const char *strfrmt_end = strfrmt + sfl;
  const char *flags;
  Buffer b;
  la_buffinit(L, &b);
  while (strfrmt < strfrmt_end) {
    if (*strfrmt != L_ESC)
      la_addchar(&b, *strfrmt++);
    else if (*++strfrmt == L_ESC)
      la_addchar(&b, *strfrmt++);
    else {
      char form[MAX_FORMAT];
      int maxitem = MAX_ITEM;
      char *buff = la_prepbuffsize(&b, (size_t)maxitem);
      int nb = 0;
      if (++arg > top)
        la_argerror(L, arg, "no value");
      strfrmt = getformat(L, strfrmt, form);
      switch (*strfrmt++) {
        case 'c': {
          checkformat(L, form, L_FMTFLAGSC, 0);
          nb = snprintf(buff, (size_t)maxitem, form, (int)la_checkinteger(L, arg));
          break;
        }
        case 'd': case 'i':
          flags = L_FMTFLAGSI;
          goto intcase;
        case 'u':
          flags = L_FMTFLAGSU;
          goto intcase;
        case 'o': case 'x': case 'X':
          flags = L_FMTFLAGSX;
        intcase: {
          lint n = la_checkinteger(L, arg);
          checkformat(L, form, flags, 1);
          addlenmod(form, "ll");
          nb = snprintf(buff, (size_t)maxitem, form, (long long)n);
          break;
        }
        case 'a': case 'A':
          checkformat(L, form, L_FMTFLAGSF, 1);
          nb = snprintf(buff, (size_t)maxitem, form, la_checknumber(L, arg));
          break;
        case 'f': case 'F': case 'e': case 'E': case 'g': case 'G': {
          lnum n = la_checknumber(L, arg);
          checkformat(L, form, L_FMTFLAGSF, 1);
          if (form[strlen(form) - 1] == 'f' || form[strlen(form) - 1] == 'F') {
            maxitem = MAX_ITEMF;
            buff = la_prepbuffsize(&b, (size_t)maxitem);
          }
          nb = snprintf(buff, (size_t)maxitem, form, n);
          break;
        }
        case 'p': {
          const void *p = ls_topointer(L, arg);
          checkformat(L, form, L_FMTFLAGSC, 0);
          if (p == NULL) {
            p = "(null)";
            form[strlen(form) - 1] = 's';
          }
          nb = snprintf(buff, (size_t)maxitem, form, p);
          break;
        }
        case 'q': {
          if (form[2] != '\0')
            la_error(L, "specifier '%%q' cannot have modifiers");
          addliteral(L, &b, arg);
          break;
        }
        case 's': {
          size_t l;
          const char *s = la_tolstring(L, arg, &l);
          if (form[2] == '\0')
            la_addvalue(&b);
          else {
            la_argcheck(L, l == strlen(s), arg, "string contains zeros");
            checkformat(L, form, L_FMTFLAGSC, 1);
            if (strchr(form, '.') == NULL && l >= 100) {
              la_addvalue(&b);
            } else {
              buff = la_prepbuffsize(&b, l + (size_t)maxitem);
              nb = snprintf(buff, l + (size_t)maxitem, form, s);
              ls_pop(L, 1);
            }
          }
          break;
        }
        default: {
          return la_error(L, "invalid conversion '%s' to 'format'", form);
        }
      }
      la_addsize(&b, (size_t)nb);
    }
  }
  la_pushresult(&b);
  return 1;
}

/* ---------------- pack / unpack ---------------- */

#define MAXINTSIZE 16
#define NB CHAR_BIT
#define MC ((1 << NB) - 1)
#define SZINT ((int)sizeof(lint))

static const union { int dummy; char little; } nativeendian = {1};

typedef struct Header {
  State *L;
  int islittle;
  int maxalign;
} Header;

typedef enum KOption {
  Kint, Kuint, Kfloat, Knumber, Kdouble, Kchar, Kstring, Kzstr, Kpadding, Kpaddalign, Knop
} KOption;

static int digit(int c) { return '0' <= c && c <= '9'; }

static int getnum(const char **fmt, int df) {
  if (!digit(**fmt))
    return df;
  else {
    int a = 0;
    do {
      a = a * 10 + (*((*fmt)++) - '0');
    } while (digit(**fmt) && a <= ((int)INT_MAX - 9) / 10);
    return a;
  }
}

static int getnumlimit(Header *h, const char **fmt, int df) {
  int sz = getnum(fmt, df);
  if (sz > MAXINTSIZE || sz <= 0)
    la_error(h->L, "integral size (%d) out of limits [1,%d]", sz, MAXINTSIZE);
  return sz;
}

static void initheader(State *L, Header *h) {
  h->L = L;
  h->islittle = nativeendian.little;
  h->maxalign = 1;
}

static KOption getoption(Header *h, const char **fmt, int *size) {
  int opt = *((*fmt)++);
  *size = 0;
  switch (opt) {
    case 'b': *size = sizeof(char); return Kint;
    case 'B': *size = sizeof(char); return Kuint;
    case 'h': *size = sizeof(short); return Kint;
    case 'H': *size = sizeof(short); return Kuint;
    case 'l': *size = sizeof(long); return Kint;
    case 'L': *size = sizeof(long); return Kuint;
    case 'j': *size = sizeof(lint); return Kint;
    case 'J': *size = sizeof(lint); return Kuint;
    case 'T': *size = sizeof(size_t); return Kuint;
    case 'f': *size = sizeof(float); return Kfloat;
    case 'n': *size = sizeof(lnum); return Knumber;
    case 'd': *size = sizeof(double); return Kdouble;
    case 'i': *size = getnumlimit(h, fmt, sizeof(int)); return Kint;
    case 'I': *size = getnumlimit(h, fmt, sizeof(int)); return Kuint;
    case 's': *size = getnumlimit(h, fmt, sizeof(size_t)); return Kstring;
    case 'c':
      *size = getnum(fmt, -1);
      if (*size == -1)
        la_error(h->L, "missing size for format option 'c'");
      return Kchar;
    case 'z': return Kzstr;
    case 'x': *size = 1; return Kpadding;
    case 'X': return Kpaddalign;
    case ' ': break;
    case '<': h->islittle = 1; break;
    case '>': h->islittle = 0; break;
    case '=': h->islittle = nativeendian.little; break;
    case '!': {
      const int maxalign = 8;
      h->maxalign = getnumlimit(h, fmt, maxalign);
      break;
    }
    default: la_error(h->L, "invalid format option '%c'", opt);
  }
  return Knop;
}

static KOption getdetails(Header *h, size_t totalsize, const char **fmt, int *psize, int *ntoalign) {
  KOption opt = getoption(h, fmt, psize);
  int align = *psize;
  if (opt == Kpaddalign) {
    if (**fmt == '\0' || getoption(h, fmt, &align) == Kchar || align == 0)
      la_argerror(h->L, 1, "invalid next option for option 'X'");
  }
  if (align <= 1 || opt == Kchar)
    *ntoalign = 0;
  else {
    if (align > h->maxalign)
      align = h->maxalign;
    if ((align & (align - 1)) != 0)
      la_argerror(h->L, 1, "format asks for alignment not power of 2");
    *ntoalign = (align - (int)(totalsize & (size_t)(align - 1))) & (align - 1);
  }
  return opt;
}

static void packint(Buffer *b, luint n, int islittle, int size, int neg) {
  char *buff = la_prepbuffsize(b, (size_t)size);
  int i;
  buff[islittle ? 0 : size - 1] = (char)(n & MC);
  for (i = 1; i < size; i++) {
    n >>= NB;
    buff[islittle ? i : size - 1 - i] = (char)(n & MC);
  }
  if (neg && size > SZINT) {
    for (i = SZINT; i < size; i++)
      buff[islittle ? i : size - 1 - i] = (char)MC;
  }
  la_addsize(b, (size_t)size);
}

static void copywithendian(char *dest, const char *src, int size, int islittle) {
  if (islittle == nativeendian.little)
    memcpy(dest, src, (size_t)size);
  else {
    dest += size - 1;
    while (size-- != 0)
      *(dest--) = *(src++);
  }
}

static int str_pack(State *L) {
  Buffer b;
  Header h;
  const char *fmt = la_checkstring(L, 1);
  int arg = 1;
  size_t totalsize = 0;
  initheader(L, &h);
  ls_pushnil(L);
  la_buffinit(L, &b);
  while (*fmt != '\0') {
    int size, ntoalign;
    KOption opt = getdetails(&h, totalsize, &fmt, &size, &ntoalign);
    totalsize += (size_t)(ntoalign + size);
    while (ntoalign-- > 0)
      la_addchar(&b, '\0');
    arg++;
    switch (opt) {
      case Kint: {
        lint n = la_checkinteger(L, arg);
        if (size < SZINT) {
          lint lim = (lint)1 << ((size * NB) - 1);
          la_argcheck(L, -lim <= n && n < lim, arg, "integer overflow");
        }
        packint(&b, (luint)n, h.islittle, size, (n < 0));
        break;
      }
      case Kuint: {
        lint n = la_checkinteger(L, arg);
        if (size < SZINT)
          la_argcheck(L, (luint)n < ((luint)1 << (size * NB)), arg, "unsigned overflow");
        packint(&b, (luint)n, h.islittle, size, 0);
        break;
      }
      case Kfloat: {
        float f = (float)la_checknumber(L, arg);
        char *buff = la_prepbuffsize(&b, sizeof(f));
        copywithendian(buff, (char *)&f, sizeof(f), h.islittle);
        la_addsize(&b, (size_t)size);
        break;
      }
      case Knumber: case Kdouble: {
        double f = (double)la_checknumber(L, arg);
        char *buff = la_prepbuffsize(&b, sizeof(f));
        copywithendian(buff, (char *)&f, sizeof(f), h.islittle);
        la_addsize(&b, (size_t)size);
        break;
      }
      case Kchar: {
        size_t len;
        const char *s = la_checklstring(L, arg, &len);
        la_argcheck(L, len <= (size_t)size, arg, "string longer than given size");
        la_addlstring(&b, s, len);
        while (len++ < (size_t)size)
          la_addchar(&b, '\0');
        break;
      }
      case Kstring: {
        size_t len;
        const char *s = la_checklstring(L, arg, &len);
        la_argcheck(L, size >= (int)sizeof(size_t) || len < ((size_t)1 << (size * NB)), arg,
                    "string length does not fit in given size");
        packint(&b, (luint)len, h.islittle, size, 0);
        la_addlstring(&b, s, len);
        totalsize += len;
        break;
      }
      case Kzstr: {
        size_t len;
        const char *s = la_checklstring(L, arg, &len);
        la_argcheck(L, strlen(s) == len, arg, "string contains zeros");
        la_addlstring(&b, s, len);
        la_addchar(&b, '\0');
        totalsize += len + 1;
        break;
      }
      case Kpadding: la_addchar(&b, '\0');
      /* FALLTHROUGH */
      case Kpaddalign: case Knop:
        arg--;
        break;
    }
  }
  la_pushresult(&b);
  return 1;
}

static int str_packsize(State *L) {
  Header h;
  const char *fmt = la_checkstring(L, 1);
  size_t totalsize = 0;
  initheader(L, &h);
  while (*fmt != '\0') {
    int size, ntoalign;
    KOption opt = getdetails(&h, totalsize, &fmt, &size, &ntoalign);
    la_argcheck(L, opt != Kstring && opt != Kzstr, 1, "variable-size format in packsize");
    size += ntoalign;
    la_argcheck(L, totalsize <= MAXSIZE - (size_t)size, 1, "format result too large");
    totalsize += (size_t)size;
  }
  ls_pushinteger(L, (lint)totalsize);
  return 1;
}

static lint unpackint(State *L, const char *str, int islittle, int size, int issigned) {
  luint res = 0;
  int i;
  int limit = (size <= SZINT) ? size : SZINT;
  for (i = limit - 1; i >= 0; i--) {
    res <<= NB;
    res |= (luint)uchar(str[islittle ? i : size - 1 - i]);
  }
  if (size < SZINT) {
    if (issigned) {
      luint mask = (luint)1 << (size * NB - 1);
      res = ((res ^ mask) - mask);
    }
  } else if (size > SZINT) {
    int mask = (!issigned || (lint)res >= 0) ? 0 : MC;
    for (i = limit; i < size; i++) {
      if (uchar(str[islittle ? i : size - 1 - i]) != mask)
        la_error(L, "%d-byte integer does not fit into Lua Integer", size);
    }
  }
  return (lint)res;
}

static int str_unpack(State *L) {
  Header h;
  const char *fmt = la_checkstring(L, 1);
  size_t ld;
  const char *data = la_checklstring(L, 2, &ld);
  size_t pos = posrelatI(la_optinteger(L, 3, 1), ld) - 1;
  int n = 0;
  la_argcheck(L, pos <= ld, 3, "initial position out of string");
  initheader(L, &h);
  while (*fmt != '\0') {
    int size, ntoalign;
    KOption opt = getdetails(&h, pos, &fmt, &size, &ntoalign);
    la_argcheck(L, (size_t)ntoalign + (size_t)size <= ld - pos, 2, "data string too short");
    pos += (size_t)ntoalign;
    la_checkstack(L, 2, "too many results");
    n++;
    switch (opt) {
      case Kint:
      case Kuint: {
        lint res = unpackint(L, data + pos, h.islittle, size, (opt == Kint));
        ls_pushinteger(L, res);
        break;
      }
      case Kfloat: {
        float f;
        copywithendian((char *)&f, data + pos, sizeof(f), h.islittle);
        ls_pushnumber(L, (lnum)f);
        break;
      }
      case Knumber: case Kdouble: {
        double f;
        copywithendian((char *)&f, data + pos, sizeof(f), h.islittle);
        ls_pushnumber(L, (lnum)f);
        break;
      }
      case Kchar: {
        ls_pushlstring(L, data + pos, (size_t)size);
        break;
      }
      case Kstring: {
        luint len = (luint)unpackint(L, data + pos, h.islittle, size, 0);
        la_argcheck(L, len <= ld - pos - (size_t)size, 2, "data string too short");
        ls_pushlstring(L, data + pos + size, (size_t)len);
        pos += (size_t)len;
        break;
      }
      case Kzstr: {
        size_t len = strlen(data + pos);
        la_argcheck(L, pos + len < ld, 2, "unfinished string for format 'z'");
        ls_pushlstring(L, data + pos, len);
        pos += len + 1;
        break;
      }
      case Kpaddalign: case Kpadding: case Knop:
        n--;
        break;
    }
    pos += (size_t)size;
  }
  ls_pushinteger(L, (lint)pos + 1);
  return n + 1;
}

static const Reg strlib[] = {
  {"byte", str_byte},
  {"char", str_char},
  {"dump", str_dump},
  {"find", str_find},
  {"format", str_format},
  {"gmatch", gmatch},
  {"gsub", str_gsub},
