      ls_pop(L, 1);
    }
    while (ls_geti(L, 1, --j), sort_comp(L, -3, -1)) {
      if (j < i)
        la_error(L, "invalid order function for sorting");
      ls_pop(L, 1);
    }
    if (j < i) {
      ls_pop(L, 1);
      set2(L, up - 1, i);
      return i;
    }
    set2(L, i, j);
  }
}

static IdxT choosePivot(IdxT lo, IdxT up, unsigned int rnd) {
  IdxT r4 = (up - lo) / 4;
  IdxT p = rnd % (r4 * 2) + (lo + r4);
  return p;
}

static void auxsort(State *L, IdxT lo, IdxT up, unsigned int rnd) {
  while (lo < up) {
    IdxT p;
    IdxT n;
    ls_geti(L, 1, lo);
    ls_geti(L, 1, up);
    if (sort_comp(L, -1, -2))
      set2(L, lo, up);
    else
      ls_pop(L, 2);
    if (up - lo == 1)
      break;
    if (up - lo < RANLIMIT || rnd == 0)
      p = (lo + up) / 2;
    else
      p = choosePivot(lo, up, rnd);
    ls_geti(L, 1, p);
    ls_geti(L, 1, lo);
    if (sort_comp(L, -2, -1))
      set2(L, p, lo);
    else {
      ls_pop(L, 1);
      ls_geti(L, 1, up);
      if (sort_comp(L, -1, -2))
        set2(L, p, up);
      else
        ls_pop(L, 2);
    }
    if (up - lo == 2)
      break;
    ls_geti(L, 1, p);
    ls_pushvalue(L, -1);
    ls_geti(L, 1, up - 1);
    set2(L, p, up - 1);
    p = partition(L, lo, up);
    if (p - lo < up - p) {
      auxsort(L, lo, p - 1, rnd);
      n = p - lo;
      lo = p + 1;
    } else {
      auxsort(L, p + 1, up, rnd);
      n = up - p;
      up = p - 1;
    }
    if ((up - lo) / 128 > n)
      rnd = l_randomizePivot();
  }
}

static int tsort(State *L) {
  lint n = aux_getn(L, 1, TAB_RW);
  if (n > 1) {
    la_argcheck(L, n < INT_MAX, 1, "array too big");
    if (!ls_isnoneornil(L, 2))
      la_checktype(L, 2, TY_FUNC);
    ls_settop(L, 2);
    auxsort(L, 1, (IdxT)n, 0);
  }
  return 0;
}

static const Reg tab_funcs[] = {
  {"concat", tconcat},
  {"create", tcreate},
  {"insert", tinsert},
  {"pack", tpack},
  {"unpack", tunpack},
  {"remove", tremove},
  {"move", tmove},
  {"sort", tsort},
  {NULL, NULL}
};

int open_table(State *L) {
  la_newlib(L, tab_funcs);
  return 1;
}
