      break;
    }
    case 2: {
      low = la_checkinteger(L, 1);
      up = la_checkinteger(L, 2);
      break;
    }
    default:
      return la_error(L, "wrong number of arguments");
  }
  la_argcheck(L, low <= up, 1, "interval is empty");
  p = project(rv, (luint)up - (luint)low, rstate);
  ls_pushinteger(L, (lint)(p + (luint)low));
  return 1;
}

static void setseed(State *L, uint64_t *state, luint n1, luint n2) {
  int i;
  state[0] = n1;
  state[1] = 0xff;
  state[2] = n2;
  state[3] = 0;
  for (i = 0; i < 16; i++) xnext(state);
  ls_pushinteger(L, (lint)n1);
  ls_pushinteger(L, (lint)n2);
}

static int math_randomseed(State *L) {
  if (ls_isnone(L, 1)) {
    luint n1 = (luint)time(NULL);
    luint n2 = (luint)(uintptr_t)L ^ (luint)clock();
    setseed(L, rstate, n1, n2);
  } else {
    lint n1 = la_checkinteger(L, 1);
    lint n2 = la_optinteger(L, 2, 0);
    setseed(L, rstate, (luint)n1, (luint)n2);
  }
  return 2;
}

static const Reg mathlib[] = {
  {"abs", math_abs},
  {"ceil", math_ceil},
  {"exp", math_exp},
  {"floor", math_floor},
  {"fmod", math_fmod},
  {"frexp", math_frexp},
  {"ldexp", math_ldexp},
  {"log", math_log},
  {"max", math_max},
  {"min", math_min},
  {"modf", math_modf},
  {"sqrt", math_sqrt},
  {"tointeger", math_toint},
  {"type", math_type},
  {"ult", math_ult},
  {"sin", math_sin},
  {"cos", math_cos},
  {"tan", math_tan},
  {"asin", math_asin},
  {"acos", math_acos},
  {"atan", math_atan},
  {"deg", math_deg},
  {"rad", math_rad},
  {"random", math_random},
  {"randomseed", math_randomseed},
  {"pi", NULL},
  {"huge", NULL},
  {"maxinteger", NULL},
  {"mininteger", NULL},
  {NULL, NULL}
};

int open_math(State *L) {
  (void)nextrand;
  la_newlib(L, mathlib);
  ls_pushnumber(L, PI);
  ls_setfield(L, -2, "pi");
  ls_pushnumber(L, (lnum)HUGE_VAL);
  ls_setfield(L, -2, "huge");
  ls_pushinteger(L, INT64_MAX);
  ls_setfield(L, -2, "maxinteger");
  ls_pushinteger(L, INT64_MIN);
  ls_setfield(L, -2, "mininteger");
  {
    luint n1 = (luint)time(NULL);
    luint n2 = (luint)(uintptr_t)L;
    setseed(L, rstate, n1, n2);
    ls_pop(L, 2);
  }
  return 1;
}
