/* table library */
#include "core.h"
#include <time.h>

#define TAB_R 1
#define TAB_W 2
#define TAB_L 4
#define TAB_RW (TAB_R | TAB_W)

static int checkfield(State *L, const char *key, int n) {
  ls_pushstring(L, key);
  return (ls_rawget(L, -n) != TY_NIL);
}

static void checktab(State *L, int arg, int what) {
  if (ls_type(L, arg) != TY_TAB) {
    int n = 1;
    if (ls_getmetatable(L, arg) &&
        (!(what & TAB_R) || checkfield(L, "__index", ++n)) &&
        (!(what & TAB_W) || checkfield(L, "__newindex", ++n)) &&
        (!(what & TAB_L) || checkfield(L, "__len", ++n))) {
      ls_pop(L, n);
    } else
      la_checktype(L, arg, TY_TAB);
  }
}

#define aux_getn(L, n, w) (checktab(L, n, (w) | TAB_L), la_len(L, n))

static int tinsert(State *L) {
  lint pos;
  lint e = aux_getn(L, 1, TAB_RW);
  e = (lint)((luint)e + 1u);
  switch (ls_gettop(L)) {
    case 2: {
      pos = e;
      break;
    }
    case 3: {
      lint i;
      pos = la_checkinteger(L, 2);
      la_argcheck(L, (luint)pos - 1u < (luint)e, 2, "position out of bounds");
      for (i = e; i > pos; i--) {
        ls_geti(L, 1, i - 1);
        ls_seti(L, 1, i);
      }
      break;
    }
    default: {
      return la_error(L, "wrong number of arguments to 'insert'");
    }
  }
  ls_seti(L, 1, pos);
  return 0;
}

static int tremove(State *L) {
  lint size = aux_getn(L, 1, TAB_RW);
  lint pos = la_optinteger(L, 2, size);
  if (pos != size)
    la_argcheck(L, (luint)pos - 1u <= (luint)size, 2, "position out of bounds");
  ls_geti(L, 1, pos);
  for (; pos < size; pos++) {
    ls_geti(L, 1, pos + 1);
    ls_seti(L, 1, pos);
  }
  ls_pushnil(L);
  ls_seti(L, 1, pos);
  return 1;
}

static int tmove(State *L) {
  lint f = la_checkinteger(L, 2);
  lint e = la_checkinteger(L, 3);
  lint t = la_checkinteger(L, 4);
  int tt = !ls_isnoneornil(L, 5) ? 5 : 1;
  checktab(L, 1, TAB_R);
  checktab(L, tt, TAB_W);
  if (e >= f) {
    lint n, i;
    la_argcheck(L, f > 0 || e < INT64_MAX + f, 3, "too many elements to move");
    n = e - f + 1;
    la_argcheck(L, t <= INT64_MAX - n + 1, 4, "destination wrap around");
    if (t > e || t > f || (tt != 1 && !ls_compare(L, 1, tt, OPCMP_EQ))) {
      for (i = 0; i < n; i++) {
        ls_geti(L, 1, f + i);
        ls_seti(L, tt, t + i);
      }
    } else {
      for (i = n - 1; i >= 0; i--) {
        ls_geti(L, 1, f + i);
        ls_seti(L, tt, t + i);
      }
    }
  }
  ls_pushvalue(L, tt);
  return 1;
}

static void addfield(State *L, Buffer *b, lint i) {
  ls_geti(L, 1, i);
  if (!ls_isstring(L, -1))
    la_error(L, "invalid value (%s) at index %I in table for 'concat'", la_typename(L, -1), i);
  la_addvalue(b);
}

static int tconcat(State *L) {
  Buffer b;
  lint last = aux_getn(L, 1, TAB_R);
  size_t lsep;
  const char *sep = la_optlstring(L, 2, "", &lsep);
  lint i = la_optinteger(L, 3, 1);
  last = la_optinteger(L, 4, last);
  la_buffinit(L, &b);
  for (; i < last; i++) {
    addfield(L, &b, i);
    la_addlstring(&b, sep, lsep);
  }
  if (i == last)
    addfield(L, &b, i);
  la_pushresult(&b);
  return 1;
}

static int tpack(State *L) {
  int i;
  int n = ls_gettop(L);
  ls_createtable(L, n, 1);
  ls_insert(L, 1);
  for (i = n; i >= 1; i--)
    ls_seti(L, 1, i);
  ls_pushinteger(L, n);
  ls_setfield(L, 1, "n");
  return 1;
}

static int tunpack(State *L) {
  luint n;
  lint i = la_optinteger(L, 2, 1);
  lint e = ls_isnoneornil(L, 3) ? la_len(L, 1) : la_checkinteger(L, 3);
  if (i > e) return 0;
  n = (luint)e - (luint)i;
  if (n >= (unsigned int)INT_MAX || !ls_checkstack(L, (int)(++n)))
    return la_error(L, "too many results to unpack");
  for (; i < e; i++) {
    ls_geti(L, 1, i);
  }
  ls_geti(L, 1, e);
  return (int)n;
}

static int tcreate(State *L) {
  lint sizeseq = la_checkinteger(L, 1);
  lint sizerest = la_optinteger(L, 2, 0);
  la_argcheck(L, sizeseq >= 0 && sizeseq <= INT_MAX, 1, "out of range");
  la_argcheck(L, sizerest >= 0 && sizerest <= INT_MAX, 2, "out of range");
  ls_createtable(L, (int)sizeseq, (int)sizerest);
  return 1;
}

/* ---------------- sort ---------------- */

typedef unsigned int IdxT;
#define RANLIMIT 100u

static unsigned int l_randomizePivot(void) {
  clock_t c = clock();
  time_t t = time(NULL);
  unsigned int buff[4];
  unsigned int i, rnd = 0;
  memset(buff, 0, sizeof(buff));
  memcpy(buff, &c, sizeof(c) < sizeof(buff) / 2 ? sizeof(c) : sizeof(buff) / 2);
  memcpy((char *)buff + sizeof(buff) / 2, &t, sizeof(t) < sizeof(buff) / 2 ? sizeof(t) : sizeof(buff) / 2);
  for (i = 0; i < 4; i++) rnd += buff[i];
  return rnd;
}

static void set2(State *L, IdxT i, IdxT j) {
  ls_seti(L, 1, i);
  ls_seti(L, 1, j);
}

static int sort_comp(State *L, int a, int b) {
  if (ls_isnil(L, 2))
    return ls_compare(L, a, b, OPCMP_LT);
  else {
    int res;
    ls_pushvalue(L, 2);
    ls_pushvalue(L, a - 1);
    ls_pushvalue(L, b - 2);
    ls_call(L, 2, 1);
    res = ls_toboolean(L, -1);
    ls_pop(L, 1);
    return res;
  }
}

static IdxT partition(State *L, IdxT lo, IdxT up) {
  IdxT i = lo;
  IdxT j = up - 1;
  for (;;) {
    while (ls_geti(L, 1, ++i), sort_comp(L, -1, -2)) {
      if (i == up - 1)
        la_error(L, "invalid order function for sorting");
      ls_pop(L, 1);
    }
    while (ls_geti(L, 1, --j), sort_comp(L, -3, -1)) {
      if (j < i)
        la_error(L, "invalid order function for sorting");
      ls_pop(L, 1);
    }
    if (j < i) {
      ls_pop(L, 1);
      set2(L, up - 1, i);
      return i;
    }
    set2(L, i, j);
  }
}

static IdxT choosePivot(IdxT lo, IdxT up, unsigned int rnd) {
  IdxT r4 = (up - lo) / 4;
  IdxT p = rnd % (r4 * 2) + (lo + r4);
  return p;
}

static void auxsort(State *L, IdxT lo, IdxT up, unsigned int rnd) {
  while (lo < up) {
    IdxT p;
    IdxT n;
    ls_geti(L, 1, lo);
    ls_geti(L, 1, up);
    if (sort_comp(L, -1, -2))
      set2(L, lo, up);
    else
      ls_pop(L, 2);
    if (up - lo == 1)
      break;
    if (up - lo < RANLIMIT || rnd == 0)
      p = (lo + up) / 2;
    else
      p = choosePivot(lo, up, rnd);
    ls_geti(L, 1, p);
    ls_geti(L, 1, lo);
    if (sort_comp(L, -2, -1))
      set2(L, p, lo);
    else {
      ls_pop(L, 1);
      ls_geti(L, 1, up);
      if (sort_comp(L, -1, -2))
        set2(L, p, up);
      else
        ls_pop(L, 2);
    }
    if (up - lo == 2)
      break;
    ls_geti(L, 1, p);
    ls_pushvalue(L, -1);
    ls_geti(L, 1, up - 1);
    set2(L, p, up - 1);
    p = partition(L, lo, up);
    if (p - lo < up - p) {
      auxsort(L, lo, p - 1, rnd);
      n = p - lo;
      lo = p + 1;
    } else {
      auxsort(L, p + 1, up, rnd);
      n = up - p;
      up = p - 1;
    }
    if ((up - lo) / 128 > n)
      rnd = l_randomizePivot();
  }
}

static int tsort(State *L) {
  lint n = aux_getn(L, 1, TAB_RW);
  if (n > 1) {
    la_argcheck(L, n < INT_MAX, 1, "array too big");
    if (!ls_isnoneornil(L, 2))
