static uint64_t rstate[4];

static uint64_t rotl(uint64_t x, int n) {
  return (x << n) | (x >> (64 - n));
}

static uint64_t nextrand(uint64_t *s) {
  uint64_t s0 = s[0], s1 = s[1], s2 = s[2] ^ s0, s3 = s[3] ^ s1;
  uint64_t res = rotl(s1 * 5, 7) * 9;
  s1 <<= 17;
  s[0] = s0 ^ s3;
  s[1] = s0 ^ s1 ^ s2;
  s[1] = s[1];
  {
    /* standard xoshiro256** update */
    uint64_t t = s[1];
    (void)t;
  }
  return res;
}

static uint64_t xnext(uint64_t *s) {
  const uint64_t result = rotl(s[1] * 5, 7) * 9;
  const uint64_t t = s[1] << 17;
  s[2] ^= s[0];
  s[3] ^= s[1];
  s[1] ^= s[2];
  s[0] ^= s[3];
  s[2] ^= t;
  s[3] = rotl(s[3], 45);
  return result;
}

static lnum I2d(uint64_t x) {
  return (lnum)(x >> 11) * (0.5 / ((uint64_t)1 << 52));
}

static luint project(luint ran, luint n, uint64_t *state) {
  if ((n & (n + 1)) == 0)
    return ran & n;
  else {
    luint lim = n;
    lim |= (lim >> 1);
    lim |= (lim >> 2);
    lim |= (lim >> 4);
    lim |= (lim >> 8);
    lim |= (lim >> 16);
    lim |= (lim >> 32);
    while ((ran &= lim) > n)
      ran = xnext(state);
    return ran;
  }
}

static int math_random(State *L) {
  lint low, up;
  luint p;
  uint64_t rv = xnext(rstate);
  switch (ls_gettop(L)) {
    case 0:
