/* utf8 library */
#include "core.h"

#define MAXUNICODE 0x10FFFFu
#define MAXUTF 0x7FFFFFFFu
#define iscont(c) (((c) & 0xC0) == 0x80)
#define iscontp(p) iscont(*(p))
#define UTF8PATT "[\0-\x7F\xC2-\xFD][\x80-\xBF]*"

typedef unsigned int utfint;

static lint u_posrelat(lint pos, size_t len) {
  if (pos >= 0) return pos;
  else if (0u - (size_t)pos > len) return 0;
  else return (lint)len + pos + 1;
}

static const char *utf8_decode(const char *s, utfint *val, int strict) {
  static const utfint limits[] = {~(utfint)0, 0x80, 0x800, 0x10000u, 0x200000u, 0x4000000u};
  unsigned int c = (unsigned char)s[0];
  utfint res = 0;
  if (c < 0x80)
    res = c;
  else {
    int count = 0;
    for (; c & 0x40; c <<= 1) {
      unsigned int cc = (unsigned char)s[++count];
      if (!iscont(cc))
        return NULL;
      res = (res << 6) | (cc & 0x3F);
    }
    res |= ((utfint)(c & 0x7F) << (count * 5));
    if (count > 5 || res > MAXUTF || res < limits[count])
      return NULL;
    s += count;
  }
  if (strict) {
    if (res > MAXUNICODE || (0xD800u <= res && res <= 0xDFFFu))
      return NULL;
  }
  if (val) *val = res;
  return s + 1;
}

static int utflen(State *L) {
  lint n = 0;
  size_t len;
  const char *s = la_checklstring(L, 1, &len);
  lint posi = u_posrelat(la_optinteger(L, 2, 1), len);
  lint posj = u_posrelat(la_optinteger(L, 3, -1), len);
  int lax = ls_toboolean(L, 4);
  la_argcheck(L, 1 <= posi && --posi <= (lint)len, 2, "initial position out of bounds");
  la_argcheck(L, --posj < (lint)len, 3, "final position out of bounds");
  while (posi <= posj) {
    const char *s1 = utf8_decode(s + posi, NULL, !lax);
    if (s1 == NULL) {
      ls_pushnil(L);
      ls_pushinteger(L, posi + 1);
      return 2;
    }
    posi = s1 - s;
    n++;
  }
  ls_pushinteger(L, n);
  return 1;
}

static int codepoint(State *L) {
  size_t len;
  const char *s = la_checklstring(L, 1, &len);
  lint posi = u_posrelat(la_optinteger(L, 2, 1), len);
  lint pose = u_posrelat(la_optinteger(L, 3, posi), len);
  int lax = ls_toboolean(L, 4);
  int n;
  const char *se;
  la_argcheck(L, posi >= 1, 2, "out of bounds");
  la_argcheck(L, pose <= (lint)len, 3, "out of bounds");
  if (posi > pose) return 0;
  if (pose - posi >= INT_MAX)
    return la_error(L, "string slice too long");
  n = (int)(pose - posi) + 1;
  la_checkstack(L, n, "string slice too long");
  n = 0;
  se = s + pose;
  for (s += posi - 1; s < se;) {
    utfint code;
    s = utf8_decode(s, &code, !lax);
    if (s == NULL)
      return la_error(L, "invalid UTF-8 code");
    ls_pushinteger(L, code);
    n++;
  }
  return n;
}

static void pushutfchar(State *L, int arg) {
  luint code = (luint)la_checkinteger(L, arg);
  la_argcheck(L, code <= MAXUTF, arg, "value out of range");
  ls_pushfstring(L, "%U", (long)code);
}

static int utfchar(State *L) {
  int n = ls_gettop(L);
  if (n == 1)
    pushutfchar(L, 1);
  else {
    int i;
    Buffer b;
    la_buffinit(L, &b);
    for (i = 1; i <= n; i++) {
      pushutfchar(L, i);
      la_addvalue(&b);
    }
    la_pushresult(&b);
  }
  return 1;
}

static int byteoffset(State *L) {
  size_t len;
  const char *s = la_checklstring(L, 1, &len);
  lint n = la_checkinteger(L, 2);
  lint posi = (n >= 0) ? 1 : (lint)len + 1;
  posi = u_posrelat(la_optinteger(L, 3, posi), len);
  la_argcheck(L, 1 <= posi && --posi <= (lint)len, 3, "position out of bounds");
  if (n == 0) {
    while (posi > 0 && iscontp(s + posi)) posi--;
  } else {
    if (iscontp(s + posi))
      return la_error(L, "initial position is a continuation byte");
    if (n < 0) {
      while (n < 0 && posi > 0) {
        do {
          posi--;
        } while (posi > 0 && iscontp(s + posi));
        n++;
      }
    } else {
      n--;
      while (n > 0 && posi < (lint)len) {
        do {
          posi++;
        } while (iscontp(s + posi));
        n--;
      }
    }
  }
  if (n == 0) {
    lint posj = posi;
    ls_pushinteger(L, posi + 1);
    if (posj < (lint)len) {
      posj++;
      while (iscontp(s + posj)) posj++;
    }
    ls_pushinteger(L, posj);
    return 2;
  } else
    ls_pushnil(L);
  return 1;
}

static int iter_aux(State *L, int strict) {
  size_t len;
  const char *s = la_checklstring(L, 1, &len);
  luint n = (luint)ls_tointeger(L, 2);
  if (n < len) {
    while (iscontp(s + n)) n++;
  }
  if (n >= len)
    return 0;
  else {
    utfint code;
    const char *next = utf8_decode(s + n, &code, strict);
    if (next == NULL || iscontp(next))
      return la_error(L, "invalid UTF-8 code");
    ls_pushinteger(L, (lint)n + 1);
    ls_pushinteger(L, code);
    return 2;
  }
}

static int iter_auxstrict(State *L) { return iter_aux(L, 1); }
static int iter_auxlax(State *L) { return iter_aux(L, 0); }

static int iter_codes(State *L) {
  int lax = ls_toboolean(L, 2);
  const char *s = la_checkstring(L, 1);
  la_argcheck(L, !iscontp(s), 1, "invalid UTF-8 code");
  ls_pushcfunction(L, lax ? iter_auxlax : iter_auxstrict);
  ls_pushvalue(L, 1);
  ls_pushinteger(L, 0);
  return 3;
}

static const Reg funcs[] = {
  {"offset", byteoffset},
  {"codepoint", codepoint},
  {"char", utfchar},
  {"len", utflen},
  {"codes", iter_codes},
  {"charpattern", NULL},
  {NULL, NULL}
};

int open_utf8(State *L) {
  la_newlib(L, funcs);
  ls_pushlstring(L, UTF8PATT, sizeof(UTF8PATT) / sizeof(char) - 1);
  ls_setfield(L, -2, "charpattern");
  return 1;
}
