static int makemask(const char *smask, int count) {
  int mask = 0;
  if (strchr(smask, 'c')) mask |= MASKCALL;
  if (strchr(smask, 'r')) mask |= MASKRET;
  if (strchr(smask, 'l')) mask |= MASKLINE;
  if (count > 0) mask |= MASKCOUNT;
  return mask;
}

static char *unmakemask(int mask, char *smask) {
  int i = 0;
  if (mask & MASKCALL) smask[i++] = 'c';
  if (mask & MASKRET) smask[i++] = 'r';
  if (mask & MASKLINE) smask[i++] = 'l';
  smask[i] = '\0';
  return smask;
}

