    fprintf(stderr, "%s", "lua_debug> ");
    fflush(stderr);
    if (fgets(buffer, sizeof(buffer), stdin) == NULL || strcmp(buffer, "cont\n") == 0)
      return 0;
    if (la_loadbufferx(L, buffer, strlen(buffer), "=(debug command)", NULL) ||
