#define MASKCALL 1
#define MASKRET 2
#define MASKLINE 4
#define MASKCOUNT 8

static int makemask(const char *smask, int count) {
  int mask = 0;
  if (strchr(smask, 'c')) mask |= MASKCALL;
  if (strchr(smask, 'r')) mask |= MASKRET;
  if (strchr(smask, 'l')) mask |= MASKLINE;
  if (count > 0) mask |= MASKCOUNT;
  return mask;
}

static char *unmakemask(int mask, char *smask) {
  int i = 0;
  if (mask & MASKCALL) smask[i++] = 'c';
  if (mask & MASKRET) smask[i++] = 'r';
  if (mask & MASKLINE) smask[i++] = 'l';
  smask[i] = '\0';
  return smask;
}

static int db_sethook(State *L) {
  int arg, mask, count;
  State *L1 = getthread(L, &arg);
  if (ls_isnoneornil(L, arg + 1)) {
    ls_settop(L, arg + 1);
    mask = 0;
    count = 0;
    setnil(&L1->hook);
  } else {
    const char *smask = la_checkstring(L, arg + 2);
    la_checktype(L, arg + 1, TY_FUNC);
    count = (int)la_optinteger(L, arg + 3, 0);
    mask = makemask(smask, count);
    L1->hook = *ls_index2value(L, arg + 1);
  }
  L1->hookmask = mask;
  L1->basehookcount = count;
  L1->hookcount = count;
  L1->oldpc = -1;
  (void)HOOKKEY;
  return 0;
}

static int db_gethook(State *L) {
  int arg;
  State *L1 = getthread(L, &arg);
  char buff[5];
  int mask = L1->hookmask;
  if (isnil(&L1->hook)) {
    ls_pushnil(L);
    return 1;
  }
  *L->top = L1->hook;
  L->top++;
  ls_pushstring(L, unmakemask(mask, buff));
  ls_pushinteger(L, L1->basehookcount);
  return 3;
}

static int db_debug(State *L) {
  for (;;) {
    char buffer[250];
    fprintf(stderr, "%s", "lua_debug> ");
    fflush(stderr);
    if (fgets(buffer, sizeof(buffer), stdin) == NULL || strcmp(buffer, "cont\n") == 0)
      return 0;
    if (la_loadbufferx(L, buffer, strlen(buffer), "=(debug command)", NULL) ||
        ls_pcall(L, 0, 0, 0)) {
      fprintf(stderr, "%s\n", la_tolstring(L, -1, NULL));
      fflush(stderr);
