static void setpath(State *L, const char *fieldname, const char *envname, const char *dft) {
  const char *dftmark;
  const char *nver = ls_pushfstring(L, "%s%s", envname, "_5_5");
  const char *path = getenv(nver);
  if (path == NULL) path = getenv(envname);
  if (path == NULL || noenv(L))
    ls_pushstring(L, dft);
  else if ((dftmark = strstr(path, LUA_PATH_SEP LUA_PATH_SEP)) == NULL)
    ls_pushstring(L, path);
  else {
    size_t len = strlen(path);
    Buffer b;
    la_buffinit(L, &b);
    if (path < dftmark) {
      la_addlstring(&b, path, (size_t)(dftmark - path));
      la_addchar(&b, *LUA_PATH_SEP);
    }
    la_addstring(&b, dft);
    if (dftmark < path + len - 2) {
      la_addchar(&b, *LUA_PATH_SEP);
      la_addlstring(&b, dftmark + 2, (size_t)((path + len - 2) - dftmark));
    }
    la_pushresult(&b);
  }
  ls_setfield(L, -3, fieldname);
  ls_pop(L, 1);
}

static int readable(const char *filename) {
  FILE *f = fopen(filename, "r");
  if (f == NULL) return 0;
  fclose(f);
  return 1;
}

static const char *getnextfilename(char **path, char *end) {
  char *sep;
  char *name = *path;
  if (name == end)
    return NULL;
  else if (*name == '\0') {
    *name = *LUA_PATH_SEP;
    name++;
  }
  sep = strchr(name, *LUA_PATH_SEP);
  if (sep == NULL)
    sep = end;
  *sep = '\0';
  *path = sep;
  return name;
}

static void pusherrornotfound(State *L, const char *path) {
  Buffer b;
  la_buffinit(L, &b);
  la_addstring(&b, "no file '");
  la_gsub(L, path, LUA_PATH_SEP, "'\n\tno file '");
  la_addvalue(&b);
  la_addstring(&b, "'");
  la_pushresult(&b);
}

static const char *searchpath(State *L, const char *name, const char *path, const char *sep, const char *dirsep) {
  Buffer buff;
  char *pathname;
  char *endpathname;
  const char *filename;
  if (*sep != '\0' && strchr(name, *sep) != NULL)
    name = la_gsub(L, name, sep, dirsep);
  la_buffinit(L, &buff);
  la_gsub(L, path, LUA_PATH_MARK, name);
  la_addvalue(&buff);
  la_addchar(&buff, '\0');
  pathname = buff.b;
  endpathname = pathname + buff.n - 1;
  while ((filename = getnextfilename(&pathname, endpathname)) != NULL) {
    if (readable(filename)) {
      const char *r = ls_pushstring(L, filename);
      ls_remove(L, -2);
      return r;
    }
  }
  la_pushresult(&buff);
  pusherrornotfound(L, ls_tostring(L, -1));
  return NULL;
}

static int ll_searchpath(State *L) {
  const char *f = searchpath(L, la_checkstring(L, 1), la_checkstring(L, 2),
                             la_optstring(L, 3, "."), la_optstring(L, 4, LUA_DIRSEP));
  if (f != NULL)
    return 1;
  else {
    ls_pushnil(L);
    ls_insert(L, -2);
    return 2;
  }
}

static const char *findfile(State *L, const char *name, const char *pname, const char *dirsep) {
  const char *path;
  ls_getfield(L, upvalueindex(1), pname);
  path = ls_tostring(L, -1);
  if (path == NULL)
    la_error(L, "'package.%s' must be a string", pname);
  return searchpath(L, name, path, ".", dirsep);
}

static int checkload(State *L, int stat, const char *filename) {
  if (stat) {
    ls_pushstring(L, filename);
    return 2;
  } else
    return la_error(L, "error loading module '%s' from file '%s':\n\t%s",
                    ls_tostring(L, 1), filename, ls_tostring(L, -1));
}

static int searcher_Lua(State *L) {
  const char *filename;
  const char *name = la_checkstring(L, 1);
  filename = findfile(L, name, "path", LUA_LSUBSEP);
  if (filename == NULL) return 1;
  return checkload(L, (la_loadfilex(L, filename, NULL) == TS_OK), filename);
}

static int searcher_C(State *L) {
  const char *name = la_checkstring(L, 1);
  const char *filename = findfile(L, name, "cpath", LUA_CSUBSEP);
  if (filename == NULL) return 1;
  ls_pushfstring(L, "dynamic libraries not enabled; check your Lua installation");
  return checkload(L, 0, filename);
}

static int searcher_Croot(State *L) {
  const char *filename;
  const char *name = la_checkstring(L, 1);
  const char *p = strchr(name, '.');
  if (p == NULL) return 0;
  ls_pushlstring(L, name, (size_t)(p - name));
  filename = findfile(L, ls_tostring(L, -1), "cpath", LUA_CSUBSEP);
  if (filename == NULL) return 1;
  ls_pushfstring(L, "no module '%s' in file '%s'", name, filename);
  return 1;
}

static int searcher_preload(State *L) {
  const char *name = la_checkstring(L, 1);
  ls_getfield(L, REGISTRYINDEX, "_PRELOAD");
  if (ls_getfield(L, -1, name) == TY_NIL) {
    ls_pushfstring(L, "no field package.preload['%s']", name);
    return 1;
  } else {
    ls_pushliteral(L, ":preload:");
    return 2;
  }
}

static void findloader(State *L, const char *name) {
  int i;
  Buffer msg;
  if (ls_getfield(L, upvalueindex(1), "searchers") != TY_TAB)
    la_error(L, "'package.searchers' must be a table");
  la_buffinit(L, &msg);
  for (i = 1;; i++) {
    la_addstring(&msg, "\n\t");
    if (ls_rawgeti(L, 3, i) == TY_NIL) {
      ls_pop(L, 1);
      la_buffsub(&msg, 2);
      la_pushresult(&msg);
      la_error(L, "module '%s' not found:%s", name, ls_tostring(L, -1));
    }
    ls_pushstring(L, name);
    ls_call(L, 1, 2);
    if (ls_isfunction(L, -2))
      return;
    else if (ls_isstring(L, -2)) {
      ls_pop(L, 1);
      la_addvalue(&msg);
    } else {
      ls_pop(L, 2);
      la_buffsub(&msg, 2);
    }
  }
}

static int ll_require(State *L) {
  const char *name = la_checkstring(L, 1);
  ls_settop(L, 1);
  ls_getfield(L, REGISTRYINDEX, "_LOADED");
  ls_getfield(L, 2, name);
  if (ls_toboolean(L, -1))
    return 1;
  ls_pop(L, 1);
  findloader(L, name);
  ls_rotate(L, -2, 1);
  ls_pushvalue(L, 1);
  ls_pushvalue(L, -3);
  ls_call(L, 2, 1);
  if (!ls_isnil(L, -1))
    ls_setfield(L, 2, name);
  else
    ls_pop(L, 1);
  if (ls_getfield(L, 2, name) == TY_NIL) {
    ls_pushboolean(L, 1);
    ls_copy(L, -1, -2);
    ls_setfield(L, 2, name);
  }
  ls_rotate(L, -2, 1);
  return 2;
}

static int ll_loadlib(State *L) {
  la_checkstring(L, 1);
  la_checkstring(L, 2);
  ls_pushnil(L);
  ls_pushliteral(L, "dynamic libraries not enabled; check your Lua installation");
  ls_pushliteral(L, "absent");
  return 3;
}

static const Reg pk_funcs[] = {
  {"loadlib", ll_loadlib},
  {"searchpath", ll_searchpath},
  {"preload", NULL},
  {"cpath", NULL},
  {"path", NULL},
  {"searchers", NULL},
  {"loaded", NULL},
  {NULL, NULL}
};

static const Reg ll_funcs[] = {
  {"require", ll_require},
  {NULL, NULL}
};

static void createsearcherstable(State *L) {
  static const CFunc searchers[] = {searcher_preload, searcher_Lua, searcher_C, searcher_Croot, NULL};
  int i;
  ls_createtable(L, 4, 0);
  for (i = 0; searchers[i] != NULL; i++) {
    ls_pushvalue(L, -2);
    ls_pushcclosure(L, searchers[i], 1);
    ls_rawseti(L, -2, i + 1);
  }
  ls_setfield(L, -2, "searchers");
}

int open_package(State *L) {
  (void)CLIBS;
  la_newlib(L, pk_funcs);
  createsearcherstable(L);
  setpath(L, "path", "LUA_PATH", LUA_PATH_DEFAULT);
  setpath(L, "cpath", "LUA_CPATH", LUA_CPATH_DEFAULT);
  ls_pushliteral(L, LUA_DIRSEP "\n" LUA_PATH_SEP "\n" LUA_PATH_MARK "\n" LUA_EXEC_DIR "\n" LUA_IGMARK "\n");
  ls_setfield(L, -2, "config");
  la_getsubtable(L, REGISTRYINDEX, "_LOADED");
  ls_setfield(L, -2, "loaded");
  la_getsubtable(L, REGISTRYINDEX, "_PRELOAD");
  ls_setfield(L, -2, "preload");
  ls_pushglobaltable(L);
  ls_pushvalue(L, -2);
  la_setfuncs(L, ll_funcs, 1);
  ls_pop(L, 1);
  return 1;
}
