/* binary chunks: dump and undump */
#include "core.h"

#define DUMP_SIG "\x1bLuaX"

typedef struct DumpState {
  State *L;
  void (*w)(State *, const void *, size_t, void *);
  void *ud;
  int strip;
} DumpState;

static void dumpblock(DumpState *D, const void *b, size_t size) {
  if (size > 0) D->w(D->L, b, size, D->ud);
}

static void dumpint(DumpState *D, lint x) { dumpblock(D, &x, sizeof(x)); }
static void dumpnum(DumpState *D, lnum x) { dumpblock(D, &x, sizeof(x)); }
static void dumpbyte(DumpState *D, int b) { unsigned char c = (unsigned char)b; dumpblock(D, &c, 1); }

static void dumpstring(DumpState *D, Str *s) {
  if (s == NULL) dumpint(D, -1);
  else {
    dumpint(D, (lint)s->len);
    dumpblock(D, getstr(s), s->len);
  }
}

static void dumpfunction(DumpState *D, const Proto *f) {
  int i;
  dumpstring(D, D->strip ? NULL : f->source);
  dumpint(D, f->linedefined);
  dumpint(D, f->lastlinedefined);
  dumpbyte(D, f->numparams);
  dumpbyte(D, f->is_vararg);
  dumpint(D, f->maxstack);
  dumpint(D, f->sizecode);
  dumpblock(D, f->code, sizeof(Instr) * (size_t)f->sizecode);
  dumpint(D, f->sizek);
  for (i = 0; i < f->sizek; i++) {
    const TValue *o = &f->k[i];
    dumpbyte(D, o->tt);
    switch (o->tt) {
      case T_INT: dumpint(D, ivalue(o)); break;
      case T_FLT: dumpnum(D, fltvalue(o)); break;
      case T_STR: dumpstring(D, strvalue(o)); break;
      default: break;
    }
  }
  dumpint(D, f->sizeup);
  for (i = 0; i < f->sizeup; i++) {
    dumpbyte(D, f->upvals[i].instack);
    dumpbyte(D, f->upvals[i].kind);
    dumpint(D, f->upvals[i].idx);
    dumpstring(D, D->strip ? NULL : f->upvals[i].name);
  }
  dumpint(D, f->sizep);
  for (i = 0; i < f->sizep; i++) dumpfunction(D, f->p[i]);
  if (D->strip) {
    dumpint(D, 0);
    dumpint(D, 0);
    dumpint(D, 0);
  } else {
    dumpint(D, f->sizecode);
    dumpblock(D, f->lineinfo, sizeof(int) * (size_t)f->sizecode);
    dumpint(D, f->sizelocvars);
    for (i = 0; i < f->sizelocvars; i++) {
      dumpstring(D, f->locvars[i].name);
      dumpint(D, f->locvars[i].startpc);
      dumpint(D, f->locvars[i].endpc);
    }
    dumpint(D, f->sizevarinfo);
    for (i = 0; i < f->sizevarinfo; i++) {
      dumpint(D, f->varinfo[i].pc);
      dumpbyte(D, f->varinfo[i].which);
      dumpbyte(D, f->varinfo[i].kind);
      dumpstring(D, f->varinfo[i].name);
    }
  }
}

int dump_proto(State *L, const Proto *p, int strip, void (*w)(State *, const void *, size_t, void *), void *ud) {
  DumpState D;
  D.L = L;
  D.w = w;
