}

typedef struct LoadState {
  State *L;
  const char *p;
  size_t n;
  const char *name;
} LoadState;

static void error(LoadState *S, const char *why) {
  pushfstring(S->L, "%s: bad binary format (%s)", S->name, why);
  d_throw(S->L, TS_ERRSYNTAX);
}

static void loadblock(LoadState *S, void *b, size_t size) {
  if (size > S->n) error(S, "truncated chunk");
  memcpy(b, S->p, size);
  S->p += size;
  S->n -= size;
}

static lint loadint(LoadState *S) { lint x; loadblock(S, &x, sizeof(x)); return x; }
static lnum loadnum(LoadState *S) { lnum x; loadblock(S, &x, sizeof(x)); return x; }
static int loadbyte(LoadState *S) { unsigned char c; loadblock(S, &c, 1); return c; }

static Str *loadstring(LoadState *S) {
  lint len = loadint(S);
  Str *s;
  if (len < 0) return NULL;
  if ((size_t)len > S->n) error(S, "truncated chunk");
  s = str_new(S->L, S->p, (size_t)len);
  S->p += len;
  S->n -= (size_t)len;
  return s;
}

static Proto *loadfunction(LoadState *S, Str *psource) {
  Proto *f = proto_new(S->L);
  int i, n;
  f->source = loadstring(S);
  if (f->source == NULL) f->source = psource;
  f->linedefined = (int)loadint(S);
  f->lastlinedefined = (int)loadint(S);
  f->numparams = (uint8_t)loadbyte(S);
  f->is_vararg = (uint8_t)loadbyte(S);
  f->maxstack = (uint16_t)loadint(S);
  n = (int)loadint(S);
  f->code = mem_newvec(S->L, n, Instr);
  f->sizecode = n;
  loadblock(S, f->code, sizeof(Instr) * (size_t)n);
  n = (int)loadint(S);
  f->k = mem_newvec(S->L, n, TValue);
  f->sizek = n;
  for (i = 0; i < n; i++) setnil(&f->k[i]);
  for (i = 0; i < n; i++) {
    TValue *o = &f->k[i];
    int t = loadbyte(S);
    switch (t) {
      case T_NIL: setnil(o); break;
      case T_FALSE: setbool(o, 0); break;
      case T_TRUE: setbool(o, 1); break;
      case T_INT: setint(o, loadint(S)); break;
      case T_FLT: setflt(o, loadnum(S)); break;
      case T_STR: setstr(o, loadstring(S)); break;
      default: error(S, "bad constant");
    }
  }
  n = (int)loadint(S);
  f->upvals = mem_newvec(S->L, n, UpvalDesc);
  f->sizeup = n;
  for (i = 0; i < n; i++) f->upvals[i].name = NULL;
  for (i = 0; i < n; i++) {
    f->upvals[i].instack = (uint8_t)loadbyte(S);
    f->upvals[i].kind = (uint8_t)loadbyte(S);
    f->upvals[i].idx = (uint16_t)loadint(S);
    f->upvals[i].name = loadstring(S);
  }
  n = (int)loadint(S);
  f->p = mem_newvec(S->L, n, Proto *);
  f->sizep = n;
  for (i = 0; i < n; i++) f->p[i] = NULL;
  for (i = 0; i < n; i++) f->p[i] = loadfunction(S, f->source);
  n = (int)loadint(S);
  if (n > 0) {
    f->lineinfo = mem_newvec(S->L, n, int);
    loadblock(S, f->lineinfo, sizeof(int) * (size_t)n);
  } else {
    f->lineinfo = mem_newvec(S->L, f->sizecode, int);
    for (i = 0; i < f->sizecode; i++) f->lineinfo[i] = -1;
  }
  n = (int)loadint(S);
  f->locvars = mem_newvec(S->L, n, LocVar);
  f->sizelocvars = n;
  for (i = 0; i < n; i++) f->locvars[i].name = NULL;
  for (i = 0; i < n; i++) {
    f->locvars[i].name = loadstring(S);
    f->locvars[i].startpc = (int)loadint(S);
    f->locvars[i].endpc = (int)loadint(S);
  }
  n = (int)loadint(S);
  f->varinfo = mem_newvec(S->L, n, VarInfo);
  f->sizevarinfo = n;
  for (i = 0; i < n; i++) f->varinfo[i].name = NULL;
  for (i = 0; i < n; i++) {
    f->varinfo[i].pc = (int)loadint(S);
    f->varinfo[i].which = (uint8_t)loadbyte(S);
    f->varinfo[i].kind = (uint8_t)loadbyte(S);
    f->varinfo[i].name = loadstring(S);
  }
  return f;
}

Proto *undump(State *L, const char *buff, size_t size, const char *name) {
  LoadState S;
  char sig[sizeof(DUMP_SIG)];
  S.L = L;
  S.p = buff;
  S.n = size;
  if (*name == '@' || *name == '=') S.name = name + 1;
  else if (*name == '\x1b') S.name = "binary string";
  else S.name = name;
  loadblock(&S, sig, sizeof(DUMP_SIG) - 1);
  if (memcmp(sig, DUMP_SIG, sizeof(DUMP_SIG) - 1) != 0) error(&S, "not a binary chunk");
  loadbyte(&S);
  return loadfunction(&S, str_newc(L, "=?"));
}
