  f->code = mem_newvec(S->L, n, Instr);
  f->sizecode = n;
  loadblock(S, f->code, sizeof(Instr) * (size_t)n);
  n = (int)loadint(S);
  f->k = mem_newvec(S->L, n, TValue);
  f->sizek = n;
  for (i = 0; i < n; i++) setnil(&f->k[i]);
  for (i = 0; i < n; i++) {
    TValue *o = &f->k[i];
    int t = loadbyte(S);
    switch (t) {
      case T_NIL: setnil(o); break;
      case T_FALSE: setbool(o, 0); break;
      case T_TRUE: setbool(o, 1); break;
      case T_INT: setint(o, loadint(S)); break;
      case T_FLT: setflt(o, loadnum(S)); break;
      case T_STR: setstr(o, loadstring(S)); break;
