    f->upvals[i].name = loadstring(S);
  }
  n = (int)loadint(S);
  f->p = mem_newvec(S->L, n, Proto *);
  f->sizep = n;
  for (i = 0; i < n; i++) f->p[i] = NULL;
  for (i = 0; i < n; i++) f->p[i] = loadfunction(S, f->source);
  n = (int)loadint(S);
  if (n > 0) {
    f->lineinfo = mem_newvec(S->L, n, int);
    loadblock(S, f->lineinfo, sizeof(int) * (size_t)n);
  } else {
    f->lineinfo = mem_newvec(S->L, f->sizecode, int);
    for (i = 0; i < f->sizecode; i++) f->lineinfo[i] = -1;
  }
