    f->locvars[i].startpc = (int)loadint(S);
    f->locvars[i].endpc = (int)loadint(S);
  }
  n = (int)loadint(S);
  f->varinfo = mem_newvec(S->L, n, VarInfo);
  f->sizevarinfo = n;
  for (i = 0; i < n; i++) f->varinfo[i].name = NULL;
  for (i = 0; i < n; i++) {
    f->varinfo[i].pc = (int)loadint(S);
    f->varinfo[i].which = (uint8_t)loadbyte(S);
    f->varinfo[i].kind = (uint8_t)loadbyte(S);
    f->varinfo[i].name = loadstring(S);
  }
  return f;
}

Proto *undump(State *L, const char *buff, size_t size, const char *name) {
  LoadState S;
  char sig[sizeof(DUMP_SIG)];
  S.L = L;
  S.p = buff;
  S.n = size;
  if (*name == '@' || *name == '=') S.name = name + 1;
  else if (*name == '\x1b') S.name = "binary string";
  else S.name = name;
  loadblock(&S, sig, sizeof(DUMP_SIG) - 1);
  if (memcmp(sig, DUMP_SIG, sizeof(DUMP_SIG) - 1) != 0) error(&S, "not a binary chunk");
  loadbyte(&S);
  return loadfunction(&S, str_newc(L, "=?"));
}
