static const char *get_prompt(State *L, int firstline) {
  if (ls_getglobal(L, firstline ? "_PROMPT" : "_PROMPT2") == TY_NIL)
    return (firstline ? "> " : ">> ");
  else {
    const char *p = la_tolstring(L, -1, NULL);
    ls_remove(L, -2);
    return p;
  }
}

#define EOFMARK "<eof>"
#define marklen (sizeof(EOFMARK) / sizeof(char) - 1)

static int incomplete(State *L, int status) {
  if (status == TS_ERRSYNTAX) {
    size_t lmsg;
    const char *msg = ls_tolstring(L, -1, &lmsg);
    if (lmsg >= marklen && strcmp(msg + lmsg - marklen, EOFMARK) == 0)
      return 1;
  }
  return 0;
}

static int interactive = 0;

static int l_readline(State *L, char *b, const char *prmt) {
  (void)L;
  fputs(prmt, stdout);
  fflush(stdout);
  if (fgets(b, LUA_MAXINPUT, stdin) == NULL) return 0;
  if (!interactive) {
    size_t l = strlen(b);
    fputs(b, stdout);
    if (l == 0 || b[l - 1] != '\n') fputs("\n", stdout);
    fflush(stdout);
  }
  return 1;
}

static int pushline(State *L, int firstline) {
  char buffer[LUA_MAXINPUT];
  char *b = buffer;
  size_t l;
  const char *prmt = get_prompt(L, firstline);
  int readstatus = l_readline(L, b, prmt);
  ls_pop(L, 1);
  if (readstatus == 0)
    return 0;
  l = strlen(b);
  if (l > 0 && b[l - 1] == '\n')
    b[--l] = '\0';
  if (firstline && b[0] == '=')
    ls_pushfstring(L, "return %s", b + 1);
  else
    ls_pushlstring(L, b, l);
  return 1;
}

static int addreturn(State *L) {
  const char *line = ls_tostring(L, -1);
  const char *retline = ls_pushfstring(L, "return %s;", line);
  int status = la_loadbufferx(L, retline, strlen(retline), "=stdin", NULL);
  if (status == TS_OK)
    ls_remove(L, -2);
  else
    ls_pop(L, 2);
  return status;
}

static int multiline(State *L) {
  size_t len;
  const char *line = ls_tolstring(L, 1, &len);
  for (;;) {
    int status = la_loadbufferx(L, line, len, "=stdin", NULL);
    if (!incomplete(L, status) || !pushline(L, 0)) {
      return status;
    }
    ls_remove(L, -2);
    ls_pushliteral(L, "\n");
    ls_insert(L, -2);
    ls_concat(L, 3);
    line = ls_tolstring(L, 1, &len);
  }
}

static int loadline(State *L) {
  int status;
  ls_settop(L, 0);
  if (!pushline(L, 1))
    return -1;
  if ((status = addreturn(L)) != TS_OK)
    status = multiline(L);
  ls_remove(L, 1);
  return status;
}

static void l_print(State *L) {
  int n = ls_gettop(L);
  if (n > 0) {
    la_checkstack(L, LUA_MINSTACK_, "too many results to print");
    ls_getglobal(L, "print");
    ls_insert(L, 1);
    if (ls_pcall(L, n, 0, 0) != TS_OK)
      l_message(progname, ls_pushfstring(L, "error calling 'print' (%s)", ls_tostring(L, -1)));
  }
}

static void doREPL(State *L) {
  int status;
  const char *oldprogname = progname;
  progname = NULL;
  interactive = isatty(0);
  while ((status = loadline(L)) != -1) {
    if (status == TS_OK)
      status = docall(L, 0, MULTRET);
    if (status == TS_OK) l_print(L);
    else report(L, status);
  }
  ls_settop(L, 0);
  writeline();
  progname = oldprogname;
}

static int pmain(State *L) {
  int argc = (int)ls_tointeger(L, 1);
  char **argv = (char **)ls_touserdata(L, 2);
  int script;
  int args = collectargs(argv, &script);
  int optlim = (script > 0) ? script : argc;
  if (args == has_error) {
    print_usage(argv[script]);
    return 0;
  }
  if (args & has_v)
    print_version();
  if (args & has_E) {
    ls_pushboolean(L, 1);
    ls_setfield(L, REGISTRYINDEX, "LUA_NOENV");
  }
  open_libs(L);
  createargtable(L, argv, argc, script);
  if (!(args & has_E)) {
    if (handle_luainit(L) != TS_OK)
      return 0;
  }
  if (!runargs(L, argv, optlim))
    return 0;
  if (script > 0) {
    if (handle_script(L, argv + script) != TS_OK)
      return 0;
  }
  if (args & has_i)
    doREPL(L);
  else if (script < 1 && !(args & (has_e | has_v))) {
    if (isatty(0)) {
      print_version();
      doREPL(L);
    } else
      dofile(L, NULL);
  }
  ls_pushboolean(L, 1);
  return 1;
}

int main(int argc, char **argv) {
  int status, result;
  State *L = ls_newstate();
  if (L == NULL) {
    l_message(argv[0], "cannot create state: not enough memory");
    return EXIT_FAILURE;
  }
  globalL = L;
  ls_pushcfunction(L, pmain);
  ls_pushinteger(L, argc);
  ls_pushlightuserdata(L, argv);
  status = ls_pcall(L, 2, 1, 0);
  result = ls_toboolean(L, -1);
  report(L, status);
  ls_close(L);
  fflush(stdout);
  return (result && status == TS_OK) ? EXIT_SUCCESS : EXIT_FAILURE;
}
