static void *slab_get(Slab *sl) {
  void *p;
  if (sl->nfree > 0) return sl->freel[--sl->nfree];
  if (sl->curleft == 0) {
    void *m = mmap(NULL, sl->slotsize * (size_t)sl->perchunk, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
    if (m == MAP_FAILED) return NULL;
    sl->cur = (char *)m;
    sl->curleft = sl->perchunk;
  }
  p = sl->cur;
  sl->cur += sl->slotsize;
  sl->curleft--;
  return p;
}

static void slab_put(Slab *sl, void *p) {
  if (sl->nfree >= sl->sizefree) {
